// ==================== 内存分配（M22：size-class slab 子分配器 + 大对象 mmap 兜底） ====================
// M11 并发 GC：sweep 会释放对象，而其他线程可能正在 malloc/free 中被 GC 信号挂起
// （持有 glibc 堆锁）→ GC 主线程 free 会死锁。因此对象与子分配全部改用
// mmap + 自管 slab（无 glibc 堆锁）：信号挂起在 mmap/munmap 中不持有堆锁。
// M22 优化（解决 M11.3 已知限制①"mmap 每对象一页 ≈4KB/对象 内存放大"）：
//   小对象（≤16KB）按 size-class 从 slab 槽位分配（16/24/32/48/64/96/128/192/256/
//   384/512/768/1024/1536/2048/3072/4096/6144/8192/12288/16384），一页多槽共享；
//   超过最大 class 回落 mmap（每分配一映射，带大小头）。
//   M11.3 曾试"无锁 slab"失败（空闲栈 next 被覆盖 = 无锁竞态）→ M22 改用互斥锁保护，
//   持锁期间屏蔽 SIG_GC_STOP（gc_block_stop，与 list/dict 结构修改函数同一模式）：
//   持锁线程不会被 GC 暂停 → GC 主线程（sweep 时 xfree）不会等待被暂停线程持有的锁。
//   对象表 g_objs 与 GC 逻辑不变，slab 仅是底层内存提供者；槽位复用只发生在 sweep
//   （stop-the-world，无并发分配）之后，杜绝 use-after-free。

#define PX_PAGE 4096
#define SLAB_MAX_CLASS 16384          // 超过此大小 → mmap 兜底
#define SLAB_CLASS_COUNT 21
static const size_t slab_classes[SLAB_CLASS_COUNT] = {
    16, 24, 32, 48, 64, 96, 128, 192, 256, 384, 512, 768,
    1024, 1536, 2048, 3072, 4096, 6144, 8192, 12288, 16384
};

typedef struct Slab {
    struct Slab* next;      // 同 class 链表
    void* base;             // mmap 映射起点（含头部）
    size_t class_size;      // 槽大小（= class 值）
    size_t slot_count;      // 槽总数
    size_t free_count;      // 空闲槽数（0 → 不可分配，需新 slab）
    void* free_head;        // 空闲链表头（槽内首 word 存 next，NULL 结束）
    unsigned char* in_use;  // 槽占用位图（1=已分配），检测双重分配/释放（M107-S3a 起内联在映射尾部）
    // ---- M107-S3（qg-issue 34 内存路径）字段 ----
    size_t map_bytes;       // S3a：本 slab 的 mmap 长度（回收 munmap 用；位图已内联其后，不再单独映射）
    int empty_streak;       // S3c：连续被观测到「完全空闲」的 GC 轮数（≥ SLAB_FREE_STREAK 才归还 OS）
    int class_idx;          // S3b：所属 size-class 下标（免去每次按 class_size 反查的线性扫描）
    int on_list;            // S3b：是否在所属 class 的「有空槽」链上（防重复入链）
} Slab;

static pthread_mutex_t g_slab_mu = PTHREAD_MUTEX_INITIALIZER;
// M107-S3b：g_slab_heads[ci] 的链式语义被强化为**不变量**：
//   链上「恰好」是该 class 中**尚有空槽（free_count > 0）**的 slab，链首即下一个分配来源。
//   · 分配：只取链首；该 slab 因分配变满 → 摘链首（O(1)：g_slab_heads[ci] = s->next）；
//          链首为空（该 class 已无任何空槽 slab）→ slab_create 新建并置链首。
//   · 释放：槽位归还所属 slab；该 slab 由「满」变「有空槽」 → 头插回链（O(1)）。
//   动机（qg-issue 34 内存路径）：原实现只从链首分配、**归还的空槽永不入链复用** ⇒
//   每个 class 的 slab 只增不减、反复 mmap/munmap（实测 59.4k 建 / 24.1k 拆）。
//   代价：分配/释放各增 O(1) 常数（一次判断 + 可能的摘/插链首），与改动前同阶。
static Slab* g_slab_heads[SLAB_CLASS_COUNT] = {0};
// ISSUE28-B1：xfree 局部性 hint——sweep 成批释放同一批 slab 的对象/数据时，跳过 O(log R)
// 反查二分（实测全量 STW 主要耗时在 sweep 的 xfree：120k 对象 ~250ms，单发 p95 尖刺根因）。
#define XFREE_HINT_N 16
// M107-S3c：空 slab 归还水位——连续观察到此轮数仍「完全空闲」才 munmap 归还 OS。
//   原实现每轮 GC 把**所有**空 slab 全量归还 ⇒ 下轮分配又 mmap 新建（真负载实测
//   24.1k 拆 / 59.4k 建交替冲刷）。滞留 1 轮即可吸收「分配-释放-再分配」抖动，
//   同时保持「程序真正缩容时内存最终回吐 OS」的 ISSUE28-B2 语义（最多滞后 1 轮）。
#define SLAB_FREE_STREAK 4
// M107-S3e：单 slab 最小页数（默认 4 页 = 16KB）。原实现按「≥4 槽」定页数，小 class
//   （≤1020B）只映射 1 页 ⇒ 槽位少的 class 会为很少的活对象反复 mmap「每 slab 一次」。
//   抬高到 16KB 让单次 mmap 覆盖更多槽位，直接按比例稀释该固定成本；代价是低占用 class
//   的尾部内部碎片（回收靠 S3b/S3c 的复用与水位兜住，实测 RSS 仍远低于改动前）。
//   约束：class 16 时槽数 = (16384-72)/17 = 958 < slab_find_locked 的 1024 健全性上限。
#define SLAB_MIN_PAGES 4
static Slab* g_xfree_hint[XFREE_HINT_N];
static int g_xfree_hint_head = 0;
static __thread int g_in_gc_sweep = 0;  // ISSUE28-B1：GC sweep 中（executor 已屏蔽 SIG_GC_STOP、单线程），xfree 跳过每趟 sigprocmask 屏蔽/恢复（实测全量 STW 耗时大头）
// 地址 → slab 反查（xfree/xrealloc 定位）：按 base 升序，二分查找
static Slab** g_slab_ranges = NULL;
static size_t g_slab_range_count = 0;
static size_t g_slab_range_cap = 0;

// ==================== M125（qg-issue 82）：分配失败「请求级失败」化 ====================
// 病灶：三处 mmap 失败（slab_raw_alloc / slab_create / xmalloc 大对象）一律
//   `fprintf(stderr,"lx: 内存不足"); exit(1);` —— **一个请求**即可带走整个服务进程。
//   实测 mahesvara（8 站点同进程）因此整站不可达约 3 s：journal `lx: 内存不足` →
//   `Main process exited, code=exited, status=1` → systemd 重启；07:17、09:06 两轮复现，
//   `NRestarts` 累计 10 次。更糟的是**归因误导**——真因往往不是内存不足，而是
//   「尺寸算成 0/负数」：`(n + 8 + pg-1) & ~(pg-1)` 在 n 接近 SIZE_MAX 时回绕成 0，
//   `mmap(NULL,0)` 返回 EINVAL，却被报成「内存不足」。
// 新语义（先给真实原因，再决定死不死）：
//   ① 尺寸非法（回绕为 0 / ≥ 1<<62）→ 报「分配尺寸非法（尺寸计算溢出/负长度）」+ 字节数；
//   ② 映射失败 → 报「内存不足」+ 字节数 + errno；
//   ③ 两种情况统一走「先隔离、后致命」：协程隔离点内（serve handler / spawn，即
//      g_err_jmp_set 为真）→ longjmp **只终止本协程** ⇒ HTTP 层按既有 M116 语义转 5xx，
//      进程与其余连接完全不受影响；无隔离点（启动期 / GC / 信号上下文）→ 保留原
//      致命语义（_exit(1)，不静默续跑，避免状态不一致）。
// 与文档口径一致：runtime 运行时错误从「进程级」收紧到「请求级」。
#define PX_ALLOC_ABSURD ((size_t)1 << 62)
static void px_alloc_fail(size_t n, size_t total, const char* what);  // 定义见 px_error 之后
static size_t px_alloc_fail_min(void);                                // 测试钩子（PX_ALLOC_FAIL_MIN）
static int px_alloc_fail_in_lock_hit(size_t n);                       // M127 测试钩子（PX_ALLOC_FAIL_IN_LOCK）
static __thread const char* t_alt_match;                              // M127：注入命中的锁名（诊断用）
static _Atomic int g_sig_err_count;   // M126：信号处理器隔离计数（定义在 sig 段；此处前置声明）
static size_t px_map_bytes(size_t n, int* overflow);

// 请求字节数 → mmap 长度（含头部 + 页对齐）。**显式检出回绕**：原实现把回绕当「内存不足」，
// 掩盖真实缺陷。overflow=1 时返回值不可用（调用方直接走 px_alloc_fail）。
static size_t px_map_bytes(size_t n, int* overflow) {
    size_t pg = PX_PAGE;
    *overflow = 0;
    if (n > SIZE_MAX - sizeof(size_t) - (pg - 1)) { *overflow = 1; return 0; }
    return (n + sizeof(size_t) + pg - 1) & ~(size_t)(pg - 1);
}

// 反查数组的裸分配：slab_create 在持 g_slab_mu 期间调用，不能走 xmalloc（会重入锁）
// M125：失败不再 exit(1) —— **返回 NULL**，由 slab_create 回滚已建成员后再让 xmalloc
//   解锁并走 px_alloc_fail（否则带锁 longjmp 会遗留 g_slab_mu ⇒ 全进程死锁）。
static void* slab_raw_alloc(size_t n) {
    int ovf = 0;
    size_t total = px_map_bytes(n, &ovf);
    if (ovf) { errno = ENOMEM; return NULL; }
    void* p = mmap(NULL, total, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (p == MAP_FAILED) return NULL;
    *(size_t*)p = total;
    return (char*)p + sizeof(size_t);
}
static void slab_raw_free(void* p) {
    if (!p) return;
    size_t total = *(size_t*)((char*)p - sizeof(size_t));
    munmap((char*)p - sizeof(size_t), total);
}

static int slab_class_index(size_t n) {
    for (int i = 0; i < SLAB_CLASS_COUNT; i++) {
        if (n <= slab_classes[i]) return i;
    }
    return -1;  // 大对象
}

static int slab_cmp(const void* a, const void* b) {
    const Slab* sa = *(const Slab* const*)a;
    const Slab* sb = *(const Slab* const*)b;
    if (sa->base < sb->base) return -1;
    if (sa->base > sb->base) return 1;
    return 0;
}

// 创建新 slab（调用方须持 g_slab_mu）：映射可容纳 ≥4 槽的页数，初始化空闲链表
//
// M107-S3a（qg-issue 34 内存路径）：原位图单独 slab_raw_alloc 一次（另一次 mmap），
//   实测每次 slab_create = 2 次 4KB mmap、每次回收 = 2 次 4KB munmap（真负载 24.1k 拆/
//   59.4k 建）。改为**位图内联在 slab 映射尾部**：
//       [Slab 头(8B 对齐)][槽区 slot_count*class_size][in_use 位图 slot_count 字节]
//   三者同属一次 mmap ⇒ 建 1 次 / 拆 1 次，且不改变任何对外语义（红线 2/3/5）。
//   位图是 1 字节/槽的占用标记（原实现即如此），尺寸 ≤ 槽数 ≤ 1024 字节级。
#define SLAB_HEADER ((sizeof(Slab) + 7) & ~(size_t)7)
static Slab* slab_create(size_t class_size, int class_idx) {
    size_t header = SLAB_HEADER;
    size_t pages = (4 * class_size + PX_PAGE - 1) / PX_PAGE;   // 至少 4 槽的页数
    if (pages < SLAB_MIN_PAGES) pages = SLAB_MIN_PAGES;        // S3e：单 slab 最小 16KB
    // 求最小页数，使 [槽区 + 位图] 能放下 ≥4 槽（位图 = 1 字节/槽）
    size_t slab_bytes = 0, slots_in_bytes = 0;
    for (;;) {
        slab_bytes = pages * PX_PAGE;
        if (slab_bytes > header + 1) {
            slots_in_bytes = (slab_bytes - header) / (class_size + 1);
            if (slots_in_bytes >= 4) break;
        }
        pages++;
    }
    void* p = mmap(NULL, slab_bytes, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    // M125：失败返回 NULL（调用方 xmalloc 解锁后走 px_alloc_fail）—— 不再 exit(1)
    if (p == MAP_FAILED) return NULL;
    Slab* s = (Slab*)p;
    s->next = g_slab_heads[class_idx];
    s->base = p;
    s->class_size = class_size;
    s->slot_count = slots_in_bytes;
    s->free_count = slots_in_bytes;
    s->free_head = NULL;
    s->map_bytes = slab_bytes;
    s->empty_streak = 0;
    s->class_idx = class_idx;
    s->on_list = 1;                     // S3b：新 slab 有空槽 → 立即在「有空槽」链上
    s->in_use = (unsigned char*)p + header + slots_in_bytes * class_size;  // S3a：内联在槽区之后
    memset(s->in_use, 0, slots_in_bytes);
    char* slots = (char*)p + header;
    // 空闲链表：从后往前串（槽内首 word 存 next）
    void* head = NULL;
    for (size_t i = slots_in_bytes; i > 0; i--) {
        void* slot = slots + (i - 1) * class_size;
        *(void**)slot = head;
        head = slot;
    }
    s->free_head = head;
    g_slab_heads[class_idx] = s;
    // 插入反查数组（保持按 base 升序）
    if (g_slab_range_count >= g_slab_range_cap) {
        size_t ncap = g_slab_range_cap ? g_slab_range_cap * 2 : 64;
        Slab** nr = (Slab**)slab_raw_alloc(ncap * sizeof(Slab*));
        if (!nr) {
            // M125：反查数组扩容失败 → **回滚**刚建好、尚未登记的 slab（保持不变量：
            //   g_slab_heads 链 / g_slab_ranges 反查数组必须一致），返回 NULL 交调用方
            //   解锁后走 px_alloc_fail。绝不带锁 longjmp（会遗留 g_slab_mu）。
            g_slab_heads[class_idx] = s->next;
            munmap(s->base, s->map_bytes);
            errno = ENOMEM;
            return NULL;
        }
        if (g_slab_ranges) { memcpy(nr, g_slab_ranges, g_slab_range_count * sizeof(Slab*)); slab_raw_free(g_slab_ranges); }
        g_slab_ranges = nr;
        g_slab_range_cap = ncap;
    }
    size_t pos = 0;
    while (pos < g_slab_range_count && g_slab_ranges[pos]->base < p) pos++;
    memmove(&g_slab_ranges[pos + 1], &g_slab_ranges[pos], (g_slab_range_count - pos) * sizeof(Slab*));
    g_slab_ranges[pos] = s;
    g_slab_range_count++;
    return s;
}

// 指针 → slab（二分；返回 NULL 表示 mmap 大对象）
// 注意：g_slab_ranges 在 slab_create（持 g_slab_mu）中 memmove 维护；
// 外部调用（xrealloc→xalloc_cap）必须经 slab_find（持锁）读取，防撕裂读竞态。
static Slab* slab_find_locked(const void* p) {
    if (g_slab_range_count == 0) return NULL;
    // 防御：检测 ranges 数组损坏（并发竞态/越界写），避免返回垃圾 Slab* 导致 xfree 误判
    if (g_slab_range_count > g_slab_range_cap) {
        fprintf(stderr, "SLAB CORRUPT: count=%zu cap=%zu\n", g_slab_range_count, g_slab_range_cap);
        abort();
    }
    size_t lo = 0, hi = g_slab_range_count;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        Slab* s = g_slab_ranges[mid];
        if ((uintptr_t)s < 0x10000 || ((uintptr_t)s & 7) != 0 ||
            s->base != (void*)s || s->class_size < 16 || s->class_size > SLAB_MAX_CLASS ||
            s->slot_count == 0 || s->slot_count > 1024) {
            fprintf(stderr, "SLAB CORRUPT: ranges[%zu]=%p count=%zu cap=%zu p=%p base=%p cs=%zu slots=%zu\n",
                    mid, (void*)s, g_slab_range_count, g_slab_range_cap, p,
                    s->base, s->class_size, s->slot_count);
            abort();
        }
        if (p < s->base) hi = mid;
        else {
            // M107-S3a：映射长度直接取自 Slab（位图内联后含位图；原按 header+槽区页对齐推算）
            void* end = (char*)s->base + s->map_bytes;
            if ((const char*)p < (const char*)end) return s;
            lo = mid + 1;
        }
    }
    return NULL;
}

// 线程安全版（供 xalloc_cap 等未持 g_slab_mu 的调用方）
static Slab* slab_find(const void* p) {
    sigset_t old;
    gc_block_stop(&old);
    pthread_mutex_lock(&g_slab_mu);
    Slab* s = slab_find_locked(p);
    pthread_mutex_unlock(&g_slab_mu);
    gc_unblock_stop(&old);
    return s;
}

static void* xmalloc(size_t n) {
    if (n <= 0) n = 1;
    if (px_alloc_fail_in_lock_hit(n)) {
        // M127 测试钩子：**在调用方仍持有运行时锁时**注入分配失败 —— 用于确定性复现
        //   「失败点落在临界区内 ⇒ 回卷留锁 ⇒ 进程假死」这条路径（见 locktrack.h）。
        int o = 0;
        size_t t = px_map_bytes(n, &o);
        px_alloc_fail(n, o ? 0 : t, t_alt_match ? "xmalloc（PX_ALLOC_FAIL_IN_LOCK 注入：临界区内）"
                                                : "xmalloc（注入）");
    }
    if (n >= px_alloc_fail_min()) {
        // M125 测试钩子：按"映射失败"语义注入（total 传真实值，避免被分类成尺寸非法）
        int o = 0;
        size_t t = px_map_bytes(n, &o);
        px_alloc_fail(n, o ? 0 : t, "xmalloc（PX_ALLOC_FAIL_MIN 注入）");
    }
    int ci = slab_class_index(n);
    if (ci < 0) {  // 大对象：mmap 每分配一映射（带大小头，行为同 M11）
        int ovf = 0;
        size_t total = px_map_bytes(n, &ovf);
        // M125：回绕 / 映射失败 → 请求级失败（原为 `lx: 内存不足` + exit(1)，整站陪葬）
        if (ovf) px_alloc_fail(n, 0, "xmalloc 大对象");
        void* p = mmap(NULL, total, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (p == MAP_FAILED) px_alloc_fail(n, total, "xmalloc 大对象");
        *(size_t*)p = total;
        return (char*)p + sizeof(size_t);
    }
    size_t cs = slab_classes[ci];
    sigset_t old;
    gc_block_stop(&old);
    pthread_mutex_lock(&g_slab_mu);
    Slab* s = g_slab_heads[ci];
    // M107-S3b：链首即「有空槽」的 slab（不变量见 g_slab_heads 声明处注释）；
    //   链为空 ⇒ 该 class 已无空槽可复用，新建（新建后自动置链首）。
    if (!s) s = slab_create(cs, ci);
    if (!s) {
        // M125：建 slab（或其反查数组扩容）失败 —— **必须先在锁内、解锁之后**再走失败处理：
        //   带锁 longjmp 不展开 pthread 锁 ⇒ g_slab_mu 永久遗留 ⇒ 全进程死锁。
        int ferr = errno;
        pthread_mutex_unlock(&g_slab_mu);
        gc_unblock_stop(&old);
        errno = ferr;
        px_alloc_fail(cs, 0, "slab_create");
    }
    void* slot = s->free_head;
    size_t header = SLAB_HEADER;
    size_t idx = ((const char*)slot - ((const char*)s->base + header)) / cs;
    if (s->in_use[idx]) { fprintf(stderr, "SLAB BUG: double-alloc slot %zu class %zu\n", idx, cs); abort(); }
    s->in_use[idx] = 1;
    s->free_head = *(void**)slot;
    s->free_count--;
    if (s->free_count == 0) {   // S3b：本 slab 已满 → 摘链首（O(1)），链首换成下一个有空槽的 slab
        g_slab_heads[ci] = s->next;
        s->next = NULL;
        s->on_list = 0;
    }
    pthread_mutex_unlock(&g_slab_mu);
    gc_unblock_stop(&old);
    memset(slot, 0, cs);   // 清零：gc_mark 等字段依赖零初始化
    return slot;
}

static void xfree(void* p) {
    if (!p) return;
    sigset_t old;
    int blk = !g_in_gc_sweep;   // ISSUE28-B1：sweep 内 executor 已屏蔽信号且单线程 → 免逐趟 sigprocmask
    if (blk) gc_block_stop(&old);
    pthread_mutex_lock(&g_slab_mu);
    // ISSUE28-B1 快路径：先查最近释放过的 slab hint（成批释放同 slab 命中即免二分反查）。
    // 仅在本锁内读写 hint；slab_reclaim_empty 归还空 slab 时同锁清零 → 无悬垂 hint。
    Slab* s = NULL;
    for (int hi = 0; hi < XFREE_HINT_N; hi++) {
        Slab* h = g_xfree_hint[hi];
        if (!h) continue;
        // M107-S3a：映射长度取自 Slab（位图内联后含位图）
        uintptr_t hend = (uintptr_t)h + h->map_bytes;
        if ((uintptr_t)p >= (uintptr_t)h && (uintptr_t)p < hend) { s = h; break; }
    }
    if (!s) s = slab_find_locked(p);
    if (s) {
        g_xfree_hint[g_xfree_hint_head] = s;
        g_xfree_hint_head = (g_xfree_hint_head + 1) % XFREE_HINT_N;
        size_t header = SLAB_HEADER;
        size_t off = (const char*)p - ((const char*)s->base + header);
        size_t idx = off / s->class_size;
        int aligned = (off % s->class_size == 0);
        if (!aligned || idx >= s->slot_count) {
            fprintf(stderr, "SLAB BUG: bad-free p=%p slab=%p class=%zu off=%zu idx=%zu aligned=%d\n",
                    p, s->base, s->class_size, off, idx, aligned);
            abort();
        }
        if (!s->in_use[idx]) {
            // 槽已空闲（double-free）：幂等忽略，不重复入链（防空闲链表环 → 双重分配）
            pthread_mutex_unlock(&g_slab_mu);
            if (blk) gc_unblock_stop(&old);
            return;
        }
        s->in_use[idx] = 0;
        *(void**)p = s->free_head;
        s->free_head = p;
        int was_full = (s->free_count == 0);
        s->free_count++;
        // M107-S3b：该 slab 由「满」变「有空槽」 → 头插回本 class 的复用链（O(1)）
        if (was_full && !s->on_list) {
            s->next = g_slab_heads[s->class_idx];
            g_slab_heads[s->class_idx] = s;
            s->on_list = 1;
        }
        pthread_mutex_unlock(&g_slab_mu);
        if (blk) gc_unblock_stop(&old);
        return;
    }
    pthread_mutex_unlock(&g_slab_mu);
    if (blk) gc_unblock_stop(&old);
    size_t total = *(size_t*)((char*)p - sizeof(size_t));
    munmap((char*)p - sizeof(size_t), total);
}

// 分配容量（xrealloc 用：slab → class 大小；mmap → 记录大小）
static size_t xalloc_cap(const void* p) {
    Slab* s = slab_find(p);
    if (s) return s->class_size;
    return *(size_t*)((char*)p - sizeof(size_t)) - sizeof(size_t);
}

static void* xrealloc(void* p, size_t n) {
    if (!p) return xmalloc(n);
    if (n <= 0) n = 1;
    size_t cap = xalloc_cap(p);
    if (n <= cap) return p;   // 容量足够，不缩小
    void* np = xmalloc(n);
    memcpy(np, p, cap < n ? cap : n);
    xfree(p);
    return np;
}

static void* xcalloc(size_t n, size_t sz) {
    // M125：乘法回绕检出 —— 原实现 n*sz 回绕时只映射出**过小**的块（随后 memset 按回绕后的
    //   小值写，看似"正常"），一旦调用方按 n*sz 使用即越界写（静默堆损坏）。
    if (sz != 0 && n > SIZE_MAX / sz) px_alloc_fail(SIZE_MAX, 0, "xcalloc 尺寸溢出");
    void* p = xmalloc(n * sz);
    memset(p, 0, n * sz);
    return p;
}

static char* xstrdup(const char* s) {
    size_t n = strlen(s);
    char* p = xmalloc(n + 1);
    memcpy(p, s, n + 1);
    return p;
}

// ==================== M128（qg-issue 85）：扩容分配移出临界区 ====================
// 病灶（M127 门坐实）：`px_dict_set` / `px_list_push` / `gc_register` 在**持 g_gc_mu**
//   期间做可失败分配（`xrealloc` / `xstrdup`）。分配失败 ⇒ M127 审计判定「带锁回卷 ⇒ 留锁
//   ⇒ 假死」，故只能退回 `_exit(1)`（服务中断约 3 s）⇒ 这三处上「OOM ⇒ 请求级 5xx」
//   **尚未**成立。次生病灶：原实现先 `cap *= 2` 再 `xrealloc`，失败会留下「cap 已翻倍、
//   数组仍是旧长度」⇒ 之后按新 cap 写入即**越界写**（真实堆破坏，对长生命期对象尤其致命）。
// 做法（两阶段；对齐 M125 对 g_slab_mu 的处置「先分配、后进临界区」）：
//   · 阶段 A（**临界区外**）：按无锁快照预判是否需要更大的数组 / 是否需要键副本，需要则先
//     分配好。备货是**本线程私有、尚未发布**的裸数组（GC 不可见）⇒ 此处任何失败都发生在
//     **无锁在身**时 ⇒ 走常规隔离 ⇒ 请求级 5xx（正是本源要的语义）。
//   · 阶段 B（临界区内）：只做**指针发布**（memcpy + 换指针 + 释放旧数组），不含任何可失败
//     分配。发现备货不足（并发增长把槽位用掉了）⇒ 解锁重来（备货在锁外释放）。
//   · 不变量：备货只是「更大的空数组」，**未发布即不可见** ⇒ 中途失败**不改变对象状态**
//     （顺带修掉上面那条 cap 与数组长度不一致的越界写缺陷）。
// 兜底（不回归、不无限循环）：锁外重试 `PX_GROW_RETRY_MAX` 次（默认 32）仍不足 ⇒ 回退
//   **锁内扩容**（= M127 及以前的行为）。`PX_GROW_RETRY_MAX=0` 直接走锁内路径（M127 门
//   对照用：证明审计闸在兜底路径上仍然生效）。
// 站点标签注入（默认关）：`PX_ALLOC_FAIL_SITE=<子串>`（可选 `PX_ALLOC_FAIL_SITE_MIN=<字节>`
//   设下限）⇒ 让**指定站点**的阶段 A 分配失败。**一次性**（只触发第一次命中）是刻意的：
//   这样「失败之后对象是否仍然完好、服务是否仍可用」才能由后续请求验证（若每次都触发，
//   后续核对请求自己也会失败，就什么都证不了）。注入落点在临界区外 ⇒ 期望「请求级 5xx ＋
//   进程存活 ＋ **无**锁审计行」，这正是与 M127 门（锁内失败 ⇒ `_exit(1)`）的对照面。
#define M128_GROW_SLACK 8     // 预留余量：降低并发增长下「备货不足 ⇒ 重试」的概率
static int m128_retry_max(void) {
    static int cached = -1;
    if (cached < 0) {
        const char* e = getenv("PX_GROW_RETRY_MAX");
        cached = (e && *e) ? atoi(e) : 32;
        if (cached < 0) cached = 0;
        if (cached > 1000) cached = 1000;   // 上界：病态竞争下也不至于长转
    }
    return cached;
}
// 站点标签注入（测试钩子，默认关；一次性）
// 注：环境变量**每次读**（不缓存）—— 这样门可以先用一个请求 env_set 打开钩子（避免启动期
//   或 HTTP 层的无关分配抢先命中），且「关」时成本仅两次 getenv（只发生在扩容路径上）。
static int m128_site_hit(size_t n, const char* site) {
    static int fired = 0;
    if (fired || !site) return 0;
    const char* pat = getenv("PX_ALLOC_FAIL_SITE");
    if (!pat || !*pat) return 0;
    if (strstr(site, pat) == NULL) return 0;
    const char* m = getenv("PX_ALLOC_FAIL_SITE_MIN");
    size_t min_bytes = (m && *m) ? (size_t)strtoull(m, NULL, 10) : 0;
    if (n < min_bytes) return 0;
    fired = 1;
    fprintf(stderr, "[px-m128] 注入命中：站点=%s，申请 %zu 字节（临界区外 ⇒ 期望请求级 5xx）\n",
            site, n);
    fflush(stderr);
    return 1;
}
// 阶段 A 分配（**只允许在临界区之外调用**）。失败/注入 ⇒ px_alloc_fail：
//   此刻无锁在身 ⇒ longjmp 回隔离点 ⇒ HTTP 5xx、进程继续（M125 语义）。
static void* m128_alloc(size_t n, const char* site) {
    if (m128_site_hit(n, site)) {
        int o = 0;
        size_t t = px_map_bytes(n, &o);
        px_alloc_fail(n, o ? 0 : t, site);
    }
    return xmalloc(n);
}
static char* m128_strdup(const char* s, const char* site) {
    size_t n = strlen(s) + 1;
    if (m128_site_hit(n, site)) {
        int o = 0;
        size_t t = px_map_bytes(n, &o);
        px_alloc_fail(n, o ? 0 : t, site);
    }
    char* p = (char*)xmalloc(n);
    memcpy(p, s, n);
    return p;
}

// ==================== ISSUE28-B2（qg-issue 28）：slab 空页归还 OS ====================
// 现象：高频短请求场景堆"只涨不落"（40MB→380MB→1.1GB 不回吐）——对象 sweep 释放后
// 槽位回空闲链表复用，但整块 slab 的 mmap 映射从不归还 OS（无 munmap/madvise 路径）。
// 本函数在 GC sweep 结束后调用：摘除并 munmap **完全空闲**（free_count==slot_count）
// 的非头 slab（每 class 保留当前头 slab 作分配缓冲，防"刚释放又立即重新 mmap"抖动），
// 反查数组 g_slab_ranges 同步移除。调用前提：stop-the-world / 单线程（调用方持
// g_gc_mu 且其他线程已暂停/无并发分配）；本函数内部取 g_slab_mu 防残余并发。
static void slab_reclaim_empty(void) {
    pthread_mutex_lock(&g_slab_mu);
    // 以 g_slab_ranges（全量登记）为准遍历：任何完全空闲 slab（含游离/链上遗漏）
    // 一律移除登记 + munmap；每 class 保留当前头 slab 作分配缓冲防抖动。
    //
    // M107-S3（关键）：**不再逐 slab 走链摘除**。原实现每个待归还 slab 都从
    //   g_slab_heads[ci] 单链头开始找自己（O(链长)），合计 O(归还数 × 链长) ——
    //   真负载实测该内层循环占采样 **77%**（top PC 落在本函数 +0x90 的链式搜索）。
    //   改为两遍：①过滤 + 归还（不算链）②按保留集合**整链重建**（O(保留数 + class 数)）。
    //   链序语义不变（分配只用链首 + S3b hint），头 slab 仍置链首。
    size_t w = 0;
    for (size_t i = 0; i < g_slab_range_count; i++) {
        Slab* s = g_slab_ranges[i];
        if (s->free_count != s->slot_count) { s->empty_streak = 0; g_slab_ranges[w++] = s; continue; }  // 非空保留
        int ci = s->class_idx;
        if (ci < 0 || ci >= SLAB_CLASS_COUNT || slab_classes[ci] != s->class_size) {
            ci = -1;
            for (int k = 0; k < SLAB_CLASS_COUNT; k++) if (slab_classes[k] == s->class_size) { ci = k; break; }
        }
        if (ci < 0) { s->empty_streak = 0; g_slab_ranges[w++] = s; continue; }   // 防御：无法归类则不回收
        s->class_idx = ci;
        if (s == g_slab_heads[ci]) { g_slab_ranges[w++] = s; continue; }  // 头 slab 缓冲保留
        // M107-S3c：空 slab 滞留水位——连续 SLAB_FREE_STREAK 轮仍空才归还（防 mmap/munmap 抖动）
        if (++s->empty_streak < SLAB_FREE_STREAK) { g_slab_ranges[w++] = s; continue; }
        // S3b：该 slab 若在复用链上，摘除交给下方整链重建（O(N) 一次完成，不做逐 slab 走链）
        // M107-S3a：位图已内联在映射尾部 ⇒ 一次 munmap 覆盖 [Slab 头 + 槽区 + 位图]
        munmap(s, s->map_bytes);
    }
    g_slab_range_count = w;
    // ---- 第 2 遍：整链重建（一次 O(N)，取代逐 slab 走链）----
    //   重建不变量：链上只保留「有空槽（free_count > 0）」的 slab（S3b 复用语义）；
    //   原链首（分配缓冲）仍置链首，其余按登记序头插（顺序无语义）。
    Slab* keep_head[SLAB_CLASS_COUNT];
    for (int k = 0; k < SLAB_CLASS_COUNT; k++) { keep_head[k] = g_slab_heads[k]; g_slab_heads[k] = NULL; }
    for (size_t i = 0; i < w; i++) {
        Slab* s = g_slab_ranges[i];
        int ci = s->class_idx;
        if (ci < 0 || ci >= SLAB_CLASS_COUNT || s->free_count == 0) { s->on_list = 0; s->next = NULL; continue; }
        if (keep_head[ci] == s) continue;                 // 头 slab 稍后统一置顶
        s->next = g_slab_heads[ci];
        g_slab_heads[ci] = s;
        s->on_list = 1;
    }
    for (int k = 0; k < SLAB_CLASS_COUNT; k++) {
        Slab* s = keep_head[k];
        if (!s) continue;
        if (s->free_count == 0) { s->on_list = 0; s->next = NULL; continue; }   // 防御：满 slab 不入链
        s->next = g_slab_heads[k];
        g_slab_heads[k] = s;
        s->on_list = 1;
    }
    memset(g_xfree_hint, 0, sizeof(g_xfree_hint));   // 归还 slab 后清 hint（同锁，防悬垂）
    g_xfree_hint_head = 0;
    pthread_mutex_unlock(&g_slab_mu);
}

// ==================== 全局表（定义前移：GC 标记根集合使用） ====================

#define GLOBAL_CAP 4096
static char* g_keys[GLOBAL_CAP];
static LXValue g_vals[GLOBAL_CAP];
static int g_len = 0;
// M55/P0 修复（GitHub issue#2）：全局符号表锁。px_serve 等并发场景多线程
// 同时读写 g_keys/g_vals/g_len，且与 GC 根扫描（g_vals 遍历，见 px_gc_collect）
// 不互斥 → g_len 非原子++、同槽覆盖、GC 扫到半写对象 → SEGV/内存损坏/优雅关闭
// core。原为互斥锁（全访问串行化 = GIL 效应，qg-issue 28 实测 500 并发 p50=5.2s）；
// ISSUE28-B3（qg-issue 28）改为**读写锁**：读路径（px_get_global/px_global_native/
// struct 方法查找）读锁并发，写路径（px_set_global/GC 根扫描）写锁独占——并发 handler
// 读全局表不再互相串行。持锁临界区一律先 gc_block_stop（协议同 g_gc_mu）：持锁线程
// 不被 GC 暂停 → GC stop-the-world 取写锁时不会被"已暂停的持锁线程"卡死（无死锁）；
// 读锁/写锁互斥语义与原子性等价旧互斥锁（同刻仅一写者；读读并发只读不改，安全）；
// 锁序固定 g_gc_mu → g_globals_mu，无反向获取。
static pthread_rwlock_t g_globals_mu = PTHREAD_RWLOCK_INITIALIZER;

// M105-S2：全局表名解析 O(1) 哈希索引。
// 依据（M105-S1 量化，见 docs/M105_PLAN.md）：真实负载 compiler_vm bc yaml.px 中
//   95.0% 的 strcmp 调用来自本表线性扫描，平均每次 GETG 探测 331.6 项（g_len≈537，
//   即平均扫过全表 62%）——px_get_global 均值 2.08µs，而 rdlock 仅 12ns。
// 设计与约束：
//   - 与 g_keys/g_vals 严格同步：唯一新增槽位点 = px_set_global 的 g_len++ 处落位；
//   - 容量 = 2×GLOBAL_CAP（负载因子 ≤0.5），开放寻址线性探测，按 64 位名哈希比对，
//     仅哈希命中时做一次 strcmp 兜底（保正确性下限）；
//   - **锁语义不变**：读锁下只读索引、写锁下只写索引（与 g_keys/g_vals 同锁保护）；
//   - **GC 根面不变**：根扫描仍线性遍历 g_vals，索引不参与 GC。
#define GHASH_CAP (GLOBAL_CAP * 2)
static uint32_t g_hidx[GHASH_CAP];   // 槽位号 + 1；0 表示空
static uint64_t g_hval[GHASH_CAP];   // 对应探测位的 64 位名哈希
static uint64_t g_name_hash(const char* s) {            // FNV-1a 64 位
    uint64_t h = 1469598103934665603ULL;
    while (*s) { h ^= (unsigned char)*s++; h *= 1099511628211ULL; }
    return h;
}
// 查找：返回 g_keys/g_vals 槽位号；-1 = 未定义。调用方须持 g_globals_mu（读或写）。
static int g_hash_find(const char* name, uint64_t hv) {
    uint32_t h = (uint32_t)hv & (GHASH_CAP - 1);
    for (;;) {
        uint32_t e = g_hidx[h];
        if (e == 0) return -1;                          // 空位 = 探测链终止
        if (g_hval[h] == hv && strcmp(g_keys[e - 1], name) == 0) return (int)(e - 1);
        h = (h + 1) & (GHASH_CAP - 1);
    }
}
// 落位：仅在 px_set_global 新增槽位时调用（持写锁），此后键指针恒稳定（永不回收）。
static void g_hash_put(uint64_t hv, int slot) {
    uint32_t h = (uint32_t)hv & (GHASH_CAP - 1);
    while (g_hidx[h] != 0) h = (h + 1) & (GHASH_CAP - 1);
    g_hidx[h] = (uint32_t)slot + 1;
    g_hval[h] = hv;
}

// ==================== GC（M8：保守标记-清除，值对象自动释放） ====================
// 所有 LXObject 注册到全局对象表 g_objs。分配累计超阈值 → gc_collect()：
//   1) mark：根 = 全局表 + 暂存根（刚创建对象）+ 当前线程栈保守扫描
//   2) sweep：未标记对象释放子分配 + 本体，从表移除
// 并发保护（M11）：spawn 线程活跃时 stop-the-world——GC 主线程向所有活跃线程
// 发送 SIG_GC_STOP 实时信号，线程在信号处理器中保存上下文（寄存器）+ 暂存根后
// 自旋等待 g_gc_resume；GC 扫描全局表 + 所有线程栈/寄存器后清扫，再恢复线程。
// 保守扫描只认对象本体地址（8 字节对齐），误标仅推迟回收（安全），漏标由暂存根
// + 全局表 + 栈扫描综合兜底。

// M152（第 34 轮 · 缺陷 143）：对象数触发阈值 **10 万 → 100 万**。
//   实测（同为 VM 轨编译器整图发射 `--emit-c`，本机 8 核）：
//     · stmt 语料 4000 语句：10 万 ⇒ **10.45s / 97MB**（GC 339 次、每次 10-33ms，
//       占 70% 墙钟；其中后 200+ 次「回收 0 个」，纯白跑）
//       100 万 ⇒ **2.03s / 292MB**（5.1× 提速，内存仍 < 旧版 450MB）
//     · func 语料 1000 函数：10 万 ⇒ 8.58s/133MB ；100 万 ⇒ **3.39s/306MB**（2.5×）
//   10 万对象 ≈ 8MB 堆 —— 对 16GB 机器是**荒谬地小**的阈值：GC 次数由
//   「分配量 / 阈值」决定，而每次 GC 的代价是 O(全堆) ⇒ 阈值越小、白跑越多。
//   内存下界由**字节阈值**（GC_TRIGGER_BYTES_DEFAULT）兜底，故对象阈值可以放大。
//   （`PX_GC_THRESHOLD` 仍可覆盖；两者一起构成「时间 ↔ 内存」的显式旋钮。）
#define GC_THRESHOLD_DEFAULT 1000000
// M152（第 34 轮 · 缺陷 142）：**字节**触发阈值 —— 旧版 g_gc_trigger_bytes 是死代码
//   （全仓无任何赋值点、无环境变量）⇒ 回收只由**对象数**决定，而「少量大对象、海量
//   分配字节」的相位（字符串逐段拼接 / 逐块渲染）**永远打不到对象数阈值**：
//   GC 不跑、RSS 无界增长。实测（第 34 轮）：VM 轨编译器整图渲染 16000 语句的整图
//   ⇒ 114s / **峰值 7.2GB**（对比 2000 语句 3.0s/125MB），token-cache 整图 3:37 达
//   8.1GB 仍未完成 —— 这正是 2026-09-19 全机 OOM（QQ 网关被 systemd 停掉→闪断）
//   的枪。**对象数阈值管不住字节**，故补字节阈值：
//     · 缺省 512MiB（PX_GC_TRIGGER_BYTES 覆盖；<=0 显式关闭）
//     · 单线程 CLI/编译轨：到量即内联回收（无安全点问题）
//     · 多线程服务轨：仍走既有「延迟到安全点」路径（改动只影响**何时**触发）
#define GC_TRIGGER_BYTES_DEFAULT (512LL * 1024 * 1024)
#define GC_HASH_MIN_CAP 4096          // 对象地址哈希集合初始容量

static pthread_mutex_t g_gc_mu = PTHREAD_MUTEX_INITIALIZER;
static LXObject** g_objs = NULL;
static int g_obj_count = 0;
static int g_obj_cap = 0;
static long long g_alloc_bytes = 0;
static long long g_gc_trigger_bytes = 0;  // 0 = 未启用字节阈值
static int g_gc_threshold = GC_THRESHOLD_DEFAULT;
// ISSUE28-B1（qg-issue 28）：GC 延迟到安全点（服务模式）。多线程服务场景把"对象越阈值
// 立即内联全量 STW"从请求热路径挪到**请求间安全点**（worker 空闲/池循环顶）执行，避免
// 300-500ms 周期尖刺打中在途请求（m88b 实测单发 p95=331ms/max=520ms）。g_gc_pending
// 置位后在安全点 px_gc_poll() 回收；单线程 CLI/解释模式无安全点，保持原内联（零回归）。
#define GC_HARD_CAP_FACTOR 4        // 延迟硬上限：对象数 ≥ 阈值×4 仍强制内联（防失控，保内存有界）
static volatile int g_gc_pending = 0;
static int g_gc_force_inline = 0;   // 调试/对拍：PX_GC_INLINE=1 强制请求热路径内联（还原 B1 前行为，验证 A/B）
static int g_gc_env_inited = 0;
static int g_gc_debug = 0;
// 分配统计（可观测性）：`PX_GC_ALLOC_STATS=1` ⇒ 进程退出时按类型打印分配计数。
//   为什么要有：本轮（缺陷 145）的判据本身就是「分配率」，没有分配率数字就只能靠时间
//   （受机器负载影响、不可复现）。计数完全确定（同一源码 + 同一实现 ⇒ 同一数字），
//   故可做**硬阈值门**。默认关闭 ⇒ 只多一次可预测的分支。
static int g_alloc_stats = 0;
// M170（缺陷 187/188）：每次分配即 GC（PX_GC_STRESS=1；native 桥漏登记 PX_KEEP 的筛子）
static int g_gc_stress = 0;
// M170（缺陷 189）：**注册期禁回收**开关。`px_register_builtins` 逐条
//   `px_set_global(name, px_native(name, fn))` —— 每条的 name 串与 native 对象都是
//   两次分配，而这里**没有**（也不该逐条）登记根 ⇒ 阈值低到会在注册期触发 GC 时，
//   刚建的 native 对象会被误回收，而它已被塞进全局槽（= 悬挂引用）⇒ 之后每轮 GC 都去
//   标记已释放对象 ⇒ 堆结构（slab 空闲链）被写坏 ⇒ SIGSEGV。
//   修法 = 建表期间**冻结回收**（对齐 V8「初始化期不允许堆分配回收」的做法）：注册是
//   一次性、内存有界的启动动作，冻结的代价只是启动期堆稍大。
static int g_gc_frozen = 0;
static long long g_a_by_type[PX_TYPE_MAX];
static long long g_a_bytes;
static long long g_a_total;
static void px_alloc_stats_dump(void);
// M170（缺陷 187）：根登记栈峰值打印（PX_GC_DEBUG=1 退出时；实现见 px_root_keep 之后）
static void px_root_peak_dump(void);
// M170（缺陷 187/188）：根登记栈深度记录/还原 + 峰值查询
int px_root_depth(int* marks_out);
void px_root_restore(int roots_depth, int marks_depth);
static __thread int t_iso_roots;
void px_root_iso_mark(void);
void px_root_restore_iso(void);



static int g_active_threads = 0;   // spawn 活跃线程数（>0 时进入并发 GC 路径）

// M11 并发 GC：线程注册表 + 暂停协议
// M88-S1（qg-issue 27）：GC 线程槽动态化。原固定 64 槽（MAX_SPAWN_THREADS）是服务端
// 高并发崩溃根因之一（http_serve/sse_serve 每连接 spawn → 64 并发槽满 → px_error → exit）。
// 现改为按槽上限（PX_MAX_THREADS，默认 1024，可配 [64,4096]）在 gc_init_env 一次性分配动态表：
//   g_threads 指针 + g_thread_cap 容量（= 配置上限，一次到位，无 realloc 指针移动）。
// 并发安全：首次分配在 gc_init_env（各并发入口均先调用，持 g_gc_mu 或单线程阶段）；
//   此后 g_threads/g_thread_cap 只读恒定 → 信号处理器 / GC 遍历读到的始终是同一稳定表，
//   无 realloc/use-after-free 竞态面（比按需 ×2 扩容更稳，代价是默认 1024 槽 ≈1MB 常驻）。
#define SIG_GC_STOP (SIGRTMIN + 2)   // 实时信号：暂停线程（可排队，不与用户信号冲突）
typedef struct {
    pthread_t tid;
    int in_use;          // 槽位占用
    int paused;          // 该线程已暂停（在信号处理器中等待恢复）
    int is_main;         // 主线程槽位（退出时不注销）
    int epoch;           // 暂停所属 GC 轮次（用于区分"本轮真暂停"与"堆积信号短暂暂停"）
    ucontext_t uc;       // 暂停时保存的上下文（寄存器）
    LXObject* tmp_root;  // 暂停时该线程的暂存根（__thread 跨线程不可读，由处理器保存）
    void* vm_state;      // S3-D-1：暂停时该线程的 VM 状态指针（PxVmState*，TLS 跨线程
                         //   不可读，由运行在目标线程上的暂停处理器保存；executor 依此
                         //   遍历其堆上帧槽做精确根标记）
    LXValue* roots;      // M92：暂停时该线程的 TLS 登记根栈指针/长度（precise 模式根面；
    int      root_n;     //   __thread 跨线程不可读，由处理器保存；executor 依此精确标记）
} GCThreadInfo;
#define MAX_SPAWN_THREADS 64   // 历史宏：默认初始容量（保留供旧引用/文档对照；实际容量读 g_thread_cap）
#define PX_DEFAULT_THREAD_CAP 64     // 默认初始容量（= 历史 MAX_SPAWN_THREADS 语义）
#define PX_DEFAULT_THREAD_MAX 1024   // 默认槽上限（env PX_MAX_THREADS 未设时）
#define PX_HARD_THREAD_LIMIT 4096    // 槽硬上限（内存 / GC stop-the-world 停顿权衡；spec 环境变量表明示）
static GCThreadInfo* g_threads = NULL;              // 动态线程表（gc_init_env 分配，此后指针恒定）
static int g_thread_cap = 0;                        // 表容量（= 配置上限，gc_init_env 置位后不变）
static int g_thread_max = PX_DEFAULT_THREAD_MAX;    // 槽上限（env PX_MAX_THREADS 夹取 [64,4096]）
static volatile int g_paused_count = 0;  // 已暂停线程数（调试用；控制流以 paused 标志 + epoch 为准）
                                         // M124：volatile —— 兼作 executor 的 futex 等待字
static volatile int g_gc_resume = 0;// （保留字段，控制流以 epoch 为准）
static volatile int g_gc_epoch = 0; // GC 轮次号：每轮开始/结束各 ++，handler 等待其变化
static volatile int g_gc_stop_in_progress = 0; // 本轮 GC 是否在进行中（handler 用其区分过期堆积信号）
static volatile pthread_t g_gc_executor = 0;   // 当前 GC 主线程（执行 px_gc_collect 的线程）；handler 用它自检防自打断
static int g_gc_runs = 0;
static int g_gc_freed = 0;
static int g_gc_skips = 0;
static long long g_gc_marked = 0;   // 调试：最近一轮 GC 标记数
static __thread LXObject* g_tmp_root = NULL;  // 暂存根：保护刚创建对象（构造函数内触发 GC）

// ---------- M124（qg-issue 80）：STW 屏障「阻塞等待」原语 ----------
// 病灶：gc_stop_handler / gc_stop_world 三处 sched_yield() 自旋 —— 每个被暂停线程
//   在**整段 GC 期间**空转，executor 等恢复时同样空转 ⇒ CPU 税 = 参与暂停的线程数 ×
//   GC 时长。生产实测：一个僵死协程把 GC 顶到 3.7 次/秒 → 稳定烧 ~2 核（sched_yield
//   占 perf 采样 ~48%）；本机压测 8 协程 = 186k sched_yield/s、5.1 核。
// 修法：改 futex 阻塞等待。等待字两个（都是 int，4 字节对齐）：
//   · g_gc_epoch      —— 被暂停线程等「本轮结束」（executor 每轮开始/结束各 ++）
//   · g_paused_count  —— executor 等「暂停/恢复进度」（handler 上报暂停、退出时递减）
// handler 内用**裸 syscall**（async-signal-safe；不可用 pthread_cond 等）；executor 侧
// 显式 FUTEX_WAKE。所有等待都带超时兜底 ⇒ 即使漏唤醒也只是迟到超时时长，绝不卡死。
// 非 Linux（mingw 交叉等）无 SYS_futex：退化为 nanosleep 轮询，语义不变。
#if defined(__linux__) && defined(SYS_futex)
#define PX_HAVE_FUTEX 1
static inline int px_futex_wait(volatile int* addr, int expect, long timeout_us) {
    struct timespec ts;
    struct timespec* tsp = NULL;
    if (timeout_us >= 0) {
        ts.tv_sec = timeout_us / 1000000;
        ts.tv_nsec = (timeout_us % 1000000) * 1000;
        tsp = &ts;
    }
    return (int)syscall(SYS_futex, (int*)addr, FUTEX_WAIT_PRIVATE, expect, tsp, NULL, 0);
}
static inline void px_futex_wake(volatile int* addr) {
    (void)syscall(SYS_futex, (int*)addr, FUTEX_WAKE_PRIVATE, 0x7fffffff, NULL, NULL, 0);
}
#else
#define PX_HAVE_FUTEX 0
static inline int px_futex_wait(volatile int* addr, int expect, long timeout_us) {
    (void)addr; (void)expect;
    if (timeout_us > 0) {
        struct timespec ts = { timeout_us / 1000000, (timeout_us % 1000000) * 1000 };
        nanosleep(&ts, NULL);
    }
    return 0;
}
static inline void px_futex_wake(volatile int* addr) { (void)addr; }
#endif

// ---- M92 精确 GC：precise/conservative 双模式 + native 桥 TLS 登记根栈 ----
// precise（VM 轨产物）：退役整栈保守扫描（gc_scan_stack/registers/thread_stack 跳过），
//   根 = 全局槽 + VM 帧槽（S3-D-1 跨线程已有）+ TLS 登记根栈 + 暂存根。C 栈上（native
//   桥 bi_*/px_* helper）跨 GC 点的局部 LXValue 引用须经 PX_KEEP 登记，否则误回收。
// conservative（默认）：保持旧行为（逃生舱 fn_* C 局部 + 所有桥局部靠保守扫栈兜底）。
static int g_gc_precise = 0;   // M92：1=precise；0=conservative（默认，零行为变化）
static __thread LXValue* g_px_roots = NULL;       // 登记根栈（本线程）
static __thread int g_px_roots_n = 0;
static __thread int g_px_roots_cap = 0;
static __thread int* g_px_root_marks = NULL;      // 作用域帧标记栈（px_root_push/pop）
static __thread int g_px_root_marks_n = 0;
static __thread int g_px_root_marks_cap = 0;
