// 开放寻址哈希集合（对象地址快速查询，供保守栈扫描）
typedef struct {
    uintptr_t* slots;
    size_t cap;
    size_t count;
} GCHash;

static void gc_hash_init(GCHash* h, size_t cap) {
    size_t c = GC_HASH_MIN_CAP;
    while (c < cap) c <<= 1;
    h->slots = xcalloc(c, sizeof(uintptr_t));
    h->cap = c;
    h->count = 0;
}

static void gc_hash_insert(GCHash* h, uintptr_t addr) {
    if ((h->count + 1) * 10 >= h->cap * 7) {  // load factor 0.7 扩容
        size_t ncap = h->cap << 1;
        uintptr_t* ns = xcalloc(ncap, sizeof(uintptr_t));
        for (size_t i = 0; i < h->cap; i++) {
            uintptr_t a = h->slots[i];
            if (!a) continue;
            size_t j = (size_t)(a ^ (a >> 16)) & (ncap - 1);
            while (ns[j]) j = (j + 1) & (ncap - 1);
            ns[j] = a;
        }
        xfree(h->slots);
        h->slots = ns;
        h->cap = ncap;
    }
    size_t j = (size_t)(addr ^ (addr >> 16)) & (h->cap - 1);
    for (size_t probes = 0; probes <= h->cap; probes++) {
        if (!h->slots[j]) { h->slots[j] = addr; h->count++; return; }
        j = (j + 1) & (h->cap - 1);
    }
    // 防御：表满（理论不可达），丢弃该插入
}

static bool gc_hash_has(GCHash* h, uintptr_t addr) {
    size_t j = (size_t)(addr ^ (addr >> 16)) & (h->cap - 1);
    // 防御：探测上限 cap+1 次，防止表损坏/满载时线性探测死循环导致 GC 卡死
    for (size_t probes = 0; probes <= h->cap; probes++) {
        uintptr_t s = h->slots[j];
        if (!s) return false;
        if (s == addr) return true;
        j = (j + 1) & (h->cap - 1);
    }
    return false;
}

static void gc_hash_free(GCHash* h) { xfree(h->slots); h->slots = NULL; }

static void gc_install_handler(void);
static void gc_ensure_main_registered(void);
static void gc_init_env(void) {
    const char* d = getenv("PX_GC_DEBUG");
    if (d && d[0] == '1') g_gc_debug = 1;
    const char* t = getenv("PX_GC_THRESHOLD");
    if (t && atoi(t) > 0) g_gc_threshold = atoi(t);
    // M152（缺陷 142）：字节阈值 —— 未设环境变量时启用缺省（内存有界兜底）
    const char* tb = getenv("PX_GC_TRIGGER_BYTES");
    if (tb) {
        long long v = atoll(tb);
        g_gc_trigger_bytes = (v > 0) ? v : 0;   // <=0 ⇒ 显式关闭（旧行为）
    } else {
        g_gc_trigger_bytes = GC_TRIGGER_BYTES_DEFAULT;
    }
    const char* inl = getenv("PX_GC_INLINE");
    if (inl && inl[0] == '1') g_gc_force_inline = 1;
    // M153：分配统计（见 g_alloc_stats 注释）
    const char* as = getenv("PX_GC_ALLOC_STATS");
    if (as && as[0] == '1') { g_alloc_stats = 1; atexit(px_alloc_stats_dump); }
    // M92：PX_GC_PRECISE=1 强制 precise 模式（debug/回归驱动；产物插桩正式生效前用）。
    // ⚠️ 仅限 VM 轨产物——C 轨逃生舱产物 + precise = fn_* C 局部失去保守扫栈根 → 误回收。
    const char* pr = getenv("PX_GC_PRECISE");
    if (pr && pr[0] == '1') g_gc_precise = 1;
    // M170（缺陷 187）：PX_GC_STRESS=1 —— **每次分配都触发 GC**（debug/门专用）。
    //   动机：native 桥（bi_*）里跨 GC 点的局部 LXValue 漏登记 PX_KEEP 时，
    //   默认阈值下要等「恰好在那一步越阈值」才发作 ⇒ 靠运气发现（清歌报的 sqlite_query
    //   即此类，默认要跑到 1.6 万次循环才炸）。stress 把「偶发」变成「必现」：
    //   任何漏登记的桥在第一轮分配就露出来 ⇒ 可被门/语料批量筛出。
    //   代价：每次分配一次全量 GC ⇒ 仅限小语料（勿用于压测/基准）。
    const char* st = getenv("PX_GC_STRESS");
    if (st && st[0] == '1') g_gc_stress = 1;
    if (g_gc_debug) atexit(px_root_peak_dump);   // M170：退出打印根登记栈峰值
    // M88-S1：PX_MAX_THREADS 可配槽上限（夹取 [64, 4096]）；线程表一次性按上限分配。
    // 此后 g_threads/g_thread_cap 恒定，无扩容/指针移动（并发安全见 §594 注释）。
    const char* mt = getenv("PX_MAX_THREADS");
    if (mt && atoi(mt) >= PX_DEFAULT_THREAD_CAP && atoi(mt) <= PX_HARD_THREAD_LIMIT)
        g_thread_max = atoi(mt);
    if (!g_threads) {
        g_threads = (GCThreadInfo*)xcalloc((size_t)g_thread_max, sizeof(GCThreadInfo));
        g_thread_cap = g_thread_max;
    }
    gc_install_handler();
    gc_ensure_main_registered();
    g_gc_env_inited = 1;
}

// ==================== ISSUE28-B1：安全点回收 + GC 耗时观测 ====================
static long long gc_mono_ms(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

// 请求间/空闲安全点回收：服务模式把 GC 延迟到此处执行（worker 处理完一请求空闲时、
// 连接池循环顶），使全量 STW 不落在在途请求处理中。持 g_gc_mu 判定+清 pending，
// 防多 worker 同时进入（thundering herd）→ 同刻仅一个触发 px_gc_collect。
void px_gc_poll(void) {
    if (!g_gc_pending) return;
    pthread_mutex_lock(&g_gc_mu);
    int run = g_gc_pending;
    g_gc_pending = 0;
    pthread_mutex_unlock(&g_gc_mu);
    if (run) px_gc_collect();
}

static void gc_debug(const char* fmt, ...) {
    if (!g_gc_debug) return;
    // 注意：必须用 write(2) 直写 fd，不能经 stdio（fprintf）——
    // GC 主线程持 g_gc_mu 时若 fprintf，而某线程在 printf 中被 GC 信号挂起
    // （持有 stdio 内部锁），会死锁。write 是原子 syscall，无 stdio 锁。
    char buf[512];
    int n = snprintf(buf, sizeof(buf), "[px-gc] ");
    va_list ap;
    va_start(ap, fmt);
    n += vsnprintf(buf + n, sizeof(buf) - n, fmt, ap);
    va_end(ap);
    if (n < 0) n = 0;
    if (n > (int)sizeof(buf) - 2) n = (int)sizeof(buf) - 2;
    buf[n++] = '\n';
    (void)write(2, buf, (size_t)n);
}

// 「是否为**堆对象**」单一事实源（GC 根标记 / 帧槽 / 全局表 / 容器递归 全靠它）。
//
// ⚠️ M135（qg-issue 87 缺陷 86 根治）：原实现是 switch 白名单，**漏了 PX_MUTEX /
//    PX_RWLOCK / PX_GEN** ⇒ 这三种值放在 list/dict/struct/tuple/result/gen/chan 里、
//    或作为全局/帧槽的**直接**值时**不被标记**，其对象被 sweep 回收 ⇒ 悬垂。
//    实测症状（token-cache 生产链路）：第 6 个「走审批判定」的请求起**永久挂死**
//    （pthread_mutex_lock 阻塞在已回收内存的 __lock 上，无持有者、无唤醒源）；
//    最小复现：`var g = [mutex()]` + 触发 GC + `g[0].lock()` 即 abort。
//
//    现改为「按 LXType **逐项列全**的位置表」+ 编译期尺寸断言：
//    新增类型必须在表里显式表态，否则 `_Static_assert` 直接编译失败 ——
//    从根上消灭这一类「白名单静默漏项」（同族历史缺陷 43：i_eq 白名单漏 bytes）。
static const bool g_type_is_obj[PX_TYPE_MAX] = {
    /* PX_NULL   */ false,
    /* PX_BOOL   */ false,
    /* PX_INT    */ false,
    /* PX_FLOAT  */ false,
    /* PX_STR    */ true,
    /* PX_BYTES  */ true,
    /* PX_LIST   */ true,
    /* PX_DICT   */ true,
    /* PX_FUNC   */ true,
    /* PX_NATIVE */ true,
    /* PX_STRUCT */ true,
    /* PX_ENUM   */ true,
    /* PX_TUPLE  */ true,
    /* PX_CHAN   */ true,
    /* PX_MUTEX  */ true,
    /* PX_RWLOCK */ true,
    /* PX_GEN    */ true,
    /* PX_RESULT */ true,
    /* PX_UNINIT */ false,   // M181（缺陷 193）：哨兵不是堆对象 ⇒ GC 不追
};
_Static_assert(sizeof(g_type_is_obj) / sizeof(g_type_is_obj[0]) == PX_TYPE_MAX,
               "LXType 新增成员未在 g_type_is_obj 表态（缺陷 86 的复发防线）");

static bool px_value_is_obj(LXValue v) {
    int t = (int)v.type;
    if (t < 0 || t >= PX_TYPE_MAX) return false;
    return g_type_is_obj[t];
}

// 释放对象内部子分配 + 对象本体（sweep 阶段调用）
static void px_obj_free(LXObject* o) {
    switch (o->type) {
        case PX_STR: xfree(o->as.str.rune_offs); break;   // M106-S2：连缓存偏移表一起回收
        // M107-S3d：data 已内联在对象分配块内，随下方 xfree(o) 一并释放（不再单独 xfree）
        // M57-S2：mmap bytes（is_mmap=1）的 data 是 mmap 映射区 → munmap；普通 bytes → xfree
        case PX_BYTES:
            if (o->is_mmap) {
                if (o->as.str.data && o->as.str.len > 0)
                    munmap(o->as.str.data, (size_t)o->as.str.len);
            } else {
                xfree(o->as.str.data);
            }
            xfree(o->as.str.rune_offs);   // M106-S2：bytes 恒不建表（NULL），防御性释放
            break;
        case PX_LIST: xfree(o->as.list.items); break;
        case PX_DICT:
            for (int i = 0; i < o->as.dict.len; i++) xfree(o->as.dict.keys[i]);
            xfree(o->as.dict.keys);
            xfree(o->as.dict.vals);
            break;
        case PX_FUNC: xfree(o->as.func.name); break;   // env 为 LXValue，随对象一并丢弃（无内部分配）
        case PX_NATIVE: xfree(o->as.native.name); break;
        case PX_STRUCT:
            xfree(o->as.struct_inst.type_name);
            for (int i = 0; i < o->as.struct_inst.nfields; i++) xfree(o->as.struct_inst.fnames[i]);
            xfree(o->as.struct_inst.fnames);
            xfree(o->as.struct_inst.fvals);
            break;
        case PX_ENUM:
            xfree(o->as.enum_inst.type_name);
            xfree(o->as.enum_inst.variant);
            break;
        case PX_TUPLE: xfree(o->as.tuple.items); break;
        case PX_RESULT: break;  // value 内嵌 LXValue（非指针），子对象由 GC 管理
        case PX_CHAN:
            xfree(o->as.chan.buf);
            pthread_mutex_destroy(&o->as.chan.mu);
            pthread_cond_destroy(&o->as.chan.cv_send);
            pthread_cond_destroy(&o->as.chan.cv_recv);
            break;
        case PX_MUTEX:
            if (getenv("PX_DBG_GC_MUTEX"))
                fprintf(stderr, "[GC-free-mutex] obj=%p locked=%d\n",
                        (void*)o, o->as.mutex.locked);
            pthread_mutex_destroy(&o->as.mutex.mu);
            pthread_cond_destroy(&o->as.mutex.cv);
            break;
        case PX_RWLOCK:
            pthread_mutex_destroy(&o->as.rwlock.mu);
            pthread_cond_destroy(&o->as.rwlock.cv);
            break;
        default: break;
    }
    xfree(o);
}

// 标记单个对象及其可达子对象（显式栈 DFS，避免深链递归栈溢出）
// M11：每个出栈对象先用 gc_hash_has 校验是否在对象表（set）——并发数据竞争
// 可能使对象图出现损坏指针（如 list.items 指向已释放/半构造区域），
// 校验后跳过垃圾指针，避免 DFS 无限遍历损坏对象图导致 GC 卡死。
static void gc_mark_obj(GCHash* set, LXObject* o) {
    if (!o) return;
    LXObject** stack = xmalloc(sizeof(LXObject*) * 1024);
    int cap = 1024, sp = 0;
#define PUSH_OBJ(x) do { if (sp >= cap) { cap *= 2; stack = xrealloc(stack, sizeof(LXObject*) * cap); } stack[sp++] = (x); } while (0)
    PUSH_OBJ(o);
    while (sp > 0) {
        LXObject* cur = stack[--sp];
        if (!gc_hash_has(set, (uintptr_t)cur)) continue;   // 垃圾指针 → 跳过
        if (cur->gc_mark) continue;
        cur->gc_mark = 1;
        g_gc_marked++;
        switch (cur->type) {
            case PX_LIST: {
                LXValue* items = cur->as.list.items;
                for (int i = 0; i < cur->as.list.len; i++) {
                    if (px_value_is_obj(items[i]) && items[i].as.obj) PUSH_OBJ(items[i].as.obj);
                }
                break;
            }
            case PX_DICT: {
                LXValue* vals = cur->as.dict.vals;
                for (int i = 0; i < cur->as.dict.len; i++) {
                    if (px_value_is_obj(vals[i]) && vals[i].as.obj) PUSH_OBJ(vals[i].as.obj);
                }
                break;
            }
            case PX_STRUCT: {
                LXValue* fvals = cur->as.struct_inst.fvals;
                for (int i = 0; i < cur->as.struct_inst.nfields; i++) {
                    if (px_value_is_obj(fvals[i]) && fvals[i].as.obj) PUSH_OBJ(fvals[i].as.obj);
                }
                break;
            }
            case PX_TUPLE: {
                LXValue* items = cur->as.tuple.items;
                for (int i = 0; i < cur->as.tuple.len; i++) {
                    if (px_value_is_obj(items[i]) && items[i].as.obj) PUSH_OBJ(items[i].as.obj);
                }
                break;
            }
            case PX_RESULT: {
                // M39：Result 载荷递归标记（Ok 的 T / Err 的 E）
                if (px_value_is_obj(cur->as.result.value) && cur->as.result.value.as.obj) {
                    PUSH_OBJ(cur->as.result.value.as.obj);
                }
                break;
            }
            case PX_CHAN: {
                // M11：并发下无锁保守扫描（chan.buf 元素为单 word 原子读写，误标仅推迟回收）
                LXValue* buf = cur->as.chan.buf;
                int phys = cur->as.chan.cap > 0 ? cur->as.chan.cap : 1;
                for (int i = 0; i < phys; i++) {
                    if (px_value_is_obj(buf[i]) && buf[i].as.obj) PUSH_OBJ(buf[i].as.obj);
                }
                break;
            }
            case PX_GEN: {
                // M89-S3-D2：生成器子对象递归标记 —— gen 可持有 物化 list /
                // 惰性 seq（list/range 等迭代源）/ transform / filter 闭包。
                // 旧实现 default 分支不标 → gen 为唯一活引用时子对象被误回收
                // （惰性 gen 的 transform/filter 闭包在 gen_next 时才调用，
                //  若已被 sweep 则 use-after-free）。四值逐一检查引用类。
                LXValue* gv[4]; int gn = 0;
                gv[gn++] = &cur->as.gen.list;
                gv[gn++] = &cur->as.gen.seq;
                gv[gn++] = &cur->as.gen.transform;
                gv[gn++] = &cur->as.gen.filter;
                for (int i = 0; i < gn; i++) {
                    if (px_value_is_obj(*gv[i]) && gv[i]->as.obj) PUSH_OBJ(gv[i]->as.obj);
                }
                break;
            }
            case PX_FUNC: {
                // M129（缺陷 21）：闭包捕获环境必须参与标记 —— 否则"只被闭包引用"的
                //   cell 会被误回收，闭包调用时读到悬垂 cell（use-after-free）。
                if (px_value_is_obj(cur->as.func.env) && cur->as.func.env.as.obj)
                    PUSH_OBJ(cur->as.func.env.as.obj);
                break;
            }
            default: break;  // STR / NATIVE / ENUM / MUTEX / RWLOCK 无子对象
        }
    }
    xfree(stack);
#undef PUSH_OBJ
}

// 当前线程栈保守扫描：把栈上"看起来像对象地址"的 word 标记为根。
// 只扫描活跃帧 [当前 RSP, 栈底)——整栈（默认 8MB）逐 word 哈希查找太慢
// （每次 GC 多线程 × 百万 word），且未使用栈区无有效指针。
static void gc_scan_stack(GCHash* set) {
    pthread_attr_t attr;
    void* stackaddr = NULL;
    size_t stacksize = 0;
    if (pthread_getattr_np(pthread_self(), &attr) == 0) {
        pthread_attr_getstack(&attr, &stackaddr, &stacksize);
        pthread_attr_destroy(&attr);
    }
    if (!stackaddr || stacksize == 0) return;
    // M67-S4：架构抽象（arch.h）—— 内联汇编直接读 SP，跨 glibc/musl/arch
    uintptr_t rsp = arch_read_sp();
    uintptr_t start = rsp & ~(uintptr_t)7;
    uintptr_t end = (uintptr_t)stackaddr + stacksize;
    if (g_gc_debug) { char dbg[160]; int dn = snprintf(dbg, sizeof(dbg), "[scan-self] rsp=%lx start=%lx end=%lx range=%lu\n", rsp, start, end, (unsigned long)(end - start)); (void)write(2, dbg, (size_t)dn); }
    for (uintptr_t p = start; p + sizeof(uintptr_t) <= end; p += sizeof(uintptr_t)) {
        uintptr_t w = *(uintptr_t*)p;
        if ((w & 7) == 0 && gc_hash_has(set, w)) {
            gc_mark_obj(set, (LXObject*)w);
        }
    }
}

// 保存/恢复通用寄存器到栈：-O2 下局部指针可能仅在寄存器中，
// 保守扫描必须把寄存器也纳入根集合，否则深链/长循环内分配易误回收。
// 实现：getcontext() 把全部通用寄存器（含 caller-saved rax/rcx/rdx/rsi/rdi/r8-r11
// 与 callee-saved rbx/rbp/r12-r15）写入 ucontext_t；该结构位于本函数栈帧，
// 被 gc_scan_stack 保守扫描覆盖。
// （ucontext.h 已在文件头部 include 区统一引入）

// ==================== M11 并发 GC：线程暂停协议 ====================
// 设计：GC 需要 stop-the-world 时，向所有已注册活跃线程发送 SIG_GC_STOP 实时信号。
// 线程在信号处理器中（async-signal-safe，仅内存读写 + 裸 futex syscall）：
//   保存 ucontext（寄存器）+ 本线程暂存根 → 计数 paused → 自旋等待 g_gc_resume → 恢复。
// GC 主线程（触发 GC 的线程）不暂停自己，扫描：全局表 + 自己栈/寄存器 + 所有暂停
// 线程的寄存器/栈/暂存根，然后设置 g_gc_resume=1 唤醒全部线程。

// 信号处理器：暂停当前线程直到 GC 完成
static void gc_stop_handler(int sig, siginfo_t* si, void* ctx) {
    (void)sig; (void)si;
    // M105-S3：软屏蔽临界区 → 延迟暂停。临界区不被打断（不保存 ucontext / 不上报 paused），
    // 交 executor 的重发循环稍后重试；临界区退出（g_gc_crit=0）后下一次重发即正常暂停。
    if (g_gc_crit) { __sync_fetch_and_add(&g_gc_deferred, 1); return; }
    pthread_t me = pthread_self();
    // M11 修复⑤：若我是当前 GC 执行者（正在跑 px_gc_collect），忽略暂停信号——
    // 否则延迟信号在本轮 GC 执行中投递，handler 自旋等 epoch，而 epoch 只有
    // 本线程自己能推进 → 死锁（依赖 5 秒兜底才恢复，每轮 GC 卡 5 秒）。
    if (g_gc_executor && pthread_equal(g_gc_executor, me)) return;
    if (!g_threads) return;  // 表尚未分配（理论不会：信号仅 GC 进行中发出，GC 前必已 init）
    GCThreadInfo* ti = NULL;
    for (int i = 0; i < g_thread_cap; i++) {
        if (g_threads[i].in_use && pthread_equal(g_threads[i].tid, me)) { ti = &g_threads[i]; break; }
    }
    if (!ti) return;  // 理论不会：未注册线程收到暂停信号
    // 关键：区分"有效暂停请求"与"过期堆积信号"。
    // 若当前没有 GC 在进行（g_gc_stop_in_progress==0），说明这是上一轮排队、
    // 延迟到现在才处理的信号——直接忽略返回，避免 my_epoch 捕获当前 epoch 后
    // 自旋等待一个永远不会到来的"本轮结束"（死锁）。
    if (!g_gc_stop_in_progress) {
        if (g_gc_debug) { char dbg[96]; int dn = snprintf(dbg, sizeof(dbg), "[stop-expired] tid=%lx\n", (unsigned long)me); (void)write(2, dbg, (size_t)dn); }
        return;
    }
    // M22 修复：堆积实时信号重入保护——若本线程已在本轮暂停（首次信号已保存用户态上下文
    // 并自旋），后续堆积信号（gc_block_stop 阻塞期间 GC 重发累积）直接忽略返回，
    // 禁止重入覆盖 ti->uc（否则寄存器扫描拿到的是信号处理器自旋状态 → 丢用户态寄存器
    // → 活跃对象漏标被误回收 → use-after-free，即并发 GC 偶发崩溃根因）。
    if (ti->paused && ti->epoch == g_gc_epoch) return;
    if (g_gc_debug) {
        char dbg[128];
        int dn = snprintf(dbg, sizeof(dbg), "[stop] tid=%lx\n", (unsigned long)me);
        (void)write(2, dbg, (size_t)dn);
    }
    ti->uc = *(const ucontext_t*)ctx;
    ti->tmp_root = g_tmp_root;
    // S3-D-1：保存本线程 VM 状态（若有）——线程自己的 TLS，此处读取安全。
    // executor 暂停全部线程后据此跨线程遍历帧槽（见 px_gc_collect 并发路径）。
    ti->vm_state = px_vm_cur_state ? px_vm_cur_state() : NULL;
    // M92：precise 模式登记根栈快照（线程自旋期无代码执行 → TLS 根栈不变；同 tmp_root 模式）
    ti->roots = g_px_roots;
    ti->root_n = g_px_roots_n;
    ti->epoch = g_gc_epoch;   // 记录暂停所属轮次
    ti->paused = 1;
    __sync_fetch_and_add(&g_paused_count, 1);
    __sync_synchronize();
    px_futex_wake(&g_paused_count);   // M124：通知 executor「本线程已暂停」（替代 200us 定长轮询）
    // 自旋等待本轮 GC 结束：条件 = 本轮仍在进行（stop_in_progress）且 epoch 未变。
    // 若本轮已结束（stop 已清除，信号为延迟/堆积）→ 立即退出，绝不空等——
    // 否则会自旋等待一个永远不会到来的"本轮结束"（偶发死锁）。
    // 兜底：自旋超上限（约 5 秒）强制恢复，宁可漏回收也绝不卡死。
    int my_epoch = g_gc_epoch;
    int hspins = 0;
    while (g_gc_stop_in_progress && g_gc_epoch == my_epoch) {
        // M124：阻塞等待本轮 GC 结束（原 sched_yield 自旋 ⇒ 每个被暂停线程空转 1 核）。
        // 唤醒源：executor 本轮结束 g_gc_epoch++ 后的 px_futex_wake；20ms 超时兜底
        // （漏唤醒最多迟 20ms 恢复），300 次 ≈ 6s 绝对上限（原 5s 兜底语义不变）。
        int cur = g_gc_epoch;
        if (!g_gc_stop_in_progress || g_gc_epoch != my_epoch) break;
        px_futex_wait(&g_gc_epoch, cur, 20000);
        if (++hspins > 300) break;
    }
    __sync_synchronize();
    ti->paused = 0;
    __sync_fetch_and_add(&g_paused_count, -1);
    px_futex_wake(&g_paused_count);   // M124：通知 executor「本线程已恢复」（resume-wait 阻塞字）
}

// M105-S3：fork 后子进程继承父线程 TLS → 复位软屏蔽层栈（防「父进程恰在软屏蔽临界区
//   fork」致子进程永久处于 skip 态：不再屏蔽信号、也不上报暂停）。子进程不再持有父进程的
//   锁与线程，故仅复位 TLS 计数。
static void gc_atfork_child(void) {
    g_gcs_depth = 0;
    g_gcs_skip = 0;
    g_gc_crit = 0;
}

static void gc_install_handler(void) {
    static int installed = 0;
    if (installed) return;
    // M88-S2（qg-issue 27）：忽略 SIGPIPE——http_serve/unix/sse_serve 等服务端对已断开
    // 连接 send()（http_conn_worker 内 5 处裸 send）会触发 SIGPIPE，默认终止整个进程
    // （无 core、无日志，表现即"高并发压测中服务进程悄然消失"）。忽略后 send 返回 EPIPE，
    // 由调用方按"连接已断"清理返回，服务进程永不因客户端断开而亡。
    signal(SIGPIPE, SIG_IGN);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_sigaction = gc_stop_handler;
    sa.sa_flags = SA_SIGINFO | SA_RESTART;  // SA_RESTART：被信号打断的系统调用自动重启
    sigemptyset(&sa.sa_mask);
#ifndef _WIN32
    pthread_atfork(NULL, NULL, gc_atfork_child);   // M105-S3：fork 子进程复位软屏蔽层栈
#endif
    sigaction(SIG_GC_STOP, &sa, NULL);
    installed = 1;
}

// 结构修改关键区「软屏蔽」（M105-S3，语义与安全性论证见文件头 g_gcs_* 注释）：
//   真屏蔽分支保留（并发模式**零行为变化**）；无并发 GC 时免 2 次 rt_sigprocmask
//   （实测 343~372ns/对，M105-S1）。仅涉及 SIG_GC_STOP，不影响其他信号；
//   chan.buf 单 word 原子写无需屏蔽。配对纪律同既有 sigprocmask 用法：LIFO 成对。
// M110-S2：协作式安全点 —— 软屏蔽临界区**出口**自查。若本轮 GC 正在等本线程上报暂停，
//   则向本线程补发一次 SIG_GC_STOP（pthread_kill）：内核在该次系统调用返回用户态的
//   **同一位置**投递信号 ⇒ 处理器执行与「真屏蔽」下**完全相同**的暂停流程（同一 ucontext、
//   同一暂停点、同一根面快照）。故「软屏蔽 + 本安全点」≡「真屏蔽」。
//   选「补发信号」而非「内联暂停体」：① 不依赖 getcontext（musl 无）；② 寄存器快照与真屏蔽
//   路径逐位同源；③ 处理器已有的防重入/过期信号保护天然复用。
//   代价：活跃轮次内每线程 1 次 tgkill，而非每次分配 2 次 rt_sigprocmask。
//   免锁：与信号处理器同款只读 g_threads（executor 正持 g_gc_mu 等暂停，此处取锁必死锁）。
static void gc_pause_if_requested(void) {
    if (!g_gc_stop_in_progress) return;       // 绝大多数分配止步于此：一次 volatile 读
    if (g_active_threads <= 0) return;        // 无并发 GC（单线程）⇒ 无人等本线程
    if (!g_threads) return;
    pthread_t me = pthread_self();
    if (g_gc_executor && pthread_equal(g_gc_executor, me)) return;   // GC 执行者不自暂停
    GCThreadInfo* ti = NULL;
    for (int i = 0; i < g_thread_cap; i++) {
        if (g_threads[i].in_use && pthread_equal(g_threads[i].tid, me)) { ti = &g_threads[i]; break; }
    }
    if (!ti) return;                          // 未注册线程（不受 GC 管辖）
    if (ti->paused && ti->epoch == g_gc_epoch) return;   // 本轮已真暂停 → 无需再补发
    __sync_synchronize();
    if (!g_gc_stop_in_progress) return;       // 二次确认：本轮可能已结束（免无谓信号）
    pthread_kill(me, SIG_GC_STOP);
}

// M110-S2（Issue 38）：软屏蔽**常开**（原门控 g_active_threads==0 取消）+ 出口协作式安全点。
//   病灶：门控在服务进程里恒不成立（池 worker 常驻注册）⇒ 每次 xmalloc/xfree 付 2 次
//   rt_sigprocmask（实测单次 64KB 正则扫描 1,053,631 次、sys 占墙钟 56%；serve 内 13.5×）。
//   门控存在的唯一原因是**停顿及时性**（软屏蔽下处理器只做延迟暂停，连续海量临界区的线程
//   可能一直抢不到 g_gc_crit==0 的窗口 → 拖到 5s 兜底 = 漏扫）。出口安全点补回该性质。
//   逃逸阀：PX_GS_HARD=1 → 旧「真屏蔽」路径（A/B 对拍与一键回滚）。
static int g_gs_hard = -1;                    // -1=未初始化（首次 gc_block_stop 惰性读 env）

static void gc_block_stop(sigset_t* old) {
    int d = ++g_gcs_depth;
    if (d > 16) {   // 防御：block/unblock 疑似不配对（只告警一次，不改变行为）
        static int warned = 0;
        if (!warned) { warned = 1; fprintf(stderr, "lx: gc_block_stop 嵌套 %d 层（block/unblock 不配对？）\n", d); }
    }
    if (d > 1) return;                        // 内层：外层已建立排他（g_gc_crit 已置）
    if (g_gs_hard < 0) {                      // 惰性读 env（多线程同写同值 → 良性竞争）
        const char* e = getenv("PX_GS_HARD");
        g_gs_hard = (e && e[0] == '1') ? 1 : 0;
    }
    if (g_gs_hard) {                          // 逃逸阀：旧「真屏蔽」路径
        g_gcs_skip = 0;
        sigset_t set;
        sigemptyset(&set);
        sigaddset(&set, SIG_GC_STOP);
        pthread_sigmask(SIG_BLOCK, &set, old);
        return;
    }
    g_gcs_skip = 1;                           // 软屏蔽：0 次系统调用
    g_gc_crit = 1;
    __atomic_signal_fence(__ATOMIC_SEQ_CST);   // 临界区写入不得被提到标志之前
}
static void gc_unblock_stop(const sigset_t* old) {
    if (g_gcs_depth <= 0) {                   // 防御：不配对（不应发生）→ 复位，绝不越界
        g_gcs_depth = 0; g_gcs_skip = 0; g_gc_crit = 0;
        return;
    }
    if (--g_gcs_depth > 0) return;            // 内层：外层退出时才解除
    if (g_gcs_skip) {
        __atomic_signal_fence(__ATOMIC_SEQ_CST);   // 标志清零不得被提到临界区写入之前
        g_gc_crit = 0;
        g_gcs_skip = 0;
        gc_pause_if_requested();              // M110-S2：临界区出口协作式安全点
        return;
    }
    pthread_sigmask(SIG_SETMASK, old, NULL);
}

// 线程槽位注册/注销（调用方须持 g_gc_mu；信号处理器只读不写注册表）
static GCThreadInfo* gc_find_thread(pthread_t tid) {
    for (int i = 0; i < g_thread_cap; i++) {
        if (g_threads[i].in_use && pthread_equal(g_threads[i].tid, tid)) return &g_threads[i];
    }
    return NULL;
}

static int gc_register_thread(pthread_t tid, int is_main) {
    if (gc_find_thread(tid)) return 0;  // 已注册
    for (int i = 0; i < g_thread_cap; i++) {
        if (!g_threads[i].in_use) {
            g_threads[i].tid = tid;
            g_threads[i].in_use = 1;
            g_threads[i].paused = 0;
            g_threads[i].is_main = is_main;
            g_threads[i].epoch = 0;
            memset(&g_threads[i].uc, 0, sizeof(g_threads[i].uc));
            g_threads[i].tmp_root = NULL;
            g_threads[i].vm_state = NULL;
            return 0;
        }
    }
    return -1;  // 槽位满
}

static void gc_unregister_thread(pthread_t tid) {
    for (int i = 0; i < g_thread_cap; i++) {
        if (g_threads[i].in_use && !g_threads[i].is_main && pthread_equal(g_threads[i].tid, tid)) {
            g_threads[i].in_use = 0;
            g_threads[i].paused = 0;
            g_threads[i].epoch = 0;
            g_threads[i].vm_state = NULL;
            return;
        }
    }
}

// 确保主线程已注册（首次 GC 初始化时调用；此时通常仍为主线程）
static void gc_ensure_main_registered(void) {
    if (gc_find_thread(pthread_self())) return;
    gc_register_thread(pthread_self(), 1);
}

// M67-S4：架构无关寄存器 word 标记回调（对象地址识别 + GC 标记；mark_cb 接口）
static void gc_mark_word_cb(void* ctx, uintptr_t w) {
    GCHash* set = (GCHash*)ctx;
    if ((w & 7) == 0 && gc_hash_has(set, w)) gc_mark_obj(set, (LXObject*)w);
}

// 扫描单个暂停线程的通用寄存器（M67-S4：arch.h 按架构实现，见 runtime/arch_*.h）
static void gc_scan_registers(GCHash* set, ucontext_t* uc) {
    arch_scan_registers(uc, gc_mark_word_cb, set);
}

// 扫描单个暂停线程的栈（pthread_getattr_np 获取边界；只扫活跃帧 [RSP, 栈底)）
static void gc_scan_thread_stack(GCHash* set, pthread_t tid, ucontext_t* uc) {
    pthread_attr_t attr;
    void* stackaddr = NULL;
    size_t stacksize = 0;
    if (pthread_getattr_np(tid, &attr) == 0) {
        pthread_attr_getstack(&attr, &stackaddr, &stacksize);
        pthread_attr_destroy(&attr);
    }
    if (!stackaddr || stacksize == 0) return;
    uintptr_t rsp = arch_uc_sp(uc);   // M67-S4：arch.h 按架构取暂停线程 SP
    uintptr_t start = rsp & ~(uintptr_t)7;
    uintptr_t end = (uintptr_t)stackaddr + stacksize;
    for (uintptr_t p = start; p + sizeof(uintptr_t) <= end; p += sizeof(uintptr_t)) {
        uintptr_t w = *(uintptr_t*)p;
        if ((w & 7) == 0 && gc_hash_has(set, w)) gc_mark_obj(set, (LXObject*)w);
    }
}

// ============ S3-D 止血切片：外部 GC 根（VM 帧槽） ============
// VM 帧槽数组在堆上（PxFrame.slots），保守 GC 只扫 C 栈/全局/暂存根，
// 帧槽引用的活跃对象不可见 → use-after-free（GC 误回收）或堆只增（漏回收）。
// 单线程 GC 标记期 g_gc_cur_set 指向当前集合；vm.c 的 px_vm_gc_mark 遍历
// 当前线程 VM 活跃帧槽调 px_gc_mark_slots 补标。无 VM 链接时弱符号空转零影响。
static GCHash* g_gc_cur_set = NULL;

void px_gc_mark_slots(LXValue* base, int n) {
    if (!base || n <= 0 || !g_gc_cur_set) return;
    for (int i = 0; i < n; i++) {
        if (px_value_is_obj(base[i]) && base[i].as.obj)
            gc_mark_obj(g_gc_cur_set, base[i].as.obj);
    }
}

// VM 活跃帧槽根标记（vm.c 实现；无 VM 链接时弱符号为空，零影响）
extern void px_vm_gc_mark(void) __attribute__((weak));

// 主回收入口：mark + sweep（M11：spawn 活跃时 stop-the-world）
// ==================== M153（第 35 轮 · 缺陷 145）：常量池 / 短串池化 ====================
// 归因实测（第 35 轮 · 插桩 runtime 的逐行归因）：VM 轨**每次 LOADK 字符串常量都新建对象**、
//   `s[i]` **每取一个字符都新建对象**、`""` **每求值一次都新建对象** —— 单次编译 284 万次
//   分配里 **96.4% 是字符串**（513MB 字符串 / 24MB 列表 / 其余个位数十万）。
// 依据（可核）：`px_str_len` 的语义不变量写明「PX_STR 的 data 恒不可变，全仓无任何就地改写
//   as.str 的站点」⇒ 同内容的字符串**共享同一对象不改变任何可观测语义**（相等/排序/长度/
//   字符索引全按字节比）；这也是 Go 的做法（字面量落只读段，同内容字面量可被合并）。
// 为什么必须「钉住」：池里的对象一旦被 GC 扫掉，池里就是悬垂指针 ⇒ 单列一张钉住表，
//   在**两条**标记路径（并发 / 单线程）里与全局表一同标记。对象仍在对象表 g_objs 内，
//   故 gc_mark_obj 的 gc_hash_has 校验自然通过。
// 边界（诚实登记）：池化后 `object_id()` 对**同内容的短串/字面量**返回同一 id（此前每次
//   求值都不同）。契约只对容器/结构断言「不同对象不同 id」（m145 门），字符串是不可变值，
//   本改动不触碰该契约。
static LXObject** g_pinned = NULL;
static int g_pinned_n = 0, g_pinned_cap = 0;
static pthread_mutex_t g_pinned_mu = PTHREAD_MUTEX_INITIALIZER;
// M154：钉住表去重集合（开放寻址；从不删除 ⇒ 无 tombstone）。容量 16K 指针 = 128KB，
//   惰性分配；满则退化为直接追加（见 px_pin_obj）。
#define PX_PIN_SLOTS (1 << 14)
static LXObject** g_pin_set = NULL;
static void px_pin_obj(LXObject* o) {
    if (!o) return;
    pthread_mutex_lock(&g_pinned_mu);
    // M154（第 36 轮）：去重改**哈希集合** —— 旧实现每次线性扫全表（O(已钉数)）。
    //   M153/M154 的池化把钉住表从「几百」推到「数千」（字面量 + 256 单字符 + 4096 rune
    //   + 4161 小整数文本），于是每次 pin 都要数千次比较、总代价 O(n²)：实测占整图编译
    //   **10.0% 采样**（榜第二，仅次于解释循环）。改为开放寻址指针集合后 pin = O(1)。
    //   集合满/探针用尽时**退化为直接追加**（数组里重复一项，标记同一对象两次无害）。
    if (!g_pin_set) g_pin_set = (LXObject**)xcalloc(PX_PIN_SLOTS, sizeof(LXObject*));
    unsigned h = (unsigned)((((uintptr_t)o >> 4) * 0x9E3779B97F4A7C15ULL) >> 40) & (PX_PIN_SLOTS - 1);
    for (int k = 0; k < 16; k++) {
        unsigned j = (h + (unsigned)k) & (PX_PIN_SLOTS - 1);
        if (g_pin_set[j] == o) { pthread_mutex_unlock(&g_pinned_mu); return; }
        if (!g_pin_set[j]) { g_pin_set[j] = o; goto append; }
    }
append:
    if (g_pinned_n >= g_pinned_cap) {
        int nc = g_pinned_cap ? g_pinned_cap * 2 : 512;
        g_pinned = (LXObject**)xrealloc(g_pinned, sizeof(LXObject*) * (size_t)nc);
        g_pinned_cap = nc;
    }
    g_pinned[g_pinned_n++] = o;
    pthread_mutex_unlock(&g_pinned_mu);
}
// 常量池：按**指针**缓存 —— 只允许「地址恒定的静态字符串」= 编译期字面量（VM 轨 BC 镜像的
//   K 表 payload；C 轨产物的字符串字面量）。**不得**传入栈上/堆上临时缓冲：地址会复用 ⇒
//   后续命中会取到**旧值**。表只建一次、只增不减；装到 3/4 或探针用尽即停止缓存（回落普通
//   分配 ⇒ 只是不省，不会错）。
#define PX_CONST_SLOTS (1 << 15)
typedef struct { const char* key; LXObject* obj; } PxConstEnt;
static PxConstEnt* g_ctab = NULL;
static int g_ctab_n = 0;
static pthread_mutex_t g_ctab_mu = PTHREAD_MUTEX_INITIALIZER;
// M154（第 36 轮）：**按指针哈希**。键本来就是指针（命中判据仍是 `key == s`，见上「只允许
//   地址恒定的字面量」），但旧实现按**内容**逐字节 FNV ⇒ 每次求值一次 strlen + 全串扫描；
//   实测在整图编译（73 模块 / 16936 行）里 px_str_const 占 3.8% 采样、strcmp 3.3%。
//   改为指针乘性散列后：查找 = 一次乘法 + 掩码 + 指针比较，**与内容无关**。
//   桶映射改变不影响正确性（键相等判据与装的条目集合都不变）；分布反而更好 ——
//   内容哈希把「同内容、不同地址」的字面量挤进同一探测链（8 探针用尽即停止缓存），
//   指针哈希把它们摊开。容量口径不变（3/4 装填 + 8 探针，用尽只回落普通分配）。
static unsigned px_const_hash(const char* p) {
    uint64_t h = (uint64_t)(uintptr_t)p * 0x9E3779B97F4A7C15ULL;
    return (unsigned)(h >> 33);
}
static LXObject* px_const_get(const char* s) {
    PxConstEnt* t = __atomic_load_n(&g_ctab, __ATOMIC_ACQUIRE);
    if (!t) return NULL;
    unsigned i = px_const_hash(s) & (PX_CONST_SLOTS - 1);
    for (int k = 0; k < 8; k++) {
        unsigned j = (i + (unsigned)k) & (PX_CONST_SLOTS - 1);
        const char* key = __atomic_load_n(&t[j].key, __ATOMIC_ACQUIRE);
        if (!key) return NULL;                       // 空槽 ⇒ 未缓存
        if (key == s) return t[j].obj;
    }
    return NULL;
}
static void px_const_put(const char* s, LXObject* o) {
    pthread_mutex_lock(&g_ctab_mu);
    if (!g_ctab) {
        g_ctab = (PxConstEnt*)xcalloc(PX_CONST_SLOTS, sizeof(PxConstEnt));
    }
    if (g_ctab_n >= PX_CONST_SLOTS * 3 / 4) { pthread_mutex_unlock(&g_ctab_mu); return; }
    unsigned i = px_const_hash(s) & (PX_CONST_SLOTS - 1);
    for (int k = 0; k < 8; k++) {
        unsigned j = (i + (unsigned)k) & (PX_CONST_SLOTS - 1);
        if (g_ctab[j].key == s) { pthread_mutex_unlock(&g_ctab_mu); return; }
        if (!g_ctab[j].key) {
            g_ctab[j].obj = o;
            __atomic_store_n(&g_ctab[j].key, s, __ATOMIC_RELEASE);
            g_ctab_n++;
            pthread_mutex_unlock(&g_ctab_mu);
            return;
        }
    }
    pthread_mutex_unlock(&g_ctab_mu);
}
static LXValue px_str_len_raw(const char* s, int len);   // 前置声明（定义见下方 px_str 区）
// 空串单例：`""` 与 `px_str_len(x, 0)` 一律返回同一对象（Go 里空串零分配）
static LXValue g_empty_str;
static int g_empty_ready = 0;
static pthread_mutex_t g_empty_mu = PTHREAD_MUTEX_INITIALIZER;
static LXValue px_empty_str_get(void) {
    if (__atomic_load_n(&g_empty_ready, __ATOMIC_ACQUIRE)) return g_empty_str;
    pthread_mutex_lock(&g_empty_mu);
    if (!g_empty_ready) {
        LXValue v = px_str_len_raw("", 0);
        px_pin_obj(v.as.obj);
        g_empty_str = v;
        __atomic_store_n(&g_empty_ready, 1, __ATOMIC_RELEASE);
    }
    pthread_mutex_unlock(&g_empty_mu);
    return g_empty_str;
}
// ASCII 单字符串表（`s[i]` 的结果）：单个字节的字符只有 256 种 ⇒ 用字节值直接索引，
//   零哈希、零探测、有界 256 项（全是钉住对象，约 256×~80B ≈ 20KB）。多字节字符
//   （非 ASCII 的单个 rune）不走此表，回落普通分配。
static LXValue g_ch1[256];
static unsigned char g_ch1_init[256];
static LXValue px_char1(unsigned char c) {
    if (!__atomic_load_n(&g_ch1_init[c], __ATOMIC_ACQUIRE)) {
        char buf[2];
        buf[0] = (char)c; buf[1] = 0;
        LXValue v = px_str_len_raw(buf, 1);          // 单字节原始构造（含 NUL 字符）
        px_pin_obj(v.as.obj);
        g_ch1[c] = v;
        __atomic_store_n(&g_ch1_init[c], 1, __ATOMIC_RELEASE);
    }
    return g_ch1[c];
}

// ---- M154（第 36 轮）：多字节 rune 短串池（px_index 的多字节分支专用）----
// 为什么：M153 的单字节表只覆盖 ASCII；`s[i]`（或 `s[g_pos]`）落在**多字节 rune**
//   （中文/拉丁扩展…）时仍走 `px_str_len(buf, clen)` ⇒ 每次索引一个新对象。实测整图
//   编译（含中文注释/字符串）里 peek/advance/ppos 三处的 `g_src[g_pos]` 合计 ~24 万次
//   分配（前三名之一）。汉字集合有界，故**按内容**池化 2..4 字节 rune 即可基本清零。
// 安全前提（与 M153 同一条不变量）：PX_STR 的 data 恒不可变、无就地改写站点 ⇒
//   同内容的两个串在语言层不可区分（相等/序/长度/索引/join/哈希全按字节）；唯一可见差异
//   是 object_id（契约只对容器/结构断言「不同对象不同 id」，短串一处早已登记为边界）。
// 结构：直接映射 + 4 探针；**不换出**（用尽即回落普通分配 —— 只是不省，不会错）。
//   条目对象一律 px_pin_obj 钉住（复用 M153 的钉住表 ⇒ 两条 GC 标记路径同批标记）。
#define PX_RUNE_SLOTS 4096
typedef struct { unsigned int key; unsigned char len; unsigned char used; LXValue v; } PxRuneEnt;
static PxRuneEnt g_rune[PX_RUNE_SLOTS];
static LXValue px_rune_pool(const char* buf, int clen) {
    if (clen < 2 || clen > 4) return px_str_len(buf, clen);   // 口径之外的长度：普通构造
    unsigned int key = 0;
    for (int i = 0; i < clen; i++) key |= ((unsigned int)(unsigned char)buf[i]) << (8 * i);
    unsigned h = (key * 2654435761u) ^ ((unsigned)clen * 0x9E3779B1u);
    unsigned base = h & (PX_RUNE_SLOTS - 1);
    for (int k = 0; k < 4; k++) {
        unsigned j = (base + (unsigned)k) & (PX_RUNE_SLOTS - 1);
        if (!__atomic_load_n(&g_rune[j].used, __ATOMIC_ACQUIRE)) break;   // 空槽 ⇒ 未缓存
        if (g_rune[j].key == key && g_rune[j].len == (unsigned char)clen) return g_rune[j].v;
    }
    LXValue v = px_str_len(buf, clen);        // 先构造（未发布）
    px_pin_obj(v.as.obj);                     // 再钉住（发布前必须已钉，否则可能被回收）
    for (int k = 0; k < 4; k++) {
        unsigned j = (base + (unsigned)k) & (PX_RUNE_SLOTS - 1);
        if (!__atomic_load_n(&g_rune[j].used, __ATOMIC_ACQUIRE)) {
            g_rune[j].key = key; g_rune[j].len = (unsigned char)clen; g_rune[j].v = v;
            __atomic_store_n(&g_rune[j].used, 1, __ATOMIC_RELEASE);
            return v;
        }
        if (g_rune[j].key == key && g_rune[j].len == (unsigned char)clen) return g_rune[j].v;
    }
    return v;                                 // 探针用尽：返回本次构造（不换出已有条目）
}

// ---- M154（第 36 轮）：小整数 `str()` 池 ----
// 为什么：`str(i)` 的常见入参是**下标 / 计数 / 操作数**（编译器发射器每条指令 4 次
//   `str(int)`），而 px_fmt_value → xmalloc → px_str 每次都要一条新对象（Go 的
//   strconv.Itoa 同样每次分配）。实测整图编译里单条指令发射那行占分配榜首（46.6 万），
//   其中 4/6 就是这四次 str()。池化后该区间**零分配**。
// 文本口径：与 `px_fmt_value(px_int(v))`（即 px_fmt_value_raw 的 `snprintf("%lld")` 分支）
//   逐字节相同 —— 见 px_fmt_value_raw 的 PX_INT 分支；本函数用同一格式串。
// 值域：[PX_INTSTR_LO, PX_INTSTR_HI]；域外走原路（不池化）。表惰性建、只增不减，
//   条目对象一律 px_pin_obj 钉住（复用 M153 钉住表）。
// 可见性边界（与 M153 的池化同款、同一条已登记边界）：同值 `str()` 返回**同一对象**，
//   故 object_id 对它们相同；语言层其余一切（相等/序/长度/连接/索引/哈希）只看字节。
#define PX_INTSTR_LO (-64)
#define PX_INTSTR_HI 4096
static LXValue* g_intstr = NULL;
static unsigned char* g_intstr_init = NULL;
static pthread_mutex_t g_intstr_mu = PTHREAD_MUTEX_INITIALIZER;
static LXValue px_str_int_pool(int64_t v) {
    if (v < PX_INTSTR_LO || v > PX_INTSTR_HI) {
        char t[32];
        int n = snprintf(t, sizeof(t), "%lld", (long long)v);
        return px_str_len(t, n);
    }
    int idx = (int)(v - PX_INTSTR_LO);
    if (g_intstr_init && __atomic_load_n(&g_intstr_init[idx], __ATOMIC_ACQUIRE)) return g_intstr[idx];
    pthread_mutex_lock(&g_intstr_mu);
    if (!g_intstr_init) {
        int n = PX_INTSTR_HI - PX_INTSTR_LO + 1;
        g_intstr = (LXValue*)xmalloc(sizeof(LXValue) * (size_t)n);
        g_intstr_init = (unsigned char*)xcalloc((size_t)n, 1);
    }
    if (!g_intstr_init[idx]) {
        char t[32];
        int n = snprintf(t, sizeof(t), "%lld", (long long)v);
        LXValue r = px_str_len(t, n);
        px_pin_obj(r.as.obj);
        g_intstr[idx] = r;
        __atomic_store_n(&g_intstr_init[idx], 1, __ATOMIC_RELEASE);
    }
    LXValue r = g_intstr[idx];
    pthread_mutex_unlock(&g_intstr_mu);
    return r;
}
// 分配统计：导出（声明见文件前部 g_alloc_stats 处）
static void px_alloc_stats_dump(void) {
    if (!g_alloc_stats) return;
    char b[256];
    int n = snprintf(b, sizeof(b), "[px-alloc-stats] total=%lld bytes=%lldMB\n",
                     g_a_total, g_a_bytes / (1024 * 1024));
    (void)write(2, b, (size_t)n);
    for (int t = 0; t < PX_TYPE_MAX; t++) {
        if (!g_a_by_type[t]) continue;
        n = snprintf(b, sizeof(b), "[px-alloc-stats] type=%d n=%lld\n", t, g_a_by_type[t]);
        (void)write(2, b, (size_t)n);
    }
}

// 标记钉住表（两条 GC 路径各调用一次；与全局表同批）
static void gc_mark_pinned(GCHash* set) {
    pthread_mutex_lock(&g_pinned_mu);
    for (int i = 0; i < g_pinned_n; i++) gc_mark_obj(set, g_pinned[i]);
    pthread_mutex_unlock(&g_pinned_mu);
}

void px_gc_collect(void) {
    // M11 修复④：GC 执行期间屏蔽自己的 SIG_GC_STOP——防止上一轮"延迟信号"
    // 在本轮 GC 执行中投递（handler 会自旋等 epoch，而 epoch 只有本线程能推进
    // → 卡死/5 秒空转）。先拿锁再屏蔽：等锁期间不屏蔽（可被其他 GC 正常暂停），
    // 持锁后屏蔽（防自打断）。出口统一 gc_unblock_stop。
    long long t0 = gc_mono_ms();   // ISSUE28-B1：GC 耗时观测
    sigset_t gc_old;
    pthread_mutex_lock(&g_gc_mu);
    gc_block_stop(&gc_old);
    g_gc_executor = pthread_self();   // 标记我是 GC 执行者（handler 自检防自打断）
    g_gc_pending = 0;                 // ISSUE28-B1：任一回收路径（内联/gc()/安全点）清除延迟标记
    if (!g_gc_env_inited) gc_init_env();
    if (g_obj_count == 0) {
        pthread_mutex_unlock(&g_gc_mu);
        g_gc_executor = 0;
        gc_unblock_stop(&gc_old);
        return;
    }

    if (g_active_threads > 0) {
        // ===== M11 并发路径：stop-the-world =====
        // M55/P0（issue#2）：暂停线程前先持 g_globals_mu。若在暂停线程后才取锁，
        // 会等一个"临界区内被信号暂停、持锁未释放"的线程 → 死锁/GC 空转。先取锁
        // （此刻线程均正常执行，持锁者会跑完释放，无暂停干扰）→ 再 stop-the-world
        // → 根1 扫描全局表（独占）→ 扫完即释放，尽量缩短持锁时长。
        pthread_rwlock_wrlock(&g_globals_mu);
        pthread_t me = pthread_self();
        if (g_gc_debug) {
            char dbg[512]; int dn = 0;
            dn += snprintf(dbg+dn, sizeof(dbg)-dn, "[gc] me=%lx active=%d deferred=%ld\n", (unsigned long)me, g_active_threads, g_gc_deferred);
            for (int i = 0; i < g_thread_cap; i++)
                if (g_threads[i].in_use)
                    dn += snprintf(dbg+dn, sizeof(dbg)-dn, "  [%d] tid=%lx main=%d paused=%d\n", i, (unsigned long)g_threads[i].tid, g_threads[i].is_main, g_threads[i].paused);
            (void)write(2, dbg, (size_t)dn);
        }
        // 本轮 GC 开始（handler 捕获 my_epoch 后自旋等待 epoch 变化）
        g_gc_epoch++;
        g_gc_stop_in_progress = 1;   // 标记进行中（handler 据此区分过期堆积信号）
        __sync_synchronize();
        // 1) 向所有已注册、非自身、已创建完成的线程发送暂停信号（只发一次）
        for (int i = 0; i < g_thread_cap; i++) {
            GCThreadInfo* ti = &g_threads[i];
            if (!ti->in_use || pthread_equal(ti->tid, me)) continue;
            if ((uintptr_t)ti->tid == 0) continue;  // 创建中：还没运行普贤代码，无需暂停
            pthread_kill(ti->tid, SIG_GC_STOP);     // ESRCH（线程恰好退出）忽略
        }
        // 2) 等待所有"仍存活且已注册"的线程**本轮**暂停。
        //    判定"本轮真暂停"：ti->paused==1 且 ti->epoch==当前 epoch。
        //    堆积信号（stop 已清除）会让 paused 短暂置 1 后立即返回，但 epoch 是旧值
        //    → 不算本轮暂停 → 重发信号直到真正本轮暂停。已退出线程（ESRCH）忽略。
        long long stop_deadline = gc_mono_ms() + 5000;   // M124：兜底改「真实 5s 预算」
        for (;;) {
            int remain = 0;
            __sync_synchronize();
            for (int i = 0; i < g_thread_cap; i++) {
                GCThreadInfo* ti = &g_threads[i];
                if (!ti->in_use || pthread_equal(ti->tid, me) || (uintptr_t)ti->tid == 0) continue;
                if (ti->paused && ti->epoch == g_gc_epoch) continue;   // 本轮已真暂停
                int rc = pthread_kill(ti->tid, SIG_GC_STOP);
                if (g_gc_debug) { char dbg[96]; int dn = snprintf(dbg, sizeof(dbg), "[kill] tid=%lx rc=%d\n", (unsigned long)ti->tid, rc); (void)write(2, dbg, (size_t)dn); }
                if (rc == 0 || (rc != 0 && errno == EAGAIN)) remain++;
                /* ESRCH：线程已退出，忽略 */
            }
            if (remain == 0) break;
            // M124（qg-issue 80）兜底：约 5 秒未全部暂停 → 降级跳过本轮（绝不卡死）。
            //   原实现用自旋计数 5,000,000 配 200us nanosleep ⇒ 实际 ≈1000s（注释与行为不符），
            //   现改为时钟预算，行为与注释一致；GC 真正卡住的场景不再拖到 16 分钟。
            if (gc_mono_ms() >= stop_deadline) {
                g_gc_skips++;
                g_gc_epoch++;
                g_gc_stop_in_progress = 0;
                __sync_synchronize();
                px_futex_wake(&g_gc_epoch);      // M124：唤醒已在等待的暂停线程（否则等满 20ms 超时）
                // M124：等已暂停线程恢复 —— 阻塞等待（原 sched_yield 自旋），上限 1s
                for (int w = 0; w < 1000 && g_paused_count > 0; w++) {
                    int pc = g_paused_count;
                    if (pc <= 0) break;
                    px_futex_wait(&g_paused_count, pc, 1000);
                }
                pthread_rwlock_unlock(&g_globals_mu);   // M55：释放暂停前持有的全局表锁
                pthread_mutex_unlock(&g_gc_mu);
                g_gc_executor = 0;
                gc_unblock_stop(&gc_old);
                return;
            }
            // M22：重发间隔加小延时，避免对长时间屏蔽信号的线程狂轰信号（实时信号排队 →
            // 解除屏蔽时堆积触发 → 信号处理器重入覆盖 ucontext，丢用户态寄存器）。
            // M124：延时改 futex 阻塞等待（原 nanosleep + sched_yield 双份让出）——
            //   有线程上报暂停即被 handler 的 wake 提前唤醒，比定长 200us 更快收敛。
            int pc = g_paused_count;
            px_futex_wait(&g_paused_count, pc, 200);   // 200us
        }
        // 3) 标记
        GCHash set;
        gc_hash_init(&set, (size_t)g_obj_count * 2);
        for (int i = 0; i < g_obj_count; i++) gc_hash_insert(&set, (uintptr_t)g_objs[i]);
        g_gc_marked = 0;
        if (g_gc_debug) (void)write(2, "[mk] hash\n", 10);
        // 根1：全局表（M55：GC 于暂停线程前已持 g_globals_mu，此处独占扫描，
        // 防读到 px_set/get_global 半写对象；扫完立即释放，供恢复后的线程使用）
        for (int i = 0; i < g_len; i++) {
            if (px_value_is_obj(g_vals[i]) && g_vals[i].as.obj) gc_mark_obj(&set, g_vals[i].as.obj);
        }
        pthread_rwlock_unlock(&g_globals_mu);
        if (g_gc_debug) (void)write(2, "[mk] globals\n", 13);
        gc_mark_pinned(&set);   // M153：常量池/短串池化对象（永久根）
        // 根2：本线程（GC 执行者）暂存根
        if (g_tmp_root) gc_mark_obj(&set, g_tmp_root);
        // S3-D-1：VM 帧槽精确根 —— executor 自身 VM 状态 + 各暂停线程 VM 状态。
        // 帧槽数组在堆上，保守栈扫描不可见；g_gc_cur_set 供 px_gc_mark_slots 使用。
        g_gc_cur_set = &set;
        // 根3：本线程栈 + 寄存器（conservative：setjmp 把寄存器写入栈上 jmp_buf，
        //      一并扫描——musl 无 getcontext，M57-S4 改 setjmp，同为外部调用强制 spill）。
        //      M92 precise：退役整栈保守扫描 → 跳过；补标本线程 TLS 登记根栈。
        if (!g_gc_precise) {
            jmp_buf jb;
            (void)setjmp(jb);
            gc_scan_stack(&set);
        }
        if (g_gc_debug) (void)write(2, g_gc_precise ? "[mk] self-precise-roots\n" : "[mk] self-stack\n", g_gc_precise ? 20 : 15);
        // 根3b：executor 自身 VM 活跃帧槽（单线程路径同款补标，此处并发路径）
        if (px_vm_gc_mark) px_vm_gc_mark();
        // 根3c：M92 precise —— executor 自身 TLS 登记根栈
        if (g_gc_precise && g_px_roots_n > 0) px_gc_mark_slots(g_px_roots, g_px_roots_n);
        // 根4：所有本轮暂停线程：寄存器 + 栈 + 暂存根 + VM 帧槽（跨线程）
        //      M92 precise：暂停线程跳过保守栈/寄存器扫描，改标其 TLS 登记根栈快照。
        for (int i = 0; i < g_thread_cap; i++) {
            GCThreadInfo* ti = &g_threads[i];
            if (!ti->in_use || !ti->paused || ti->epoch != g_gc_epoch || pthread_equal(ti->tid, me)) continue;
            if (g_gc_precise) {
                if (ti->roots && ti->root_n > 0) px_gc_mark_slots(ti->roots, ti->root_n);
            } else {
                gc_scan_registers(&set, &ti->uc);
                gc_scan_thread_stack(&set, ti->tid, &ti->uc);
            }
            if (ti->tmp_root) gc_mark_obj(&set, ti->tmp_root);
            if (ti->vm_state && px_vm_gc_mark_state) px_vm_gc_mark_state(ti->vm_state);
            if (g_gc_debug) { char dbg[64]; int dn = snprintf(dbg, sizeof(dbg), "[mk] scanned tid=%lx\n", (unsigned long)ti->tid); (void)write(2, dbg, (size_t)dn); }
        }
        // 根4b：M93-S2 帧协程根面 —— 全部存活协程（就绪参数副本 + 运行/阻塞中帧槽）。
        //   运行中协程 vm 已由所属 worker 的 ti->vm_state 覆盖（重复标无害）；
        //   就绪队列协程的 args 副本仅本表可达 → 必须补标（漏标 = worker 取到 UAF）。
        if (px_coro_gc_mark_roots) px_coro_gc_mark_roots();
        http_pend_gc_mark();   // M95-S2：http 挂起连接 req/resp 补标
        px_pxserve_pend_gc_mark();   // M98-S2a：px_serve 挂起连接 req/resp 补标
        g_gc_cur_set = NULL;
        // 4) sweep
        if (g_gc_debug) { char dbg[128]; int dn = snprintf(dbg, sizeof(dbg), "[mk] 暂停+标记+扫栈耗时%lldms\n", gc_mono_ms() - t0); (void)write(2, dbg, (size_t)dn); }
        if (g_gc_debug) { char dbg[96]; int dn = snprintf(dbg, sizeof(dbg), "[mk] sweep count=%d\n", g_obj_count); (void)write(2, dbg, (size_t)dn); }
        g_in_gc_sweep = 1;   // ISSUE28-B1：sweep 单线程（executor 已屏蔽信号）→ xfree 免逐趟 sigprocmask
        int freed = 0, w = 0;
        for (int i = 0; i < g_obj_count; i++) {
            LXObject* o = g_objs[i];
            if (!gc_hash_has(&set, (uintptr_t)o)) continue;   // 防御：损坏条目，丢弃
            if (o->gc_mark) {
                o->gc_mark = 0;
                g_objs[w++] = o;
            } else {
                px_obj_free(o);
                freed++;
            }
        }
        g_in_gc_sweep = 0;
        g_obj_count = w;
        g_alloc_bytes = 0;
        g_gc_freed += freed;
        g_gc_runs++;
        g_tmp_root = NULL;
        if (g_obj_count >= g_gc_threshold) g_gc_threshold = g_obj_count * 2;
        gc_debug("collect #%d(并发): 标记 %lld/%d 回收 %d 存活 %d 线程 %d 耗时%lldms", g_gc_runs, g_gc_marked, g_obj_count + freed, freed, g_obj_count, g_paused_count, gc_mono_ms() - t0);
        if (g_gc_debug) (void)write(2, "[mk] after-collect\n", 19);
        gc_hash_free(&set);
        // ISSUE28-B2：sweep 后归还完全空闲 slab 页给 OS（仍 STW，无并发分配，安全）
        slab_reclaim_empty();
        // 5) 本轮结束：epoch++ 唤醒所有暂停线程；清除进行中标志；等待其全部恢复
        g_gc_epoch++;
        g_gc_stop_in_progress = 0;
        px_futex_wake(&g_gc_epoch);   // M124：唤醒全部「等本轮结束」的暂停线程（原自旋轮询 epoch）
        __sync_synchronize();
        if (g_gc_debug) (void)write(2, "[mk] resume-wait\n", 17);
        // M124：等全部暂停线程恢复 —— 阻塞等待（原 sched_yield 自旋 ⇒ executor 在整段恢复
        //   窗口空转 1 核）。唤醒源 = handler 退出时 g_paused_count 递减后的 px_futex_wake。
        int wstable = 0;
        long long wdeadline = gc_mono_ms() + 5000;   // 兜底：5s 未全部恢复 → 强制继续（绝不卡死）
        for (;;) {
            int any_paused = 0;
            __sync_synchronize();
            for (int i = 0; i < g_thread_cap; i++)
                if (g_threads[i].in_use && g_threads[i].paused) { any_paused = 1; break; }
            if (!any_paused) { if (++wstable >= 2) break; }
            else wstable = 0;
            if (gc_mono_ms() >= wdeadline) break;
            int pc = g_paused_count;
            px_futex_wait(&g_paused_count, pc, 200);   // 200us：阻塞等待，线程恢复即被唤醒
        }
        if (g_gc_debug) (void)write(2, "[mk] resume-done\n", 17);
        pthread_mutex_unlock(&g_gc_mu);
        g_gc_executor = 0;
        gc_unblock_stop(&gc_old);
        return;
    }

    // ===== 单线程快路径（无活跃 spawn 线程）=====
    GCHash set;
    gc_hash_init(&set, (size_t)g_obj_count * 2);
    for (int i = 0; i < g_obj_count; i++) gc_hash_insert(&set, (uintptr_t)g_objs[i]);
    g_gc_marked = 0;
    pthread_rwlock_wrlock(&g_globals_mu);
    for (int i = 0; i < g_len; i++) {
        if (px_value_is_obj(g_vals[i]) && g_vals[i].as.obj) gc_mark_obj(&set, g_vals[i].as.obj);
    }
    pthread_rwlock_unlock(&g_globals_mu);
    gc_mark_pinned(&set);   // M153：常量池/短串池化对象（永久根）
    if (g_tmp_root) gc_mark_obj(&set, g_tmp_root);
    // M92 precise：退役整栈保守扫描 → 跳过本线程栈/寄存器扫描（conservative 保持旧行为）
    if (!g_gc_precise) {
        jmp_buf jb;
        (void)setjmp(jb);
        gc_scan_stack(&set);
    }
    // S3-D 止血：补标当前线程 VM 活跃帧槽（堆上根，保守 C 栈扫不到）
    g_gc_cur_set = &set;
    if (px_vm_gc_mark) px_vm_gc_mark();
    // M92 precise：补标当前线程 TLS 登记根栈（native 桥局部显式根）
    if (g_gc_precise && g_px_roots_n > 0) px_gc_mark_slots(g_px_roots, g_px_roots_n);
    // M93-S2：帧协程根面补标（单线程 GC 路径同款；协程存在即有 worker 活跃走并发路径，
    //   此处兜底纯就绪/创建窗口）
    if (px_coro_gc_mark_roots) px_coro_gc_mark_roots();
    http_pend_gc_mark();   // M95-S2：同上（单线程 GC 路径兜底）
    px_pxserve_pend_gc_mark();   // M98-S2a：同上（单线程 GC 路径兜底）
    g_gc_cur_set = NULL;
    g_in_gc_sweep = 1;   // ISSUE28-B1：单线程 sweep 同上免逐趟 sigprocmask
    int freed = 0, w = 0;
    for (int i = 0; i < g_obj_count; i++) {
        LXObject* o = g_objs[i];
        if (!gc_hash_has(&set, (uintptr_t)o)) continue;   // 防御：损坏条目，丢弃
        if (o->gc_mark) {
            o->gc_mark = 0;
            g_objs[w++] = o;
        } else {
            px_obj_free(o);
            freed++;
        }
    }
    g_in_gc_sweep = 0;
    g_obj_count = w;
    g_alloc_bytes = 0;
    g_gc_freed += freed;
    g_gc_runs++;
    g_tmp_root = NULL;
    if (g_obj_count >= g_gc_threshold) g_gc_threshold = g_obj_count * 2;
    gc_debug("collect #%d: 标记 %lld/%d 回收 %d 存活 %d 跳过 %d 耗时%lldms", g_gc_runs, g_gc_marked, g_obj_count + freed, freed, g_obj_count, g_gc_skips, gc_mono_ms() - t0);
    gc_hash_free(&set);
    // ISSUE28-B2：sweep 后归还完全空闲 slab 页给 OS（单线程路径，无并发分配）
    slab_reclaim_empty();
    pthread_mutex_unlock(&g_gc_mu);
    g_gc_executor = 0;
    gc_unblock_stop(&gc_old);
}

// ---- M92 精确 GC：precise/conservative 模式 + native 桥根登记 API ----
// 模式切换只在程序启动早期（产物 main）调用一次，不做并发安全（GC 开始后不可切）。
void px_gc_set_precise(int precise) {
    g_gc_precise = precise ? 1 : 0;
}

// 作用域开始：保存当前登记栈深度（native 桥入口调用，与 px_root_pop 配对）。
// 登记栈为 TLS，native 桥在同一线程执行，作用域天然线程隔离。
// M92-S2c：屏蔽 SIG_GC_STOP —— 根栈 push/pop/keep 非原子，若信号落在
// push/keep 的 n++ 中途，GC handler 快照 ti->root_n 读到半态 → 刚登记的
// 局部漏根被误回收（并发 GC 偶发 UAF 根因）。与 list/dict 结构修改同模式。
void px_root_push(void) {
    sigset_t old;
    gc_block_stop(&old);
    if (g_px_root_marks_n >= g_px_root_marks_cap) {
        int nc = g_px_root_marks_cap ? g_px_root_marks_cap * 2 : 16;
        g_px_root_marks = (int*)xrealloc(g_px_root_marks, sizeof(int) * (size_t)nc);
        g_px_root_marks_cap = nc;
    }
    g_px_root_marks[g_px_root_marks_n++] = g_px_roots_n;
    if (g_px_root_marks_n > g_px_root_marks_peak) g_px_root_marks_peak = g_px_root_marks_n;
    gc_unblock_stop(&old);
}

// 作用域结束：弹回 px_root_push 时的深度（与 push 严格配对）。
void px_root_pop(void) {
    sigset_t old;
    gc_block_stop(&old);
    if (g_px_root_marks_n <= 0) { gc_unblock_stop(&old); return; }
    int mark = g_px_root_marks[--g_px_root_marks_n];
    g_px_roots_n = mark;
    gc_unblock_stop(&old);
}

// 登记一个局部 LXValue 引用（跨可能触发 GC 的调用前调用）。只压引用类值
// （int/bool/null 无对象无需保护）；压入的是值拷贝，后续对局部变量的赋值
// 不影响已登记条目（登记 = 快照该时刻的引用，语义正确：局部变量持有期即该值）。
void px_root_keep(const LXValue* v) {
    if (!v || !px_value_is_obj(*v)) return;
    sigset_t old;
    gc_block_stop(&old);
    if (g_px_roots_n >= g_px_roots_cap) {
        int nc = g_px_roots_cap ? g_px_roots_cap * 2 : 64;
        g_px_roots = (LXValue*)xrealloc(g_px_roots, sizeof(LXValue) * (size_t)nc);
        g_px_roots_cap = nc;
    }
    g_px_roots[g_px_roots_n++] = *v;
    if (g_px_roots_n > g_px_roots_peak) g_px_roots_peak = g_px_roots_n;
    gc_unblock_stop(&old);
}

// M170（缺陷 188）：根登记栈的「记录 / 还原」——**隔离点 longjmp 落点专用**。
// 病灶：`px_root_push`/`PX_KEEP` 与 `px_root_pop` 是**手动配对**（native 桥入口/出口）。
//   longjmp 会**跳过**中间所有未 pop 的作用域（它不展开 C 帧）⇒ 这些条目留在 TLS 根栈里，
//   而它们指向的对象**已经被正常 GC 回收**（不再是根）⇒ 之后每一轮 GC 都会去「标记」这些
//   **野指针**：轻则假保留（内存不降），重则把已归还给 malloc 的内存当 LXObject 解析 ⇒
//   SIGSEGV。且每个被隔离的错误都会**永久**多留 2~N 条 ⇒ 长跑服务里线性累积。
// 修法：隔离点 setjmp 之前记录深度，longjmp 落点**还原**（被跳过的登记一律作废 ——
//   此刻那些 C 帧已不复存在，登记本就该失效）。
// 语义边界：只**收缩**不扩张（还原深度大于当前值时不动，防止把别人登记的根弹掉）。
// **用途限定（M170 收尾修订）**：本接口只给「**同一函数内的正常出口归一**」用
//   （h3 桥的十余个早退分支：进函数记深度、出口统一归还，中间不让出、不经 longjmp）。
//   隔离点（setjmp/longjmp）落点**必须**改走 px_root_iso_mark / px_root_restore_iso ——
//   原因见那两个函数的注释（栈局部在 longjmp 后失效 · marks 栈被协程共享）。
int px_root_depth(int* marks_out) {
    if (marks_out) *marks_out = g_px_root_marks_n;
    return g_px_roots_n;
}

void px_root_restore(int roots_depth, int marks_depth) {
    int r0 = g_px_roots_n, m0 = g_px_root_marks_n;
    if (g_px_roots_n > roots_depth) g_px_roots_n = roots_depth;
    if (g_px_root_marks_n > marks_depth) g_px_root_marks_n = marks_depth;
    // M170：观测点（PX_GC_DEBUG=1）—— 门据此断言「每次被隔离的错误都归还了登记深度」。
    //   打印发生在**被隔离线程自己**的日志里 ⇒ 与线程生命周期无关（长跑线程也能看到）。
    if (g_gc_debug) {
        char dbg[128];
        int dn = snprintf(dbg, sizeof(dbg),
                          "[px-gc] root 还原 marks=%d→%d roots=%d→%d\n",
                          m0, g_px_root_marks_n, r0, g_px_roots_n);
        (void)write(2, dbg, (size_t)dn);
    }
}

// ---- M170 收尾修订：**隔离点专用**的根登记归还（缺陷 188 的正确形态）----
// 背景：隔离点 = setjmp/longjmp（px_error 跳回捕获点）。longjmp**不展开 C 帧** ⇒
//   被跳过的 `px_root_push`/`PX_KEEP` 留在 TLS 根栈里成为**野根**（指向已被正常回收的对象）
//   ⇒ 之后每轮 GC 都标记它们 ⇒ 假保留 / 把已归还内存当 LXObject 解析 ⇒ SIGSEGV。
//
// ⚠️ 现场实测的两条**硬约束**（本函数与 px_root_iso_mark 的形态即由此而来；改前请先读）：
//   ① **记录值必须存 TLS，不得用栈局部**。原写法「`int rd_marks = 0;
//      int rd_roots = px_root_depth(&rd_marks);` 再在 longjmp 落点读取」会读到**垃圾**
//      —— C 标准不保证非 volatile 局部在 longjmp 后有效。实测落点拿到
//      `marks_depth = -1811936416`（随机负值）⇒ `g_px_root_marks_n` 被设为负数 ⇒
//      下一次 `px_root_push` 走「n < cap」快路径写 `marks[负数]` ⇒ SIGSEGV（18/30 次）。
//   ② **不得收缩 marks 栈**（`g_px_root_marks_n`）。marks 栈是**线程级 TLS**，而执行流是
//      **协程级**（M93 帧协程 M:N：同一 worker 线程上多协程交替、协程可在让出后迁移）。
//      收缩会把「本隔离作用域内让出期间**其它协程** push 的条目」一起弹掉 ⇒ 之后那些协程
//      pop 时弹到错误 mark ⇒ 根面被破坏 ⇒ SIGSEGV（实测 7/20 次；只收缩 roots 则 0/20）。
//   ⇒ 结论：归还**只作用于根栈**（`g_px_roots_n`），marks 栈条目留给原有 push/pop 配对逻辑。
//   ③ 哨兵 `-1` = 本线程无记录（记录点与落点不同线程 ⇒ 不动作）：宁可不修，也不误伤。
static __thread int t_iso_roots = -1;

// 隔离点进入（setjmp 之前调用）：记录当前根栈深度。
void px_root_iso_mark(void) { t_iso_roots = g_px_roots_n; }

// 隔离点落点（longjmp 落点调用）：归还到记录的深度并清哨兵。
//   只收缩、不扩张；同线程才动作；打印格式与 px_root_restore 一致（门据此断言）。
void px_root_restore_iso(void) {
    int r0 = g_px_roots_n, m0 = g_px_root_marks_n;
    if (t_iso_roots >= 0 && g_px_roots_n > t_iso_roots) g_px_roots_n = t_iso_roots;
    if (g_gc_debug) {
        char dbg[128];
        int dn = snprintf(dbg, sizeof(dbg),
                          "[px-gc] root 还原 marks=%d→%d roots=%d→%d\n",
                          m0, g_px_root_marks_n, r0, g_px_roots_n);
        (void)write(2, dbg, (size_t)dn);
    }
    t_iso_roots = -1;
}

int px_root_peak(void) { return g_px_roots_peak; }

// M170：根登记栈峰值（PX_GC_DEBUG=1 时退出打印）——门据此判定「错误路径不泄漏登记」。
static void px_root_peak_dump(void) {
    fprintf(stderr, "[px-gc] 根登记栈峰值 marks=%d roots=%d\n",
            g_px_root_marks_peak, g_px_roots_peak);
}

// 注册对象（构造时调用）。est = 估算占用字节（触发字节阈值用，当前主用对象数阈值）。
static void gc_register(LXObject* o, long long est) {
    // M128：对象表扩容移到临界区外（两阶段，见本文件 M128 段）—— 锁内只做指针发布。
    //   `PX_GROW_RETRY_MAX=0` ⇒ 不备货，直接走锁内 xrealloc（= M127 及以前行为，供对照验收）。
    LXObject** spare = NULL;
    int spare_cap = 0;
    if (m128_retry_max() > 0 && g_obj_count >= g_obj_cap) {
        int ncap = g_obj_cap ? g_obj_cap * 2 : 8192;
        if (ncap < g_obj_count + M128_GROW_SLACK) ncap = g_obj_count + M128_GROW_SLACK;
        spare = (LXObject**)m128_alloc(sizeof(LXObject*) * (size_t)ncap, "gc_objs_grow");
        spare_cap = ncap;
    }
    pthread_mutex_lock(&g_gc_mu);
    if (!g_gc_env_inited) gc_init_env();
    o->gc_mark = 0;   // 关键：xmalloc 未清零，gc_mark 垃圾值=1 会导致 DFS 跳过该节点（子对象漏标）
    o->is_mmap = 0;   // M57-S2：同上，is_mmap 垃圾值=1 会导致 sweep 误对普通 data 走 munmap
    if (g_obj_count >= g_obj_cap) {
        if (spare && spare_cap > g_obj_count) {          // 发布备货（只换指针，无分配）
            if (g_obj_count > 0) memcpy(spare, g_objs, sizeof(LXObject*) * (size_t)g_obj_count);
            LXObject** oldobjs = g_objs;
            g_objs = spare;
            g_obj_cap = spare_cap;
            spare = NULL;
            if (oldobjs) xfree(oldobjs);                 // 旧数组：锁内释放（同 xrealloc 语义）
        } else {                                         // 备货不足（并发增长）或未备货 ⇒ 兜底
            int ncap = g_obj_cap ? g_obj_cap * 2 : 8192;
            if (ncap < g_obj_count + M128_GROW_SLACK) ncap = g_obj_count + M128_GROW_SLACK;
            g_objs = xrealloc(g_objs, sizeof(LXObject*) * ncap);
            g_obj_cap = ncap;
        }
    }
    g_objs[g_obj_count++] = o;
    if (g_alloc_stats) {
        int _t = (int)o->type;
        if (_t > 0 && _t < PX_TYPE_MAX) g_a_by_type[_t]++;
        g_a_bytes += est;
        g_a_total++;
    }
    g_alloc_bytes += est;
    g_tmp_root = o;  // 保护刚创建对象
    int need = (g_obj_count >= g_gc_threshold) ||
               (g_gc_trigger_bytes && g_alloc_bytes >= g_gc_trigger_bytes);
    if (g_gc_stress) need = 1;   // M170：每次分配即 GC（debug/门；见 gc_init_env 注释）
    if (g_gc_frozen) need = 0;   // M170（缺陷 189）：native 建表期禁回收（见 g_gc_frozen 注释）
    int snap_count = g_obj_count;
    int snap_thr = g_gc_threshold;
    int deferrable = (g_active_threads > 0) && !g_gc_force_inline;   // 服务/并发模式：存在请求间安全点（PX_GC_INLINE=1 对拍强制内联）
    pthread_mutex_unlock(&g_gc_mu);
    if (spare) xfree(spare);   // M128：备料未用（提交时发现无需扩容）⇒ 锁外释放（从未发布 ⇒ 安全）
    if (need) {
        // ISSUE28-B1：多线程服务模式（spawn/连接池活跃）把 GC 延迟到安全点（worker 空闲/
        // 池循环顶），避免全量 STW 落在请求热路径；对象数超过 阈值×4 硬上限仍强制内联
        // （内存有界兜底）；单线程 CLI/解释模式无安全点，保持原内联（零行为回归）。
        if (deferrable && (long long)snap_count < (long long)snap_thr * GC_HARD_CAP_FACTOR) {
            g_gc_pending = 1;
        } else {
            px_gc_collect();
        }
    }
}

int px_gc_stats(int* live, int* total) {
    pthread_mutex_lock(&g_gc_mu);
    if (live) *live = g_obj_count;
    if (total) *total = g_gc_freed;
    int runs = g_gc_runs;
    pthread_mutex_unlock(&g_gc_mu);
    return runs;
}

// 调试辅助：对象是否仍注册在对象表（未回收）
int px_gc_contains(LXObject* o) {
    pthread_mutex_lock(&g_gc_mu);
    int found = 0;
    for (int i = 0; i < g_obj_count; i++) {
        if (g_objs[i] == o) { found = 1; break; }
    }
    pthread_mutex_unlock(&g_gc_mu);
    return found;
}

// ==================== 值构造 ====================

LXValue px_null(void) { LXValue v; v.type = PX_NULL; v.as.i = 0; return v; }
// M181（第 59 轮 · 缺陷 193）：未初始化哨兵 + 读检查。
//   `px_uninit()` 只构造哨兵（帧入口 hoist 槽初值）；`px_chk_uninit` 在**按需发射的读点**
//   兜底：哨兵 ⇒ R1001（与 px_get_global 的未定义变量**同一条词条**，spec §17.9/§17.12）。
//   为什么用哨兵而不是"编译期拒绝"：本仓从 M62-L5/M169 起是 **Python 式函数级作用域**，
//   `let g = fn (): x` 之后才 `let x = 1`、而调用发生在声明**之后**是**合法**的
//   （解释轨给 1）⇒ 静态拒绝会误拒合法程序 ⇒ 只能运行期判。
LXValue px_chk_uninit(LXValue v, const char* name) {
    if (v.type == PX_UNINIT) px_error("R1001: 未定义变量: '%s'", name);
    return v;   // 返回原值 ⇒ 可包在任意表达式位置（发射器只需把它套在读点外面）
}
LXValue px_uninit(void) { LXValue v; v.type = PX_UNINIT; v.as.i = 0; return v; }
LXValue px_bool(bool b) { LXValue v; v.type = PX_BOOL; v.as.b = b; return v; }
LXValue px_int(int64_t i) { LXValue v; v.type = PX_INT; v.as.i = i; return v; }
LXValue px_float(double f) { LXValue v; v.type = PX_FLOAT; v.as.f = f; return v; }

static LXValue px_str_len_raw(const char* s, int len) {
    LXValue v; v.type = PX_STR;
    // M107-S3d（qg-issue 34 内存路径）：LXObject 与字符串数据**合并为一次 xmalloc**
    //   （原 2 次：LXObject 一次 + data 一次）。M106-S1 采样归因显示 xmalloc 占 28.84%，
    //   其中 95.25% 来自本函数 ⇒ 分配次数减半直接砍掉近半分配热成本。
    //   语义不变量：PX_STR 的 data 恒不可变（全仓无任何就地改写 as.str 的站点）且恒由
    //   本函数生产（PX_BYTES 走 px_bytes_len 分支、mmap bytes 走独立路径）⇒
    //   px_obj_free 的 PX_STR 分支不再单独释放 data。
    //   红线 2/4：xmalloc 返回值仍被整体清零；**LXObject 尺寸与 union 布局未变**，
    //   仅「对象内存块的容量」变大（同一个 slab class 机制，超 16KB 自动回落 mmap）。
    LXObject* o = xmalloc(sizeof(LXObject) + (size_t)len + 1);
    o->type = PX_STR;
    char* d = (char*)o + sizeof(LXObject);   // data 内联在对象之后（同一次分配内）
    memcpy(d, s, len); d[len] = 0;
    o->as.str.data = d; o->as.str.len = len;
    o->as.str.rune_len = -1; o->as.str.offs_cnt = 0; o->as.str.rune_offs = NULL;  // M106-S2：惰性缓存初值
    v.as.obj = o;
    gc_register(o, sizeof(LXObject) + len + 1);
    return v;
}

LXValue px_str(const char* s) { return px_str_len(s, (int)strlen(s)); }

// M153：空串单例（len <= 0 一律返回同一对象）—— 见本文件 M153 段
LXValue px_str_len(const char* s, int len) {
    if (len <= 0) return px_empty_str_get();
    return px_str_len_raw(s, len);
}

// M153：常量池入口（**仅限静态字面量**；见本文件 M153 段的红线说明）
LXValue px_str_const(const char* s) {
    if (!s || s[0] == '\0') return px_empty_str_get();
    LXObject* o = px_const_get(s);
    if (o) { LXValue v; v.type = PX_STR; v.as.obj = o; return v; }
    LXValue v = px_str_len_raw(s, (int)strlen(s));
    px_pin_obj(v.as.obj);
    px_const_put(s, v.as.obj);
    return v;
}

// M155（缺陷 148）：**显式字节长**的字面量常量池入口（含 NUL 的常量）。
//   键仍是**指针**（同一地址 ⇒ 同一内容与长度：发射器里 `PX_STR_LIT` 的 `sizeof(lit)-1`
//   与字面量一一对应，C 的字面量合并只在字节完全相同（含结尾）时发生）⇒ 与 `px_str_const`
//   共用同一张表不冲突。复用缓存 ⇒ LOADK 的热路径仍零分配。
LXValue px_str_const_n(const char* s, int len) {
    if (!s || len <= 0) return px_empty_str_get();
    LXObject* o = px_const_get(s);
    if (o) { LXValue v; v.type = PX_STR; v.as.obj = o; return v; }
    LXValue v = px_str_len_raw(s, len);
    px_pin_obj(v.as.obj);
    px_const_put(s, v.as.obj);
    return v;
}

// M23b：二进制安全字节串构造（复制 len 字节，可含 NUL；union 复用 str data/len）
LXValue px_bytes_len(const void* data, int len) {
    LXValue v; v.type = PX_BYTES;
    LXObject* o = xmalloc(sizeof(LXObject));
    o->type = PX_BYTES;
    char* d = xmalloc(len + 1);
    if (len > 0 && data) memcpy(d, data, (size_t)len);
    d[len] = 0;
    o->as.str.data = d; o->as.str.len = len;
    o->as.str.rune_len = -1; o->as.str.offs_cnt = 0; o->as.str.rune_offs = NULL;  // M106-S2：bytes 恒不建表
    v.as.obj = o;
    gc_register(o, sizeof(LXObject) + len + 1);
    return v;
}

LXValue px_list(int cap) {
    LXValue v; v.type = PX_LIST;
    LXObject* o = xmalloc(sizeof(LXObject));
    o->type = PX_LIST;
    o->as.list.items = xmalloc(sizeof(LXValue) * (cap > 0 ? cap : 8));
    o->as.list.len = 0; o->as.list.cap = cap > 0 ? cap : 8;
    v.as.obj = o;
    gc_register(o, sizeof(LXObject) + (size_t)o->as.list.cap * sizeof(LXValue));
    return v;
}

LXValue px_list_n(LXValue* items, int n) {
    LXValue v = px_list(n);
    for (int i = 0; i < n; i++) px_list_push(v, items[i]);
    return v;
}

LXValue px_dict(void) {
    LXValue v; v.type = PX_DICT;
    LXObject* o = xmalloc(sizeof(LXObject));
    o->type = PX_DICT;
    o->as.dict.keys = xmalloc(sizeof(char*) * 8);
    o->as.dict.vals = xmalloc(sizeof(LXValue) * 8);
    o->as.dict.len = 0; o->as.dict.cap = 8;
    v.as.obj = o;
    gc_register(o, sizeof(LXObject) + 8 * (sizeof(char*) + sizeof(LXValue)));
    return v;
}

LXValue px_func(const char* name, LXFuncPtr fn, void* ctx) {
    LXValue v; v.type = PX_FUNC;
    LXObject* o = xmalloc(sizeof(LXObject));
    o->type = PX_FUNC;
    o->as.func.name = xstrdup(name); o->as.func.fn = fn; o->as.func.ctx = ctx;
    o->as.func.env = px_null();          // M129：无捕获（旧行为零变化）
    v.as.obj = o;
    gc_register(o, sizeof(LXObject) + strlen(name) + 1);
    return v;
}

// ── M129（qg-issue 87 缺陷 21）：编译轨真词法闭包（upvalue cell） ──
// 背景：编译轨此前**没有词法闭包** —— 闭包体里引用外层函数的参数/局部变量会被
//   当作"全局名"编译（px_get_global），运行时要么取到 null、要么报「未定义变量」。
//   而解释器轨（env 链）一直是真捕获 ⇒ 双轨语义分叉（M89_PLAN 记为 B4「闭包 P2」）。
// 方案：**按引用捕获（cell）**，与解释器轨语义一致（捕获后再改外层变量，闭包读到新值）。
//   · cell = 单元素 list（GC 自动可达，无需新类型）
//   · 闭包对象的 env 字段 = {名 → cell}；ctx 指向该字段（见 runtime.h 注释）
//   · 闭包体用 px_env_lookup(ctx, name) 取回 cell，读写都过 cell ⇒ 引用语义
LXValue px_func_env(const char* name, LXFuncPtr fn, LXValue env) {
    LXValue v = px_func(name, fn, NULL);
    v.as.obj->as.func.env = env;
    v.as.obj->as.func.ctx = &v.as.obj->as.func.env;
    return v;
}

LXValue px_cell(LXValue val) {
    LXValue l = px_list(1);
    px_list_push(l, val);
    return l;
}

LXValue px_cell_get(LXValue cell) {
    return px_index(cell, px_int(0));
}

void px_cell_set(LXValue cell, LXValue val) {
    px_index_set(cell, px_int(0), val);
}

LXValue px_env_lookup(void* ctx, const char* name) {
    if (!ctx) return px_null();
    return px_dict_get(*(LXValue*)ctx, name);
}

LXValue px_native(const char* name, LXFuncPtr fn) {
    LXValue v; v.type = PX_NATIVE;
    LXObject* o = xmalloc(sizeof(LXObject));
    o->type = PX_NATIVE;
    o->as.native.name = xstrdup(name); o->as.native.fn = fn;
    v.as.obj = o;
    gc_register(o, sizeof(LXObject) + strlen(name) + 1);
    return v;
}

LXValue px_struct(const char* type_name, char** fnames, LXValue* fvals, int nfields) {
    LXValue v; v.type = PX_STRUCT;
    LXObject* o = xmalloc(sizeof(LXObject));
    o->type = PX_STRUCT;
    o->as.struct_inst.type_name = xstrdup(type_name);
    o->as.struct_inst.fnames = xmalloc(sizeof(char*) * (nfields ? nfields : 1));
    o->as.struct_inst.fvals = xmalloc(sizeof(LXValue) * (nfields ? nfields : 1));
    long long est = sizeof(LXObject) + strlen(type_name) + 1;
    for (int i = 0; i < nfields; i++) {
        o->as.struct_inst.fnames[i] = xstrdup(fnames[i]);
        o->as.struct_inst.fvals[i] = fvals[i];
        est += strlen(fnames[i]) + 1 + sizeof(LXValue);
    }
    o->as.struct_inst.nfields = nfields;
    v.as.obj = o;
    gc_register(o, est);
    return v;
}

LXValue px_enum(const char* type_name, const char* variant) {
    LXValue v; v.type = PX_ENUM;
    LXObject* o = xmalloc(sizeof(LXObject));
    o->type = PX_ENUM;
    o->as.enum_inst.type_name = xstrdup(type_name);
    o->as.enum_inst.variant = xstrdup(variant);
    v.as.obj = o;
    gc_register(o, sizeof(LXObject) + strlen(type_name) + strlen(variant) + 2);
    return v;
}

LXValue px_enum_variant(LXValue v) {
    if (v.type == PX_ENUM) return px_str(v.as.obj->as.enum_inst.variant);
    return px_null();
}

LXValue px_tuple(LXValue* items, int len) {
    LXValue v; v.type = PX_TUPLE;
    LXObject* o = xmalloc(sizeof(LXObject));
    o->type = PX_TUPLE;
    o->as.tuple.items = xmalloc(sizeof(LXValue) * (len ? len : 1));
    for (int i = 0; i < len; i++) o->as.tuple.items[i] = items[i];
    o->as.tuple.len = len;
    v.as.obj = o;
    gc_register(o, sizeof(LXObject) + (size_t)(len ? len : 1) * sizeof(LXValue));
    return v;
}

// ==================== 类型判断 ====================

bool px_is_null(LXValue v) { return v.type == PX_NULL; }

bool px_is_truthy(LXValue v) {
    switch (v.type) {
        case PX_NULL: return false;
        case PX_BOOL: return v.as.b;
        case PX_INT: return v.as.i != 0;
        case PX_FLOAT: return v.as.f != 0.0;
        case PX_STR: return v.as.obj->as.str.len > 0;
        case PX_BYTES: return v.as.obj->as.str.len > 0;
        case PX_LIST: return v.as.obj->as.list.len > 0;
        case PX_DICT: return v.as.obj->as.dict.len > 0;
        default: return true;
    }
}

const char* px_type_name(LXValue v) {
    switch (v.type) {
        case PX_NULL: return "null";
        case PX_BOOL: return "bool";
        case PX_INT: return "int";
        case PX_FLOAT: return "float";
        case PX_STR: return "string";
        case PX_BYTES: return "bytes";
        case PX_LIST: return "list";
        case PX_DICT: return "dict";
        case PX_FUNC: return "function";
        case PX_NATIVE: return "native";
        case PX_STRUCT: return "struct";
        case PX_ENUM: return "enum";
        case PX_TUPLE: return "tuple";
        case PX_CHAN: return "chan";
        case PX_MUTEX: return "mutex";
        case PX_RWLOCK: return "rwlock";
        case PX_GEN: return "generator";
        case PX_RESULT: return "result";
        case PX_UNINIT: return "未初始化";
    }
    return "unknown";
}

// ==================== M32/M34 生成器 ====================

LXValue px_gen_from_list(LXValue list) {
    LXObject* o = xmalloc(sizeof(LXObject));
    memset(o, 0, sizeof(LXObject));
    o->type = PX_GEN;
    o->as.gen.list = list;
    o->as.gen.cursor = 0;
    o->as.gen.is_lazy = 0;
    LXValue v;
    v.type = PX_GEN;
    v.as.obj = o;
    return v;
}

// M34：惰性生成器——seq（list/range）不展开，transform/filter 闭包在 gen_next 时逐项调用。
LXValue px_gen_lazy(LXValue seq, LXValue transform, LXValue filter) {
    LXObject* o = xmalloc(sizeof(LXObject));
    memset(o, 0, sizeof(LXObject));
    o->type = PX_GEN;
    o->as.gen.list = px_list(0);   // 物化缓冲（for-in / list / len 时展开）
    o->as.gen.cursor = 0;
    o->as.gen.is_lazy = 1;
    o->as.gen.seq = seq;
    o->as.gen.transform = transform;
    o->as.gen.filter = filter;
    LXValue v;
    v.type = PX_GEN;
    v.as.obj = o;
    return v;
}

// 惰性 seq 取第 i 个元素（list 索引；C 端 range 已物化为 list）
static void px_gen_materialize(LXObject* o);

static LXValue px_lazy_seq_get(LXValue seq, int i, int* has) {
    if (seq.type == PX_LIST) {
        if (i >= 0 && i < seq.as.obj->as.list.len) {
            *has = 1;
            return seq.as.obj->as.list.items[i];
        }
    }
    // M39 修复（M34 遗留）：惰性生成器的 seq 支持嵌套生成器（gen of gen）
    // ——先物化内层生成器，再按下标取项
    if (seq.type == PX_GEN) {
        LXObject* go = seq.as.obj;
        if (go->as.gen.is_lazy) px_gen_materialize(go);
        LXValue l = go->as.gen.list;
        if (l.type == PX_LIST && i >= 0 && i < l.as.obj->as.list.len) {
            *has = 1;
            return l.as.obj->as.list.items[i];
        }
    }
    // M164（第 50 轮 · 缺陷 174）：惰性生成器的 seq 支持**全部可迭代类型**。
    //   修前只认 list/gen ⇒ `(c for c in "abc")` / `(e for e in (1,2,3))` / `(k for k in d)`
    //   在 VM 轨与 C 轨**静默产出空生成器**（解释轨正常给出 rune / 元素 / 键）；
    //   `range(...)` 之所以「看起来正常」只是因为 C 端 range 早已物化成 list。
    //   走 px_iter_at（迭代位置语义）：dict → 第 i 个键；str/tuple → 与整数索引等价。
    //   长度由 px_len（与解释轨 `len(seq)` 同源）给定 —— 超出即结束。
    if (seq.type == PX_DICT) {
        LXObject* o = seq.as.obj;
        if (i >= 0 && i < o->as.dict.len) {
            *has = 1;
            return px_str(o->as.dict.keys[i]);
        }
    }
    if (seq.type == PX_STR || seq.type == PX_TUPLE) {
        int n = px_len(seq);
        if (i >= 0 && i < n) {
            *has = 1;
            return px_iter_at(seq, px_int(i));
        }
    }
    *has = 0;
    return px_null();
}

// 惰性生成器剩余项全部物化到 list（for-in / list() / len / 索引时调用，保持 M32 行为一致）
static void px_gen_materialize(LXObject* o) {
    if (!o->as.gen.is_lazy) return;
    o->as.gen.is_lazy = 0;
    for (;;) {
        int has = 0;
        LXValue x = px_lazy_seq_get(o->as.gen.seq, o->as.gen.cursor, &has);
        o->as.gen.cursor++;
        if (!has) break;
        if (o->as.gen.filter.type == PX_FUNC) {
            LXValue keep = px_call(o->as.gen.filter, &x, 1);
            if (!px_is_truthy(keep)) continue;
        }
        LXValue r = px_call(o->as.gen.transform, &x, 1);
        px_list_push(o->as.gen.list, r);
    }
}

LXValue px_gen_next(LXValue g) {
    if (g.type != PX_GEN) px_error("gen_next 需要生成器对象");
    LXObject* o = g.as.obj;
    if (o->as.gen.is_lazy) {
        for (;;) {
            int has = 0;
            LXValue x = px_lazy_seq_get(o->as.gen.seq, o->as.gen.cursor, &has);
            o->as.gen.cursor++;
            if (!has) { o->as.gen.is_lazy = 0; return px_null(); }
            if (o->as.gen.filter.type == PX_FUNC) {
                LXValue keep = px_call(o->as.gen.filter, &x, 1);
                if (!px_is_truthy(keep)) continue;
            }
            return px_call(o->as.gen.transform, &x, 1);
        }
    }
    if (o->as.gen.list.type == PX_LIST && o->as.gen.cursor < o->as.gen.list.as.obj->as.list.len) {
        LXValue r = o->as.gen.list.as.obj->as.list.items[o->as.gen.cursor];
        o->as.gen.cursor++;
        return r;
    }
    return px_null();
}

// ==================== M39 Result（spec §3.5 错误处理唯一通道） ====================

LXValue px_ok(LXValue v) {
    LXValue r;
    r.type = PX_RESULT;
    LXObject* o = xmalloc(sizeof(LXObject));
    o->type = PX_RESULT;
    o->gc_mark = 0;
    o->as.result.ok = 1;
    o->as.result.value = v;
    r.as.obj = o;
    gc_register(o, sizeof(LXObject));
    return r;
}
LXValue px_err(LXValue v) {
    LXValue r;
    r.type = PX_RESULT;
    LXObject* o = xmalloc(sizeof(LXObject));
    o->type = PX_RESULT;
    o->gc_mark = 0;
    o->as.result.ok = 0;
    o->as.result.value = v;
    r.as.obj = o;
    gc_register(o, sizeof(LXObject));
    return r;
}
bool px_is_result(LXValue v) { return v.type == PX_RESULT; }
bool px_result_ok(LXValue v) { return v.as.obj->as.result.ok; }
LXValue px_result_unwrap(LXValue v) { return v.as.obj->as.result.value; }
// Some(x) = x（Option 无运行时包装：None 即 null）
LXValue px_some(LXValue v) { return v; }

// ==================== 错误 ====================

// M72-S2（Issue 10 D1）：编译产物运行时 .px 源位置追踪（cg 每语句插 px_srcline、
// 函数入口插 px_srcfunc；px_error 打印最近位置）。__thread → spawn 各协程独立
// 追踪（S3 错误隔离按线程打印现场）。
__thread int g_px_src_line = 0;
__thread const char* g_px_src_func = NULL;
void px_srcline(int line) { g_px_src_line = line; }
void px_srcfunc(const char* name) { g_px_src_func = name; }
// M72-S3（Issue 10 D2）：spawn 协程错误捕获边界（TLS per-thread）——spawn_thread 在
// 调 fn 前 setjmp；协程内 px_error 打印现场后 longjmp 回捕获点 → 该协程安全退出
// （走 GC 注销路径），宿主进程继续。主线程不设捕获 → 顶层错误保持 exit(1)。
static __thread jmp_buf g_err_jmp;
static __thread int g_err_jmp_set = 0;

// ==================== M127（qg-issue 84）：回卷的锁安全审计 ====================
// 机制与边界见 runtime/locktrack.h 头部。此处 = 两件东西：
//   ① 测试钩子（默认关）：让「失败点落在临界区内」这条路径**确定性可复现**；
//   ② 审计：隔离点 longjmp 之前调用 —— 无锁在身照旧隔离（请求级 5xx）；有锁在身则
//      **不能带锁回卷**（longjmp 不展开 pthread 锁 ⇒ 该锁永久遗留 ⇒ 全进程假死），
//      改为打印持锁清单并 `_exit(1)` 保留致命语义（systemd 3s 内拉起）。
//
// ① PX_ALLOC_FAIL_IN_LOCK=<锁名子串>：仅当**本线程此刻持有一把名字含该子串的运行时锁**、
//    且**正处在隔离点内**（g_err_jmp_set）时，才让这次分配失败。放在隔离点内的条件很关键：
//    启动期的临界区内分配（如 gc_init_env）本来就没有隔离点、本来就 exit(1)，注入它只会
//    让门测不到真正想测的路径。
static int px_alloc_fail_in_lock_hit(size_t n) {
    static const char* pat = NULL;
    static int inited = 0;
    if (!inited) {
        const char* e = getenv("PX_ALLOC_FAIL_IN_LOCK");
        pat = (e && *e) ? e : NULL;
        inited = 1;
    }
    if (!pat) return 0;
    if (!g_err_jmp_set) return 0;      // 无隔离点：注入无意义（那条路径本来就致命）
    int cnt = px_lt_n < PX_LT_MAX ? px_lt_n : PX_LT_MAX;
    for (int i = 0; i < cnt; i++) {
        const char* nm = px_lt_name[i];
        if (nm && strstr(nm, pat)) {
            t_alt_match = nm;
            // 诊断（仅开钩子时出现）：说清「本次注入踩在哪把锁上、当时栈上还有谁」——
            //   否则门失败时无法区分「锁没记上」与「记上了但审计没跑」。
            fprintf(stderr, "[px-locktrack] 注入命中：本线程持锁栈深度=%d，匹配=%s，申请 %zu 字节；栈=",
                    px_lt_n, nm, n);
            for (int j = 0; j < cnt; j++) fprintf(stderr, "%s%s", j ? "," : "", px_lt_name[j] ? px_lt_name[j] : "?");
            fprintf(stderr, "\n");
            fflush(stderr);
            return 1;
        }
    }
    return 0;
}

// ② 审计。返回 = 可以安全回卷；判定「不可」时打印清单并 _exit(1)（不返回）。
static void px_unwind_lock_guard(const char* where) {
    if (px_lt_n <= 0) return;                        // 无锁在身：照旧隔离（绝大多数情况）
    const char* esc = getenv("PX_UNWIND_LOCK_GUARD");
    if (esc && esc[0] == '0') return;                // 逃生舱：无条件回卷（M127 门负控用；生产勿设）
    fprintf(stderr,
            "运行时错误: 隔离点无法安全回滚【%s】—— 本线程此刻仍持有 %d 个运行时锁：\n",
            where, px_lt_n);
    int shown = px_lt_n < PX_LT_MAX ? px_lt_n : PX_LT_MAX;
    for (int i = 0; i < shown; i++)
        fprintf(stderr, "            · %s\n", px_lt_name[i] ? px_lt_name[i] : "?");
    if (px_lt_n > shown) fprintf(stderr, "            · （另有 %d 个未记录）\n", px_lt_n - shown);
    fprintf(stderr,
            "          原因：longjmp 不展开 pthread 锁 ⇒ 回卷会把上述锁**永久**留在「已锁」状态，\n"
            "                其他线程随后阻塞在 pthread_mutex_lock 上 = 进程既不服务也不退出\n"
            "                （假死：systemd 看不到失败、监控看不到异常，比旧的 exit(1) 更难发现）。\n"
            "          故此处保留致命语义：_exit(1)（systemd 会拉起，服务中断约 3 秒）。\n"
            "          处理建议：把该失败点移出临界区（临界区内先用 Result/? 收敛可预期错误），\n"
            "                    或缩小临界区范围。逃生舱 PX_UNWIND_LOCK_GUARD=0（仅调试用）。\n");
    fflush(stderr);
    _exit(1);
}

// M126（qg-issue 83）：隔离点**种类** —— 只用于失败文案精确化，生死判定仍只看 g_err_jmp_set。
//   1 = 协程/spawn 隔离点（请求级：HTTP 5xx）；2 = 信号处理器隔离点（本次处理器调用级）；
//   0 = 无隔离点（启动期 / GC 上下文 → 保留致命语义）。
static __thread int t_isolate_kind = 0;
static __thread char g_err_last_msg[512];   // M96-S2：本线程最后 px_error 文本（px_err_last）

// M120（qg-issue 76 E1）：被隔离的协程运行时错误**进程级计数** —— 隔离是为了让宿主
//   继续（Issue 10 D2），但"继续"不等于"没发生"。此前顶层工作全部跑在协程里的程序
//   （服务/轮询器常见）出错后进程**以 rc=0 退出**= 假成功：CI 判绿、systemd 不判失败、
//   监控看不出。修法：隔离落点计数 + 生成产物 main 收尾调 px_exit_code_final。
//   计数口径 = **未被应用层消费**的隔离错误数：handler/middleware 把错误变成 HTTP 500
//   属于"被处理的请求失败"，不是"进程假成功"，**不计入退出码** —— 否则长跑服务只要历史
//   上有过一次失败请求，优雅关闭就会返回非 0 ⇒ systemd/脚本误判（与本项目 Issue 72
//   「重启风暴」同类风险）。裸 spawn 的协程死了没人管 → 计入。
static _Atomic int g_coro_err_count = 0;
static _Atomic int g_coro_err_atexit_reg = 0;   // atexit 兜底是否已注册
static _Atomic int g_coro_err_reported = 0;     // 退出码是否已在 main 收尾反映
int px_coro_err_count(void) { return atomic_load(&g_coro_err_count); }
// 应用层消费（handler/middleware → 500 的边界调用）
void px_coro_err_consume(void) {
    int n = atomic_load(&g_coro_err_count);
    while (n > 0 && !atomic_compare_exchange_weak(&g_coro_err_count, &n, n - 1)) { }
}
// 时序兜底：顶层先返回、协程错误随后才被观测到的窗口（实测 sleep 0.3 的场景）——
//   仍在进程退出前把话说清楚并把退出码拉成 1。
static void px_coro_err_exit_sink(void) {
    int n = atomic_load(&g_coro_err_count);
    if (n <= 0) return;
    if (atomic_load(&g_coro_err_reported)) return;
    fprintf(stderr, "退出码修正（exit 收尾）：本次运行有 %d 个协程因运行时错误被隔离终止（现场见上）\n", n);
    fflush(stderr);
    _exit(1);
}
int px_exit_code_final(int code) {
    int n = atomic_load(&g_coro_err_count);
    if (n > 0) {
        atomic_store(&g_coro_err_reported, 1);
        fprintf(stderr, "退出码修正：本次运行有 %d 个协程因运行时错误被隔离终止（现场见上）\n", n);
        fflush(stderr);
        if (code == 0) return 1;
    }
    // M126（qg-issue 83）：信号处理器隔离**不改变退出码** —— 属「服务侧已处理的
    //   生命周期事件」（对齐 nginx：reload 失败保留旧配置、服务不受影响），不是
    //   「进程假成功」；若计入退出码，长跑服务只要历史上有过一次 reload 失败，
    //   systemd 就会在**计划内**重启时判 failed（qg-issue 72 重启风暴同源）。
    //   此处只做收尾提示（证据主渠道是 stderr 的 [px-signal] 行，可被监控 grep）。
    {
        int sn = atomic_load(&g_sig_err_count);
        if (sn > 0) {
            fprintf(stderr,
                    "收尾提示：本次运行有 %d 次信号处理器错误被隔离（**退出码不变**：服务未中断，"
                    "详见上方 [px-signal] 行）\n", sn);
            fflush(stderr);
        }
    }
    return code;
}

void px_error(const char* fmt, ...) {
    // M129（缺陷 38）：json_parse_opt 的局部捕获点在最优先位置 —— 期间任何 px_error
    //   都变成 Err(msg) 返回给调用方，既不打印也不退出（等价 Go 的 error 返回）。
    //   ⚠️ 必须放在 fflush/日志**之前**，否则畸形 JSON 仍会污染服务端 stderr。
    if (g_json_opt_active) {
        va_list cap;
        va_start(cap, fmt);
        vsnprintf(g_json_opt_msg, sizeof(g_json_opt_msg), fmt, cap);
        va_end(cap);
        longjmp(g_json_opt_jb, 1);
    }
    // 先刷新 stdout 缓冲：print 输出在管道/重定向下是全缓冲，exit 前不刷会丢
    fflush(stdout);
    va_list ap;
    va_start(ap, fmt);
    // M96-S2：记录本线程最后一次错误文本（offload 外包线程捕获后回传协程重抛用）。
    //   va_copy 独立消费（vfprintf 随后仍需原 ap）。
    { va_list ap2; va_copy(ap2, ap); vsnprintf(g_err_last_msg, sizeof(g_err_last_msg), fmt, ap2); va_end(ap2); }
    // M72-S2（Issue 10 D1）：运行时错误带 .px 源位置（编译产物路径；pxi 解释器
    // 走 i_err line:col 不受影响）。无追踪位置（native 初始化期）→ 原样前缀。
    if (g_px_src_line > 0) {
        if (g_px_src_func && g_px_src_func[0])
            fprintf(stderr, "运行时错误 [%s 行%d]: ", g_px_src_func, g_px_src_line);
        else
            fprintf(stderr, "运行时错误 [行%d]: ", g_px_src_line);
    } else {
        fprintf(stderr, "运行时错误: ");
    }
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
    va_end(ap);
    fflush(stderr);
    // M72-S3（Issue 10 D2）：spawn 协程内错误 → longjmp 隔离（宿主继续）；主线程
    // /无捕获点 → exit(1)（带现场）。隔离由 spawn_thread setjmp 提供。
    if (g_err_jmp_set) {
        px_unwind_lock_guard("px_error 运行时错误");   // M127：带锁回卷 ⇒ 留锁假死，宁可致命退出
        longjmp(g_err_jmp, 1);
    }
    exit(1);
}

// ==================== M125（qg-issue 82）：分配失败处理 ====================
// 测试钩子（默认关）：PX_ALLOC_FAIL_MIN=<字节>，xmalloc 请求 ≥ 该值即注入一次失败。
//   用途 = 让「分配失败 → 请求级 5xx、进程不死」这条语义**可被自动化门验证**
//   （否则只能等真 OOM）。首次读取后缓存；未设或 0 → 恒不触发。
static size_t px_alloc_fail_min(void) {
    static size_t cached = 0;
    if (cached == 0) {
        const char* e = getenv("PX_ALLOC_FAIL_MIN");
        cached = (e && *e) ? (size_t)strtoull(e, NULL, 10) : 0;
        if (cached == 0) cached = SIZE_MAX;   // 0 / 未设 → 阈值拉到 u64 上限（含比较恒假）
    }
    return cached;
}

// 分配失败统一出口（三处 mmap 失败 + xcalloc 溢出）。语义见文件头部 M125 段：
//   协程隔离点内 → longjmp（只终止本协程 ⇒ HTTP 层转 5xx，进程与其余连接不受影响）；
//   隔离点外（启动期 / GC / 信号上下文）→ _exit(1)（保留原致命语义，绝不静默续跑）。
// 无论哪种，都先把**真实原因**（尺寸 / errno / 判定类别）打到 stderr —— 原实现只有
// 一句 `lx: 内存不足`，把「尺寸算成 0 / 负数」这类真缺陷一律误报为内存不足。
static void px_alloc_fail(size_t n, size_t total, const char* what) {
    int e = errno;
    int illegal = (total == 0 || n >= PX_ALLOC_ABSURD);
    fprintf(stderr,
            "运行时错误: %s【%s】申请 %zu 字节（映射 %zu 字节）errno=%d (%s)\n"
            "          处理：%s\n",
            illegal ? "分配尺寸非法（尺寸计算溢出 / 负长度）" : "内存不足",
            what ? what : "?", n, total, e, strerror(e),
            !g_err_jmp_set
                ? "无隔离点 → 保留致命语义退出（启动期 / GC 上下文）"
                : (t_isolate_kind == 2
                       ? "信号处理器隔离点内 → 只终止本次处理器调用（进程与在途连接不受影响）"
                       : "协程隔离点内 → 只终止本请求（HTTP 层转 5xx），进程继续服务"));
    fflush(stderr);
    if (g_err_jmp_set) {
        px_unwind_lock_guard("px_alloc_fail 分配失败");   // M127：带锁回卷 ⇒ 留锁假死，宁可致命退出
        longjmp(g_err_jmp, 1);
    }
    _exit(1);
}

// 前导字节 → 该字符**声称**的字节数（只读首字节，不校验后续）
static inline int px_utf8_clen(unsigned char cc) {
    if ((cc & 0x80) == 0) return 1;
    if ((cc & 0xE0) == 0xC0) return 2;
    if ((cc & 0xF0) == 0xE0) return 3;
    if ((cc & 0xF8) == 0xF0) return 4;
    return 1;
}

// M142（缺陷 111/112）：**全运行时唯一的「一个字符 = 多少字节」判定**。
//   p = 当前位置，rem = 本串剩余字节数。返回该字符的字节数（1..4）。
//   规则：合法序列 → 其长度；ASCII → 1；**孤立续字节 / 尾部截断的前导字节 /
//   后续字节不是续字节** → 1（即"每个非法字节各自成字符"）。
//   这样保证：① 走查永不越过 rem（不存在越界读，缺陷 112 由构造消除）；
//             ② 合法 UTF-8 下的结果与旧实现逐字节相同（零回归）；
//             ③ 畸形 UTF-8 下 len(s) == 走查步数，且 offs[c] 单调覆盖**全部字节**
//                （旧实现里"声称长度"会吞掉后续字节，导致 s[i] 与 s[i:i+1] 不一致）。
static inline int px_utf8_step(const unsigned char* p, int rem) {
    if (rem <= 0) return 1;
    int n = px_utf8_clen(p[0]);
    if (n == 1) return 1;
    if (n > rem) return 1;
    for (int k = 1; k < n; k++) {
        if ((p[k] & 0xC0) != 0x80) return 1;
    }
    return n;
}

// ==================== 字符串工具 ====================

// M83-S1（Issue 16 GAP-STR-1-B1）：带字节长度边界的 UTF-8 字符计数——str 内嵌 NUL 时
// len() 尊重 str.len（完整字节边界）而非 C strlen（在首个 NUL 截断）。边界 n 为字节数。
//
// 缺陷 111（M142）：原实现数「非连续字节」⇒ **孤立续字节（0x80..0xBF）不计入**：
//     len("A\x80B") == 2，而 s[i] / 单字符切片按 px_utf8_clen 前导字节走查（3 步），
//     rune_offs 偏移表也建 3 项 —— 同一份值上「字符数」有两个互不相容的定义。
//     后果（实测）：逐字符扫描器在**畸形 UTF-8** 上索引错位（len 与 s[i] 不同源），
//     即"看得见的字节数"与"循环次数"对不上（`for i in range(len(s))` 会漏字节）。
//   修法：与 px_index / 偏移表同源 —— 按前导字节走查，**一个走查步 = 一个字符**
//     （孤立续字节自身成一步，故其 len 与 bytes_len 一致；合法 UTF-8 结果不变）。
int px_unicode_len_n(const char* s, int n) {
    int c = 0;
    int i = 0;
    const unsigned char* p = (const unsigned char*)s;
    while (i < n) {
        i += px_utf8_step(p + i, n - i);
        c++;
    }
    return c;
}

int px_unicode_len(const char* s) {
    return px_unicode_len_n(s, (int)strlen(s));
}

// ==================== M106-S2（Issue 33-A）：str 惰性 rune 缓存 ====================
// 病灶：px_index / px_len 的 PX_STR 分支每次调用都 px_unicode_len_n 全扫一遍（O(n)），
//   且 px_index 还要从 byte0 线性走到第 i 个 rune（O(i)）⇒ 逐字符扫描 .px 代码天然 O(n²)
//   （64KB 实测 5.4s；ws-approve /check 因 json_valid 逐字符两趟 → 11.6s → 越过 fail-closed）。
// 解法：str 对象上挂两个惰性缓存（见 runtime.h 的 str 子结构注释）——
//   rune_len（一次 O(n)，之后 O(1)）+ rune_offs（一次 O(n) 建表，之后 s[i] 取起始偏移 O(1)）。
// 语义红线（逐条对齐改动前；第 1/2/4 条经 M142 缺陷 111 修订，见下）：
//   1. rune_len 值 = px_unicode_len_n 的结果；M142 起 px_unicode_len_n 与建表**同源**
//      （px_utf8_step）⇒ 畸形 UTF-8 下二者也相等（旧注："不是建表步数"已不成立）；
//   2. 偏移表按 px_utf8_step 建（前导字节判长 + 校验后续续字节；非法字节各自成步），
//      合法 UTF-8 下与旧代码走 i 步后的 p 逐字节相同；
//   3. 索引 i ≥ 表步数时（仅畸形 UTF-8 可能）**回落原线性走查**，连越界读行为都保持原样；
//   4. 单字符结果按 px_utf8_step 判长（M142：原为 px_utf8_clen 只读首字节 ⇒ 尾部截断的
//      前导字节会越读到 str.len 之外的字节，缺陷 112）；
// 内存/性能取舍：仅字节长度 ≥ PX_STR_OFFS_MIN 的串才建表（表 = 4B×步数），小串线性走更划算。
#ifndef PX_STR_OFFS_MIN
#define PX_STR_OFFS_MIN 1024          // 可 -DPX_STR_OFFS_MIN=… 覆盖（用于等价性/边界试验）
#endif
// 上界护栏（M106-S3）：偏移表内存 ≈ sizeof(int)×(字节数+1) ≈ 4× 串长。KB 级串无碍；
//   但若对数百 MB 的巨串反复取 s[i]，4× 放大可能压垮内存 ⇒ 超过 PX_STR_OFFS_MAX 的串
//   一律不建表，回落 px_index 原线性走查（与 M105 及更早逐字节同行为），仅保留
//   rune_len 惰性计数（O(1) 空间）。阈值 16 MiB 串 ⇒ 表上界 ≈ 64 MiB。
#ifndef PX_STR_OFFS_MAX
#define PX_STR_OFFS_MAX (16 * 1024 * 1024)   // 可 -DPX_STR_OFFS_MAX=… 覆盖
#endif

// 前导字节 → 该字符字节数：**定义已上移至「字符串工具」段**（缺陷 111：px_unicode_len_n
// 需要它 ⇒ 单一来源，避免两处判定式漂移）。

// 惰性 rune 计数（结果与 px_unicode_len_n 完全一致；str 不可变 ⇒ 无失效逻辑）
static inline int px_str_rune_len(LXObject* o) {
    int c = __atomic_load_n(&o->as.str.rune_len, __ATOMIC_RELAXED);
    if (c < 0) {
        c = px_unicode_len_n(o->as.str.data, o->as.str.len);
        __atomic_store_n(&o->as.str.rune_len, c, __ATOMIC_RELAXED);
    }
    return c;
}

// 惰性 rune→byte 起始偏移表；返回 NULL 表示"小串/空串，走原线性走查"
static int* px_str_offs_get(LXObject* o) {
    int* p = __atomic_load_n(&o->as.str.rune_offs, __ATOMIC_ACQUIRE);
    if (p) return p;
    int n = o->as.str.len;
    if (n < PX_STR_OFFS_MIN) return NULL;          // 小串：不建表（避免小串也付分配代价）
    if (n > PX_STR_OFFS_MAX) return NULL;          // M106-S3 巨串：不建表（护栏，防 4× 内存放大）→ 回落线性走查
    const unsigned char* s = (const unsigned char*)o->as.str.data;
    if (!s) return NULL;
    int* offs = (int*)xmalloc(sizeof(int) * ((size_t)n + 1));   // 步数 ≤ 字节数 ⇒ n+1 足够
    int c = 0, i = 0;
    while (i < n) { offs[c++] = i; i += px_utf8_step(s + i, n - i); }   // 与 px_index / px_slice 同源（缺陷 111）
    int* old = __atomic_load_n(&o->as.str.rune_offs, __ATOMIC_ACQUIRE);
    if (old) { xfree(offs); return old; }          // 竞态：他线程已建 → 用它的，丢弃本次
    __atomic_store_n(&o->as.str.offs_cnt, c, __ATOMIC_RELAXED);
    __atomic_store_n(&o->as.str.rune_offs, offs, __ATOMIC_RELEASE);   // 先放数据后发布指针
    return offs;
}

// 简单数字转字符串（int/float）
static char num_buf[64];
static const char* fmt_num(LXValue v) {
    if (v.type == PX_INT) {
        snprintf(num_buf, sizeof(num_buf), "%lld", (long long)v.as.i);
    } else {
        double f = v.as.f;
        // M63-L9：float→str 最短 roundtrip 全精度（替代原 %g 6 位截断，MINI_SUBSET §十三.8）
        // 格式规则 = 语言既有 %g 定点舒适区：定点 iff 十进制指数 x ∈ [-4,15)（即
        // 1e-4 <= |f| < 1e15），否则科学计数——保持语言习惯：100000.0→"100000.0"、
        // 250.0→"250.0"、1e15→"1e+15"（%g6 时代同界；M63 把精度提到 roundtrip 全精度：
        // 0.1+0.2→"0.30000000000000004"（旧 "0.3"）、1/3→"0.3333333333333333"、
        // 123456789.123→"123456789.123"（旧 "1.23457e+08"））。
        // 精度：roundtrip 所需最小位数——%.*f（定点）/%.*e（科学）逐位递增 + strtod
        // 回读校验，首个相等即最短（位数单调，IEEE754 17 位内必达）。区别于早期实现
        // 全扫 %.g 取字符最短（会把 100000.0 显成科学 "1e+05"、250.0 显 "2.5e+02"）。
        if (isnan(f)) {
            // M148（顺带发现的一条**潜伏**缺陷）：NaN 的文本**归一为 `nan`**（丢掉符号位）。
            //   原先走 libc `%g`：glibc 对**负 NaN** 给 `-nan`（符号位来自位模式），
            //   而 `str()` 是**语言约定**，必须是**确定值**（负 NaN 的符号位是平台/运算
            //   相关的：x86 的 `0.0/0.0` 就给负 NaN）。更要紧的是编译器侧
            //   `selfhost/codegen.px::cg_fmt_float` 的非有限值名单只列了
            //   `"inf" / "-inf" / "nan"` ⇒ 一旦真出现 `"-nan"` 就会**漏过该分支**，
            //   继续走去掉 `.0` 的逻辑（与缺陷 130 同族的手法）⇒ 产出错误字面量。
            //   ⇒ 从源头归一，并给 codegen 的名单补上 `-nan` 作纵深防御。
            strcpy(num_buf, "nan");
        } else if (isinf(f)) {
            snprintf(num_buf, sizeof(num_buf), "%g", f);          /* inf / -inf */
        } else if (f == 0.0) {
            strcpy(num_buf, signbit(f) ? "-0" : "0");             /* ±0，.0 补丁同下 */
        } else {
            double a2 = (f < 0.0) ? -f : f;
            int x = (int)floor(log10(a2));
            double p10 = pow(10.0, (double)x);
            if (a2 < p10) { x--; p10 /= 10.0; }
            else if (a2 >= p10 * 10.0) { x++; p10 *= 10.0; }
            int dec;
            if (x >= -4 && x < 15) {                              /* 定点舒适区 */
                /* M148（缺陷 133）：上界必须按**有效位数**定。定点文本的"位数"是
                   小数点后的位数，要覆盖 17 位有效数字需要 `17 - x` 位；原先写死
                   `dec <= 17`，在 x ∈ [-4,-1]（0.000… 形态）**不够** ⇒ 循环跑到最后
                   一个候选仍未回读相等，num_buf 就留下了一串**不可往返**的文本
                   （实测 0x3f2d1ac1aeaf35e2 → "0.00022204984938272"，读回来已不是
                   原值 —— 静默丢精度，比"报错"更糟）。 */
                int maxdec = 17 - x;
                if (maxdec < 1) maxdec = 1;
                if (maxdec > 21) maxdec = 21;
                for (dec = 0; dec <= maxdec; dec++) {
                    snprintf(num_buf, sizeof(num_buf), "%.*f", dec, f);
                    if (strtod(num_buf, NULL) == f) break;
                }
            } else {                                              /* 科学计数 */
                for (dec = 0; dec <= 16; dec++) {
                    snprintf(num_buf, sizeof(num_buf), "%.*e", dec, f);
                    if (strtod(num_buf, NULL) == f) break;
                }
            }
        }
        // M62-L1：对齐解释器 i_fmt_float（selfhost/ival.px）：整值且有限且 |f| < 1e15
        // 且 %g 输出无 ./e/E/inf/nan → 补 ".0"（编译模式原 %g 打印 3.0 → "3"，解释器 "3.0"，
        // 双模式不对称；补 .0 后与解释器/golden(Rust fmt_float) 一致）
        double af = (f < 0.0) ? -f : f;
        if (af < 1e15 && f == (double)(int64_t)f) {
            if (!strpbrk(num_buf, ".eE") && !strchr(num_buf, 'i') && !strchr(num_buf, 'n')) {
                size_t ln = strlen(num_buf);
                if (ln + 2 < sizeof(num_buf)) {
                    num_buf[ln] = '.';
                    num_buf[ln + 1] = '0';
                    num_buf[ln + 2] = '\0';
                }
            }
        }
    }
    return num_buf;
}

// ---- 字符串构建（M-B5：值格式化用；原位于 regex 替换处，提前复用） ----
typedef struct { char* data; int len, cap; } RStrBuf;
static void rsb_append(RStrBuf* b, const char* s, int n) {
    if (n <= 0) return;
    if (b->len + n > b->cap) {
        int nc = b->cap ? b->cap * 2 : 64;
        while (nc < b->len + n) nc *= 2;
        b->data = xrealloc(b->data, nc);
        b->cap = nc;
    }
    memcpy(b->data + b->len, s, n);
    b->len += n;
}
static char* rsb_done(RStrBuf* b) {
    char* out = xmalloc(b->len + 1);
    if (b->len > 0) memcpy(out, b->data, b->len);
    out[b->len] = 0;
    xfree(b->data);
    return out;
}
static char* rsb_done_len(RStrBuf* b, int* out_len) {   // M155：带长度收尾（内嵌 NUL 也算）
    if (out_len) *out_len = b->len;
    return rsb_done(b);
}
// M155（缺陷 150）：dict 渲染的排序项「文本 + 长度」随行 —— 排序键仍是 strcmp（口径不变），
//   但 append 用真长度（此前 append 用 strlen(parts[i])，含内嵌 NUL 的值会被截断）。
typedef struct { char* p; int len; } PxDisp;
static int px_cmp_disp(const void* a, const void* b) {
    return strcmp(((const PxDisp*)a)->p, ((const PxDisp*)b)->p);
}

// ==================== 输出 ====================

// ---- M-B5：值格式化（对齐 Rust value.rs fmt_value）----
// 递归渲染 list/dict/tuple/enum/struct/result/gen；原子类型直接格式化
// 返回 malloc 字符串（调用方 free）
// 注意：dict 按完整 "k: v" 字符串排序（对齐 Rust parts.sort()，而非按键排序）
// ═══ 缺陷 125（M145）：循环引用值上的比较/渲染**不得**无界递归 ═══
//   背景：BIRCH CF 树（token-cache 聚类族）天然带 parent↔child 环；此前
//     `var g = {}; g.set("me", g); g == g` ⇒ compare_values 无限递归 ⇒ C 栈溢出 ⇒ SIGSEGV
//     （VM 轨与 C 轨同源，实测 rc=139；`str()`/`json_stringify()` 同族三条通路同样段错误）。
//   比较语义对齐 Go `reflect.DeepEqual`：维护「已访问对象对」(ptrA,ptrB) 集合，
//     再次遇到同一对 ⇒ 视为相等（不再下潜）。非容器值走零开销快路径。
typedef struct { const LXObject* a; const LXObject* b; } PxEqPair;
typedef struct { PxEqPair* it; int n; int cap; } PxEqCtx;
static __thread PxEqCtx* g_eq_ctx = NULL;

static int px_is_container(LXValue v) {
    return v.type == PX_LIST || v.type == PX_TUPLE || v.type == PX_DICT || v.type == PX_RESULT;
}
static void px_eq_ctx_free(void) {
    if (g_eq_ctx) { xfree(g_eq_ctx->it); xfree(g_eq_ctx); g_eq_ctx = NULL; }
}

// ── 渲染（str/print/json）的**路径**环保护：只认「当前递归路径上」的对象 ──
//   为何不用累积集合：`var a = {"x":1}; var d = {"p":a,"q":a}` 是**共享而非环**，
//     累积集合会把第二次出现误渲染成 `...`（既有合法输出会被改坏）⇒ 用路径栈。
typedef struct { const LXObject** it; int n; int cap; } PxPath;
static __thread PxPath g_fmt_path = { NULL, 0, 0 };   // 人类可读渲染（px_fmt_value）
static __thread PxPath g_json_path = { NULL, 0, 0 };  // JSON 序列化（stringify / stringify_go）
static void px_path_reset(PxPath* p) { p->n = 0; }
static int px_path_has(PxPath* p, const LXObject* o) {
    for (int i = 0; i < p->n; i++) if (p->it[i] == o) return 1;
    return 0;
}
static void px_path_push(PxPath* p, const LXObject* o) {
    if (p->n == p->cap) {
        p->cap = p->cap ? p->cap * 2 : 16;
        p->it = (const LXObject**)xrealloc(p->it, (size_t)p->cap * sizeof(LXObject*));
    }
    p->it[p->n++] = o;
}
static void px_path_pop(PxPath* p) { if (p->n > 0) p->n--; }

// M155（第 37 轮 · 缺陷 150）：渲染结果**带长度**。此前 `px_fmt_value` 只回 `char*`，
//   而全部调用方一律 `strlen(s)` / `printf("%s")` ⇒ **渲染出的内嵌 NUL 被截断**：
//   实测 `print(bytes_to_str(hex_to_bytes("410042")))` 只写出 `A`（Go 的 `fmt.Print` 写 3 字节）。
//   命名口径：`_n(v, &len)` 出长度；`px_fmt_value(v)` 保留为包装（语义逐字节不变）。
static char* px_fmt_value_raw_n(LXValue v, int* out_len);
static char* px_fmt_value_raw(LXValue v) { int n; return px_fmt_value_raw_n(v, &n); }
static char* px_fmt_value_n(LXValue v, int* out_len) {
    // 缺陷 125（M145）：环保护（**路径**语义 ⇒ 共享而非环的对象照常完整渲染）
    if (px_is_container(v)) {
        if (px_path_has(&g_fmt_path, v.as.obj)) {
            RStrBuf b = {0};
            rsb_append(&b, "...", 3);
            return rsb_done_len(&b, out_len);
        }
        px_path_push(&g_fmt_path, v.as.obj);
        char* out = px_fmt_value_raw_n(v, out_len);
        px_path_pop(&g_fmt_path);
        return out;
    }
    return px_fmt_value_raw_n(v, out_len);
}
static char* px_fmt_value(LXValue v) { int n; return px_fmt_value_n(v, &n); }
static char* px_fmt_value_raw_n(LXValue v, int* out_len) {
    RStrBuf b = {0};
    switch (v.type) {
        case PX_NULL: rsb_append(&b, "null", 4); break;
        case PX_BOOL: rsb_append(&b, v.as.b ? "true" : "false", v.as.b ? 4 : 5); break;
        case PX_INT: { char t[32]; int n = snprintf(t, sizeof(t), "%lld", (long long)v.as.i); rsb_append(&b, t, n); break; }
        case PX_FLOAT: { const char* t = fmt_num(v); rsb_append(&b, t, (int)strlen(t)); break; }
        case PX_STR: rsb_append(&b, v.as.obj->as.str.data, v.as.obj->as.str.len); break;
        case PX_BYTES: { char t[64]; int n = snprintf(t, sizeof(t), "<bytes %d>", v.as.obj->as.str.len); rsb_append(&b, t, n); break; }
        case PX_LIST: {
            LXObject* o = v.as.obj;
            rsb_append(&b, "[", 1);
            for (int i = 0; i < o->as.list.len; i++) {
                if (i) rsb_append(&b, ", ", 2);
                int sn = 0;
                char* s = px_fmt_value_n(o->as.list.items[i], &sn);
                rsb_append(&b, s, sn);
                xfree(s);
            }
            rsb_append(&b, "]", 1);
            break;
        }
        case PX_TUPLE: {
            LXObject* o = v.as.obj;
            rsb_append(&b, "(", 1);
            for (int i = 0; i < o->as.tuple.len; i++) {
                if (i) rsb_append(&b, ", ", 2);
                int sn = 0;
                char* s = px_fmt_value_n(o->as.tuple.items[i], &sn);
                rsb_append(&b, s, sn);
                xfree(s);
            }
            rsb_append(&b, ")", 1);
            break;
        }
        case PX_DICT: {
            LXObject* o = v.as.obj;
            int n = o->as.dict.len;
            PxDisp* parts = n > 0 ? xmalloc((size_t)n * sizeof(PxDisp)) : NULL;
            for (int i = 0; i < n; i++) {
                int vlen = 0;
                char* vs = px_fmt_value_n(o->as.dict.vals[i], &vlen);
                int klen = (int)strlen(o->as.dict.keys[i]);
                parts[i].p = xmalloc((size_t)klen + vlen + 4);
                memcpy(parts[i].p, o->as.dict.keys[i], klen);
                parts[i].p[klen] = ':'; parts[i].p[klen + 1] = ' ';
                memcpy(parts[i].p + klen + 2, vs, vlen);
                parts[i].p[klen + vlen + 2] = 0;
                parts[i].len = klen + vlen + 2;
                xfree(vs);
            }
            if (n > 1) qsort(parts, (size_t)n, sizeof(PxDisp), px_cmp_disp);
            rsb_append(&b, "{", 1);
            for (int i = 0; i < n; i++) {
                if (i) rsb_append(&b, ", ", 2);
                rsb_append(&b, parts[i].p, parts[i].len);
                xfree(parts[i].p);
            }
            rsb_append(&b, "}", 1);
            xfree(parts);
            break;
        }
        case PX_FUNC: { char t[256]; int n = snprintf(t, sizeof(t), "<fn %s>", v.as.obj->as.func.name); rsb_append(&b, t, n); break; }
        case PX_NATIVE: { char t[256]; int n = snprintf(t, sizeof(t), "<builtin %s>", v.as.obj->as.native.name); rsb_append(&b, t, n); break; }
        case PX_STRUCT: { char t[256]; int n = snprintf(t, sizeof(t), "<struct %s>", v.as.obj->as.struct_inst.type_name); rsb_append(&b, t, n); break; }
        case PX_ENUM: { char t[256]; int n = snprintf(t, sizeof(t), "%s.%s", v.as.obj->as.enum_inst.type_name, v.as.obj->as.enum_inst.variant); rsb_append(&b, t, n); break; }
        case PX_RESULT: {
            LXObject* o = v.as.obj;
            int sn = 0;
            char* s = px_fmt_value_n(o->as.result.value, &sn);
            if (o->as.result.ok) {
                rsb_append(&b, "Ok(", 3);
                rsb_append(&b, s, sn);
                rsb_append(&b, ")", 1);
            } else {
                rsb_append(&b, "Err(", 4);
                rsb_append(&b, s, sn);
                rsb_append(&b, ")", 1);
            }
            xfree(s);
            break;
        }
        case PX_GEN: {
            LXObject* o = v.as.obj;
            char t[128];
            int n = snprintf(t, sizeof(t), "<gen %d items, cursor=%d>",
                             o->as.gen.list.as.obj->as.list.len, o->as.gen.cursor);
            rsb_append(&b, t, n);
            break;
        }
        default: rsb_append(&b, "?", 1); break;
    }
    return rsb_done_len(&b, out_len);
}

static char* escape_str(const char* s, int len) {
    char* out = xmalloc(len * 4 + 1);
    int j = 0;
    for (int i = 0; i < len; i++) {
        unsigned char c = s[i];
        switch (c) {
            case '\n': out[j++] = '\\'; out[j++] = 'n'; break;
            case '\t': out[j++] = '\\'; out[j++] = 't'; break;
            case '\r': out[j++] = '\\'; out[j++] = 'r'; break;
            case '"': out[j++] = '\\'; out[j++] = '"'; break;
            case '\\': out[j++] = '\\'; out[j++] = '\\'; break;
            default:
                if (c < 0x20) { snprintf(out + j, 5, "\\x%02x", c); j += 4; }
                else out[j++] = (char)c;
        }
    }
    out[j] = 0;
    return out;
}

void px_print_value(LXValue v, bool newline) {
    // M-B5：统一用 px_fmt_value（对齐 Rust fmt_value），保证 print 与 str() 容器渲染一致
    // M155（缺陷 150）：按**长度**写（fwrite）—— 此前 `printf("%s")` 在首个 0x00 处截断。
    int n = 0;
    char* s = px_fmt_value_n(v, &n);
    if (n > 0) fwrite(s, 1, (size_t)n, stdout);
    xfree(s);
    if (newline) fputc('\n', stdout);
}

char* px_to_string(LXValue v) {
    static char* buf = NULL;
    static int cap = 0;
    // 简化：针对 int/float 直接用 num_buf，字符串用转义缓冲
    if (v.type == PX_INT || v.type == PX_FLOAT) return (char*)fmt_num(v);
    if (v.type == PX_BOOL) return v.as.b ? (char*)"true" : (char*)"false";
    if (v.type == PX_NULL) return (char*)"null";
    if (v.type == PX_STR) return (char*)v.as.obj->as.str.data;
    // 其他类型：写临时文件流
    FILE* tmp = tmpfile();
    if (tmp) { px_print_value(v, false); fflush(tmp); }
    return (char*)"<object>";
}

// ==================== 运算 ====================

static double math_num(LXValue v, const char* fn);  // M122：数值内建类型校验（对齐 i_as_f64「需要数值」）

static double num_val(LXValue v) {
    return v.type == PX_INT ? (double)v.as.i : v.as.f;
}
static int64_t int_val(LXValue v) {
    if (v.type == PX_INT) return v.as.i;
    if (v.type == PX_FLOAT) return (int64_t)v.as.f;
    px_error("R1002: 期望整数，实际是 %s", px_type_name(v));
    return 0;
}

// ═══ M179（第 57 轮 · 缺陷 195/196）：算术族的**类型守卫** + 统一文案 ═══
// 修前：数值分支直接用 `num_val(a)`，而 num_val 是
//     `return v.type == PX_INT ? (double)v.as.i : v.as.f;`
//   ⇒ 非数值实参读的是 union 的 `as.f` —— 对 PX_STR 那是**对象指针的位模式**（UB）：
//     实测 `1.0 * "x"`：VM 轨 `6.905411902715e-310` / C 轨 `6.95199933934835e-310`
//     （**同一台机、同一份源码，两个不同的垃圾值**）；`1 / "x"` ⇒ `inf`、
//     `1.0 + "x"` ⇒ `1.0`、`2 ** "x"` ⇒ `1.0`。
//   而解释轨一直是响亮的「需要数值」⇒ 三轨分叉 **且** 编译轨静默坏值（最坏一类）。
// 修法：所有数值分支先判型（INT/FLOAT），文案统一
//   `R1002: 无法<运算>: <ta> <op> <tb>`（与解释轨 ival.px 同码同文）。
static inline int px_num_ok(LXValue v) { return v.type == PX_INT || v.type == PX_FLOAT; }
static void px_req_num2(LXValue a, LXValue b, const char* opname, const char* sym) {
    if (!px_num_ok(a) || !px_num_ok(b))
        px_error("R1002: 无法%s: %s %s %s", opname, px_type_name(a), sym, px_type_name(b));
}

LXValue px_add(LXValue a, LXValue b) {
    if (a.type == PX_STR && b.type == PX_STR) {
        int la = a.as.obj->as.str.len, lb = b.as.obj->as.str.len;
        char* d = xmalloc(la + lb + 1);
        memcpy(d, a.as.obj->as.str.data, la);
        memcpy(d + la, b.as.obj->as.str.data, lb);
        d[la + lb] = 0;
        LXValue r = px_str_len(d, la + lb);
        xfree(d);   // ISSUE28-B2 修复：中间缓冲 px_str_len 已深拷贝，用毕即还 slab（原泄漏每拼接 1 缓冲）
        return r;
    }
    if (a.type == PX_INT && b.type == PX_INT) return px_int(a.as.i + b.as.i);
    if (a.type == PX_FLOAT || b.type == PX_FLOAT) {
        px_req_num2(a, b, "相加", "+");   // M179：非数值 ⇒ 响亮（修前读 union 的 as.f = UB）
        return px_float(num_val(a) + num_val(b));
    }
    if (a.type == PX_LIST && b.type == PX_LIST) {
        LXValue r = px_list(a.as.obj->as.list.len + b.as.obj->as.list.len);
        px_root_push();
        PX_KEEP(r);   // M92 precise：拼接 list 跨 px_list_push 扩容分配
        LXObject* ro = r.as.obj; LXObject* ao = a.as.obj; LXObject* bo = b.as.obj;
        for (int i = 0; i < ao->as.list.len; i++) px_list_push(r, ao->as.list.items[i]);
        for (int i = 0; i < bo->as.list.len; i++) px_list_push(r, bo->as.list.items[i]);
        (void)ro;
        px_root_pop();
        return r;
    }
    px_error("R1002: 无法相加: %s + %s", px_type_name(a), px_type_name(b));
    return px_null();
}

LXValue px_sub(LXValue a, LXValue b) {
    if (a.type == PX_INT && b.type == PX_INT) return px_int(a.as.i - b.as.i);
    if (a.type == PX_FLOAT || b.type == PX_FLOAT) {
        px_req_num2(a, b, "相减", "-");
        return px_float(num_val(a) - num_val(b));
    }
    px_error("R1002: 无法相减: %s - %s", px_type_name(a), px_type_name(b));
    return px_null();
}

LXValue px_mul(LXValue a, LXValue b) {
    if (a.type == PX_INT && b.type == PX_INT) return px_int(a.as.i * b.as.i);
    if (a.type == PX_FLOAT || b.type == PX_FLOAT) {
        px_req_num2(a, b, "相乘", "*");
        return px_float(num_val(a) * num_val(b));
    }
    if (a.type == PX_STR && b.type == PX_INT) {
        int n = (int)b.as.i;
        int len = a.as.obj->as.str.len;
        char* d = xmalloc((size_t)len * (size_t)(n > 0 ? n : 0) + 1);
        for (int i = 0; i < n; i++) memcpy(d + i * len, a.as.obj->as.str.data, len);
        d[len * (n > 0 ? n : 0)] = 0;
        LXValue r = px_str_len(d, len * (n > 0 ? n : 0));
        xfree(d);   // ISSUE28-B2 修复：同上，重复串中间缓冲用毕即还
        return r;
    }
    px_error("R1002: 无法相乘: %s * %s", px_type_name(a), px_type_name(b));
    return px_null();
}

LXValue px_div(LXValue a, LXValue b) {
    // M148（第 30 轮，缺陷 118）：`/` 是**浮点除法** ⇒ 完全 IEEE-754 语义，
    //   永不报错：x/±0.0 → ±Inf、0.0/0.0 → NaN、溢出 → ±Inf、下溢 → ±0.0。
    //   与 Go 的**浮点**除法一致（`float64(x)/float64(0)` = ±Inf）。
    //   对齐 Go 的**整数**除零（panic `integer divide by zero`）由 `//`（px_idiv）
    //   与整数 `%`（px_mod 的整数分支）守护 —— 那两条仍然 px_error。
    //   修前这里对零除数一律 px_error 杀进程 ⇒ Go 侧「÷0 → Inf/NaN」这条路
    //   在语言里**表达不出来**（比值/余弦/成功率/均值都要手写零判断）。
    // M179：类型守卫 —— 修前 `1 / "x"` 走 num_val 的 UB 读出极小 double ⇒ **inf**（静默坏值）。
    px_req_num2(a, b, "相除", "/");
    return px_float(num_val(a) / num_val(b));
}

LXValue px_idiv(LXValue a, LXValue b) {
    // M-B5：对齐 Rust div_euclid / floor 语义
    //   int//int：欧几里得除法（余数非负 0<=r<|d|）-7//2=-4, 7//-2=-3, -7//-2=4
    //   float 参与：floor(af/bf) 转 int（-5.5//2=-3）
    // M148（缺陷 118）：零除数**仍然** px_error —— 对齐 Go 的整数除零 panic
    //   （`integer divide by zero`）；本语言的浮点除法走 `/`，那里才是 IEEE。
    //   浮点 `//` 在本语言无 Go 对应物，保持 fail-fast（不静默给 Inf/NaN）。
    // M179：类型守卫（修前非数值落到 int_val 的「期望整数」⇒ 与解释轨措辞不同）
    px_req_num2(a, b, "整除", "//");
    if (a.type == PX_FLOAT || b.type == PX_FLOAT) {
        double d = num_val(b);
        if (d == 0.0) px_error("R1006: 除零错误");
        return px_int((int64_t)floor(num_val(a) / d));
    }
    int64_t d = int_val(b);
    if (d == 0) px_error("R1006: 除零错误");
    int64_t n = int_val(a);
    int64_t r = n % d;
    if (r < 0) r += (d < 0 ? -d : d);  // 欧几里得余数（非负）
    return px_int((n - r) / d);        // 精确整除（对齐 div_euclid 商）
}

LXValue px_mod(LXValue a, LXValue b) {
    // M148（缺陷 118）：**浮点**取模 = `fmod`（IEEE），÷0 → NaN —— 对齐 Go
    //   `math.Mod(x, 0)` = NaN、`math.Mod(±Inf, y)` = NaN。注意 fmod 的余数取
    //   **被除数**符号（fmod(-5,3) = -2），与下面整数分支的**欧几里得**余数
    //   （-7 % 3 = 2，Rust rem_euclid 语义）**不是一回事**。
    // M179：类型守卫 + 除零统一为 `R1006: 除零错误`（修前「取模除零错误」）
    px_req_num2(a, b, "取模", "%");
    if (a.type == PX_FLOAT || b.type == PX_FLOAT) return px_float(fmod(num_val(a), num_val(b)));
    int64_t d = int_val(b);
    if (d == 0) px_error("R1006: 除零错误");
    // M-B5：对齐 Rust rem_euclid（余数非负）-7%3=2, 7%-3=1, -7%-3=2
    int64_t n = int_val(a);
    int64_t r = n % d;
    if (r < 0) r += (d < 0 ? -d : d);
    return px_int(r);
}

LXValue px_pow(LXValue a, LXValue b) {
    // M179：类型守卫（修前 `2 ** "x"` ⇒ pow(2, 垃圾) ⇒ `1.0`，静默坏值）
    px_req_num2(a, b, "幂运算", "**");
    if (a.type == PX_INT && b.type == PX_INT && b.as.i >= 0) {
        int64_t r = 1;
        for (int64_t i = 0; i < b.as.i; i++) r *= a.as.i;
        return px_int(r);
    }
    return px_float(pow(num_val(a), num_val(b)));
}

LXValue px_neg(LXValue a) {
    if (a.type == PX_INT) return px_int(-a.as.i);
    if (a.type == PX_FLOAT) return px_float(-a.as.f);
    px_error("R1002: 无法取负: -%s", px_type_name(a));
    return px_null();
}

// M179：按位运算的**整数守卫** —— 修前走 `int_val()`，它对 float **静默截断**
//   （`1.5 & 1` ⇒ `1 & 1` = 1），而解释轨一直报「此运算符要求整数操作数」。
//   现在两侧同码同文：`R1002: <运算> 需要整数，实际是 <t>`。
static int64_t px_req_int(LXValue v, const char* what) {
    if (v.type != PX_INT) px_error("R1002: %s 需要整数，实际是 %s", what, px_type_name(v));
    return v.as.i;
}

LXValue px_not(LXValue a) { return px_bool(!px_is_truthy(a)); }
LXValue px_bitnot(LXValue a) { return px_int(~px_req_int(a, "按位取反")); }
LXValue px_bitand(LXValue a, LXValue b) { return px_int(px_req_int(a, "按位与") & px_req_int(b, "按位与")); }
LXValue px_bitor(LXValue a, LXValue b) { return px_int(px_req_int(a, "按位或") | px_req_int(b, "按位或")); }
LXValue px_bitxor(LXValue a, LXValue b) { return px_int(px_req_int(a, "按位异或") ^ px_req_int(b, "按位异或")); }
LXValue px_shl(LXValue a, LXValue b) { return px_int(px_req_int(a, "左移") << px_req_int(b, "左移")); }
LXValue px_shr(LXValue a, LXValue b) { return px_int(px_req_int(a, "右移") >> px_req_int(b, "右移")); }
LXValue px_ushr(LXValue a, LXValue b) {
    // 无符号（逻辑）右移：按 uint64 解释后右移，再转回 int64。
    // 移位量对 64 取模（与解释器 wrapping_shr 一致；负移位量按无符号取模）。
    uint64_t v = (uint64_t)px_req_int(a, "无符号右移");
    uint64_t sh = (uint64_t)px_req_int(b, "无符号右移") & 63u;
    return px_int((int64_t)(v >> sh));
}

static int compare_values_raw(LXValue a, LXValue b);
static int compare_values(LXValue a, LXValue b) {
    // 快路径：任一侧不是容器 ⇒ 不可能成环（标量无引用）
    if (!px_is_container(a) || !px_is_container(b)) return compare_values_raw(a, b);
    int root = (g_eq_ctx == NULL);
    if (root) {
        g_eq_ctx = (PxEqCtx*)xmalloc(sizeof(PxEqCtx));
        g_eq_ctx->it = NULL; g_eq_ctx->n = 0; g_eq_ctx->cap = 0;
    }
    const LXObject* oa = a.as.obj;
    const LXObject* ob = b.as.obj;
    for (int i = 0; i < g_eq_ctx->n; i++) {
        if (g_eq_ctx->it[i].a == oa && g_eq_ctx->it[i].b == ob) {
            // 这一对正在（或已经）比较中 ⇒ 环上视为相等（DeepEqual 语义）
            if (root) px_eq_ctx_free();
            return 0;
        }
    }
    if (g_eq_ctx->n == g_eq_ctx->cap) {
        g_eq_ctx->cap = g_eq_ctx->cap ? g_eq_ctx->cap * 2 : 16;
        g_eq_ctx->it = (PxEqPair*)xrealloc(g_eq_ctx->it, (size_t)g_eq_ctx->cap * sizeof(PxEqPair));
    }
    g_eq_ctx->it[g_eq_ctx->n].a = oa;
    g_eq_ctx->it[g_eq_ctx->n].b = ob;
    g_eq_ctx->n++;
    int r = compare_values_raw(a, b);
    // 不弹出：与 Go reflect.DeepEqual 一致（已比较过的对象对再次出现即视为相等）
    if (root) px_eq_ctx_free();
    return r;
}

static int compare_values_raw(LXValue a, LXValue b) {
    // M154（第 36 轮）：同一性快路径 —— 同一对象必同值（PX_STR/PX_BYTES 的 data 恒不可变），
    //   故三态比较直接判 0。覆盖「次序比较」这一族（px_lt/le/gt/ge → compare_values_raw），
    //   它们没有 px_eq 那样的独立快路径；池化后 `c >= "0"` 常在**同一对象**上比较。
    if (a.type == b.type && (a.type == PX_STR || a.type == PX_BYTES) && a.as.obj == b.as.obj) return 0;
    if (a.type == PX_INT && b.type == PX_INT) {
        return a.as.i < b.as.i ? -1 : (a.as.i > b.as.i ? 1 : 0);
    }
    if ((a.type == PX_INT || a.type == PX_FLOAT) && (b.type == PX_INT || b.type == PX_FLOAT)) {
        double x = num_val(a), y = num_val(b);
        // M146（第 27 轮 · 缺陷 126 同族）：NaN 与任何值（**含自身**）不可比 ⇒ 返回**非零**。
        //   为什么：`px_eq` 对**两个标量**已改走直接浮点比较（IEEE 正确），但**容器**的相等
        //   仍经 compare_values 递归到元素 —— 旧的三态 else 分支会把 NaN 对判成"相等"，
        //   于是 `[NaN] == [NaN]` 为**真**；而 Go `reflect.DeepEqual`（M145 的对齐目标）
        //   用 `v1.Float() == v2.Float()` ⇒ 含 NaN 的容器**判不等**。
        //   三态比较器只能以"非零"表达"不可比"；符号只为给出确定性顺序，无数学含义。
        if (x != x) return (y != y) ? 2 : 1;
        if (y != y) return -1;
        return x < y ? -1 : (x > y ? 1 : 0);
    }
    if (a.type == PX_STR && b.type == PX_STR) {
        int la = a.as.obj->as.str.len, lb = b.as.obj->as.str.len;
        int m = la < lb ? la : lb;
        int c = memcmp(a.as.obj->as.str.data, b.as.obj->as.str.data, m);
        if (c != 0) return c < 0 ? -1 : 1;
        return la < lb ? -1 : (la > lb ? 1 : 0);
    }
    if (a.type == PX_BYTES && b.type == PX_BYTES) {
        int la = a.as.obj->as.str.len, lb = b.as.obj->as.str.len;
        int m = la < lb ? la : lb;
        int c = memcmp(a.as.obj->as.str.data, b.as.obj->as.str.data, m);
        if (c != 0) return c < 0 ? -1 : 1;
        return la < lb ? -1 : (la > lb ? 1 : 0);
    }
    if (a.type == PX_BOOL && b.type == PX_BOOL) {
        return a.as.b == b.as.b ? 0 : (a.as.b ? 1 : -1);
    }
    if (a.type == PX_ENUM && b.type == PX_ENUM) {
        return strcmp(a.as.obj->as.enum_inst.variant, b.as.obj->as.enum_inst.variant);
    }
    if ((a.type == PX_LIST || a.type == PX_TUPLE) && (b.type == PX_LIST || b.type == PX_TUPLE)) {
        int na = (a.type == PX_LIST) ? a.as.obj->as.list.len : a.as.obj->as.tuple.len;
        int nb = (b.type == PX_LIST) ? b.as.obj->as.list.len : b.as.obj->as.tuple.len;
        int m = na < nb ? na : nb;
        for (int i = 0; i < m; i++) {
            LXValue x = (a.type == PX_LIST) ? a.as.obj->as.list.items[i] : a.as.obj->as.tuple.items[i];
            LXValue y = (b.type == PX_LIST) ? b.as.obj->as.list.items[i] : b.as.obj->as.tuple.items[i];
            int c = compare_values(x, y);
            if (c != 0) return c;
        }
        return na < nb ? -1 : (na > nb ? 1 : 0);
    }
    if (a.type == PX_NULL && b.type == PX_NULL) return 0;
    // M-B5：dict 相等——键集合相同 + 每键值递归相等（对齐 Rust HashMap PartialEq；
    // 原缺此分支导致 dict == 恒 true，`{"a":1} == {"a":2}` 错误）
    if (a.type == PX_DICT && b.type == PX_DICT) {
        LXObject* oa = a.as.obj;
        LXObject* ob = b.as.obj;
        if (oa->as.dict.len != ob->as.dict.len)
            return oa->as.dict.len < ob->as.dict.len ? -1 : 1;
        for (int i = 0; i < oa->as.dict.len; i++) {
            const char* k = oa->as.dict.keys[i];
            LXValue* bv = NULL;
            for (int j = 0; j < ob->as.dict.len; j++) {
                if (strcmp(ob->as.dict.keys[j], k) == 0) { bv = &ob->as.dict.vals[j]; break; }
            }
            if (!bv) return 1;  // b 缺键 → a > b（不相等）
            int c = compare_values(oa->as.dict.vals[i], *bv);
            if (c != 0) return c;
        }
        return 0;
    }
    // M39：Result 相等——ok 标志相同 + 载荷递归比较
    if (a.type == PX_RESULT && b.type == PX_RESULT) {
        if (a.as.obj->as.result.ok != b.as.obj->as.result.ok) return a.as.obj->as.result.ok ? 1 : -1;
        return compare_values(a.as.obj->as.result.value, b.as.obj->as.result.value);
    }
    // 默认按类型名比较，保证可比性
    return strcmp(px_type_name(a), px_type_name(b));
}

// M146（第 27 轮 · 缺陷 126）：**数值比较的 NaN 语义**（IEEE754 / Go）——
//   `compare_values` 是**三态**比较器（-1/0/1），它**无法表达** NaN 的
//   「既不小于、也不等于、也不大于」。旧实现让 px_ne / px_le / px_ge 借道三态，
//   NaN 落进 `x < y ? -1 : (x > y ? 1 : 0)` 的 **else 分支**被当成**相等**：
//     `NaN != NaN` → **假**（Go：真）· `NaN <= 1.0` → **真**（Go：假）·
//     `NaN >= 1.0` → **真**（Go：假）。Go/IEEE 的口径是**四路皆假**（只有 `!=` 为真）。
//   为什么以前没暴露：语言里**造不出 NaN**（M143 只给了 float32 的位模式族，64 位的一直缺）
//   ⇒ 这条通路对用户不可达。M146 补上 `bits_to_float64` 后**当轮就被 m146 门照出**。
//   修法：数值情形**直接**用 C 的浮点比较（IEEE 语义原生正确）；非数值情形仍走
//   `compare_values` ⇒ 容器 / 字符串 / 枚举的**全序**（`sorted` / `sort_by` / `min` / `max`）
//   语义**零变化**。
//   ⚠️ INT-INT 保留**整数**比较（不绕 double）：否则 >2^53 的大整数会丢精度 ——
//      `9007199254740993 == 9007199254740992` 会误判为真。
static int px_is_num(LXValue v) { return v.type == PX_INT || v.type == PX_FLOAT; }

LXValue px_eq(LXValue a, LXValue b) {
    // 数值跨类型相等：1 == 1.0
    if (a.type == PX_INT && b.type == PX_INT) return px_bool(a.as.i == b.as.i);
    if (px_is_num(a) && px_is_num(b)) return px_bool(num_val(a) == num_val(b));
    // M154（第 36 轮）：串类快路径 —— 同对象 ⇒ 相等（PX_STR/PX_BYTES 的 data 恒不可变）；
    //   长度不同 ⇒ 不等；其余才 memcmp。M153/M154 的池化（字面量 / ASCII 单字符 /
    //   2..4 字节 rune）让「同一对象」成为高频情形（`c == "/"`、`tok == "let"`、
    //   `peek() == ""`），旧路径每次都要经 compare_values → compare_values_raw 再做
    //   一次全串 memcmp（实测 px_eq 分支占整图编译 7.0% 采样 + memcmp 4.0%）。
    if (a.type == b.type && (a.type == PX_STR || a.type == PX_BYTES)) {
        if (a.as.obj == b.as.obj) return px_bool(true);
        int la = a.as.obj->as.str.len, lb = b.as.obj->as.str.len;
        if (la != lb) return px_bool(false);
        return px_bool(memcmp(a.as.obj->as.str.data, b.as.obj->as.str.data, (size_t)la) == 0);
    }
    return px_bool(compare_values(a, b) == 0);
}
LXValue px_ne(LXValue a, LXValue b) {
    if (a.type == PX_INT && b.type == PX_INT) return px_bool(a.as.i != b.as.i);
    if (px_is_num(a) && px_is_num(b)) return px_bool(num_val(a) != num_val(b));
    // M154：与 px_eq 同构的串类快路径
    if (a.type == b.type && (a.type == PX_STR || a.type == PX_BYTES)) {
        if (a.as.obj == b.as.obj) return px_bool(false);
        int la = a.as.obj->as.str.len, lb = b.as.obj->as.str.len;
        if (la != lb) return px_bool(true);
        return px_bool(memcmp(a.as.obj->as.str.data, b.as.obj->as.str.data, (size_t)la) != 0);
    }
    return px_bool(compare_values(a, b) != 0);
}
// M179：**次序比较**的类型守卫 —— 只允许「双数值」或「同类型」。
//   修前 `px_lt/le/gt/ge` 的兜底走 `compare_values`，而它的**默认分支**是
//     `strcmp(px_type_name(a), px_type_name(b))`（「保证可比性」）
//   ⇒ `1 < "x"` 在编译轨**静默给 true**（按类型名字典序），而解释轨报
//   `R1002 比较不支持: int vs string`。
//   取舍（§17 的「响亮优于静默」）：**用户面的次序比较**要求可比值，
//   跨型 ⇒ `R1002: 无法比较: <ta> vs <tb>`；而 `sorted`/`min`/`max` 用的
//   **内部比较器**仍是全序（`compare_values`，跨型按类型名）——
//   排序需要全序才可能确定，这条在 §17.13 单独写明。
static void px_req_cmp(LXValue a, LXValue b) {
    if (px_num_ok(a) && px_num_ok(b)) return;   // int/float 互通
    if (a.type == b.type) return;               // 同类型（str/bytes/bool/list/dict…）
    px_error("R1002: 无法比较: %s vs %s", px_type_name(a), px_type_name(b));
}

LXValue px_lt(LXValue a, LXValue b) {
    if (a.type == PX_INT && b.type == PX_INT) return px_bool(a.as.i < b.as.i);
    if (px_is_num(a) && px_is_num(b)) return px_bool(num_val(a) < num_val(b));
    px_req_cmp(a, b);
    return px_bool(compare_values(a, b) < 0);
}
LXValue px_le(LXValue a, LXValue b) {
    if (a.type == PX_INT && b.type == PX_INT) return px_bool(a.as.i <= b.as.i);
    if (px_is_num(a) && px_is_num(b)) return px_bool(num_val(a) <= num_val(b));
    px_req_cmp(a, b);
    return px_bool(compare_values(a, b) <= 0);
}
LXValue px_gt(LXValue a, LXValue b) {
    if (a.type == PX_INT && b.type == PX_INT) return px_bool(a.as.i > b.as.i);
    if (px_is_num(a) && px_is_num(b)) return px_bool(num_val(a) > num_val(b));
    px_req_cmp(a, b);
    return px_bool(compare_values(a, b) > 0);
}
LXValue px_ge(LXValue a, LXValue b) {
    if (a.type == PX_INT && b.type == PX_INT) return px_bool(a.as.i >= b.as.i);
    if (px_is_num(a) && px_is_num(b)) return px_bool(num_val(a) >= num_val(b));
    px_req_cmp(a, b);
    return px_bool(compare_values(a, b) >= 0);
}

LXValue px_and(LXValue a, LXValue b) {
    return px_is_truthy(a) ? b : a;  // 短路由 codegen 保证
}
LXValue px_or(LXValue a, LXValue b) {
    return px_is_truthy(a) ? a : b;
}

// ==================== 容器操作 ====================

// M179：索引位置的**整数守卫** —— 修前 `int_val(idx)` 对 float **静默截断**
//   （`l[1.9]` ⇒ `l[1]`），而解释轨 `i_as_index` 一直要求 int
//   （`R1002 索引必须是整数`）⇒ 三轨分叉 + 编译轨静默取错元素。
static int64_t px_req_int_idx(LXValue v) {
    if (v.type != PX_INT) px_error("R1002: 索引必须是整数，实际是 %s", px_type_name(v));
    return v.as.i;
}

LXValue px_index(LXValue obj, LXValue idx) {
    if (obj.type == PX_GEN) {
        // M34：惰性生成器先物化剩余（索引语义需要全量结果）
        if (obj.as.obj->as.gen.is_lazy) px_gen_materialize(obj.as.obj);
        obj = obj.as.obj->as.gen.list;
    }
    if (obj.type == PX_LIST) {
        int i = (int)px_req_int_idx(idx);
        int len = obj.as.obj->as.list.len;
        if (i < 0) i += len;
        if (i < 0 || i >= len) px_error("R1003: 索引越界: %d (len=%d)", i, len);
        return obj.as.obj->as.list.items[i];
    }
    if (obj.type == PX_TUPLE) {
        int i = (int)px_req_int_idx(idx);
        int len = obj.as.obj->as.tuple.len;
        if (i < 0) i += len;
        if (i < 0 || i >= len) px_error("R1003: 索引越界: %d (len=%d)", i, len);
        return obj.as.obj->as.tuple.items[i];
    }
    if (obj.type == PX_STR) {
        // M-B2 修复：字符串索引按 UTF-8 字符（与解释器字符语义、px_len 一致；原按字节导致中文错位）
        // M89-S3-C1 补漏（M83-S1 GAP-STR-1-B1）：索引越界须用 str.len 字节边界（strlen 在
        //   内嵌 NUL 处截断 → 含 \u{0} 的串 len()=N 但 s[0] 判越界，自举编译 pxlexer.px 崩）
        int i = (int)px_req_int_idx(idx);
        int ulen = px_str_rune_len(obj.as.obj);   // M106-S2：惰性 rune 计数（首次 O(n)，之后摊还 O(1)）
        if (i < 0) i += ulen;
        if (i < 0 || i >= ulen) px_error("R1003: 索引越界: %d (len=%d)", i, ulen);
        const unsigned char* base = (const unsigned char*)obj.as.obj->as.str.data;
        const unsigned char* p;
        int* offs = px_str_offs_get(obj.as.obj);  // M106-S2：≥1KB 的串建一次偏移表
        int ocnt = offs ? __atomic_load_n(&obj.as.obj->as.str.offs_cnt, __ATOMIC_RELAXED) : 0;
        if (offs && i < ocnt) {
            p = base + offs[i];                   // 第 i 个 rune 的起始字节 —— O(1)
        } else {
            // 回落原线性走查（小串未建表；或 i ≥ 建表步数——仅畸形 UTF-8 可达）：
            //   步进规则与建表完全一致，故 offs[i] 与"走 i 步"结果逐字节相同，此处纯为等义兜底。
            p = base;
            int count = 0;
            while (count < i) { p += px_utf8_step(p, (int)(base + obj.as.obj->as.str.len - p)); count++; }
        }
        unsigned char c0 = *p;
        // 缺陷 111/112（M142）：字符长度与 **offs 表 / len() 同一判定**（px_utf8_step），
        //   clen 由构造保证 ≤ 剩余字节 ⇒ 原「按声称长度 memcpy 越读尾部」不再可能。
        int clen = px_utf8_step(p, (int)(base + obj.as.obj->as.str.len - p));
        char buf[8] = {0};
        memcpy(buf, p, clen);
        // M89-S3-C1 补漏：单字符结果须按 clen 带长构造（px_str 用 strlen → 取到 NUL 字符时
        //   截断成空串，与 compare_values 的 memcmp+len 字节安全语义不一致）
        if (clen == 1) return px_char1((unsigned char)buf[0]);   // M153：ASCII 单字符串表
        return px_rune_pool(buf, clen);                          // M154：多字节 rune 短串池（2..4 字节）
    }
    if (obj.type == PX_DICT) {
        if (idx.type == PX_STR) {
            // M116（qg-issue 71 D2）：**缺键 = 运行时错误**，与解释器轨 R1008 同口径。
            //   此前 C/VM 轨静默返回 null，而 `pxi` 直接抛 R1008 杀进程 —— 同一份源码
            //   两轨行为不同（违背 docs/MINI_SUBSET §五 双模式一致契约，也与
            //   docs/M65_PLAN.md 记载的「R1008 + .has() 守卫」口径相悖）。
            //   实测被它坑过：移植 ws-center 时 `str(r["role"])`（键缺失）在编译轨下
            //   得到字符串 "null" 并被**写进数据库**，解释轨则当场报错。
            const char* k = idx.as.obj->as.str.data;
            if (!px_dict_has(obj, k))
                px_error("R1008: 字典没有键 '%s'", k);
            return px_dict_get(obj, k);
        }
        // M164（第 50 轮 · 缺陷 170）：**删掉 M37 的「dict 整数索引 → 第 i 个键」分支**。
        //   那个位置语义本是为 `for k in d`（用 px_len/px_index 遍历）开的后门，却同时
        //   成了用户可见的 `d[0]` —— 于是解释轨 `d[0]` 报 R1002 而 VM/C 轨返回第 0 个键
        //   （三轨分叉，且 C 轨用户会把「第 i 个键」误读成「第 i 个元素」）。
        //   现在迭代机制走**独立入口** px_iter_at（见下），用户索引一律严格。
        px_error("R1002: 字典索引键必须是字符串");
    }
    px_error("R1002: 此类型不支持索引: %s", px_type_name(obj));
    return px_null();
}

// ==================== M164（第 50 轮 · 缺陷 170）：迭代专用索引 ====================
// 语义：**dict → 第 i 个键**（与解释轨 `i_iter` 的 `v.keys()` 逐位对应，插入序）；
//   其余类型 → 与 px_index 完全一致（list/tuple/string/bytes 的整数索引）。
// 为什么单列一个入口：`for k in d` 需要「第 i 个键」，而 `d[i]` 必须是**错误**。
//   两者此前共用 px_index ⇒ 位置语义从迭代机制漏进用户语言面。拆开后：
//     · C 轨  cg_stmt For / cg_expr 推导式  → px_iter_at
//     · VM 轨 PXOP_ITERAT（for / 推导式）  → px_iter_at
//     · 用户 `d[i]`：三轨一律 R1002「字典索引键必须是字符串」
LXValue px_iter_at(LXValue obj, LXValue idx) {
    if (obj.type == PX_DICT) {
        if (idx.type != PX_INT)
            px_error("R1002: 字典索引键必须是字符串");
        LXObject* o = obj.as.obj;
        int i = (int)idx.as.i;
        if (i < 0) i += o->as.dict.len;
        if (i >= 0 && i < o->as.dict.len)
            return px_str(o->as.dict.keys[i]);
        px_error("R1003: 索引越界: %d (len=%d)", i, o->as.dict.len);
    }
    return px_index(obj, idx);
}

// ============ M166（第 52 轮 · 缺陷 176）：迭代长度校验 ============
// 语义：for-in / 推导式在**进入循环时快照长度**（= 当时的 `len(迭代源)`）；迭代过程中被迭代
//   容器的长度**必须恒定**，增或减一律 R1003（同码同文，三轨一致）。
// 修前实测（同一份源码）：
//   · `for x in l { l.append(9) }`   解释/C 轨按活长度多迭代（泄漏新元素）vs VM 轨按快照
//   · `for x in l { l.pop() }`       VM 轨越界 rc=1 vs 解释/C 轨正常退出
//   · `for k in d { d.set(...) }`    解释/VM 轨按键快照 vs C 轨按活长度（迭代到新键）
//   · `for k in d { d.remove(...) }` VM 轨越界 rc=1 vs 解释轨键快照 / C 轨中途停
// ⇒ 四类分歧。为什么不选「活长度」或「静默跳过」：前者三轨难同（且「边遍历边删」的结果
//   依赖容器实现），后者是**静默的错**。本项目一贯口径 = 响亮优于静默（R1008 / M163 键严格化）。
// 「遍历时过滤/收集」的推荐写法：`let ks = d.keys()` 先快照，或新建结果容器。
void px_iter_ck(LXValue obj, int n0) {
    int n1 = px_len(obj);
    if (n1 != n0)
        px_error("R1003: 迭代期间被迭代容器长度变化: %d → %d", n0, n1);
}

// ============ M167（第 53 轮 · 缺陷 180）：解包（destructuring）校验 ============
// 语义（三轨一条真相）：变量个数 N ≥ 2 时，被解包值必须是 **list/tuple 且长度恰为 N**；
//   否则 R1002，同码同文（解释轨 i_unpack_bind / VM 轨 PXOP_UNPACKCK / C 轨 px_unpack_ck）：
//     · 非 list/tuple → `R1002 解包需要 list/tuple，实际是 <t>`
//     · 长度 ≠ N      → `R1002 解包需要 N 个元素，实际是 M`
// 修前实测（同一份源码**三轨四种行为**）：
//   · `[k for k, v in d]`（元素是字符串键）：解释轨 `R1002 推导式解包需要 list/tuple…`，
//     VM/C 轨 `R1003 字符串索引越界: 1`（码与文都不同）
//   · `[a for a, b in [[1], [2, 3]]]`（长度不足）：解释轨**静默给 null**（错值！），
//     VM 轨 `列表索引越界: 1 (len=1)`（无 R1003 前缀）、C 轨 `R1003: 列表索引越界: 1 (len=1)`
// 为什么严格（长度必须相等，不做「缺位给 null」也不做「多的忽略」）：① 缺位给 null 是
//   **静默的错值**（M116/M120 静默 null 族、M163 键严格化、M166 长度变化报错 —— 同一哲学：
//   响亮优于静默）；② 三轨本已四种行为，只有「严格」能收敛为一条真相；③ 与 Python 的解包
//   （`ValueError: not enough values to unpack` / `too many values to unpack`）同向。
void px_unpack_ck(LXValue item, int n) {
    if (item.type != PX_LIST && item.type != PX_TUPLE)
        px_error("R1002: 解包需要 list/tuple，实际是 %s", px_type_name(item));
    int len = px_len(item);
    if (len != n)
        px_error("R1002: 解包需要 %d 个元素，实际是 %d", n, len);
}

// ==================== M21/M24 切片 a[start:end] / a[start:end:step] ====================
// start/end/step 为 PX_NULL 表示省略；负索引从尾部算；越界 clamp；step<0 反向，step=0 报错。
// str 按 UTF-8 字符切（与解释器字符语义一致，中文正常）；list/tuple/bytes 取元素返回新对象。

// M24：切片边界调整（Python slice_adjust 语义，与解释器 Rust adjust 逐字节一致）
// v<0 先 +len；再按步长方向 clamp：step>0 → [0,len]，step<0 → [-1,len-1]
static int64_t px_slice_adjust(int64_t v, int len, int64_t step) {
    if (v < 0) v += len;
    if (step > 0) {
        if (v < 0) v = 0;
        if (v > len) v = len;
    } else {
        if (v < -1) v = -1;
        if (v > len - 1) v = len - 1;
    }
    return v;
}

LXValue px_slice(LXValue obj, LXValue start, LXValue end, LXValue step) {
    // Python slice.indices(len) 语义（与解释器 interp.rs slice_indices 逐字节一致）：
    //   step 缺省=1，step=0 报错；step>0 时 start 缺省 0、end 缺省 len；
    //   step<0 时 start 缺省 len-1、end 缺省 -1（取到索引 0 含）；
    //   负边界 +len 后按步长方向 clamp。
    int s_missing = start.type == PX_NULL;
    int e_missing = end.type == PX_NULL;
    int k_missing = step.type == PX_NULL;
    int64_t k_in = k_missing ? 1 : int_val(step);
    if (k_in == 0) px_error("切片步长不能为 0");

    int len, kind = 0; // 0=list 1=tuple 2=str 3=bytes
    if (obj.type == PX_LIST) { kind = 0; len = obj.as.obj->as.list.len; }
    else if (obj.type == PX_TUPLE) { kind = 1; len = obj.as.obj->as.tuple.len; }
    else if (obj.type == PX_STR) { kind = 2; len = px_str_rune_len(obj.as.obj); }   // M106-S2：惰性缓存
    else if (obj.type == PX_BYTES) { kind = 3; len = obj.as.obj->as.str.len; }
    else { px_error("无法切片: %s", px_type_name(obj)); return px_null(); }

    int64_t s = s_missing ? (k_in < 0 ? len - 1 : 0) : px_slice_adjust(int_val(start), len, k_in);
    int64_t e = e_missing ? (k_in < 0 ? -1 : len) : px_slice_adjust(int_val(end), len, k_in);

    // 元素个数
    int n = 0;
    if (k_in > 0) { for (int64_t i = s; i < e; i += k_in) n++; }
    else { for (int64_t i = s; i > e; i += k_in) n++; }

    if (kind == 0) { // list
        LXValue r = px_list(n);
        px_root_push();
        PX_KEEP(r);   // M92 precise：切片 list 跨 px_list_push 扩容分配
        if (k_in > 0) { for (int64_t i = s; i < e; i += k_in) px_list_push(r, obj.as.obj->as.list.items[(int)i]); }
        else { for (int64_t i = s; i > e; i += k_in) px_list_push(r, obj.as.obj->as.list.items[(int)i]); }
        px_root_pop();
        return r;
    }
    if (kind == 1) { // tuple
        LXValue* items = xmalloc(sizeof(LXValue) * (size_t)(n > 0 ? n : 1));
        int j = 0;
        if (k_in > 0) { for (int64_t i = s; i < e; i += k_in) items[j++] = obj.as.obj->as.tuple.items[(int)i]; }
        else { for (int64_t i = s; i > e; i += k_in) items[j++] = obj.as.obj->as.tuple.items[(int)i]; }
        LXValue r = px_tuple(items, j);
        xfree(items);
        return r;
    }
    if (kind == 3) { // bytes（按字节）
        const char* data = obj.as.obj->as.str.data;
        char* out = xmalloc((size_t)(n + 1));
        int j = 0;
        if (k_in > 0) { for (int64_t i = s; i < e; i += k_in) out[j++] = data[(int)i]; }
        else { for (int64_t i = s; i > e; i += k_in) out[j++] = data[(int)i]; }
        LXValue r = px_bytes_len(out, j);
        xfree(out);
        return r;
    }
    // str：按 UTF-8 字符收集（预构建字符字节偏移表）
    //   缺陷 111（M142）：此处原用「走 1 字节再跳过续字节」的**第三种**字符定义 ⇒
    //   与 px_index / len() 在畸形 UTF-8 上互相矛盾（同一串 s[1] 与 s[1:2] 不同）。
    //   现改为与 px_index / len() **同一判定**（px_utf8_step）⇒ offs[len] == blen
    //   （覆盖全部字节，无字节被"吞掉"），合法 UTF-8 下结果不变。
    const char* data = obj.as.obj->as.str.data;
    int blen = obj.as.obj->as.str.len;
    int* offs = xmalloc(sizeof(int) * (size_t)(len + 1));
    int boff = 0;
    offs[0] = 0;
    for (int c = 0; c < len; c++) {
        boff += px_utf8_step((const unsigned char*)data + boff, blen - boff);
        offs[c + 1] = boff;
    }
    int total = 0;
    if (k_in > 0) { for (int64_t i = s; i < e; i += k_in) total += offs[(int)i + 1] - offs[(int)i]; }
    else { for (int64_t i = s; i > e; i += k_in) total += offs[(int)i + 1] - offs[(int)i]; }
    char* out = xmalloc((size_t)(total + 1));
    int oi = 0;
    if (k_in > 0) {
        for (int64_t i = s; i < e; i += k_in) {
            int cl = offs[(int)i + 1] - offs[(int)i];
            memcpy(out + oi, data + offs[(int)i], (size_t)cl);
            oi += cl;
        }
    } else {
        for (int64_t i = s; i > e; i += k_in) {
            int cl = offs[(int)i + 1] - offs[(int)i];
            memcpy(out + oi, data + offs[(int)i], (size_t)cl);
            oi += cl;
        }
    }
    out[oi] = 0;
    LXValue r = px_str_len(out, oi);
    xfree(out);
    xfree(offs);
    return r;
}

void px_index_set(LXValue obj, LXValue idx, LXValue val) {
    if (obj.type == PX_LIST) {
        int i = (int)px_req_int_idx(idx);
        int len = obj.as.obj->as.list.len;
        if (i < 0) i += len;
        if (i < 0 || i >= len) px_error("R1003: 索引越界: %d (len=%d)", i, len);
        // M11：与 GC 互斥（见 px_list_push 注释）。注意：必须先拿锁再屏蔽信号——
        // 等锁期间不能屏蔽 SIG_GC_STOP，否则 GC 无法暂停该线程（信号 pending），
        // 导致 stop-the-world 空转/降级/漏扫描。
        sigset_t old;
        pthread_mutex_lock(&g_gc_mu);
        gc_block_stop(&old);
        obj.as.obj->as.list.items[i] = val;
        gc_unblock_stop(&old);
        pthread_mutex_unlock(&g_gc_mu);
        return;
    }
    if (obj.type == PX_DICT) {
        if (idx.type == PX_STR) {
            px_dict_set(obj, idx.as.obj->as.str.data, val);   // 内部已互斥
            return;
        }
        px_error("R1002: 字典索引键必须是字符串");
    }
    px_error("R1002: 此类型不支持索引赋值: %s", px_type_name(obj));
}

LXValue px_field(LXValue obj, const char* name) {
    if (obj.type == PX_STRUCT) {
        LXObject* o = obj.as.obj;
        for (int i = 0; i < o->as.struct_inst.nfields; i++) {
            if (strcmp(o->as.struct_inst.fnames[i], name) == 0) return o->as.struct_inst.fvals[i];
        }
        px_error("R1008: 结构体没有字段 '%s'", name);
    }
    if (obj.type == PX_DICT) {
        // M116（qg-issue 71 D2）：同 px_index —— 缺键报 R1008（对齐解释器 i_field）
        if (!px_dict_has(obj, name)) px_error("R1008: 字典没有键 '%s'", name);
        return px_dict_get(obj, name);
    }
    px_error("R1007: 类型 %s 没有字段 '%s'", px_type_name(obj), name);
    return px_null();
}

void px_field_set(LXValue obj, const char* name, LXValue val) {
    if (obj.type == PX_STRUCT) {
        LXObject* o = obj.as.obj;
        for (int i = 0; i < o->as.struct_inst.nfields; i++) {
            if (strcmp(o->as.struct_inst.fnames[i], name) == 0) {
                // M11：与 GC 互斥（见 px_list_push 注释）
                sigset_t old;
                pthread_mutex_lock(&g_gc_mu);
                gc_block_stop(&old);
                o->as.struct_inst.fvals[i] = val;
                gc_unblock_stop(&old);
                pthread_mutex_unlock(&g_gc_mu);
                return;
            }
        }
        px_error("R1008: 结构体没有字段 '%s'", name);
    }
    px_error("R1002: 类型 %s 不支持字段赋值: '%s'", px_type_name(obj), name);
}

// M127 及以前的锁内扩容路径（兜底 + `PX_GROW_RETRY_MAX=0` 对照用）。与历史实现逐字一致。
static void px_list_push_locked(LXValue list, LXValue val) {
    LXObject* o = list.as.obj;
    sigset_t old;
    pthread_mutex_lock(&g_gc_mu);
    gc_block_stop(&old);
    if (o->as.list.len >= o->as.list.cap) {
        o->as.list.cap *= 2;
        o->as.list.items = xrealloc(o->as.list.items, sizeof(LXValue) * o->as.list.cap);
    }
    o->as.list.items[o->as.list.len++] = val;
    gc_unblock_stop(&old);
    pthread_mutex_unlock(&g_gc_mu);
}

void px_list_push(LXValue list, LXValue val) {
    LXObject* o = list.as.obj;
    // M11：对象结构修改与 GC 标记/清扫通过 g_gc_mu 互斥（消除数据竞争）。
    // 必须先拿锁再屏蔽信号：等锁期间若屏蔽 SIG_GC_STOP，GC 无法暂停本线程
    // （信号 pending），导致 stop-the-world 空转、GC 降级、栈漏扫描（use-after-free）。
    // 持锁后屏蔽：持锁期间 GC 主线程在等锁（不会发信号），不会被挂起。
    // M128：扩容分配移到临界区外（两阶段，见本文件 M128 段）—— 锁内只做指针发布。
    int maxr = m128_retry_max();
    int retry = 0;
    void* spare = NULL;          // 备好的新 items 数组（本线程私有、未发布 ⇒ GC 不可见）
    int spare_cap = 0;
    sigset_t old;
    for (;;) {
        if (retry >= maxr) {     // 兜底 / 对照：锁内扩容（M127 及以前行为）
            if (spare) xfree(spare);
            px_list_push_locked(list, val);
            return;
        }
        // —— 阶段 A（临界区外，可失败）——
        int len0 = o->as.list.len, cap0 = o->as.list.cap;   // 无锁快照（仅用于预估容量）
        if (!spare && len0 >= cap0) {
            int ncap = cap0 ? cap0 * 2 : 8;
            if (ncap < len0 + M128_GROW_SLACK) ncap = len0 + M128_GROW_SLACK;
            spare = m128_alloc(sizeof(LXValue) * (size_t)ncap, "list_grow");
            spare_cap = ncap;
        }
        // —— 阶段 B（临界区内，不可失败）——
        pthread_mutex_lock(&g_gc_mu);
        gc_block_stop(&old);
        int len = o->as.list.len;
        if (len < o->as.list.cap) {          // 仍有空槽：直接追加
            o->as.list.items[len] = val;
            o->as.list.len = len + 1;
            gc_unblock_stop(&old);
            pthread_mutex_unlock(&g_gc_mu);
            if (spare) xfree(spare);         // 备货未用：锁外释放（从未发布 ⇒ 安全）
            return;
        }
        if (spare && spare_cap > len) {      // 发布备货（只换指针，无分配）
            if (len > 0) memcpy(spare, o->as.list.items, sizeof(LXValue) * (size_t)len);
            void* oldbuf = o->as.list.items;
            o->as.list.items = (LXValue*)spare;
            o->as.list.cap = spare_cap;
            o->as.list.items[len] = val;
            o->as.list.len = len + 1;
            spare = NULL;
            if (oldbuf) xfree(oldbuf);       // 旧数组：锁内释放（同 xrealloc 语义）
            gc_unblock_stop(&old);
            pthread_mutex_unlock(&g_gc_mu);
            return;
        }
        gc_unblock_stop(&old);
        pthread_mutex_unlock(&g_gc_mu);
        if (spare) { xfree(spare); spare = NULL; spare_cap = 0; }   // 备货不足 ⇒ 丢弃重来
        retry++;
    }
}

// M127 及以前的锁内扩容 + 锁内键副本路径（兜底 + `PX_GROW_RETRY_MAX=0` 对照用）。与历史实现逐字一致。
static void px_dict_set_locked(LXValue dict, const char* key, LXValue val) {
    LXObject* o = dict.as.obj;
    sigset_t old;
    pthread_mutex_lock(&g_gc_mu);
    gc_block_stop(&old);
    for (int i = 0; i < o->as.dict.len; i++) {
        if (strcmp(o->as.dict.keys[i], key) == 0) {
            o->as.dict.vals[i] = val;
            gc_unblock_stop(&old);
            pthread_mutex_unlock(&g_gc_mu);
            return;
        }
    }
    if (o->as.dict.len >= o->as.dict.cap) {
        o->as.dict.cap *= 2;
        o->as.dict.keys = xrealloc(o->as.dict.keys, sizeof(char*) * o->as.dict.cap);
        o->as.dict.vals = xrealloc(o->as.dict.vals, sizeof(LXValue) * o->as.dict.cap);
    }
    o->as.dict.keys[o->as.dict.len] = xstrdup(key);
    o->as.dict.vals[o->as.dict.len] = val;
    o->as.dict.len++;
    gc_unblock_stop(&old);
    pthread_mutex_unlock(&g_gc_mu);
}

void px_dict_set(LXValue dict, const char* key, LXValue val) {
    LXObject* o = dict.as.obj;
    // M11：与 GC 通过 g_gc_mu 互斥（见 px_list_push 注释）。先拿锁再屏蔽信号。
    // M128：键副本与扩容数组都在临界区外备好（两阶段，见本文件 M128 段）——锁内只做指针发布。
    int maxr = m128_retry_max();
    int retry = 0;
    char** spare_keys = NULL;    // 备好的新 keys 数组（未发布 ⇒ GC 不可见）
    LXValue* spare_vals = NULL;
    int spare_cap = 0;
    char* spare_key = NULL;      // 备好的键副本（只在「已判定键缺失」后才备，避免热路径多做一次分配）
    int absent = 0;              // 上一轮锁内判定：键缺失
    int absent_len = -1;         // 判定时的 len —— 无删除 ⇒ 键集单调，len 未变即可免重扫（O(1) 复核）
    sigset_t old;
    for (;;) {
        if (retry >= maxr) {     // 兜底 / 对照：锁内扩容 + 锁内 xstrdup（M127 及以前行为）
            if (spare_keys) xfree(spare_keys);
            if (spare_vals) xfree(spare_vals);
            if (spare_key) xfree(spare_key);
            px_dict_set_locked(dict, key, val);
            return;
        }
        // —— 阶段 A（临界区外，可失败）——
        int len0 = o->as.dict.len, cap0 = o->as.dict.cap;   // 无锁快照（仅用于预估容量）
        if (!spare_key && absent) spare_key = m128_strdup(key, "dict_key_dup");
        // 只在「快照显示需要扩容」时备数组 —— 插入路径**仅有**在 len0 >= cap0 时才需要更大的数组
        //   （快照陈旧时提交阶段会走「备货不足 ⇒ 解锁重来」，故正确性不依赖本预判）。
        if (!spare_keys && len0 >= cap0) {
            int ncap = cap0 ? cap0 * 2 : 8;
            if (ncap < len0 + M128_GROW_SLACK) ncap = len0 + M128_GROW_SLACK;
            spare_keys = (char**)m128_alloc(sizeof(char*) * (size_t)ncap, "dict_keys_grow");
            spare_vals = (LXValue*)m128_alloc(sizeof(LXValue) * (size_t)ncap, "dict_vals_grow");
            spare_cap = ncap;
        }
        // —— 阶段 B（临界区内，不可失败）——
        pthread_mutex_lock(&g_gc_mu);
        gc_block_stop(&old);
        int len = o->as.dict.len;
        int idx = -1;
        if (absent && len == absent_len) {
            idx = len;   // 免重扫：无删除 ⇒ i<len 的键集未变；len 未变 ⇒ 期间没有插入发生
        } else {
            for (int i = 0; i < len; i++) {
                if (strcmp(o->as.dict.keys[i], key) == 0) { idx = i; break; }
            }
            if (idx < 0) { absent = 1; absent_len = len; } else { absent = 0; }
        }
        if (idx >= 0 && idx < len) {         // 命中已有键：只改值（零分配）
            o->as.dict.vals[idx] = val;
            gc_unblock_stop(&old);
            pthread_mutex_unlock(&g_gc_mu);
            if (spare_keys) xfree(spare_keys);
            if (spare_vals) xfree(spare_vals);
            if (spare_key) xfree(spare_key);
            return;
        }
        if (!spare_key) {                    // 键缺失但还没备键副本 ⇒ 解锁备货后重来（不改对象状态）
            gc_unblock_stop(&old);
            pthread_mutex_unlock(&g_gc_mu);
            absent = 1; absent_len = len;
            retry++;
            continue;
        }
        if (len >= o->as.dict.cap) {          // 需要更大的数组：发布备货（只换指针）
            if (!spare_keys || spare_cap <= len) {   // 备货不足 ⇒ 解锁重来
                gc_unblock_stop(&old);
                pthread_mutex_unlock(&g_gc_mu);
                if (spare_keys) xfree(spare_keys);
                if (spare_vals) xfree(spare_vals);
                spare_keys = NULL; spare_vals = NULL; spare_cap = 0;
                retry++;
                continue;
            }
            if (len > 0) {
                memcpy(spare_keys, o->as.dict.keys, sizeof(char*) * (size_t)len);
                memcpy(spare_vals, o->as.dict.vals, sizeof(LXValue) * (size_t)len);
            }
            char** oldk = o->as.dict.keys;
            LXValue* oldv = o->as.dict.vals;
            o->as.dict.keys = spare_keys;
            o->as.dict.vals = spare_vals;
            o->as.dict.cap = spare_cap;
            spare_keys = NULL; spare_vals = NULL;
            if (oldk) xfree(oldk);            // 旧数组：锁内释放（同 xrealloc 语义）
            if (oldv) xfree(oldv);
        }
        o->as.dict.keys[len] = spare_key;      // 插入（此处必有空槽）
        o->as.dict.vals[len] = val;
        o->as.dict.len = len + 1;
        spare_key = NULL;
        gc_unblock_stop(&old);
        pthread_mutex_unlock(&g_gc_mu);
        return;
    }
}

// ==================== M163（第 49 轮 · 缺陷 168/169）：字典键类型严格化 ====================
// 病灶：`{1: "a"}`（字面量）与 `{x: x for x in [1]}`（推导式）的非字符串键在 **VM 轨与 C 轨
//   被静默丢弃**（`if (_k.type == PX_STR) px_dict_set(...)` / NEWDICT 同名条件）⇒
//   ① 与解释轨（R1002）分叉；② **静默数据丢失**（`{1: 11, 2: 22}` 得 `len=0`）。
//   `px_dict_set` 的签名收 `const char* key` ⇒ 调用方早已决定「不是字符串就不传」，
//   键类型检查只能发生在值层 ⇒ 新增本入口（字面量 / 推导式 / VM 的 DICTSET 指令共用）。
// 契约（三轨同码同文，见 docs/DICT_STRICT_MIGRATION.md §1）：
//   · 构造位置上非字符串键 ⇒ R1002 `字典键必须是字符串，实际是 <类型名>`
//   · 索引读/写 `d[k]` 仍为 R1002 `字典索引键必须是字符串`（M120 起文档口径，未变）
//   · 方法族 `d.set(k, v)` 仍为 R1002 `方法 set 参数 1 需要 string`（文档口径，未变）
void px_dict_set_checked(LXValue dict, LXValue k, LXValue v) {
    if (k.type != PX_STR)
        px_error("R1002: 字典键必须是字符串，实际是 %s", px_type_name(k));
    px_dict_set(dict, k.as.obj->as.str.data, v);
}

LXValue px_dict_get(LXValue dict, const char* key) {
    LXObject* o = dict.as.obj;
    for (int i = 0; i < o->as.dict.len; i++) {
        if (strcmp(o->as.dict.keys[i], key) == 0) return o->as.dict.vals[i];
    }
    return px_null();
}

bool px_dict_has(LXValue dict, const char* key) {
    LXObject* o = dict.as.obj;
    for (int i = 0; i < o->as.dict.len; i++) {
        if (strcmp(o->as.dict.keys[i], key) == 0) return true;
    }
    return false;
}

int px_len(LXValue v) {
    switch (v.type) {
        case PX_STR: return px_str_rune_len(v.as.obj); // M106-S2：惰性 rune 计数（原为每次 px_unicode_len_n 全扫）；M83-S1：尊重 str.len（内嵌 NUL 不再截断）
        // M175（缺陷 153）：`len(bytes)` = **字节数**（与 str 的 rune 数各按自己的自然单位）。
        //   修前落到 default ⇒ `len 不支持类型 bytes`，用户只能改用 `bytes_len(b)` ——
        //   而解释轨的 `i_builtin_len` **本来就写了 bytes 分支**（`len(args[0])`），只是那一步
        //   最终调到的正是本函数 ⇒ 两轨一起撞同一堵墙（「同一份意图、两处实现」的又一例）。
        case PX_BYTES: return v.as.obj->as.str.len;
        case PX_LIST: return v.as.obj->as.list.len;
        case PX_DICT: return v.as.obj->as.dict.len;
        case PX_TUPLE: return v.as.obj->as.tuple.len;
        case PX_GEN:
            // M34：惰性生成器先物化剩余（len 需要全量）
            if (v.as.obj->as.gen.is_lazy) px_gen_materialize(v.as.obj);
            return v.as.obj->as.gen.list.as.obj->as.list.len;
        default: px_error("len 不支持类型 %s", px_type_name(v)); return 0;
    }
}

// ==================== 调用 ====================

LXValue px_call(LXValue fn, LXValue* args, int nargs) {
    if (fn.type == PX_FUNC) return fn.as.obj->as.func.fn(args, nargs, fn.as.obj->as.func.ctx);
    if (fn.type == PX_NATIVE) {
        // M31 沙箱安全：危险函数禁限（sandbox_enter deny 列表 → 调用报错，双模式同文案）
        if (g_sandbox_active && g_sandbox_deny_count > 0) {
            const char* nm = fn.as.obj->as.native.name;
            for (int i = 0; i < g_sandbox_deny_count; i++) {
                if (strcmp(g_sandbox_deny[i], nm) == 0) {
                    px_error("沙箱：函数 %s 已被禁用", nm);
                }
            }
        }
        return fn.as.obj->as.native.fn(args, nargs, NULL);
    }
    px_error("R1002: 无法调用非函数: %s", px_type_name(fn));
    return px_null();
}

// 以 self 为第一参数调用全局函数（字符串方法转发）
static LXValue call_with_self(const char* fn, LXValue self, LXValue* args, int nargs) {
    LXValue* a = xmalloc(sizeof(LXValue) * (nargs + 1));
    a[0] = self;
    for (int i = 0; i < nargs; i++) a[i+1] = args[i];
    LXValue r = px_call(px_get_global(fn), a, nargs + 1);
    xfree(a);
    return r;
}

LXValue px_method(LXValue obj, const char* name, LXValue* args, int nargs) {
    // 通道方法
    if (obj.type == PX_CHAN) {
        if (strcmp(name, "send") == 0) {
            if (nargs != 1) px_error("send 需要 1 个参数");
            return px_chan_send(obj, args[0]);
        }
        if (strcmp(name, "recv") == 0) return px_chan_recv(obj);
        if (strcmp(name, "close") == 0) { px_chan_close(obj); return px_null(); }
    }
    // 互斥锁方法（M13）
    if (obj.type == PX_MUTEX) {
        if (strcmp(name, "lock") == 0) return px_mutex_lock(obj);
        if (strcmp(name, "unlock") == 0) return px_mutex_unlock(obj);
        if (strcmp(name, "try_lock") == 0) return px_mutex_try_lock(obj);
        if (strcmp(name, "with") == 0) {
            if (nargs != 1) px_error("mutex.with 需要 1 个函数参数");
            px_mutex_lock(obj);
            LXValue r = px_call(args[0], NULL, 0);
            px_mutex_unlock(obj);
            return r;
        }
    }
    // 读写锁方法（M13）
    if (obj.type == PX_RWLOCK) {
        if (strcmp(name, "rlock") == 0) return px_rwlock_rlock(obj);
        if (strcmp(name, "runlock") == 0) return px_rwlock_runlock(obj);
        if (strcmp(name, "wlock") == 0) return px_rwlock_wlock(obj);
        if (strcmp(name, "wunlock") == 0) return px_rwlock_wunlock(obj);
        if (strcmp(name, "try_rlock") == 0) return px_rwlock_try_rlock(obj);
        if (strcmp(name, "try_wlock") == 0) return px_rwlock_try_wlock(obj);
        if (strcmp(name, "with_read") == 0) {
            if (nargs != 1) px_error("rwlock.with_read 需要 1 个函数参数");
            px_rwlock_rlock(obj);
            LXValue r = px_call(args[0], NULL, 0);
            px_rwlock_runlock(obj);
            return r;
        }
        if (strcmp(name, "with_write") == 0) {
            if (nargs != 1) px_error("rwlock.with_write 需要 1 个函数参数");
            px_rwlock_wlock(obj);
            LXValue r = px_call(args[0], NULL, 0);
            px_rwlock_wunlock(obj);
            return r;
        }
    }
    // 字符串方法
    if (obj.type == PX_STR) {
        if (strcmp(name, "upper") == 0 || strcmp(name, "to_upper") == 0) {
            return call_with_self("to_upper", obj, args, nargs);
        }
        if (strcmp(name, "lower") == 0 || strcmp(name, "to_lower") == 0) {
            return call_with_self("to_lower", obj, args, nargs);
        }
        if (strcmp(name, "len") == 0) return px_int(px_len(obj));
        if (strcmp(name, "trim") == 0) return call_with_self("trim", obj, args, nargs);
        if (strcmp(name, "split") == 0) return call_with_self("split", obj, args, nargs);
        if (strcmp(name, "contains") == 0) return call_with_self("contains", obj, args, nargs);
        if (strcmp(name, "replace") == 0) return call_with_self("replace", obj, args, nargs);
        if (strcmp(name, "starts_with") == 0) return call_with_self("starts_with", obj, args, nargs);
        if (strcmp(name, "ends_with") == 0) return call_with_self("ends_with", obj, args, nargs);
    }
    if (obj.type == PX_LIST) {
        if (strcmp(name, "append") == 0) {
            if (nargs != 1) px_error("append 需要 1 个参数");
            px_list_push(obj, args[0]);
            return px_null();
        }
        if (strcmp(name, "len") == 0) return px_int(px_len(obj));
        if (strcmp(name, "push") == 0) { px_list_push(obj, args[0]); return px_null(); }
        if (strcmp(name, "contains") == 0) {
            if (nargs < 1) px_error("contains 需要 1 个参数");
            LXObject* o = obj.as.obj;
            for (int i = 0; i < o->as.list.len; i++) {
                if (px_eq(o->as.list.items[i], args[0]).as.b) return px_bool(true);
            }
            return px_bool(false);
        }
        if (strcmp(name, "join") == 0) return call_with_self("join", args[0], &obj, 1);
        // M-B2：C 端 list.pop 缺失（自举 lexer 缩进栈用），与解释器一致
        if (strcmp(name, "pop") == 0) {
            if (nargs != 0) px_error("pop 不接受参数");
            LXObject* o = obj.as.obj;
            if (o->as.list.len == 0) px_error("pop 空列表");
            o->as.list.len--;
            return o->as.list.items[o->as.list.len];
        }
    }
    if (obj.type == PX_DICT) {
        if (strcmp(name, "get") == 0) {
            if (nargs < 1) px_error("R1005: 方法 get 需要 1 个参数");
            // M120（qg-issue 76 E4）：**实参类型校验**。此前直接解引用 args[0] 的 str 载荷，
            //   传非字符串（如 int）→ 段错误（实测 rc=139 core dumped）；解释轨友好报 R1002。
            if (args[0].type != PX_STR || !args[0].as.obj)
                px_error("R1002: 方法 get 参数 1 需要 string");
            // M-B1：支持默认值参数（第 2 参数，键不存在时返回）
            // M174（缺陷 194）：**必须按「键是否存在」而不是「取出的值是不是 null」判** ——
            //   修前这里是 `px_is_null(v) && nargs >= 2` ⇒ 「键存在但值为 null」时
            //   VM/C 轨返回默认值，而解释轨（`i_dict_call` 的 `if d.has(k): return d[k]`）
            //   返回 null ⇒ 三轨分叉，且**与文档相悖**：`docs/DICT_STRICT_MIGRATION.md`
            //   与速查表都写「默认值只覆盖『键不存在』」（= Go map / Python dict.get 语义）。
            const char* gk = args[0].as.obj->as.str.data;
            if (!px_dict_has(obj, gk)) {
                if (nargs >= 2) return args[1];
                return px_null();
            }
            return px_dict_get(obj, gk);
        }
        if (strcmp(name, "set") == 0) {
            if (nargs < 2) px_error("R1005: 方法 set 需要 2 个参数");
            if (args[0].type != PX_STR || !args[0].as.obj)
                px_error("R1002: 方法 set 参数 1 需要 string");
            px_dict_set(obj, args[0].as.obj->as.str.data, args[1]);
            return px_null();
        }
        if (strcmp(name, "len") == 0) return px_int(px_len(obj));
        if (strcmp(name, "has") == 0 || strcmp(name, "contains") == 0) {
            if (nargs < 1) px_error("R1005: 方法 %s 需要 1 个参数", name);
            // M120（qg-issue 76 E4）：非字符串键此前直接解引用 → SIGSEGV（实测 d.has(1) rc=139）
            if (args[0].type != PX_STR || !args[0].as.obj)
                px_error("R1002: 方法 %s 参数 1 需要 string", name);
            return px_bool(px_dict_has(obj, args[0].as.obj->as.str.data));
        }
        if (strcmp(name, "keys") == 0) {
            LXObject* o = obj.as.obj;
            LXValue r = px_list(0);
            px_root_push();
            PX_KEEP(r);   // M92 precise：keys list 跨 px_list_push/px_str 分配
            for (int i = 0; i < o->as.dict.len; i++) px_list_push(r, px_str(o->as.dict.keys[i]));
            px_root_pop();
            return r;
        }
        if (strcmp(name, "values") == 0) {
            LXObject* o = obj.as.obj;
            LXValue r = px_list(0);
            px_root_push();
            PX_KEEP(r);   // M92 precise：values list 跨 px_list_push 扩容分配
            for (int i = 0; i < o->as.dict.len; i++) px_list_push(r, o->as.dict.vals[i]);
            px_root_pop();
            return r;
        }
        if (strcmp(name, "items") == 0) {
            // M167（第 53 轮）：[[k, v], …] **插入序快照**（与 keys()/values() 同口径）——
            //   `for k, v in d.items()` 即 Go `for k, v := range m` 的对应写法。
            //   为什么单开方法：dict 直接迭代只产**键**（字符串）⇒ 多变量解包会因
            //   解包校验（px_unpack_ck）**响亮报 R1002**（不静默），指引用户写 .items()。
            LXObject* o = obj.as.obj;
            LXValue r = px_list(0);
            px_root_push();
            PX_KEEP(r);   // 外层 list 跨 px_list_push/px_list（内层）分配
            for (int i = 0; i < o->as.dict.len; i++) {
                px_root_push();
                PX_KEEP(r);
                LXValue pair = px_list(0);
                PX_KEEP(pair);
                px_list_push(pair, px_str(o->as.dict.keys[i]));
                px_list_push(pair, o->as.dict.vals[i]);
                px_list_push(r, pair);
                px_root_pop();
            }
            px_root_pop();
            return r;
        }
        if (strcmp(name, "remove") == 0) {
            // M37 修复：C 端 dict.remove 真删除（原"置 null"导致键残留：has() 仍 true、keys() 仍列出）
            if (nargs < 1) px_error("R1005: 方法 remove 需要 1 个参数");
            if (args[0].type != PX_STR || !args[0].as.obj)
                px_error("R1002: 方法 remove 参数 1 需要 string");
            LXObject* o = obj.as.obj;
            const char* key = args[0].as.obj->as.str.data;
            LXValue v = px_null();
            for (int i = 0; i < o->as.dict.len; i++) {
                if (strcmp(o->as.dict.keys[i], key) == 0) {
                    v = o->as.dict.vals[i];
                    // 收缩：后续元素前移
                    for (int j = i; j < o->as.dict.len - 1; j++) {
                        o->as.dict.keys[j] = o->as.dict.keys[j + 1];
                        o->as.dict.vals[j] = o->as.dict.vals[j + 1];
                    }
                    o->as.dict.len--;
                    break;
                }
            }
            return v;
        }
    }
    // M39：Result 方法（is_ok / is_err / unwrap / ok / err）
    if (obj.type == PX_RESULT) {
        if (strcmp(name, "is_ok") == 0) {
            if (nargs != 0) px_error("is_ok 不接受参数");
            return px_bool(obj.as.obj->as.result.ok);
        }
        if (strcmp(name, "is_err") == 0) {
            if (nargs != 0) px_error("is_err 不接受参数");
            return px_bool(!obj.as.obj->as.result.ok);
        }
        if (strcmp(name, "unwrap") == 0) {
            if (nargs != 0) px_error("unwrap 不接受参数");
            if (obj.as.obj->as.result.ok) return obj.as.obj->as.result.value;
            px_error("unwrap 失败: Err(%s)", px_to_string(obj.as.obj->as.result.value));
        }
        if (strcmp(name, "ok") == 0) {
            // Ok(v) → Some(v)=v；Err(_) → null
            return obj.as.obj->as.result.ok ? obj.as.obj->as.result.value : px_null();
        }
        if (strcmp(name, "err") == 0) {
            // Err(e) → e；Ok(_) → null
            return obj.as.obj->as.result.ok ? px_null() : obj.as.obj->as.result.value;
        }
    }
    // M-B1：struct 方法（impl 方法注册为全局 "Type.method"，方法绑定 self）
    // M55/P0（issue#2）：全局表遍历与 px_set/get_global/GC 根扫描经 g_globals_mu
    // 互斥。锁内仅查找并拷贝函数值；px_call 在锁外执行——其内部会拿 g_gc_mu，
    // 避免 g_globals_mu→g_gc_mu 与 GC 的 g_gc_mu→g_globals_mu 反向死锁。
    if (obj.type == PX_STRUCT) {
        char buf[256];
        snprintf(buf, sizeof(buf), "%s.%s", obj.as.obj->as.struct_inst.type_name, name);
        LXValue m = px_null();
        bool m_found = false;
        sigset_t old;
        pthread_rwlock_rdlock(&g_globals_mu);
        gc_block_stop(&old);
        // M105-S2：原线性 strcmp 扫描 → O(1) 哈希查找（CALLM 热路径；名=「类型.方法」）
        int mslot = g_hash_find(buf, g_name_hash(buf));
        if (mslot >= 0 && (g_vals[mslot].type == PX_FUNC || g_vals[mslot].type == PX_NATIVE)) {
            m = g_vals[mslot];
            m_found = true;
        }
        gc_unblock_stop(&old);
        pthread_rwlock_unlock(&g_globals_mu);
        if (m_found) {
            LXValue* argv = xmalloc(sizeof(LXValue) * (nargs + 1));
            argv[0] = obj; // self
            for (int j = 0; j < nargs; j++) argv[j + 1] = args[j];
            LXValue r = px_call(m, argv, nargs + 1);
            xfree(argv);
            return r;
        }
    }
    // M120（qg-issue 76 E3）：补错误码 R1007 + 文案对齐解释轨（此前无码、且用"对象"而非"类型"）
    px_error("R1007: 类型 %s 没有方法 '%s'", px_type_name(obj), name);
    return px_null();
}

// ==================== 全局表 ====================

// ==================== M107-S2（Issue 35）：VM 轨全局名「稳定指针槽位记忆」 ====================
// 依据（M107-S0 三轨实测）：每次全局名访问 ≈30ns，其中 strlen + FNV-1a + 开放寻址探测 + strcmp
//   占大半。VM 轨 GETG 传入的名字来自 BCModule 全局名表 m->G[b]——**编译期常量字符串指针，
//   程序生命周期内地址不变** ⇒ 可以「名字指针」为键做一级记忆，命中即整条按名查找链全省。
// 不失效论证（红线 7）：全局表 name→槽位 映射**只增不改**——px_set_global 仅在未命中时
//   xstrdup 追加（g_len++），命中时只覆写 g_vals[gi]（槽位号恒定）；表永不删除/移动/压缩。
//   ⇒ 记忆项一旦落位，槽位号在进程余下生命周期内恒有效；同名重定义只改值、仍走同一槽位，
//     取值结果与逐次按名查找**逐字一致**。
// 适用边界（**调用方契约**）：仅限**地址稳定**的名字（VM 轨常量池名表）。其它调用方
//   （如 spawn 的运行时函数名、总线 topic 键）可能传入会被 GC 回收的堆字符串，继续走
//   px_get_global 的按名查找，**不进本记忆**（否则地址复用会致误命中）。
// 并发：记忆只缓存**槽位号**，取值仍在校验同款读锁内从 g_vals 拷贝 ⇒ 可见性与改动前一致。
#define PX_NG_CACHE 128                    // 2 的幂；直接映射，冲突即换出
static __thread struct { const char* nm; int gi; } g_ng_memo[PX_NG_CACHE];

static inline int px_ng_slot(const char* nm) {
    // 乘性折叠取**高位**：字符串常量在 .rodata 中常相邻（地址仅低几位不同），
    //   若先右移会把这些区分位丢掉 ⇒ 相邻名撞同一槽（实测 G_b/G_n 撞槽致 50% 未命中、
    //   反而比按名查找更慢）。裸指针乘黄金常数后取高 7 位可把低位差异扩散到高位。
    return (int)((uintptr_t)nm * 0x9E3779B97F4A7C15ULL >> (64 - 7));   // 7 位 ⇒ 128 槽
}

// 解析「地址稳定」全局名 → 槽位号（-1 = 未定义）。首次按名查找，其后走记忆。
int px_global_resolve_stable(const char* name) {
    int cs = px_ng_slot(name);
    if (g_ng_memo[cs].nm == name) return g_ng_memo[cs].gi;   // 命中：免 strlen+哈希+探测+strcmp
    sigset_t old;
    pthread_rwlock_rdlock(&g_globals_mu);
    gc_block_stop(&old);
    int gi = g_hash_find(name, g_name_hash(name));
    gc_unblock_stop(&old);
    pthread_rwlock_unlock(&g_globals_mu);
    if (gi >= 0) { g_ng_memo[cs].nm = name; g_ng_memo[cs].gi = gi; }
    return gi;
}

// 按已解析槽位号取值（持读锁拷贝，语义同 px_get_global 取到值的部分）
LXValue px_global_at(int gi) {
    sigset_t old;
    pthread_rwlock_rdlock(&g_globals_mu);
    gc_block_stop(&old);
    LXValue v = g_vals[gi];
    gc_unblock_stop(&old);
    pthread_rwlock_unlock(&g_globals_mu);
    return v;
}

LXValue px_get_global(const char* name) {    // M55/P0（issue#2）：与 px_set_global/GC 根扫描经 g_globals_mu 互斥。持锁 +
    // 屏蔽 SIG_GC_STOP（协议同 g_gc_mu）：临界区不被 GC 暂停，stop-the-world 取
    // 本锁不会被"已暂停持锁线程"卡死；确保读到完整值（锁内拷贝，解锁返回）。
    sigset_t old;
    pthread_rwlock_rdlock(&g_globals_mu);
    gc_block_stop(&old);
    // M105-S2：原 O(g_len) 线性 strcmp 扫描 → O(1) 哈希查找（命中数/返回值不变）
    int gi = g_hash_find(name, g_name_hash(name));
    if (gi >= 0) {
        LXValue v = g_vals[gi];
        gc_unblock_stop(&old);
        pthread_rwlock_unlock(&g_globals_mu);
        return v;
    }
    gc_unblock_stop(&old);
    pthread_rwlock_unlock(&g_globals_mu);
    px_error("R1001: 未定义变量: '%s'", name);
    return px_null();
}

// M68：非致命全局 native 查询（bi_ffi_call 双表兜底用；未找到不 px_error）
// 锁协议与 px_get_global 一致（g_globals_mu + gc_block_stop）；仅当全局值存在
// 且为 PX_NATIVE（px_set_global 注册的内置函数）时返回 true 并拷贝出值。
// 用途：ffi_call 查 ffi 注册表未命中 → 兜底查宿主全局 PX_NATIVE → pxi 解释器
// 用户裸脚本（零 extern def）调用 runtime 全部内置函数，与编译产物可达性一致。
bool px_global_native(const char* name, LXValue* out) {
    sigset_t old;
    pthread_rwlock_rdlock(&g_globals_mu);
    gc_block_stop(&old);
    // M105-S2：同 px_get_global，改 O(1) 哈希查找（语义：名存在则按类型返回）
    int gi = g_hash_find(name, g_name_hash(name));
    if (gi >= 0) {
        LXValue v = g_vals[gi];
        gc_unblock_stop(&old);
        pthread_rwlock_unlock(&g_globals_mu);
        if (v.type == PX_NATIVE) {
            if (out) *out = v;
            return true;
        }
        return false;   // 名存在但非内置函数（用户变量/常量/结构体等）
    }
    gc_unblock_stop(&old);
    pthread_rwlock_unlock(&g_globals_mu);
    return false;
}

void px_set_global(const char* name, LXValue v) {
    // M55/P0（issue#2）：写全局表全程持 g_globals_mu（含 g_len++ 与 key/val 槽位
    // 写入），与 px_get_global 读、GC 根扫描互斥；g_len 在锁内更新保证原子可见。
    // 错误路径先解锁再 px_error（px_error 不持锁返回，避免锁泄漏/死锁）。
    sigset_t old;
    uint64_t hv = g_name_hash(name);   // M105-S2：哈希在拿写锁前算（纯函数，只读 name）
    pthread_rwlock_wrlock(&g_globals_mu);
    gc_block_stop(&old);
    // M105-S2：原 O(g_len) 线性 strcmp 扫描 → O(1) 哈希查找；新增槽位处同步落位索引
    int gi = g_hash_find(name, hv);
    if (gi >= 0) {
        g_vals[gi] = v;
        gc_unblock_stop(&old);
        pthread_rwlock_unlock(&g_globals_mu);
        return;
    }
    if (g_len >= GLOBAL_CAP) {
        gc_unblock_stop(&old);
        pthread_rwlock_unlock(&g_globals_mu);
        px_error("全局表溢出");
        return;
    }
    g_keys[g_len] = xstrdup(name);
    g_vals[g_len] = v;
    g_hash_put(hv, g_len);
    g_len++;
    gc_unblock_stop(&old);
    pthread_rwlock_unlock(&g_globals_mu);
}

// ==================== 内置函数 ====================

// M96-S4：并发 print 整行原子锁 —— 帧协程多 worker 共写同一 stdout，行内多次
//   printf 非原子（stdio 锁仅单次调用）→ 行交错合并（R37 行写一半 R39 插入）。
//   GC 标记不涉此锁，简单互斥即可；print 为低频 I/O，串行化开销可忽略。
static pthread_mutex_t g_print_mu = PTHREAD_MUTEX_INITIALIZER;

static LXValue bi_print(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    pthread_mutex_lock(&g_print_mu);
    for (int i = 0; i < nargs; i++) {
        if (i) printf(" ");
        px_print_value(args[i], false);
    }
    printf("\n");
    // M72-S1（Issue 9）：print 即人读日志——stdout 重定向到管道/journald/文件时
    // C stdio 变全缓冲（8192B），不刷则服务日志运行中不可见、崩溃前缓冲丢失。
    // 行尾 fflush → 每行实时（行级 syscall 对日志场景可接受）。
    fflush(stdout);
    pthread_mutex_unlock(&g_print_mu);
    return px_null();
}

// M72-S1（Issue 9 方案 C 最小版）：flush() —— .px 脚本自主刷 stdout/stderr
static LXValue bi_flush(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 0) px_error("R1002: flush 不接受参数");
    fflush(stdout);
    fflush(stderr);
    return px_null();
}

// M72-S1（Issue 9/10）：print_err(...) —— 渲染对齐 print（px_fmt_value）但输出到
// stderr（默认无缓冲，天然实时）→ 服务错误/诊断出口统一 stderr 的基础。
static LXValue bi_print_err(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    // M172（缺陷 186）：先刷 stdout —— 诊断走 stderr 后，若 stdout 仍留在缓冲里，
    //   `2>&1` 合并捕获（门/日志的标准做法）里诊断会**跑到程序输出前面**，与
    //   「程序先输出、再报错」的因果相反。px_error 早有同样一行，此处补平。
    fflush(stdout);
    pthread_mutex_lock(&g_print_mu);
    for (int i = 0; i < nargs; i++) {
        if (i) fputc(' ', stderr);
        int n = 0;
        char* s = px_fmt_value_n(args[i], &n);
        if (n > 0) fwrite(s, 1, (size_t)n, stderr);
        xfree(s);
    }
    fputc('\n', stderr);
    fflush(stderr);
    pthread_mutex_unlock(&g_print_mu);
    return px_null();
}

// M39：Result/Option 构造函数（spec §3.5；Some(x) = x，None 即 null）
static LXValue bi_ok(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: Ok 需要 1 个参数");
    return px_ok(args[0]);
}
static LXValue bi_err(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: Err 需要 1 个参数");
    return px_err(args[0]);
}
static LXValue bi_some(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: Some 需要 1 个参数");
    return args[0];
}

static LXValue bi_len(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: len 需要一个参数");
    return px_int(px_len(args[0]));
}

static LXValue bi_range(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    int64_t start = 0, end = 0, step = 1;
    if (nargs == 1) { end = int_val(args[0]); }
    else if (nargs == 2) { start = int_val(args[0]); end = int_val(args[1]); }
    else if (nargs == 3) { start = int_val(args[0]); end = int_val(args[1]); step = int_val(args[2]); }
    else px_error("R1002: range 需要 1-3 个参数");
    if (step == 0) px_error("R1002: range step 不能为 0");
    LXValue r = px_list(0);
    px_root_push();
    PX_KEEP(r);   // M92 precise：累积 list 跨 px_list_push 扩容分配
    if (step > 0) for (int64_t i = start; i < end; i += step) px_list_push(r, px_int(i));
    else for (int64_t i = start; i > end; i += step) px_list_push(r, px_int(i));
    px_root_pop();
    return r;
}

static LXValue bi_type(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: type 需要一个参数");
    return px_str(px_type_name(args[0]));
}

// M145（缺陷 125 配套）：`object_id(v)` —— 对象的**不透明**标识（同一性判断）。
//   动机：PuXian 的 `==` 是**结构相等**，语言里无法表达「是不是同一个对象」⇒
//     ① 解释器（selfhost/ival.px）的环检测拿不到对象身份；
//     ② 移植带指针语义的 Go 代码（如 BIRCH CF 树的 `child == leaf`）只能靠下标近似。
//   语义：堆对象返回其地址（mark-sweep 非移动 GC ⇒ 存活期内恒定）；非堆值（int/float/
//     bool/null/range/chan/锁…）返回 0。**仅供同一性比较，不保证跨进程/跨次运行稳定**。
static LXValue bi_object_id(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: object_id 需要一个参数");
    LXValue v = args[0];
    switch (v.type) {
        case PX_LIST: case PX_TUPLE: case PX_DICT: case PX_STR: case PX_BYTES:
        case PX_RESULT: case PX_STRUCT: case PX_ENUM: case PX_FUNC: case PX_NATIVE:
        case PX_GEN:
            return px_int((int64_t)(intptr_t)v.as.obj);
        default:
            return px_int(0);
    }
}

static LXValue bi_str(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: str 需要一个参数");
    // M136（qg-issue 87 缺陷 92）：**入参已是字符串 ⇒ 原样返回**。
    //   此前一律走 px_fmt_value（返回 char*）→ px_str() ⇒ 在**首个 0x00 处静默截断**：
    //   PX_STR 自身是长度感知的（能承载内嵌 NUL），只有 `str()` 这一跳把它按 C 串重造。
    //   实证（examples/m135_multi_header 同批的最小复现）：
    //     bytes("AB\0CD\0EF") → bytes_to_str ⇒ 8 字节 ✓；再 str() ⇒ **2 字节** ✗
    //   影响面：一切"二进制体经 str() 中转"的路径 —— 媒体代理透传 25 字节音频响应
    //   时被截成 3 字节（第 16 轮对拍门当场判红）。
    //   注：PX_BYTES 保持既有显示形式（`<bytes N>`）不变，避免改动 str(bytes) 的既有语义。
    if (args[0].type == PX_STR) return args[0];
    // M154（第 36 轮）：整数快路径 —— 小整数池（见 px_str_int_pool）。文本与
    //   px_fmt_value(px_int(v)) 逐字节相同；池化的是**对象**，不改变任何字节语义。
    if (args[0].type == PX_INT) return px_str_int_pool(args[0].as.i);
    // M-B5：统一用 px_fmt_value——str() 支持全部类型（list/dict/enum/struct/result 等），
    // 对齐 Rust 内置 str()（fmt_value 渲染）
    int n = 0;
    char* s = px_fmt_value_n(args[0], &n);
    LXValue r = px_str_len(s, n);   // M155（缺陷 150）：容器渲染里的内嵌 NUL 不再被 strlen 截断
    xfree(s);
    return r;
}

static LXValue bi_int(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: int 需要一个参数");
    LXValue a = args[0];
    if (a.type == PX_INT) return a;
    if (a.type == PX_FLOAT) return px_int((int64_t)a.as.f);
    if (a.type == PX_BOOL) return px_int(a.as.b ? 1 : 0);
    if (a.type == PX_STR) { return px_int(atoll(a.as.obj->as.str.data)); }
    px_error("R1002: int 不支持类型 %s", px_type_name(a));
    return px_null();
}

static LXValue bi_float(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: float 需要一个参数");
    LXValue a = args[0];
    if (a.type == PX_FLOAT) return a;
    if (a.type == PX_INT) return px_float((double)a.as.i);
    if (a.type == PX_STR) return px_float(atof(a.as.obj->as.str.data));
    px_error("R1002: float 不支持类型 %s", px_type_name(a));
    return px_null();
}

static LXValue bi_bool(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: bool 需要一个参数");
    return px_bool(px_is_truthy(args[0]));
}

static LXValue bi_assert(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs < 1) px_error("R1002: assert 需要 1-2 个参数");
    if (!px_is_truthy(args[0])) {
        if (nargs >= 2 && args[1].type == PX_STR) px_error("断言失败: %s", args[1].as.obj->as.str.data);
        else px_error("断言失败");
    }
    return px_null();
}

static LXValue bi_panic(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs >= 1 && args[0].type == PX_STR) px_error("%s", args[0].as.obj->as.str.data);
    px_error("panic");
    return px_null();
}

static LXValue bi_sleep(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs < 1) px_error("R1002: sleep 需要 1 个参数");
    int64_t ms = int_val(args[0]);
    // M88-S2（qg-issue 27）：EINTR 自动续睡——并发 GC（M11 stop-the-world）向所有已注册
    // 线程发 SIG_GC_STOP 实时信号，nanosleep 被信号打断返回 EINTR（nanosleep 不在
    // SA_RESTART 自动重启清单）。若不续睡，主线程 sleep(长) 会在首轮 GC 后提前返回 →
    // main 结束 → 进程静默退出（高并发压测"服务进程悄然消失"根因）。timer_sleep_ms/
    // sleep_us 均已按此模式续睡，此处对齐。
    struct timespec ts;
    ts.tv_sec = ms / 1000;
    ts.tv_nsec = (ms % 1000) * 1000000L;
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {}
    return px_null();
}

static LXValue bi_to_upper(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1 || args[0].type != PX_STR) px_error("R1002: to_upper 需要一个字符串参数");
    const char* s = args[0].as.obj->as.str.data;
    int len = (int)strlen(s);
    char* d = xmalloc(len + 1);
    for (int i = 0; i < len; i++) {
        char c = s[i];
        d[i] = (c >= 'a' && c <= 'z') ? (char)(c - 32) : c;
    }
    d[len] = 0;
    return px_str(d);
}

static LXValue bi_to_lower(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1 || args[0].type != PX_STR) px_error("R1002: to_lower 需要一个字符串参数");
    const char* s = args[0].as.obj->as.str.data;
    int len = (int)strlen(s);
    char* d = xmalloc(len + 1);
    for (int i = 0; i < len; i++) {
        char c = s[i];
        d[i] = (c >= 'A' && c <= 'Z') ? (char)(c + 32) : c;
    }
    d[len] = 0;
    return px_str(d);
}

// ==================== M133：码点 ↔ 字符（ord / chr） ====================
// 背景（token-cache PuXian 化第 12 轮）：native 表里**没有 ord/chr**（qg-issue 87 缺陷 29），
//   而 Go 侧到处是 `s[i]` 逐字节/逐码点比较（`hex.DecodeString` 的 `U+007A 'z'` 错误文案、
//   控制字符扫描、UTF-8 手写解码）。项目里的旧做法是**手写 UTF-8 解码**（api-server 移植即如此）
//   —— 每处都可能写错边界（过长编码/代理区/孤立续字节），且与 Go 的 utf8.DecodeRune 语义
//   悄悄分叉。补成原语后这种手写可以彻底消失。
// 语义：
//   ord(s) → int：返回 s **第一个字符**（码点）的 Unicode 码点；s 为空 → 0。
//                 非法 UTF-8 序列按 Go `utf8.DecodeRune` 的 RuneError(0xFFFD) 处理。
//   chr(n) → str：码点 → UTF-8 字符串（Go `string(rune(n))`）；非法码点（<0、代理区、
//                 >0x10FFFF）→ "\uFFFD"（三者都对齐 Go 的行为）。
static LXValue bi_ord(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: ord 需要一个字符串参数");
    const char* p = px_val_cstr(args[0]);
    if (!p || !*p) return px_int(0);
    const unsigned char* s = (const unsigned char*)p;
    unsigned cp = 0;
    int need = 0;
    if (s[0] < 0x80)      { return px_int(s[0]); }
    else if (s[0] >= 0xC2 && s[0] <= 0xDF) { cp = s[0] & 0x1F; need = 1; }
    else if (s[0] >= 0xE0 && s[0] <= 0xEF) { cp = s[0] & 0x0F; need = 2; }
    else if (s[0] >= 0xF0 && s[0] <= 0xF4) { cp = s[0] & 0x07; need = 3; }
    else return px_int(0xFFFD);
    for (int i = 1; i <= need; i++) {
        if (s[i] == 0) return px_int(0xFFFD);          // 截断
        if ((s[i] & 0xC0) != 0x80) return px_int(0xFFFD);
        cp = (cp << 6) | (s[i] & 0x3F);
    }
    if ((need == 2 && cp < 0x800) || (need == 3 && cp < 0x10000) ||
        (cp >= 0xD800 && cp <= 0xDFFF) || cp > 0x10FFFF)
        return px_int(0xFFFD);
    return px_int((int64_t)cp);
}

static LXValue bi_chr(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: chr 需要 (码点) 参数");
    int64_t cp = int_val(args[0]);
    char buf[8];
    int n = 0;
    if (cp < 0 || cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF)) {
        buf[0] = (char)0xEF; buf[1] = (char)0xBF; buf[2] = (char)0xBD; n = 3;  // U+FFFD
    } else if (cp < 0x80) {
        buf[0] = (char)cp; n = 1;
    } else if (cp < 0x800) {
        buf[0] = (char)(0xC0 | (cp >> 6)); buf[1] = (char)(0x80 | (cp & 0x3F)); n = 2;
    } else if (cp < 0x10000) {
        buf[0] = (char)(0xE0 | (cp >> 12)); buf[1] = (char)(0x80 | ((cp >> 6) & 0x3F));
        buf[2] = (char)(0x80 | (cp & 0x3F)); n = 3;
    } else {
        buf[0] = (char)(0xF0 | (cp >> 18)); buf[1] = (char)(0x80 | ((cp >> 12) & 0x3F));
        buf[2] = (char)(0x80 | ((cp >> 6) & 0x3F)); buf[3] = (char)(0x80 | (cp & 0x3F)); n = 4;
    }
    return px_str_len(buf, n);
}

static LXValue bi_trim(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1 || args[0].type != PX_STR) px_error("R1002: trim 需要一个字符串参数");
    const char* s = args[0].as.obj->as.str.data;
    while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
    int len = (int)strlen(s);
    while (len > 0 && (s[len-1] == ' ' || s[len-1] == '\t' || s[len-1] == '\n' || s[len-1] == '\r')) len--;
    return px_str_len(s, len);
}

static LXValue bi_now_ms(LXValue* args, int nargs, void* ctx) {
    (void)args; (void)nargs; (void)ctx;
    // M36 修复：C 端 now_ms 用 CLOCK_REALTIME（Unix 毫秒），与解释器 SystemTime 一致
    // （原用 CLOCK_MONOTONIC 导致双模式时间基准不一致：now_ms()/1000 无法算日期）
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return px_int((int64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000L);
}

static LXValue bi_abs(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: abs 需要一个参数");
    LXValue a = args[0];
    if (a.type == PX_INT) return px_int(a.as.i < 0 ? -a.as.i : a.as.i);
    if (a.type == PX_FLOAT) return px_float(fabs(a.as.f));
    px_error("R1002: abs 不支持类型 %s", px_type_name(a));
    return px_null();
}

// M177（缺陷 165 的审计发现）：**可迭代实参统一物化**。
//   修前各内置自定「收什么」—— `sum` 只收 list、`min/max` 单参数**直接返回实参本身**
//   （传生成器 ⇒ 静默返回生成器对象！）、`join/reversed/contains` 各报各家文案；
//   而解释轨另一侧又是另一套（收 list/tuple、`min` 干脆只收 2 个参数）。
//   ⇒ 统一走**一条**迭代语义：`px_len` + `px_iter_at`（与 `for x in xs` 同源）。
//   返回 1 成功（*out 为 list）；0 = 类型不可迭代（调用方负责响亮报错）。
//   ⚠️ GC 纪律（M170）：本函数**不自行登记根** —— tuple/str 转换会新建 list，它此后只活在
//   调用方的 C 局部；调用方必须 `px_root_push(); PX_KEEP(lst);` 一直保到**用完**，
//   否则中途一次分配触发的 GC 就会把它收走（「登记时机」比「登记与否」更常出错）。
static int px_as_list(LXValue v, LXValue* out) {
    if (v.type == PX_LIST) { *out = v; return 1; }
    if (v.type == PX_GEN) {
        LXObject* go = v.as.obj;
        if (go->as.gen.is_lazy) px_gen_materialize(go);
        *out = go->as.gen.list;
        return 1;
    }
    if (v.type != PX_TUPLE && v.type != PX_STR) return 0;
    int n = px_len(v);
    LXValue l = px_list(n > 0 ? n : 1);
    for (int i = 0; i < n; i++) px_list_push(l, px_iter_at(v, px_int(i)));
    *out = l;
    return 1;
}

// M177：`min`/`max` 的**单参数可迭代**形态 —— 取元素最值（空 ⇒ 响亮，不静默给 null）。
static LXValue px_minmax_iter(LXValue it, int want_max, const char* what) {
    LXValue l;
    px_root_push();
    if (!px_as_list(it, &l)) { px_root_pop(); px_error("R1002: %s 参数需要 list/tuple/生成器", what); }
    PX_KEEP(l);
    if (l.as.obj->as.list.len == 0) { px_root_pop(); px_error("R1002: %s 需要至少一个元素", what); }
    LXObject* o = l.as.obj;
    LXValue m = o->as.list.items[0];
    for (int i = 1; i < o->as.list.len; i++) {
        LXValue cur = o->as.list.items[i];
        // M179：`min`/`max`/`sorted` 用的是**内部比较器**（全序；跨型按类型名）——
        //   与解释轨 `i_cmp_values`、C 轨的 `compare_values` 同源。
        //   修前这里借 `px_lt`/`px_gt`：用户面比较学现在要求「可比值」，
        //   借道会让 `min([1,"a"])` 变成三轨分叉（解释轨 1 / 编译轨报错）。
        int c = compare_values(cur, m);
        if (want_max ? c > 0 : c < 0) m = cur;
    }
    px_root_pop();
    return m;
}

static LXValue bi_min(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs < 1) px_error("R1002: min 需要至少 1 个参数");
    if (nargs == 1) {
        // M177：单参数若是 list/tuple/生成器/字符串 ⇒ 取元素最值（修前直接返回实参本身！）
        if (args[0].type == PX_LIST || args[0].type == PX_TUPLE ||
            args[0].type == PX_GEN || args[0].type == PX_STR)
            return px_minmax_iter(args[0], 0, "min");
        return args[0];
    }
    LXValue m = args[0];
    for (int i = 1; i < nargs; i++) {
        // M179：全序内部比较器（同 sorted；修前只收「双数值或双字符串」并报「比较不支持」）
        int c = compare_values(args[i], m);
        if (c < 0) m = args[i];   // m > args[i] → 换
    }
    return m;
}

static LXValue bi_max(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs < 1) px_error("R1002: max 需要至少 1 个参数");
    if (nargs == 1) {
        if (args[0].type == PX_LIST || args[0].type == PX_TUPLE ||
            args[0].type == PX_GEN || args[0].type == PX_STR)
            return px_minmax_iter(args[0], 1, "max");
        return args[0];
    }
    LXValue m = args[0];
    for (int i = 1; i < nargs; i++) {
        int c = compare_values(args[i], m);
        if (c > 0) m = args[i];   // m < args[i] → 换
    }
    return m;
}

static LXValue bi_sum(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: sum 需要 1 个参数");
    // M177：收 list/tuple/生成器（物化）—— 修前只收 list（解释轨收 list/tuple ⇒ 两轨不同）
    LXValue lst;
    px_root_push();     // M170：tuple/str→list 的新对象此后只活在 C 局部
    if (!px_as_list(args[0], &lst)) { px_root_pop(); px_error("R1002: sum 参数需要 list/tuple/生成器，实际是 %s", px_type_name(args[0])); }
    PX_KEEP(lst);
    LXObject* o = lst.as.obj;
    LXValue r = px_int(0);
    for (int i = 0; i < o->as.list.len; i++) r = px_add(r, o->as.list.items[i]);
    px_root_pop();
    return r;
}

// M177：`dict()` 空字典构造 —— 解释轨一直有（`i_builtin_dict`），**编译轨没有**
//   （实测 `R1001 未定义变量: 'dict'`）⇒ 用户照解释轨写的代码一上生产就炸。
//   与 `json_parse("{}")` 等价（`{}` 字面量求值为 null 是另一条已文档化的坑）。
static LXValue bi_dict_ctor(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 0) px_error("R1002: dict 不需要参数");
    return px_dict();
}

// M177：`unique(list)` / `flatten(list)` —— 同样是**解释轨有、编译轨没有**的两个名字
//   （`selfhost/ibuiltin.px` 里以 .px 实现）。语义照抄解释轨：去重保持顺序 / 展平一层。
static LXValue bi_unique(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: unique 需要 1 个参数");
    LXValue lst;
    px_root_push();
    if (!px_as_list(args[0], &lst)) { px_root_pop(); px_error("R1002: unique 参数需要 list/tuple/生成器，实际是 %s", px_type_name(args[0])); }
    PX_KEEP(lst);
    LXValue out = px_list(0);
    PX_KEEP(out);
    LXObject* o = lst.as.obj;
    for (int i = 0; i < o->as.list.len; i++) {
        LXValue it = o->as.list.items[i];
        int dup = 0;
        LXObject* oo = out.as.obj;
        for (int j = 0; j < oo->as.list.len; j++) {
            LXValue e = px_eq(oo->as.list.items[j], it);
            if (e.type == PX_BOOL && e.as.b) { dup = 1; break; }
        }
        if (!dup) px_list_push(out, it);
    }
    px_root_pop();
    return out;
}

static LXValue bi_flatten(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: flatten 需要 1 个参数");
    LXValue lst;
    px_root_push();
    if (!px_as_list(args[0], &lst)) { px_root_pop(); px_error("R1002: flatten 参数需要 list/tuple/生成器，实际是 %s", px_type_name(args[0])); }
    PX_KEEP(lst);
    LXValue out = px_list(0);
    PX_KEEP(out);
    LXObject* o = lst.as.obj;
    for (int i = 0; i < o->as.list.len; i++) {
        LXValue sub;
        if (!px_as_list(o->as.list.items[i], &sub)) {
            px_root_pop();
            px_error("R1002: flatten 的元素需要可迭代，实际是 %s", px_type_name(o->as.list.items[i]));
        }
        LXObject* so = sub.as.obj;
        for (int j = 0; j < so->as.list.len; j++) px_list_push(out, so->as.list.items[j]);
    }
    px_root_pop();
    return out;
}

static LXValue bi_sqrt(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: sqrt 需要一个参数");
    return px_float(sqrt(math_num(args[0], "sqrt")));
}

// ==================== M59 数学与随机内置 ====================
// 设计（docs/M59_PLAN.md §三）：延续 abs/sqrt/pow 先例（C libm 内置，零新依赖），
// 域错误透传 C 语义 NaN/+inf（不终止），参数个数/类型错误 px_error 终止（编程契约）。
// pi/e 常量不用 M_PI/M_E（防个别 libm 缺省宏），本地宏常量更稳。

#ifndef PX_PI
#define PX_PI 3.14159265358979323846
#endif
#ifndef PX_E
#define PX_E 2.71828182845904523536
#endif

// 一元数学参数校验：仅接受 int/float（字符串/列表等 → 终止）
static double math_num(LXValue v, const char* fn) {
    if (v.type == PX_INT) return (double)v.as.i;
    if (v.type == PX_FLOAT) return v.as.f;
    px_error("R1002: %s 参数必须是数字，实际是 %s", fn, px_type_name(v));
    return 0.0;
}

