static const int GO_ERRNO_STR_N = (int)(sizeof(GO_ERRNO_STR) / sizeof(GO_ERRNO_STR[0]));

// go_errno_string(errno) → str：返回 **Go** `syscall.Errno.Error()` 的文案。
//   为什么不用 libc 的 strerror：① 大小写不同（glibc 给 "No such file or directory"，
//   Go 给 "no such file or directory"）——移植 Go 的 `*PathError.Error()` 文案时**必然分叉**；
//   ② 跨 libc 不确定（glibc/musl 文案不同）⇒ 对拍门会随运行环境漂移。
//   表由 `tools/gen_go_errno_table.go` 从 Go 自身导出（单一事实源，非手抄）；
//   表外/空文案 → `"errno <N>"`（与 Go 的兜底分支逐字一致）。
static LXValue bi_go_errno_string(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: go_errno_string 需要 (errno) 参数");
    int n = (int)int_val(args[0]);
    if (n >= 0 && n < GO_ERRNO_STR_N && GO_ERRNO_STR[n][0] != '\0') return px_str(GO_ERRNO_STR[n]);
    char buf[32];
    snprintf(buf, sizeof(buf), "errno %d", n);
    return px_str(buf);
}

// ==================== M60-S2：设备组 tty_config / fd_wait ====================
// 设计（docs/M60_PLAN.md §三.2）：服务边缘设备 GAP #3（串口 UART 无 termios：设不了
// 波特率/raw 模式）与 #2（GPIO 边沿中断/多 fd 等待无 fd 多路复用）。内部 poll 已有
// （子进程池读帧用），本步将其暴露为语言函数 fd_wait。失败语义延续 M57：-1/false + os_errno()。
//   tty_config(fd, baud, raw) → bool：tcgetattr →（raw=true 则 cfmakeraw：关 canonical/echo/
//     信号转换，串口 raw 标准姿势）→ cfsetispeed+cfsetospeed → tcsetattr(TCSANOW)。
//     raw=false 仅改波特率保留原模式。baud 支持常规档 9600/19200/38400/57600/115200/
//     230400/460800/921600；不支持的档 px_error（编程契约参数错误）。
//   fd_wait(fds, timeout_ms) → list<就绪 fd>（空=超时）| int -1（poll 系统错误 + os_errno）。
//     fds 接受 int 单 fd 或 list<int>（上限 64）；timeout_ms>=0（0=立即查，负值 px_error）；
//     events 只监听 POLLIN 可读；revents 非 0（POLLIN/POLLHUP/POLLERR/POLLNVAL）即视为
//     事件返回该 fd——HUP/ERR 场景由上层随后 read 判 EOF(空 bytes)/-1+errno。EINTR 自动续等。
static LXValue bi_tty_config(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 3) px_error("R1002: tty_config 需要 (fd, baud, raw) 参数");
    if (args[0].type != PX_INT) px_error("R1002: tty_config 的 fd 需要 int");
    int fd = (int)args[0].as.i;
    int64_t baud = int_val(args[1]);
    if (args[2].type != PX_BOOL) px_error("R1002: tty_config 的 raw 需要 bool");
    int raw = args[2].as.b ? 1 : 0;
    struct termios tio;
    if (tcgetattr(fd, &tio) != 0) return px_bool(false);   // os_errno() 查具体原因
    if (raw) cfmakeraw(&tio);
    speed_t sp;
    switch (baud) {
        case 9600:   sp = B9600;   break;
        case 19200:  sp = B19200;  break;
        case 38400:  sp = B38400;  break;
        case 57600:  sp = B57600;  break;
        case 115200: sp = B115200; break;
        case 230400: sp = B230400; break;
        case 460800: sp = B460800; break;
        case 921600: sp = B921600; break;
        default:
            px_error("R1002: tty_config 不支持的波特率 %lld（支持 9600/19200/38400/57600/115200/230400/460800/921600）", (long long)baud);
            return px_bool(false);
    }
    if (cfsetispeed(&tio, sp) != 0) return px_bool(false);
    if (cfsetospeed(&tio, sp) != 0) return px_bool(false);
    if (tcsetattr(fd, TCSANOW, &tio) != 0) return px_bool(false);
    return px_bool(true);
}

static LXValue bi_fd_wait(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 2) px_error("R1002: fd_wait 需要 (fds, timeout_ms) 参数");
    if (args[1].type != PX_INT) px_error("R1002: fd_wait 的 timeout_ms 需要 int");
    int64_t tmo = args[1].as.i;
    if (tmo < 0) px_error("R1002: fd_wait 的 timeout_ms 需要 >= 0");
    if (tmo > 2147483647L) tmo = 2147483647L;   // poll 超时 int 上限保护
    int fds[64];
    int n = 0;
    if (args[0].type == PX_INT) {
        fds[n++] = (int)args[0].as.i;
    } else if (args[0].type == PX_LIST) {
        LXObject* o = args[0].as.obj;
        if (o->as.list.len > 64) px_error("fd_wait 一次最多监听 64 个 fd");
        for (int i = 0; i < o->as.list.len; i++) {
            if (o->as.list.items[i].type != PX_INT) px_error("R1002: fd_wait 的 fds 列表元素需要 int");
            fds[n++] = (int)o->as.list.items[i].as.i;
        }
    } else {
        px_error("R1002: fd_wait 的 fds 需要 int 或 list<int>，实际 %s", px_type_name(args[0]));
    }
    if (n == 0) return px_list(0);   // 空集合立即返回空
    struct pollfd pfds[64];
    for (int i = 0; i < n; i++) { pfds[i].fd = fds[i]; pfds[i].events = POLLIN; pfds[i].revents = 0; }
    int rc;
    do { rc = poll(pfds, (nfds_t)n, (int)tmo); } while (rc < 0 && errno == EINTR);
    if (rc < 0) return px_int(-1);   // os_errno() 查（如 EINVAL）
    LXValue r = px_list(0);
    if (rc == 0) return r;           // 超时 → 空 list（与就绪返回类型统一，非错误）
    px_root_push();
    PX_KEEP(r);   // M92 precise：就绪 list 跨 px_list_push 扩容分配
    for (int i = 0; i < n; i++) {
        if (pfds[i].revents != 0) px_list_push(r, px_int(pfds[i].fd));
    }
    px_root_pop();
    return r;
}

static void bytes_to_hex(const unsigned char* in, size_t len, char* out) {
    static const char HEX[] = "0123456789abcdef";
    for (size_t i = 0; i < len; i++) {
        out[i * 2] = HEX[in[i] >> 4];
        out[i * 2 + 1] = HEX[in[i] & 0x0F];
    }
    out[len * 2] = '\0';
}

// ==================== M21 base64（RFC 4648 标准，带 padding） ====================

static const char B64_TBL[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static int b64_val(char c) {
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '+') return 62;
    if (c == '/') return 63;
    return -1;
}

// base64_encode(data) → str（RFC 4648 标准，带 padding；非字符串自动字符串化）
static LXValue bi_base64_encode(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: base64_encode 需要一个参数");
    const char* data = bdata(args[0]);
    int len = blen(args[0]);
    int olen = ((len + 2) / 3) * 4;
    char* out = xmalloc((size_t)olen + 1);
    int oi = 0, i = 0;
    while (i + 3 <= len) {
        unsigned n = ((unsigned char)data[i] << 16) | ((unsigned char)data[i+1] << 8) | (unsigned char)data[i+2];
        out[oi++] = B64_TBL[(n >> 18) & 63];
        out[oi++] = B64_TBL[(n >> 12) & 63];
        out[oi++] = B64_TBL[(n >> 6) & 63];
        out[oi++] = B64_TBL[n & 63];
        i += 3;
    }
    int rem = len - i;
    if (rem == 1) {
        unsigned n = (unsigned char)data[i] << 16;
        out[oi++] = B64_TBL[(n >> 18) & 63];
        out[oi++] = B64_TBL[(n >> 12) & 63];
        out[oi++] = '='; out[oi++] = '=';
    } else if (rem == 2) {
        unsigned n = ((unsigned char)data[i] << 16) | ((unsigned char)data[i+1] << 8);
        out[oi++] = B64_TBL[(n >> 18) & 63];
        out[oi++] = B64_TBL[(n >> 12) & 63];
        out[oi++] = B64_TBL[(n >> 6) & 63];
        out[oi++] = '=';
    }
    out[oi] = 0;
    LXValue r = px_str_len(out, oi);
    xfree(out);
    return r;
}

// base64_decode(b64) → str 或 null（非法输入返回 null，不抛错）
static LXValue bi_base64_decode(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: base64_decode 需要一个参数");
    const char* s = val_cstr(args[0]);
    int n = (int)strlen(s);
    int pad = 0;
    while (n > 0 && s[n-1] == '=') { pad++; n--; }
    if (pad > 2 || (n % 4) == 1) return px_null();
    int cap = (n / 4) * 3 + 3;
    char* out = xmalloc((size_t)cap + 1);
    int oi = 0, i = 0, q[4], qi = 0;
    while (i < n) {
        int v = b64_val(s[i]);
        if (v < 0) { xfree(out); return px_null(); }
        q[qi++] = v;
        if (qi == 4) {
            unsigned vv = ((unsigned)q[0] << 18) | ((unsigned)q[1] << 12) | ((unsigned)q[2] << 6) | (unsigned)q[3];
            out[oi++] = (char)((vv >> 16) & 0xFF);
            out[oi++] = (char)((vv >> 8) & 0xFF);
            out[oi++] = (char)(vv & 0xFF);
            qi = 0;
        }
        i++;
    }
    if (qi == 2) {
        unsigned vv = ((unsigned)q[0] << 18) | ((unsigned)q[1] << 12);
        out[oi++] = (char)((vv >> 16) & 0xFF);
    } else if (qi == 3) {
        unsigned vv = ((unsigned)q[0] << 18) | ((unsigned)q[1] << 12) | ((unsigned)q[2] << 6);
        out[oi++] = (char)((vv >> 16) & 0xFF);
        out[oi++] = (char)((vv >> 8) & 0xFF);
    } else if (qi != 0) {
        xfree(out); return px_null();
    }
    out[oi] = 0;
    LXValue r = px_str_len(out, oi);
    xfree(out);
    return r;
}

// ==================== M22 P1：位运算 / 二进制数据视图 ====================
// int_to_hex(n, width) → str（固定宽度小写 hex，负数按补码取低 4*width 位）
static LXValue bi_int_to_hex(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 2) px_error("R1002: int_to_hex 需要 (n, width) 参数");
    int64_t n = int_val(args[0]);
    int64_t w = int_val(args[1]);
    if (w < 1 || w > 16) px_error("R1002: int_to_hex 的 width 必须在 1..16");
    uint64_t mask = (w >= 16) ? ~0ULL : ((1ULL << (4 * (int)w)) - 1);
    uint64_t v = (uint64_t)n & mask;
    char out[40];
    snprintf(out, sizeof(out), "%0*llx", (int)w, (unsigned long long)v);
    return px_str(out);
}

// hex_to_int(hex) → int 或 null（非法 → null；允许空白）
static LXValue bi_hex_to_int(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: hex_to_int 需要一个参数");
    const char* s = val_cstr(args[0]);
    while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
    if (*s == '\0') return px_null();
    char* end = NULL;
    errno = 0;
    long long v = strtoll(s, &end, 16);
    while (end && (*end == ' ' || *end == '\t' || *end == '\n' || *end == '\r')) end++;
    if (errno != 0 || end == s || (end && *end != '\0')) return px_null();
    return px_int((int64_t)v);
}

// bytes_to_hex(data) → str（字节 → 小写 hex；非字符串自动字符串化）
static LXValue bi_bytes_to_hex(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: bytes_to_hex 需要一个参数");
    const char* data = bdata(args[0]);
    int len = blen(args[0]);
    char* out = xmalloc((size_t)len * 2 + 1);
    bytes_to_hex((const unsigned char*)data, (size_t)len, out);
    LXValue r = px_str(out);
    xfree(out);
    return r;
}

// hex_to_bytes(hex) → bytes 或 null（hex → 原始字节；非法/奇数长度 → null）
// M129（Issue 87 缺陷 34）：**空串必须返回零长度 bytes，而不是 null** ——
//   Go 的 `hex.DecodeString("")` 返回空切片（无错误），因此 `hex_to_bytes("")` 的
//   null 会让 `bytes_len`/`bytes_concat` 直接 R1002 杀进程；更糟的是把 null 一路
//   传给 `sha256`/`base64_encode` 会**静默**算出错误摘要（见缺陷 35）。
//   合法性与"非法 hex"必须分开：空串合法，奇数长度/非 hex 字符才是 null。
//   ⚠️ 已知与 Go 的**宽容差异**（缺陷 36，暂留以保兼容）：本实现会**剥掉空白字符**
//   后再解码，Go `hex.DecodeString` 则对空白报错。移植代码若依赖"含空格即失败"的
//   行为需自行校验（本仓库的所有调用点都先 trim，不受影响）。
static LXValue bi_hex_to_bytes(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: hex_to_bytes 需要一个参数");
    const char* s = val_cstr(args[0]);
    size_t n = strlen(s);
    char* clean = xmalloc(n + 1);
    size_t m = 0;
    for (size_t i = 0; i < n; i++) {
        if (s[i] != ' ' && s[i] != '\t' && s[i] != '\n' && s[i] != '\r') clean[m++] = s[i];
    }
    clean[m] = 0;
    if (m % 2 != 0) { xfree(clean); return px_null(); }
    if (m == 0) { xfree(clean); return px_bytes_len(NULL, 0); }
    size_t olen = m / 2;
    char* out = xmalloc(olen + 1);
    for (size_t i = 0; i < m; i += 2) {
        int hi = -1, lo = -1;
        char c = clean[i];
        if (c >= '0' && c <= '9') hi = c - '0';
        else if (c >= 'a' && c <= 'f') hi = c - 'a' + 10;
        else if (c >= 'A' && c <= 'F') hi = c - 'A' + 10;
        c = clean[i + 1];
        if (c >= '0' && c <= '9') lo = c - '0';
        else if (c >= 'a' && c <= 'f') lo = c - 'a' + 10;
        else if (c >= 'A' && c <= 'F') lo = c - 'A' + 10;
        if (hi < 0 || lo < 0) { xfree(clean); xfree(out); return px_null(); }
        out[i / 2] = (char)((hi << 4) | lo);
    }
    out[olen] = 0;
    xfree(clean);
    LXValue r = px_bytes_len(out, (int)olen);
    xfree(out);
    return r;
}

// bit_count(n) → int（popcount：二进制中 1 的个数）
static LXValue bi_bit_count(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: bit_count 需要一个参数");
    uint64_t v = (uint64_t)int_val(args[0]);
    int c = 0;
    while (v) { v &= v - 1; c++; }
    return px_int(c);
}

// bit_length(n) → int（二进制位数；n<=0 → 0）
static LXValue bi_bit_length(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: bit_length 需要一个参数");
    int64_t n = int_val(args[0]);
    if (n <= 0) return px_int(0);
    int bits = 0;
    uint64_t v = (uint64_t)n;
    while (v) { bits++; v >>= 1; }
    return px_int(bits);
}

// sha256(data) → 64 字符小写 hex 字符串（mbedtls 实现，与解释器一致）
// M84-S2（Issue 21）：bdata/blen 二进制安全——接受 str|bytes|数值，bytes 与含 NUL 载荷
// 完整哈希（不再被 strlen 截断）；纯 ASCII str 输出与旧版逐字节一致（零回归）。
static LXValue bi_sha256(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: sha256 需要一个参数");
    const char* data = bdata(args[0]);
    int len = blen(args[0]);
    unsigned char digest[32];
    if (mbedtls_sha256((const unsigned char*)data, (size_t)len, digest, 0) != 0)
        px_error("sha256 计算失败");
    char hex[65];
    bytes_to_hex(digest, 32, hex);
    return px_str(hex);
}

// hmac_sha256(key, msg) → 64 字符小写 hex（HMAC-SHA256）
// M84-S2（Issue 21 GAP-HMAC-1）：key/msg 均收 str|bytes，二进制安全可含 NUL（数值自动
// 字符串化，与 bytes() 语义一致）。腾讯云 TC3 4 级 HMAC 链 / SigV4 / webhook / JWT HS256 解锁。
static void px_hmac_sha256(const unsigned char* key, int klen,
                           const unsigned char* data, int dlen, unsigned char out[32]);
static LXValue bi_hmac_sha256(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 2) px_error("R1002: hmac_sha256 需要 (key, msg) 参数");
    const unsigned char* kd = (const unsigned char*)bdata(args[0]);
    int kl = blen(args[0]);
    const unsigned char* md = (const unsigned char*)bdata(args[1]);
    int ml = blen(args[1]);
    unsigned char digest[32];
    px_hmac_sha256(kd, kl, md, ml, digest);
    char hex[65];
    bytes_to_hex(digest, 32, hex);
    return px_str(hex);
}

// ═══ M150（第 32 轮）：摘要 / 密钥派生族（md5 / md5_bytes / pbkdf2_sha256）═══
// 动机（token-cache 的 PostgreSQL 驱动移植 = lib/pq v1.12.3 的**认证面**）：
//   ① **MD5**：`AuthenticationMD5Password`(code 5) 的应答是一个嵌套 MD5 ——
//        "md5" + hex( md5( hex(md5(password || user)) || salt ) )
//      语言里只有 sha256 / hmac_sha256（M84-S2），**没有 md5**。
//   ② **PBKDF2-HMAC-SHA256**：`SCRAM-SHA-256`（PG 14+ 服务端的默认认证方式）里
//        `SaltedPassword = Hi(password, salt, i)` 就是 PBKDF2 迭代；语言里没有 PBKDF2，
//        手搓只能借 `hmac_sha256`（返回 **hex 文本**）⇒ 每轮都要 hex↔bytes 往返。
// 口径（与既有族一致，不发明新约定）：
//   md5(data)        → 32 字符**小写 hex**（= `hex.EncodeToString(md5.Sum(x)[:])`）
//   md5_bytes(data)  → 16 **字节**（= `md5.Sum(x)` 本身；要文本用 bytes_to_hex）
//   pbkdf2_sha256(password, salt, iterations, dklen) → **原始字节**（密钥材料是二进制）
//     · password/salt 收 str|bytes（二进制安全可含 NUL；数值自动字符串化，同 bytes()）
//     · iterations < 1 → 1（RFC 8018 要求 c ≥ 1；Go 的 x/crypto/pbkdf2 亦如此收敛）
//     · dklen < 1 → 32（SHA-256 输出宽度）；dklen > 4096 → 4096（防误用巨量分配）
//   底层取 mbedtls 3.6.2 的 `mbedtls_md5` / `mbedtls_pkcs5_pbkdf2_hmac_ext`（与 RFC 逐字节一致）。
static LXValue bi_md5(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: md5 需要一个参数 (data)");
    const unsigned char* d = (const unsigned char*)bdata(args[0]);
    int n = blen(args[0]);
    unsigned char digest[16];
    if (mbedtls_md5(d, (size_t)n, digest) != 0) px_error("md5 计算失败");
    char hex[33];
    bytes_to_hex(digest, 16, hex);
    return px_str(hex);
}

static LXValue bi_md5_bytes(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: md5_bytes 需要一个参数 (data)");
    const unsigned char* d = (const unsigned char*)bdata(args[0]);
    int n = blen(args[0]);
    unsigned char digest[16];
    if (mbedtls_md5(d, (size_t)n, digest) != 0) px_error("md5 计算失败");
    return px_bytes_len(digest, 16);
}

static LXValue bi_pbkdf2_sha256(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 4) px_error("R1002: pbkdf2_sha256 需要 (password, salt, iterations, dklen) 参数");
    if (args[2].type != PX_INT || args[3].type != PX_INT)
        px_error("R1002: pbkdf2_sha256 的 iterations/dklen 需要 int");
    const unsigned char* pw = (const unsigned char*)bdata(args[0]);
    int pwl = blen(args[0]);
    const unsigned char* salt = (const unsigned char*)bdata(args[1]);
    int sl = blen(args[1]);
    int64_t iters = args[2].as.i;
    int64_t dklen = args[3].as.i;
    if (iters < 1) iters = 1;
    if (iters > 0x7fffffffLL) iters = 0x7fffffffLL;
    if (dklen < 1) dklen = 32;
    if (dklen > 4096) dklen = 4096;
    unsigned char* out = (unsigned char*)xmalloc((size_t)dklen);
    int ret = mbedtls_pkcs5_pbkdf2_hmac_ext(MBEDTLS_MD_SHA256, pw, (size_t)pwl,
                                            salt, (size_t)sl, (unsigned int)iters,
                                            (uint32_t)dklen, out);
    if (ret != 0) { xfree(out); px_error("pbkdf2_sha256 计算失败 (%d)", ret); }
    LXValue r = px_bytes_len(out, (int)dklen);
    xfree(out);
    return r;
}

// dns_lookup(domain) → list[str]（IPv4+IPv6 全部地址，A/AAAA）
// M84-S3（Issue 22 GAP-DNS-1）：getaddrinfo(AF_UNSPEC+SOCK_STREAM) 域名解析原生实现——
// 守护类模块（bs-safeip util.px resolve_ips 每轮解析）不再依赖 getent 外部命令代偿。
// 返回全部 A+AAAA 地址（顺序即 getaddrinfo 返回序）；解析失败
// （NXDOMAIN/超时/无地址记录）返回 Err("dns: <host>: <原因>")，调用方可 is_err()/`?` 判定。
static LXValue bi_dns_lookup(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: dns_lookup 需要一个参数 (domain)");
    const char* host = val_cstr(args[0]);
    char msg[320];
    struct addrinfo hints, *res = NULL;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;      // A + AAAA
    hints.ai_socktype = SOCK_STREAM;  // 与 hconnect 同口径，避免重复返回
    int rc = getaddrinfo(host, NULL, &hints, &res);
    if (rc != 0) {
        snprintf(msg, sizeof(msg), "dns: %s: %s", host, gai_strerror(rc));
        return px_err(px_str(msg));
    }
    LXValue list = px_list(0);
    px_root_push();
    PX_KEEP(list);   // M92 precise：累积 list 跨 px_list_push/px_str 分配
    char ip[INET6_ADDRSTRLEN];
    for (struct addrinfo* p = res; p; p = p->ai_next) {
        const void* src = NULL;
        if (p->ai_family == AF_INET)
            src = &((struct sockaddr_in*)p->ai_addr)->sin_addr;
        else if (p->ai_family == AF_INET6)
            src = &((struct sockaddr_in6*)p->ai_addr)->sin6_addr;
        if (src && inet_ntop(p->ai_family, src, ip, sizeof(ip)))
            px_list_push(list, px_str(ip));
    }
    freeaddrinfo(res);
    if (list.as.obj->as.list.len == 0) {
        snprintf(msg, sizeof(msg), "dns: %s: no address records", host);
        px_root_pop();
        return px_err(px_str(msg));
    }
    px_root_pop();
    return list;
}

// ---- M103-S2a（Issue 29 GAP-DNS-TXT-1）：DNS TXT 查询（TYPE=16，手写 UDP wire）----
// ws-ddns server 端授权 TXT 校验 native：getaddrinfo 只 A/AAAA（结构上不可能返回 TXT），
// libc res_query 在 musl（交叉 aarch64/armv7/riscv64）仅 A/AAAA 桩、mingw 无 → 手写
// DNS 报文经系统 resolv.conf nameserver UDP 查询，跨 glibc/musl/mingw 零依赖。
// 返回全部 TXT 记录字符串 list（多段 character-string 合并，对齐 Go net.LookupTXT）；
// 无 TXT 记录/NXDOMAIN → 空 list（非报错：授权 TXT 可能未配置，调用方按无记录处理）；
// 查询失败（无 nameserver/超时/TC 截断/格式错）→ Err("dns: <host>: <原因>") 可 is_err 判定。
static uint16_t dns_txt_next_id(void) {
    static unsigned int c = 0x51f15e;
    c = c * 1103515245u + 12345u;
    return (uint16_t)((c >> 8) ^ (unsigned int)getpid() ^ (unsigned int)time(NULL));
}
// 跳过 DNS name（label 序列或压缩指针），返回新 offset；非法返回 -1
static int dns_skip_name(const unsigned char* b, int blen, int off) {
    while (off < blen) {
        int l = b[off];
        if ((l & 0xC0) == 0xC0) return off + 2;   // 压缩指针：2 字节结束
        if (l == 0) return off + 1;               // root 结束
        if (l > 63) return -1;
        off += 1 + l;
    }
    return -1;
}
// ---- M116（qg-issue 71 D5）：DNS over TCP 回退（RFC 1035 §4.2.2）----
//   UDP 响应置 TC（截断）时改用 TCP 重发。此前直接 Err("response truncated (TCP
//   回退二期)")，后果不是"少个功能"而是**能力面倒挂**：Go 的 net.LookupTXT 自动
//   回退 TCP，故 `dns_txt("google.com")` / `dns_txt("cloudflare.com")` 这类多记录、
//   长 TXT 域名在 PuXian 侧直接失败 —— 而 ws-ddns 这类"TXT 就是协议载体"的系统里
//   多记录/长 TXT 恰恰是常态。
//   线格式：2 字节长度前缀（大端）+ 原查询报文；响应同为 2 字节长度前缀。
//   返回响应字节数，失败 -1 并把原因写入 msg。
static int dns_tcp_query(const char* ns, const unsigned char* q, int ql,
                         unsigned char* rb, int rbsz, char* msg, size_t msgsz) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) { snprintf(msg, msgsz, "dns: tcp socket() failed"); return -1; }
    struct sockaddr_in sa;
    memset(&sa, 0, sizeof(sa));
    sa.sin_family = AF_INET;
    sa.sin_port = htons(53);
    if (inet_pton(AF_INET, ns, &sa.sin_addr) != 1) {
        close(fd); snprintf(msg, msgsz, "dns: bad nameserver %s", ns); return -1;
    }
    struct timeval tv;
    tv.tv_sec = 3; tv.tv_usec = 0;
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
    if (connect(fd, (struct sockaddr*)&sa, sizeof(sa)) != 0) {
        close(fd); snprintf(msg, msgsz, "dns: tcp connect() failed"); return -1;
    }
    if (ql + 2 > 4096) { close(fd); snprintf(msg, msgsz, "dns: tcp query too large"); return -1; }
    unsigned char wb[4096];
    wb[0] = (unsigned char)((ql >> 8) & 0xFF);
    wb[1] = (unsigned char)(ql & 0xFF);
    memcpy(wb + 2, q, (size_t)ql);
    if (send(fd, wb, (size_t)ql + 2, 0) != ql + 2) {
        close(fd); snprintf(msg, msgsz, "dns: tcp send() failed"); return -1;
    }
    // TCP 是字节流：长度前缀与报文体都可能短读 → 循环读满
    int got = 0;
    while (got < 2) {
        ssize_t n = recv(fd, wb + got, (size_t)(2 - got), 0);
        if (n <= 0) { close(fd); snprintf(msg, msgsz, "dns: tcp length read failed"); return -1; }
        got += (int)n;
    }
    int rlen = (wb[0] << 8) | wb[1];
    if (rlen <= 0 || rlen > rbsz) {
        close(fd); snprintf(msg, msgsz, "dns: tcp response size %d out of range", rlen); return -1;
    }
    got = 0;
    while (got < rlen) {
        ssize_t n = recv(fd, rb + got, (size_t)(rlen - got), 0);
        if (n <= 0) { close(fd); snprintf(msg, msgsz, "dns: tcp body read failed"); return -1; }
        got += (int)n;
    }
    close(fd);
    return rlen;
}
static LXValue bi_dns_txt(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: dns_txt 需要一个参数 (domain)");
    const char* host = val_cstr(args[0]);
    char msg[320];
    if (host[0] == '\0') return px_err(px_str("dns: empty domain"));
    // 1) resolv.conf 首个 nameserver
    char ns[64] = "";
    FILE* rf = fopen("/etc/resolv.conf", "r");
    if (rf) {
        char line[256];
        while (fgets(line, (int)sizeof(line), rf)) {
            char kw[16] = "", ip[64] = "";
            if (sscanf(line, " %15s %63s", kw, ip) == 2 && strcmp(kw, "nameserver") == 0) {
                snprintf(ns, sizeof(ns), "%s", ip);
                break;
            }
        }
        fclose(rf);
    }
    if (ns[0] == '\0') {
        snprintf(msg, sizeof(msg), "dns: %s: no nameserver in /etc/resolv.conf", host);
        return px_err(px_str(msg));
    }
    // 2) 编码 query（header + question QTYPE=TXT(16) QCLASS=IN(1)）
    unsigned char q[512];
    uint16_t id = dns_txt_next_id();
    q[0] = (unsigned char)(id >> 8); q[1] = (unsigned char)(id & 0xFF);
    q[2] = 0x01; q[3] = 0x00;                    // RD
    q[4] = 0; q[5] = 1;                          // QDCOUNT=1
    memset(q + 6, 0, 6);                         // AN/NS/AR=0
    int ql = 12;
    const char* p = host;
    while (*p) {
        const char* dot = strchr(p, '.');
        int l = dot ? (int)(dot - p) : (int)strlen(p);
        if (l <= 0 || l > 63) {
            snprintf(msg, sizeof(msg), "dns: %s: invalid domain label", host);
            return px_err(px_str(msg));
        }
        if (ql + 1 + l + 5 > (int)sizeof(q)) {
            snprintf(msg, sizeof(msg), "dns: %s: domain too long", host);
            return px_err(px_str(msg));
        }
        q[ql++] = (unsigned char)l;
        memcpy(q + ql, p, (size_t)l); ql += l;
        p = dot ? dot + 1 : p + l;
        if (dot && *(dot + 1) == '\0') break;    // 尾点：root 段由下面统一补
    }
    q[ql++] = 0;                                 // root
    q[ql++] = 0; q[ql++] = 16;                   // QTYPE TXT
    q[ql++] = 0; q[ql++] = 1;                    // QCLASS IN
    // 3) UDP 发送（nameserver:53，SO_RCVTIMEO 3s）
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) return px_err(px_str("dns: socket() failed"));
    struct sockaddr_in sa;
    memset(&sa, 0, sizeof(sa));
    sa.sin_family = AF_INET;
    sa.sin_port = htons(53);
    if (inet_pton(AF_INET, ns, &sa.sin_addr) != 1) {
        close(fd);
        snprintf(msg, sizeof(msg), "dns: %s: bad nameserver %s", host, ns);
        return px_err(px_str(msg));
    }
    if (connect(fd, (struct sockaddr*)&sa, sizeof(sa)) != 0) {
        close(fd);
        return px_err(px_str("dns: connect() failed"));
    }
    struct timeval tv;
    tv.tv_sec = 3; tv.tv_usec = 0;
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    if (send(fd, q, ql, 0) != ql) { close(fd); return px_err(px_str("dns: send() failed")); }
    unsigned char rb[4096];
    int rl = (int)recv(fd, rb, sizeof(rb), 0);
    close(fd);
    if (rl < 0) {
        snprintf(msg, sizeof(msg), "dns: %s: query timeout", host);
        return px_err(px_str(msg));
    }
    // 3b) M116（qg-issue 71 D5）：TC=1（UDP 放不下）→ TCP 重发同一查询
    //     （RFC 1035 §4.2.2；QUERY 的 TC 位在 flags 高位字节 bit1）
    if (rl >= 4 && (rb[2] & 0x02) != 0) {
        int tl = dns_tcp_query(ns, q, ql, rb, (int)sizeof(rb), msg, sizeof(msg));
        if (tl < 0) return px_err(px_str(msg));
        rl = tl;
    }
    // 4) 解析响应
    if (rl < 12) return px_err(px_str("dns: short response"));
    uint16_t rid = (uint16_t)((rb[0] << 8) | rb[1]);
    if (rid != id) return px_err(px_str("dns: response id mismatch"));
    uint16_t flags = (uint16_t)((rb[2] << 8) | rb[3]);
    if ((flags & 0x8000) == 0) return px_err(px_str("dns: not a response"));
    int rcode = flags & 0x000F;
    if (rcode == 3) return px_list(0);           // NXDOMAIN → 无记录 → 空 list（非报错）
    if (rcode != 0) {
        snprintf(msg, sizeof(msg), "dns: %s: rcode=%d", host, rcode);
        return px_err(px_str(msg));
    }
    if (flags & 0x0200) {
        // M116（qg-issue 71 D5）：正常路径已在上面走 TCP 回退；此处仅剩"TCP 响应
        //   仍置 TC"的病态情形（服务端实现异常），保留显式报错不静默。
        snprintf(msg, sizeof(msg), "dns: %s: response truncated (TCP 回退后仍置 TC)", host);
        return px_err(px_str(msg));
    }
    int qd = (rb[4] << 8) | rb[5];
    int an = (rb[6] << 8) | rb[7];
    if (qd < 1) return px_err(px_str("dns: no question in response"));
    int off = 12;
    for (int i = 0; i < qd; i++) {
        off = dns_skip_name(rb, rl, off);
        if (off < 0 || off + 4 > rl) return px_err(px_str("dns: bad question"));
        off += 4;
    }
    char* txts[128];
    int nt = 0;
    int bad = 0;
    while (an-- > 0) {
        off = dns_skip_name(rb, rl, off);
        if (off < 0 || off + 10 > rl) { bad = 1; break; }
        int rtype = (rb[off] << 8) | rb[off + 1];
        int rclass = (rb[off + 2] << 8) | rb[off + 3];
        int rdlen = (rb[off + 8] << 8) | rb[off + 9];   // TYPE2+CLASS2+TTL4 后 RDLENGTH2
        off += 10;
        if (off + rdlen > rl) { bad = 1; break; }
        if (rtype == 16 && rclass == 1) {
            char tmp[2048];
            int tl = 0;
            int pos = off;
            int end = off + rdlen;
            while (pos < end && tl < (int)sizeof(tmp) - 1) {
                int sl = rb[pos++];
                if (pos + sl > end) break;
                if (tl + sl > (int)sizeof(tmp) - 1) { tl = (int)sizeof(tmp) - 1; break; }
                memcpy(tmp + tl, rb + pos, (size_t)sl); tl += sl; pos += sl;
            }
            tmp[tl] = '\0';
            if (tl > 0 && nt < 128) {
                txts[nt] = (char*)malloc((size_t)tl + 1);
                memcpy(txts[nt], tmp, (size_t)tl + 1);
                nt++;
            }
        }
        off += rdlen;
    }
    LXValue list = px_list(0);
    px_root_push();
    PX_KEEP(list);
    if (!bad) {
        for (int i = 0; i < nt; i++) px_list_push(list, px_str(txts[i]));
    }
    px_root_pop();
    for (int i = 0; i < nt; i++) free(txts[i]);
    if (bad) return px_err(px_str("dns: malformed response"));
    return list;
}

// ---- XXH64（xxHash, seed=0）----
#define XXH_P1 0x9E3779B185EBCA87ULL
#define XXH_P2 0xC2B2AE3D27D4EB4FULL
#define XXH_P3 0x165667B19E3779F9ULL
#define XXH_P4 0x85EBCA77C2B2AE63ULL
#define XXH_P5 0x27D4EB2F165667C5ULL

static uint64_t xxh_rotl(uint64_t x, int r) { return (x << r) | (x >> (64 - r)); }

static uint64_t xxh_round(uint64_t acc, uint64_t input) {
    acc += input * XXH_P2;
    acc = xxh_rotl(acc, 31);
    acc *= XXH_P1;
    return acc;
}

static uint64_t xxh_merge(uint64_t acc, uint64_t val) {
    acc ^= xxh_round(0, val);
    acc = acc * XXH_P1 + XXH_P4;
    return acc;
}

static uint64_t rd64(const unsigned char* p) {
    uint64_t v = 0;
    for (int i = 7; i >= 0; i--) v = (v << 8) | p[i];
    return v;
}

static uint64_t xxh64(const unsigned char* data, size_t len) {
    size_t p = 0;
    uint64_t h;
    if (len >= 32) {
        uint64_t v1 = XXH_P1 + XXH_P2, v2 = XXH_P2, v3 = 0, v4 = 0 - XXH_P1;
        while (p + 32 <= len) {
            v1 = xxh_round(v1, rd64(data + p));
            v2 = xxh_round(v2, rd64(data + p + 8));
            v3 = xxh_round(v3, rd64(data + p + 16));
            v4 = xxh_round(v4, rd64(data + p + 24));
            p += 32;
        }
        h = xxh_rotl(v1, 1) + xxh_rotl(v2, 7) + xxh_rotl(v3, 12) + xxh_rotl(v4, 18);
        h = xxh_merge(h, v1);
        h = xxh_merge(h, v2);
        h = xxh_merge(h, v3);
        h = xxh_merge(h, v4);
    } else {
        h = XXH_P5;
    }
    h += len;
    while (p + 8 <= len) {
        uint64_t k = xxh_round(0, rd64(data + p));
        h ^= k;
        h = xxh_rotl(h, 27) * XXH_P1 + XXH_P4;
        p += 8;
    }
    if (p + 4 <= len) {
        uint64_t k = 0;
        for (int i = 3; i >= 0; i--) k = (k << 8) | data[p + i];
        h ^= k * XXH_P1;
        h = xxh_rotl(h, 23) * XXH_P2 + XXH_P3;
        p += 4;
    }
    while (p < len) {
        h ^= (uint64_t)data[p] * XXH_P5;
        h = xxh_rotl(h, 11) * XXH_P1;
        p++;
    }
    h ^= h >> 33;
    h *= XXH_P2;
    h ^= h >> 29;
    h *= XXH_P3;
    h ^= h >> 32;
    return h;
}

// xxhash(data) → int（XXH64, seed=0；高速指纹/取模分片）
static LXValue bi_xxhash(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: xxhash 需要一个参数");
    const char* data = val_cstr(args[0]);
    return px_int((int64_t)xxh64((const unsigned char*)data, strlen(data)));
}


// ==================== M15 P1：正则表达式（与解释器 regex.rs 同一回溯算法） ====================
// 候选列表法：rmatch 返回节点从 pos 起的所有 (end, groups) 候选，贪心优先（次数多在前）。
// 支持：字面量/./字符类/\d\w\s(及取反)/量词 * + ? {n,m}/锚点 ^$/(捕获组 9 个)/交替 |/转义

enum { RN_CHAR = 0, RN_ANY, RN_CLASS, RN_SEQ, RN_ALT, RN_REP, RN_GROUP, RN_START, RN_END,
       // M138（qg-issue 87 缺陷 84）：零宽断言。`\b` / `\B` 是 Go `regexp` 的 ASCII 词边界
       //   （\w 一侧、\W/\A/\z 一侧）；`\A` / `\z` 复用 RN_START / RN_END。
       //   追加在末尾 ⇒ 既有 9 个取值不变（无任何按类型下标存储/序列化的地方，已核）。
       RN_WB, RN_NWB,
       // M138：`(?m)`（多行）模式下的 ^ $ —— 零宽、按行判定（匹配器 2 行，见 rmatch）
       RN_START_ML, RN_END_ML };
#define RG_N 10

// M110-S1（Issue 34 附页2 / Issue 38）：交替「必备字面核心」整串预筛（见 §2.2 论证，写在
//   rn_necess_core 处）。每项长度上限 RN_CORE_LEN；项数上限 RN_CORE_MAX（超出即放弃预筛，保守）。
#define RN_CORE_MAX 16
#define RN_CORE_LEN 24

typedef struct RNode {
    int type;
    unsigned char ch;        // RN_CHAR
    unsigned char* cls_lo;   // RN_CLASS
    unsigned char* cls_hi;
    int ncls;
    int neg;
    struct RNode** kids;     // RN_SEQ / RN_ALT
    int nkids;
    struct RNode* child;     // RN_REP / RN_GROUP
    int min, max;            // RN_REP
    int gidx;                // RN_GROUP
    // M107-S1b（Issue 34 建议 A 的保守子集）：根节点的「必备字面前缀」（由 rcompile 填充，预筛用）
    unsigned char lit[32];
    int lit_len;
    // M110-S1（Issue 34 附页2 / Issue 38）：根节点的「必备字面核心」集合（由 rcompile 填充）。
    //   前缀对「无公共前缀的大交替」（现网 secret_patterns[1]）取不到 ⇒ 回落逐起点 rmatch
    //   （1MB 干净文本 1.54s）。本集合是该情形下的整串预筛：每项都是「模式若匹配则必出现于
    //   文本」的字面串；若一项都不出现 ⇒ 必不匹配 ⇒ 直接返回无匹配。仅根节点使用。
    unsigned char core[RN_CORE_MAX][RN_CORE_LEN];
    unsigned char core_len[RN_CORE_MAX];
    int core_n;
} RNode;

typedef struct { int end; int64_t groups[RG_N]; } RCand;
typedef struct { RCand* items; int len, cap; } RCandList;

static RCandList rcand_new(void) { RCandList l = {0, 0, 0}; return l; }
static void rcand_add(RCandList* l, int end, const int64_t* g) {
    if (l->len >= l->cap) { l->cap = l->cap ? l->cap * 2 : 8; l->items = xrealloc(l->items, sizeof(RCand) * l->cap); }
    l->items[l->len].end = end;
    if (g) memcpy(l->items[l->len].groups, g, sizeof(int64_t) * RG_N);
    l->len++;
}
static void rcand_free(RCandList* l) { if (l->items) { xfree(l->items); l->items = NULL; } l->len = l->cap = 0; }
static void rcand_extend(RCandList* dst, RCandList* src) {
    for (int i = 0; i < src->len; i++) rcand_add(dst, src->items[i].end, src->items[i].groups);
}

// ---- 解析 ----
// M138：内联标志（`(?i)` `(?s)` `(?m)`）——**解析期**落到节点形状，匹配器零改动。
//   作用域：作用于「本组剩余部分」，遇 `)` 由 rp_parse_atom 恢复（与 Go 的组作用域一致）。
typedef struct { const unsigned char* b; int len; int pos; int groups; int f_i; int f_s; int f_m; char err[160]; } RParser;

static int rp_peek(RParser* p) { return p->pos < p->len ? p->b[p->pos] : -1; }
static RNode* rp_new(int type) { RNode* n = xmalloc(sizeof(RNode)); memset(n, 0, sizeof(RNode)); n->type = type; return n; }
static void rp_add_kid(RNode* n, RNode* k) {
    n->kids = xrealloc(n->kids, sizeof(RNode*) * (n->nkids + 1));
    n->kids[n->nkids++] = k;
}
static void rp_free(RNode* n) {
    if (!n) return;
    if (n->kids) { for (int i = 0; i < n->nkids; i++) rp_free(n->kids[i]); xfree(n->kids); }
    if (n->child) rp_free(n->child);
    if (n->cls_lo) xfree(n->cls_lo);
    if (n->cls_hi) xfree(n->cls_hi);
    xfree(n);
}

static RNode* rp_parse_alt(RParser* p);
static RNode* rp_parse_seq(RParser* p);
static RNode* rp_parse_repeat(RParser* p);
static RNode* rp_parse_atom(RParser* p);
static RNode* rp_parse_class(RParser* p);
static RNode* rp_parse_escape(RParser* p);
static int rp_parse_class_elem(RParser* p, unsigned char* lo, unsigned char* hi);

// ---- M138（qg-issue 87 缺陷 84）：转义表**照 Go `regexp/syntax` 实测** ----
// 语料由 Go 本尊生成（examples/m138_regex_go_parity/truth）：**穷举** 0x20..0x7e 全部可打印
//   ASCII 的 `\c`（类外）与 `[\c]`（类内），逐条比对「合法/非法」。
// Go 的规则（ASCII）：
//   · 类转义：d D w W s S（大小写 = 取反）
//   · 控制字符：a f n r t v（**没有 \e**）
//   · 锚点/断言：b B（词边界）· A z（文本首尾）——**类内非法**
//   · 字面引用：Q…E（**类内非法**）· Unicode 类：p P（本引擎无 Unicode 表 ⇒ 显式报错）
//   · 码点：x（`\xHH` / `\x{H…}`）· 八进制 `\0`..`\377`（最多 3 位）
//   · 字面量转义：见下方 rn_escapable_literal（比"标点"更宽：非字母数字皆可，含空格/控制字符）
//   · 其余（`\q` `\e` `\8` `\C` `\Z` `\N` …）一律 `invalid escape sequence`
// ⚠️ 与 POSIX 类的区别：Go 的 `\s` == `[\t\n\f\r ]`（**不含 \v**），
//   而 `[[:space:]]` == `[\t\n\v\f\r ]`（**含 \v**）。本引擎此前两处都用"含 \v"⇒ 已按此拆分。
// M138（Go 实测）：**除 ASCII 字母/数字与非 ASCII 字节外**，任何字节都能转义成字面量
//   —— 含控制字符（0x01..0x1f、0x7f）与空格：`\ ` `\-` `\/` `\,` `\!` `\^` 皆合法。
//   非 ASCII（`\中`）Go 报 invalid escape sequence，本引擎同样报错（按字节判定）。
//   ⚠️ 这张表由 examples/m138_regex_go_parity **穷举** 0x20..0x7e 对照 Go 生成，不靠语感。
static int rn_escapable_literal(int e) {
    if (e < 0 || e > 0x7f) return 0;
    if (e >= '0' && e <= '9') return 0;
    if (e >= 'A' && e <= 'Z') return 0;
    if (e >= 'a' && e <= 'z') return 0;
    return 1;
}

// 码点 → UTF-8 字节数（定义见下；此处前置声明 —— rp_mk_utf8 用它）
static int rp_utf8_encode(int cp, unsigned char* out);
// M138 `(?i)`：大小写折叠辅助（定义在 rp_parse_atom 之前；此处前置声明 —— rp_parse_class /
//   rp_parse_escape 都比它早用到）
static RNode* rp_case_char(int c);
static void rp_fold_class(RNode* cls);

// `\0`..`\777`：首位已在 first，最多再看 2 位八进制（Go 同）
static int rp_octal_escape(RParser* p, int first) {
    int v = first - '0';
    for (int i = 0; i < 2; i++) {
        int c = rp_peek(p);
        if (c < '0' || c > '7') break;
        v = v * 8 + (c - '0');
        p->pos++;
    }
    return v;
}

// `\xHH` 或 `\x{H…}`（进入时 p->pos 指向 'x' 之后）→ 码点；失败返回 -1 并填 p->err
static int rp_hex_escape(RParser* p) {
    int v = 0, n = 0;
    if (rp_peek(p) == '{') {
        p->pos++;
        for (;;) {
            int c = rp_peek(p);
            if (c == '}') { p->pos++; break; }
            int d = -1;
            if (c >= '0' && c <= '9') d = c - '0';
            else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
            else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
            if (d < 0 || n > 8) { snprintf(p->err, sizeof(p->err), "invalid escape sequence: `\\x`"); return -1; }
            v = v * 16 + d;
            n++;
            p->pos++;
        }
        if (n == 0) { snprintf(p->err, sizeof(p->err), "invalid escape sequence: `\\x`"); return -1; }
    } else {
        for (int i = 0; i < 2; i++) {
            int c = rp_peek(p);
            int d = -1;
            if (c >= '0' && c <= '9') d = c - '0';
            else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
            else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
            if (d < 0) { snprintf(p->err, sizeof(p->err), "invalid escape sequence: `\\x`"); return -1; }
            v = v * 16 + d;
            p->pos++;
        }
    }
    // Go 只拒绝 > U+10FFFF 与空 `\x{}`；**surrogate 合法**（`\x{D800}` 实测合法）
    if (v > 0x10FFFF) {
        snprintf(p->err, sizeof(p->err), "invalid escape sequence: `\\x`");
        return -1;
    }
    return v;
}

// 码点 → 节点：< 0x80 单字节 RN_CHAR；否则展开 UTF-8 字节序列（引擎按字节匹配）
static RNode* rp_mk_utf8(int v) {
    unsigned char b[4];
    int bl = rp_utf8_encode(v, b);
    RNode* seq = rp_new(RN_SEQ);
    for (int i = 0; i < bl; i++) {
        RNode* ch = rp_new(RN_CHAR);
        ch->ch = b[i];
        rp_add_kid(seq, ch);
    }
    return seq;
}

// 码点 → UTF-8（最多 4 字节）；返回写入长度
static int rp_utf8_encode(int cp, unsigned char* out) {
    if (cp < 0x80) { out[0] = (unsigned char)cp; return 1; }
    if (cp < 0x800) {
        out[0] = (unsigned char)(0xC0 | (cp >> 6));
        out[1] = (unsigned char)(0x80 | (cp & 0x3F));
        return 2;
    }
    if (cp < 0x10000) {
        out[0] = (unsigned char)(0xE0 | (cp >> 12));
        out[1] = (unsigned char)(0x80 | ((cp >> 6) & 0x3F));
        out[2] = (unsigned char)(0x80 | (cp & 0x3F));
        return 3;
    }
    out[0] = (unsigned char)(0xF0 | (cp >> 18));
    out[1] = (unsigned char)(0x80 | ((cp >> 12) & 0x3F));
    out[2] = (unsigned char)(0x80 | ((cp >> 6) & 0x3F));
    out[3] = (unsigned char)(0x80 | (cp & 0x3F));
    return 4;
}

// 字符类内的转义（e = 反斜杠后的字符，p->pos 已越过 e）。
//   类内合法性 = Go 实测；取反类（D W S）按**字节**展开为互补区间（引擎是字节的）。
static int rp_class_escape(RParser* p, int e, unsigned char* lo, unsigned char* hi) {
    switch (e) {
        case 'd': lo[0] = '0'; hi[0] = '9'; return 1;
        case 'D': lo[0] = 0x00; hi[0] = '/'; lo[1] = ':'; hi[1] = 0xff; return 2;
        case 'w': lo[0]='0';hi[0]='9'; lo[1]='A';hi[1]='Z'; lo[2]='a';hi[2]='z'; lo[3]='_';hi[3]='_'; return 4;
        case 'W': lo[0]=0x00;hi[0]='/'; lo[1]=':';hi[1]='@'; lo[2]='[';hi[2]='^'; lo[3]='`';hi[3]='`'; lo[4]='{';hi[4]=0xff; return 5;
        case 's': lo[0]='\t';hi[0]='\n'; lo[1]=0x0c;hi[1]='\r'; lo[2]=' ';hi[2]=' '; return 3;
        case 'S': lo[0]=0x00;hi[0]=0x08; lo[1]=0x0b;hi[1]=0x0b; lo[2]=0x0e;hi[2]=0x1f; lo[3]='!';hi[3]=0xff; return 4;
        case 'a': lo[0]=0x07; hi[0]=0x07; return 1;
        case 'f': lo[0]=0x0c; hi[0]=0x0c; return 1;
        case 'n': lo[0]='\n'; hi[0]='\n'; return 1;
        case 'r': lo[0]='\r'; hi[0]='\r'; return 1;
        case 't': lo[0]='\t'; hi[0]='\t'; return 1;
        case 'v': lo[0]=0x0b; hi[0]=0x0b; return 1;
        default: break;
    }
    // M138：八进制转义的**入口条件是 Go 的**（非"首位 0-7"）：
    //   首位 `0` ⇒ 合法（后随最多 2 位八进制）；首位 `1`-`7` ⇒ 仅当**后面还有一位八进制**才合法
    //   （`\77` 合法 = 0o77、`\7` 非法：Go 视单字符 `\1`..`\9` 为不支持的反向引用）；
    //   首位 `8`/`9` ⇒ 非法。旧实现（首位 0-7 一律收）把 `\1`..`\7` 误判为合法。
    if (e == '0' || (e >= '1' && e <= '7' && rp_peek(p) >= '0' && rp_peek(p) <= '7')) {
        int v = rp_octal_escape(p, e);
        if (v > 0xff) {
            snprintf(p->err, sizeof(p->err), "字符类内不支持 U+00FF 以上的转义（本引擎按字节匹配）");
            return -1;
        }
        lo[0] = (unsigned char)v; hi[0] = (unsigned char)v; return 1;
    }
    if (e == 'x') {
        int v = rp_hex_escape(p);
        if (v < 0) return -1;
        if (v > 0xff) {
            // 字节引擎无法在字符类里表达多字节码点 —— 报错，绝不静默截断成单个字节
            snprintf(p->err, sizeof(p->err), "字符类内不支持 U+00FF 以上的转义（本引擎按字节匹配）");
            return -1;
        }
        lo[0] = (unsigned char)v; hi[0] = (unsigned char)v; return 1;
    }
    if (e == 'p' || e == 'P') {
        snprintf(p->err, sizeof(p->err), "不支持的转义 \\%c（Unicode 类别：本引擎无 Unicode 表）", e);
        return -1;
    }
    if (e == '\\' || rn_escapable_literal(e)) {
        lo[0] = (unsigned char)e; hi[0] = (unsigned char)e; return 1;
    }
    snprintf(p->err, sizeof(p->err), "invalid escape sequence: `\\%c`", e);   // b B A z Q E C Z …
    return -1;
}

static int rp_parse_class_elem(RParser* p, unsigned char* lo, unsigned char* hi) {
    int c = rp_peek(p);
    if (c < 0) { snprintf(p->err, sizeof(p->err), "字符类提前结束"); return -1; }
    p->pos++;
    if (c == '\\') {
        int e = rp_peek(p);
        if (e < 0) { snprintf(p->err, sizeof(p->err), "转义提前结束"); return -1; }
        p->pos++;
        return rp_class_escape(p, e, lo, hi);   // M138：表驱动（含 D/W/S 取反、b/B 非法）
    }
    lo[0] = (unsigned char)c; hi[0] = (unsigned char)c;
    return 1;
}

// M117（qg-issue 72 F3）：**POSIX 字符类** `[[:space:]]` / `[[:digit:]]` / `[[:alpha:]]` …
//   缺陷现场：字符类解析器不认识 `[:name:]`，把 `[` 当字面量、并把内层 `]` 当**类结束**，
//   于是 `^[[:space:]]{2,}api_key:…` 这类正则**静默不匹配**（regex_search 返回 null，
//   不报错、不告警）—— 实测在 ws-install 的 YAML 行解析上直接失效。
//   修法：在类元素处识别 `[:name:]` 并展开为等价区间；未知名字**报错**（不静默）。
static int rp_posix_class(const char* name, unsigned char* lo, unsigned char* hi) {
    if (strcmp(name, "space") == 0) { lo[0]='\t';hi[0]='\r'; lo[1]=' ';hi[1]=' '; return 2; }
    if (strcmp(name, "digit") == 0) { lo[0]='0';hi[0]='9'; return 1; }
    if (strcmp(name, "alpha") == 0) { lo[0]='A';hi[0]='Z'; lo[1]='a';hi[1]='z'; return 2; }
    if (strcmp(name, "alnum") == 0) { lo[0]='0';hi[0]='9'; lo[1]='A';hi[1]='Z'; lo[2]='a';hi[2]='z'; return 3; }
    if (strcmp(name, "upper") == 0) { lo[0]='A';hi[0]='Z'; return 1; }
    if (strcmp(name, "lower") == 0) { lo[0]='a';hi[0]='z'; return 1; }
    if (strcmp(name, "xdigit") == 0) { lo[0]='0';hi[0]='9'; lo[1]='A';hi[1]='F'; lo[2]='a';hi[2]='f'; return 3; }
    if (strcmp(name, "blank") == 0) { lo[0]='\t';hi[0]='\t'; lo[1]=' ';hi[1]=' '; return 2; }
    if (strcmp(name, "punct") == 0) {
        lo[0]='!';hi[0]='/'; lo[1]=':';hi[1]='@'; lo[2]='[';hi[2]='`'; lo[3]='{';hi[3]='~'; return 4;
    }
    if (strcmp(name, "print") == 0) { lo[0]=' ';hi[0]='~'; return 1; }
    if (strcmp(name, "graph") == 0) { lo[0]='!';hi[0]='~'; return 1; }
    if (strcmp(name, "cntrl") == 0) { lo[0]=0;hi[0]=0x1f; lo[1]=0x7f;hi[1]=0x7f; return 2; }
    return -1;
}

static RNode* rp_parse_class(RParser* p) {
    p->pos++; // '['
    int neg = 0;
    if (rp_peek(p) == '^') { neg = 1; p->pos++; }
    unsigned char lo[256], hi[256];
    int ncls = 0, first = 1;
    for (;;) {
        int c = rp_peek(p);
        if (c < 0) { snprintf(p->err, sizeof(p->err), "字符类缺少 ]"); return NULL; }
        if (c == ']' && !first) { p->pos++; break; }
        first = 0;
        // M117：`[[:name:]]` —— 类元素为 POSIX 字符类名
        if (c == '[' && p->pos + 1 < p->len && p->b[p->pos + 1] == ':') {
            int close = -1;
            for (int k = p->pos + 2; k + 1 < p->len; k++) {
                if (p->b[k] == ':' && p->b[k + 1] == ']') { close = k; break; }
            }
            if (close > 0) {
                char nm[24];
                int nl = close - (p->pos + 2);
                if (nl > 0 && nl < (int)sizeof(nm)) {
                    memcpy(nm, p->b + p->pos + 2, (size_t)nl);
                    nm[nl] = 0;
                    unsigned char plo[16], phi[16];
                    int pn = rp_posix_class(nm, plo, phi);
                    if (pn < 0) { snprintf(p->err, sizeof(p->err), "未知 POSIX 字符类 [[:%s:]]", nm); return NULL; }
                    p->pos = close + 2;
                    for (int i = 0; i < pn && ncls < 256; i++) { lo[ncls] = plo[i]; hi[ncls] = phi[i]; ncls++; }
                    continue;
                }
            }
        }
        unsigned char elo[10], ehi[10];
        int n = rp_parse_class_elem(p, elo, ehi);
        if (n < 0) return NULL;
        if (n == 1 && rp_peek(p) == '-' && p->pos + 1 < p->len && p->b[p->pos + 1] != ']') {
            p->pos++; // '-'
            unsigned char elo2[10], ehi2[10];
            int n2 = rp_parse_class_elem(p, elo2, ehi2);
            if (n2 < 0) return NULL;
            if (n2 != 1) { snprintf(p->err, sizeof(p->err), "字符范围右端不能是转义类"); return NULL; }
            if (ehi2[0] < elo[0]) { snprintf(p->err, sizeof(p->err), "字符范围 hi < lo"); return NULL; }
            if (ncls < 256) { lo[ncls] = elo[0]; hi[ncls] = ehi2[0]; ncls++; }
        } else {
            for (int i = 0; i < n && ncls < 256; i++) { lo[ncls] = elo[i]; hi[ncls] = ehi[i]; ncls++; }
        }
    }
    if (ncls == 0) { snprintf(p->err, sizeof(p->err), "空字符类"); return NULL; }
    RNode* nd = rp_new(RN_CLASS);
    nd->cls_lo = xmalloc(ncls);
    nd->cls_hi = xmalloc(ncls);
    memcpy(nd->cls_lo, lo, ncls);
    memcpy(nd->cls_hi, hi, ncls);
    nd->ncls = ncls;
    nd->neg = neg;
    if (p->f_i) rp_fold_class(nd);                   // M138 `(?i)`：字符类补大小写对侧
    return nd;
}

static RNode* rp_parse_escape(RParser* p) {
    p->pos++; // '\\'
    int e = rp_peek(p);
    if (e < 0) { snprintf(p->err, sizeof(p->err), "转义字符缺失"); return NULL; }
    p->pos++;
    switch (e) {
        case 'd': case 'D': case 'w': case 'W': case 's': case 'S': {
            RNode* n = rp_new(RN_CLASS);
            unsigned char lo[10], hi[10];
            int cnt = 0, neg = 0;
            switch (e) {
                case 'd': lo[0]='0'; hi[0]='9'; cnt = 1; break;
                case 'D': lo[0]='0'; hi[0]='9'; cnt = 1; neg = 1; break;
                case 'w': lo[0]='0';hi[0]='9'; lo[1]='A';hi[1]='Z'; lo[2]='a';hi[2]='z'; lo[3]='_';hi[3]='_'; cnt = 4; break;
                case 'W': lo[0]='0';hi[0]='9'; lo[1]='A';hi[1]='Z'; lo[2]='a';hi[2]='z'; lo[3]='_';hi[3]='_'; cnt = 4; neg = 1; break;
                // M138：Go 的 \s == [\t\n\f\r ]（**不含 \v**，与 POSIX [[:space:]] 不同）——
                //   旧实现含 0x0b ⇒ `\s` 会多匹一个字节（静默语义差）。
                case 's': lo[0]='\t';hi[0]='\n'; lo[1]=0x0c;hi[1]='\r'; lo[2]=' ';hi[2]=' '; cnt = 3; break;
                case 'S': lo[0]='\t';hi[0]='\n'; lo[1]=0x0c;hi[1]='\r'; lo[2]=' ';hi[2]=' '; cnt = 3; neg = 1; break;
                default: break;
            }
            n->cls_lo = xmalloc(cnt);
            n->cls_hi = xmalloc(cnt);
            memcpy(n->cls_lo, lo, cnt);
            memcpy(n->cls_hi, hi, cnt);
            n->ncls = cnt;
            n->neg = neg;
            return n;
        }
        // M138（缺陷 84）：零宽断言/锚点
        case 'b': return rp_new(RN_WB);
        case 'B': return rp_new(RN_NWB);
        case 'A': return rp_new(RN_START);
        case 'z': return rp_new(RN_END);
        // M138：字面引用 `\Q…\E`（中间全部字面，含 `\` 自身；无 `\E` 则引到模式末尾）
        case 'Q': {
            RNode* seq = rp_new(RN_SEQ);
            while (p->pos < p->len) {
                if (p->b[p->pos] == '\\' && p->pos + 1 < p->len && p->b[p->pos + 1] == 'E') { p->pos += 2; break; }
                RNode* ch = rp_new(RN_CHAR);
                ch->ch = p->b[p->pos];
                p->pos++;
                rp_add_kid(seq, ch);
            }
            return seq;
        }
        case 'a': { RNode* n = rp_new(RN_CHAR); n->ch = 0x07; return n; }
        case 'n': { RNode* n = rp_new(RN_CHAR); n->ch = '\n'; return n; }
        case 't': { RNode* n = rp_new(RN_CHAR); n->ch = '\t'; return n; }
        case 'r': { RNode* n = rp_new(RN_CHAR); n->ch = '\r'; return n; }
        case 'f': { RNode* n = rp_new(RN_CHAR); n->ch = 0x0c; return n; }
        case 'v': { RNode* n = rp_new(RN_CHAR); n->ch = 0x0b; return n; }
        default: break;
    }
    if (e == '0' || (e >= '1' && e <= '7' && rp_peek(p) >= '0' && rp_peek(p) <= '7')) {
        // 八进制 `\0`..`\777`（Go 允许到 U+01FF）；首位非 0 时**必须**还有一位八进制（照 Go）
        int v = rp_octal_escape(p, e);
        if (v < 0x80) { RNode* n = rp_new(RN_CHAR); n->ch = (unsigned char)v; return n; }
        return rp_mk_utf8(v);                         // M138：`\400` = U+0100 ⇒ 展开 UTF-8（旧实现静默截断）
    }
    if (e == 'x') {                                   // `\xHH` / `\x{H…}`
        int v = rp_hex_escape(p);
        if (v < 0) return NULL;
        if (v < 0x80) { RNode* n = rp_new(RN_CHAR); n->ch = (unsigned char)v; return n; }
        return rp_mk_utf8(v);
    }
    if (e == 'p' || e == 'P') {
        snprintf(p->err, sizeof(p->err), "不支持的转义 \\%c（Unicode 类别：本引擎无 Unicode 表）", e);
        return NULL;
    }
    // 除 ASCII 字母/数字与非 ASCII 外的任何字节：字面量（照 Go）
    if (e == '\\' || rn_escapable_literal(e)) {
        if (p->f_i) return rp_case_char(e);          // M138 `(?i)`：转义字面量同样不敏感
        RNode* n = rp_new(RN_CHAR); n->ch = (unsigned char)e; return n;
    }
    snprintf(p->err, sizeof(p->err), "invalid escape sequence: `\\%c`", e);
    return NULL;
}

// ---- M138：内联标志 `(?i)` `(?s)` `(?m)` 与命名组 `(?P<n>…)` `(?<n>…)` ----
//   `(?i)`：字面量 → 大小写两个区间；字符类 → 每个区间补上大小写对侧
//   `(?s)`：`.` → 0x00-0xFF 的类（匹配任意字节，含换行）
//   `(?m)`：`^` `$` → RN_START_ML / RN_END_ML
//   `(?P<n>…)` `(?<n>…)`：**捕获组**（名字只是别名，不改匹配语义）
//   其余 `(?…)`（环视等）→ 显式报错
static int rp_fold_lo(int c) { return (c >= 'A' && c <= 'Z') ? c + 32 : c; }
static int rp_fold_up(int c) { return (c >= 'a' && c <= 'z') ? c - 32 : c; }

// `(?i)` 下的字面量：单字符 → 单区间；ASCII 字母 → 两区间（小写与大写）
static RNode* rp_case_char(int c) {
    RNode* n = rp_new(RN_CLASS);
    n->cls_lo = xmalloc(2);
    n->cls_hi = xmalloc(2);
    unsigned char lo = (unsigned char)rp_fold_lo(c), up = (unsigned char)rp_fold_up(c);
    n->ncls = 0;
    n->cls_lo[n->ncls] = lo; n->cls_hi[n->ncls] = lo; n->ncls++;
    if (up != lo) { n->cls_lo[n->ncls] = up; n->cls_hi[n->ncls] = up; n->ncls++; }
    n->neg = 0;
    return n;
}

// 字符类在 `(?i)` 下的折叠：把每个区间的大小写对侧补进去（原区间保留）
static void rp_fold_class(RNode* cls) {
    int extra_lo[128], extra_hi[128], nx = 0;
    for (int i = 0; i < cls->ncls && nx + 2 < 128; i++) {
        int lo = cls->cls_lo[i], hi = cls->cls_hi[i];
        if (lo >= 'a' && hi <= 'z') { extra_lo[nx] = lo - 32; extra_hi[nx] = hi - 32; nx++; }
        if (lo >= 'A' && hi <= 'Z') { extra_lo[nx] = lo + 32; extra_hi[nx] = hi + 32; nx++; }
    }
    if (nx == 0) return;
    unsigned char* nl = xrealloc(cls->cls_lo, (size_t)(cls->ncls + nx));
    unsigned char* nh = xrealloc(cls->cls_hi, (size_t)(cls->ncls + nx));
    cls->cls_lo = nl; cls->cls_hi = nh;
    for (int i = 0; i < nx; i++) {
        cls->cls_lo[cls->ncls] = (unsigned char)extra_lo[i];
        cls->cls_hi[cls->ncls] = (unsigned char)extra_hi[i];
        cls->ncls++;
    }
}

static RNode* rp_parse_atom(RParser* p) {
    int c = rp_peek(p);
    if (c < 0) { snprintf(p->err, sizeof(p->err), "意外的结尾"); return NULL; }
    switch (c) {
        case '(': {
            p->pos++;
            // M138（qg-issue 87）：`(?:…)` **非捕获组**。此前引擎把 `?:` 当**字面量**
            //   （`(` → 捕获组包裹，`?` 因后面是 ':' 不成量词 ⇒ 字面 '?'，再字面 ':'）⇒
            //   `(?:api[_-]?key|apikey|…)` 这样的模式**永不匹配**，且不报错 ——
            //   实测：`regex_find("(?:ab)", "xaby")` 返回 null（应命中 "ab"）。
            //   现场：token-cache 的 `secret_patterns` 正是这种写法 ⇒ 本地快判静默漏检。
            int noncap = 0;
            int save_i = p->f_i, save_s = p->f_s, save_m = p->f_m;
            if (rp_peek(p) == '?') {
                int c1 = (p->pos + 1 < p->len) ? p->b[p->pos + 1] : -1;
                if (c1 == ':') {
                    p->pos += 2;
                    noncap = 1;
                } else if (c1 == 'P' || c1 == '<') {
                    // (?P<name>…) / (?<name>…) → 捕获组（名字只是别名）
                    int k = (c1 == 'P') ? p->pos + 2 : p->pos + 1;
                    if (k >= p->len || p->b[k] != '<') {
                        snprintf(p->err, sizeof(p->err), "非法的命名组语法 `(?%c…`", c1);
                        return NULL;
                    }
                    k++;
                    while (k < p->len && p->b[k] != '>') k++;
                    if (k >= p->len) { snprintf(p->err, sizeof(p->err), "命名组缺少 `>`"); return NULL; }
                    p->pos = k + 1;
                } else {
                    // 内联标志：形如 (?i) (?is) (?i-s) —— 到一个 ')' 结束且只含标志字符/'-'
                    int k = p->pos + 1, si = 0, ss = 0, sm = 0, neg_seen = 0, bad = 0;
                    while (k < p->len && p->b[k] != ')') {
                        int ch = p->b[k];
                        if (ch == '-') { neg_seen = 1; k++; continue; }
                        if (ch == 'i') { if (neg_seen) p->f_i = 0; else si = 1; }
                        else if (ch == 's') { if (neg_seen) p->f_s = 0; else ss = 1; }
                        else if (ch == 'm') { if (neg_seen) p->f_m = 0; else sm = 1; }
                        else { bad = 1; break; }
                        k++;
                    }
                    if (bad || k >= p->len || k == p->pos + 1) {
                        // 环视（?= ?! ?<= ?<!）等其余形式：**显式报错**，绝不静默降级成字面量
                        snprintf(p->err, sizeof(p->err),
                                 "不支持的组语法 `(?…)`（支持 `(?:…)` `(?P<n>…)` `(?i)` `(?s)` `(?m)`）");
                        return NULL;
                    }
                    if (si) p->f_i = 1;
                    if (ss) p->f_s = 1;
                    if (sm) p->f_m = 1;
                    p->pos = k + 1;              // 越过 ')'
                    return rp_parse_repeat(p);   // 标志本身零宽：继续解析其后的原子
                }
            }
            RNode* node = rp_parse_alt(p);
            p->f_i = save_i; p->f_s = save_s; p->f_m = save_m;   // 组作用域结束 ⇒ 恢复标志
            if (!node) return NULL;
            if (rp_peek(p) != ')') { rp_free(node); snprintf(p->err, sizeof(p->err), "缺少 )"); return NULL; }
            p->pos++;
            if (noncap) return node;                       // 不占捕获组编号、不加 RN_GROUP
            if (p->groups >= 9) { rp_free(node); snprintf(p->err, sizeof(p->err), "捕获组最多 9 个"); return NULL; }
            p->groups++;
            RNode* g = rp_new(RN_GROUP);
            g->child = node;
            g->gidx = p->groups;
            return g;
        }
        case '[': return rp_parse_class(p);
        case '.': p->pos++;
            if (p->f_s) {                       // M138 `(?s)`：`. ` 匹配任意字节（含换行）
                RNode* n = rp_new(RN_CLASS);
                n->cls_lo = xmalloc(1); n->cls_hi = xmalloc(1);
                n->cls_lo[0] = 0x00; n->cls_hi[0] = 0xFF; n->ncls = 1; n->neg = 0;
                return n;
            }
            return rp_new(RN_ANY);
        case '^': p->pos++; return rp_new(p->f_m ? RN_START_ML : RN_START);
        case '$': p->pos++; return rp_new(p->f_m ? RN_END_ML : RN_END);
        case '\\': return rp_parse_escape(p);
        case ')': snprintf(p->err, sizeof(p->err), "意外的 )"); return NULL;
        default:
            p->pos++;
            if (p->f_i) return rp_case_char(c);      // M138 `(?i)`：字面量大小写不敏感
            { RNode* n = rp_new(RN_CHAR); n->ch = (unsigned char)c; return n; }
    }
}

static RNode* rp_parse_repeat(RParser* p) {
    RNode* atom = rp_parse_atom(p);
    if (!atom) return NULL;
    int c = rp_peek(p);
    if (c == '*') { p->pos++; RNode* r = rp_new(RN_REP); r->child = atom; r->min = 0; r->max = -1; return r; }
    if (c == '+') { p->pos++; RNode* r = rp_new(RN_REP); r->child = atom; r->min = 1; r->max = -1; return r; }
    if (c == '?') { p->pos++; RNode* r = rp_new(RN_REP); r->child = atom; r->min = 0; r->max = 1; return r; }
    if (c == '{') {
        int save = p->pos;
        p->pos++;
        int min = 0, got = 0;
        while (rp_peek(p) >= '0' && rp_peek(p) <= '9') { min = min * 10 + (rp_peek(p) - '0'); p->pos++; got = 1; }
        if (!got) { p->pos = save; return atom; }
        int max = -1;
        c = rp_peek(p);
        if (c == '}') { p->pos++; max = min; }
        else if (c == ',') {
            p->pos++;
            if (rp_peek(p) == '}') { p->pos++; max = -1; }
            else {
                int m2 = 0, got2 = 0;
                while (rp_peek(p) >= '0' && rp_peek(p) <= '9') { m2 = m2 * 10 + (rp_peek(p) - '0'); p->pos++; got2 = 1; }
                if (!got2 || rp_peek(p) != '}') { p->pos = save; return atom; }
                p->pos++;
                max = m2;
            }
        } else { p->pos = save; return atom; }
        if (max != -1 && max < min) { snprintf(p->err, sizeof(p->err), "{n,m} 中 m 不能小于 n"); rp_free(atom); return NULL; }
        RNode* r = rp_new(RN_REP);
        r->child = atom;
        r->min = min;
        r->max = max;
        return r;
    }
    return atom;
}

static RNode* rp_parse_seq(RParser* p) {
    RNode* n = rp_new(RN_SEQ);
    for (;;) {
        int c = rp_peek(p);
        if (c < 0 || c == '|' || c == ')') break;
        RNode* r = rp_parse_repeat(p);
        if (!r) { rp_free(n); return NULL; }
        rp_add_kid(n, r);
    }
    if (n->nkids == 1) { RNode* k = n->kids[0]; xfree(n->kids); xfree(n); return k; }
    return n;
}

static RNode* rp_parse_alt(RParser* p) {
    RNode* n = rp_new(RN_ALT);
    RNode* s = rp_parse_seq(p);
    if (!s) { rp_free(n); return NULL; }
    rp_add_kid(n, s);
    while (rp_peek(p) == '|') {
        p->pos++;
        s = rp_parse_seq(p);
        if (!s) { rp_free(n); return NULL; }
        rp_add_kid(n, s);
    }
    if (n->nkids == 1) { RNode* k = n->kids[0]; xfree(n->kids); xfree(n); return k; }
    return n;
}

// ---- M107-S1b（Issue 34 建议 A 的保守子集）：必备字面前缀预筛 ----
// 目的：rsearch_from 原本在**每个起点**都试一次 rmatch；若模式必以某字面串 P 开头（|P|=L>0），
//   则任何匹配起点必落在 P 的出现位置上 ⇒ 用 memchr/自实现字面扫描跳过其余起点。
//   ws-approve 的 7 条 secret_patterns 全部以字面开头（`sk-`/`ghp_`/`AKIA`…），
//   干净大文本上原本「逐起点重试」的 ~104ms/1MB 降为一次扫描（<1ms）。
// 可靠性：**只用于「可证明必消费 P」的形态，其余一律返回 0 = 不启用预筛（回落逐起点原行为）**。
//   1) RN_CHAR / RN_GROUP / RN_SEQ / RN_ALT 直接由结构给出；
//   2) RN_REP 仅当 **min ≥ 1 且 child 恰为固定字面串**（最少消费 min 份该字面）；
//   3) RN_ANY / RN_CLASS 贡献为空；RN_START / RN_END 零宽（确定消费 0 字节）⇒ `^abc` 仍可取得前缀
//      `abc`：预筛只减少「试哪些起点」，且按出现位置**升序**推进，与逐起点升序等价，
//      故不影响「首个匹配起点」的判定（`x|^y` 一类由 ALT 取公共前缀天然排除）；
//   4) 可匹配空串的模式取不到非空前缀（min=0 的 REP / 空分支 ⇒ 返回 0）⇒ 零长匹配语义不受影响；
//   5) 前缀含 NUL 时禁用（避免与 C 字符串扫描混用）。
static int rn_lit_exact(RNode* n, unsigned char* out, int cap, int* outlen) {
    switch (n->type) {
        case RN_CHAR:
            if (cap < 1) return 0;
            out[0] = n->ch; *outlen = 1; return 1;
        case RN_GROUP:
            return rn_lit_exact(n->child, out, cap, outlen);
        case RN_START: case RN_END:      // 零宽：确定消费 0 字节
        case RN_WB: case RN_NWB:         // M138：词边界同为零宽（`\bapi_key\b` 仍能取得前缀 api_key）
        case RN_START_ML: case RN_END_ML: // M138 `(?m)`：行首/行尾同为确定零宽
            *outlen = 0; return 1;
        case RN_SEQ: {
            int tot = 0;
            for (int i = 0; i < n->nkids; i++) {
                int l = 0;
                if (!rn_lit_exact(n->kids[i], out + tot, cap - tot, &l)) return 0;
                tot += l;
            }
            *outlen = tot; return 1;
        }
        case RN_REP:
            if (n->min != n->max) return 0;              // 只有定长 {k} 才算「恰为字面」
            {
                unsigned char tmp[64];
                int l = 0;
                if (n->min > 0 && !rn_lit_exact(n->child, tmp, (int)sizeof(tmp), &l)) return 0;
                if (l > 0 && n->min > cap / l) return 0; // 放不下完整字面 → 不声称「恰为字面」
                for (int i = 0; i < n->min; i++) memcpy(out + i * l, tmp, (size_t)l);
                *outlen = n->min * l; return 1;
            }
        default:
            return 0;                                    // RN_ANY / RN_CLASS / RN_ALT → 非固定字面
    }
}

static int rn_lit_prefix(RNode* n, unsigned char* out, int cap) {
    switch (n->type) {
        case RN_CHAR:
            if (cap < 1) return 0;
            out[0] = n->ch; return 1;
        case RN_GROUP:
            return rn_lit_prefix(n->child, out, cap);
        case RN_SEQ: {
            int tot = 0;
            for (int i = 0; i < n->nkids; i++) {
                int l = 0;
                if (rn_lit_exact(n->kids[i], out + tot, cap - tot, &l)) { tot += l; continue; }
                tot += rn_lit_prefix(n->kids[i], out + tot, cap - tot);  // 非字面块：取其必备前缀后停止
                break;
            }
            return tot;
        }
        case RN_REP:
            if (n->min < 1) return 0;                    // 可能一次都不消费 ⇒ 无必备前缀
            {
                unsigned char tmp[64];
                int l = 0;
                if (!rn_lit_exact(n->child, tmp, (int)sizeof(tmp), &l) || l == 0) return 0;
                int tot = 0;
                for (int i = 0; i < n->min && tot + l <= cap; i++) { memcpy(out + tot, tmp, (size_t)l); tot += l; }
                return tot;
            }
        case RN_ALT: {
            int best = -1;
            for (int i = 0; i < n->nkids; i++) {
                unsigned char tmp[64];
                int l = rn_lit_prefix(n->kids[i], tmp, (int)sizeof(tmp));
                if (l == 0) return 0;
                if (best < 0) { best = l; memcpy(out, tmp, (size_t)l); continue; }
                int m = best < l ? best : l;
                int j = 0;
                while (j < m && out[j] == tmp[j]) j++;
                best = j;
                if (best == 0) return 0;
                memcpy(out, tmp, (size_t)j);
            }
            return best < 0 ? 0 : best;
        }
        default:
            return 0;                                    // RN_ANY / RN_CLASS / RN_START / RN_END
    }
}

// ---- M110-S1（Issue 34 附页2 / Issue 38）：交替「必备字面核心」整串预筛 ----
// 目的：M107-S1b 的必备字面前缀对**无公共前缀的大交替**（现网 `secret_patterns[1]`：
//   `(api[_-]?key|apikey|access[_-]?key|…|auth)\s*(?::=|[:=])…`）取不到前缀 ⇒ 回落
//   `for (s=start; s<=len; s++) rmatch(root,s)`，1MB 干净文本 ≈1541ms（1.5us/字节）。
// 做法：把「前缀」推广为「必备字面核心集合」——对交替的**每个分支**各取一个**可证明必出现于
//   匹配文本中**的字面串，取并集；若整段文本中一个都不出现 ⇒ 该模式必不匹配 ⇒ 直接返回无匹配。
// 可靠性（保守扩张，逐类可证；「若 n 匹配则 out 中至少一项出现于被匹配文本」）：
//   RN_CHAR → {该字符}（匹配即消费该字符）；RN_GROUP → child；
//   RN_REP(min≥1) → child（至少消费一次）；RN_REP(min=0) → 无（可一次都不消费）；
//   RN_SEQ → **首个能给出核心的 kid**（SEQ 匹配 ⇒ 每个 kid 均匹配 ⇒ 该 kid 的核心必出现）；
//   RN_ALT → **每个分支都能给出核心**时取并集（匹配必落在某一分支），任一分支给不出 ⇒ 放弃；
//   RN_ANY / RN_CLASS / RN_START / RN_END → 无（前两者太弱，后两者零宽）。
// 优先复用 rn_lit_prefix（最强；且长度自然截断到 RN_CORE_LEN —— **截断仍保持必要性**）。
// 含 NUL / 超长 / 超项数 一律弃用（保守：宁可放弃预筛，绝不误判）。
typedef struct {
    unsigned char lit[RN_CORE_MAX][RN_CORE_LEN];
    unsigned char len[RN_CORE_MAX];
    int n;
} RCoreSet;

// 加入一项（去重）。返回 0 = 无法容纳（含 NUL / 超长 / 超项数）→ 调用方必须放弃整次预筛。
static int rn_core_add(RCoreSet* s, const unsigned char* p, int l) {
    if (l <= 0 || l > RN_CORE_LEN) return 0;
    for (int i = 0; i < l; i++) if (p[i] == 0) return 0;
    for (int i = 0; i < s->n; i++) {
        if (s->len[i] == l && memcmp(s->lit[i], p, (size_t)l) == 0) return 1;   // 去重：已存在
    }
    if (s->n >= RN_CORE_MAX) return 0;
    memcpy(s->lit[s->n], p, (size_t)l);
    s->len[s->n] = (unsigned char)l;
    s->n++;
    return 1;
}

static int rn_necess_core(RNode* n, RCoreSet* out) {
    // 1) 先试「必备字面前缀」——最强，且长度自然截断（截断不破坏必要性）
    unsigned char buf[RN_CORE_LEN];
    int L = rn_lit_prefix(n, buf, RN_CORE_LEN);
    if (L > 0) return rn_core_add(out, buf, L);
    switch (n->type) {
        case RN_GROUP:
            return rn_necess_core(n->child, out);
        case RN_REP:
            if (n->min < 1) return 0;                       // 可不消费 ⇒ 无必备核心
            return rn_necess_core(n->child, out);
        case RN_SEQ: {
            for (int i = 0; i < n->nkids; i++) {
                RCoreSet tmp; memset(&tmp, 0, sizeof(tmp));
                if (!rn_necess_core(n->kids[i], &tmp) || tmp.n == 0) continue;   // 该 kid 给不出 → 试下一个
                for (int j = 0; j < tmp.n; j++) if (!rn_core_add(out, tmp.lit[j], tmp.len[j])) return 0;
                return 1;
            }
            return 0;
        }
        case RN_ALT: {
            for (int i = 0; i < n->nkids; i++) {
                RCoreSet tmp; memset(&tmp, 0, sizeof(tmp));
                if (!rn_necess_core(n->kids[i], &tmp) || tmp.n == 0) return 0;   // 任一分支给不出 → 整条放弃
                for (int j = 0; j < tmp.n; j++) if (!rn_core_add(out, tmp.lit[j], tmp.len[j])) return 0;
            }
            return out->n > 0;
        }
        default:
            return 0;                                        // RN_ANY / RN_CLASS / RN_START / RN_END
    }
}

// 任一核心是否出现于 hay[0..hlen)。**首两字节哈希位图**（512B）剪枝，再逐串 memcmp
// （保守字面匹配，不依赖 memmem）。纯「存在性」判定，不关心出现位置。
// 用哈希对 (b0,b1) 而非两个独立位图：交替的多个核心常共享首字节（api/apikey/access/
// authorization/auth 都以 'a' 起），独立位图对纯 'a' 文本无效；对 (b0,b1) 则 ('a','a') 直接出局。
// 哈希碰撞只会造成误放行（→ 精确 memcmp 判定），不影响正确性。
static int rn_find_any_lit(const unsigned char* hay, int hlen,
                           unsigned char lits[][RN_CORE_LEN], const unsigned char* lens, int n) {
    if (hlen <= 0 || n <= 0) return 0;
    for (int i = 0; i < n; i++) {                // 单字节核心（极少见）：直接一次 memchr
        if (lens[i] < 2 && memchr(hay, lits[i][0], (size_t)hlen)) return 1;
    }
    unsigned char pf[512];
    memset(pf, 0, sizeof(pf));
    int m = 0;
    for (int i = 0; i < n; i++) {
        if (lens[i] < 2) continue;
        unsigned idx = (unsigned)lits[i][0] * 257u + lits[i][1];
        pf[(idx & 4095u) >> 3] |= (unsigned char)(1u << (idx & 7u));
        m++;
    }
    if (m == 0) return 0;
    for (int i = 0; i + 1 < hlen; i++) {
        unsigned idx = (unsigned)hay[i] * 257u + hay[i + 1];
        if (!(pf[(idx & 4095u) >> 3] & (1u << (idx & 7u)))) continue;
        for (int j = 0; j < n; j++) {
            int l = lens[j];
            if (l < 2 || lits[j][0] != hay[i]) continue;
            if (i + l > hlen) continue;
            if (memcmp(hay + i + 1, lits[j] + 1, (size_t)(l - 1)) == 0) return 1;
        }
    }
    return 0;
}

// 保守字面扫描（不依赖 memmem：musl/mingw 无该扩展）
static const unsigned char* rn_find_lit(const unsigned char* hay, int hlen, const unsigned char* pat, int plen) {
    if (plen <= 0 || plen > hlen) return NULL;
    if (plen == 1) return (const unsigned char*)memchr(hay, pat[0], (size_t)hlen);
    const unsigned char c0 = pat[0];
    int last = hlen - plen;
    for (int i = 0; i <= last; i++) {
        if (hay[i] != c0) continue;
        if (memcmp(hay + i + 1, pat + 1, (size_t)(plen - 1)) == 0) return hay + i;
    }
    return NULL;
}

static RNode* rcompile(const char* pat, char* errbuf, int errsz) {
    RParser p;
    memset(&p, 0, sizeof(p));
    p.b = (const unsigned char*)pat;
    p.len = (int)strlen(pat);
    RNode* root = rp_parse_alt(&p);
    if (root && p.pos != p.len) {
        snprintf(errbuf, errsz, "正则语法错误: 位置 %d 处意外的字符", p.pos);
        rp_free(root);
        return NULL;
    }
    if (!root && errbuf) snprintf(errbuf, errsz, "%s", p.err);
    if (root) {
        root->lit_len = rn_lit_prefix(root, root->lit, (int)sizeof(root->lit));
        // M110-S1：仅当「必备字面前缀」不可用（无公共前缀的大交替等）才计算「必备字面核心」。
        //   前缀可用时那条路更强（直接跳过起点），无需再做整串预筛。
        if (root->lit_len == 0) {
            RCoreSet cs;
            memset(&cs, 0, sizeof(cs));
            if (rn_necess_core(root, &cs) && cs.n > 0) {
                for (int i = 0; i < cs.n; i++) {
                    memcpy(root->core[i], cs.lit[i], cs.len[i]);
                    root->core_len[i] = cs.len[i];
                }
                root->core_n = cs.n;
            }
        }
    }
    return root;
}

// ---- 匹配（候选列表回溯，与 Rust 端同序） ----
static RCandList rmatch(RNode* n, const unsigned char* text, int len, int pos, const int64_t* groups);

// ---- M107-S1（Issue 34）：`X{n,}` / `X*` / `X+` 的「单字节原子」快速路径 ----
// 病灶（qg-issue/34-puxian-regex-throughput/34-ADDENDUM-20260911.md）：RN_REP 用 BFS 枚举
//   **所有**重复层数候选，再对每个候选做 O(#候选) 的重复检查 + 收尾 O(k²) 插入排序
//   ⇒ 当 child 是「每次恰好吃 1 字节」的原子（RN_CHAR / RN_ANY / RN_CLASS）且输入是长连续段时
//   （如 `[A-Za-z0-9]{20,}` 命中 64KB 连续字母），候选数 ≈ 段长 ⇒ O(n²)（实测 64KB 10598ms）。
// 等价性（可证明，无需放宽语义）：此类 child 在任意位置**至多 1 个候选**，end 恒为 pos+1，
//   且不改 groups ⇒ BFS 的 level L 恰对应唯一候选 end=pos+L，各层 end 两两不同（dup 检查恒不命中）。
//   故「贪心优先（level 降序）」的候选序列 == end 从 k 递减到 min，其中 k = min(max, 连续命中长度)。
//   本快速路径按此线性产出：**数量、顺序（end 降序）、groups 与原实现逐项相同**。
// 覆盖范围：`{n,}`（本次主诉）、`{n,m}`、`*`、`+`、`?` 中所有 child 为上述三类原子的情形；
//   其余 child（含分组/交替/多字符序列）一律回落原 BFS，行为不变。
// ---- M138（qg-issue 87 缺陷 84）：零宽断言 \b / \B / \A / \z ----
// Go 的 `\b` 是 **ASCII 词边界**（文档：\w 一侧、\W/\A/\z 一侧；`\w` == [0-9A-Za-z_]）。
//   实测（examples/m138_regex_go_parity 的语料由 Go 本尊生成）：`\b` 在「前一字节是词字符」与
//   「后一字节是词字符」**恰好一个成立**的位置命中；文本首尾视作非词字符。
static int rn_is_word(unsigned char c) {
    return (c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '_';
}
static int rn_word_boundary(const unsigned char* text, int len, int pos) {
    int a = (pos > 0) && rn_is_word(text[pos - 1]);
    int b = (pos < len) && rn_is_word(text[pos]);
    return a != b;
}
// 零宽节点：匹配不消费任何字节 ⇒ 量词语义特殊（见 rmatch 的 RN_REP 分支）
static int rn_zero_width(RNode* n) {
    return n->type == RN_START || n->type == RN_END || n->type == RN_WB || n->type == RN_NWB ||
           n->type == RN_START_ML || n->type == RN_END_ML;
}

static int rn_byte_atom(RNode* k) {
    return k->type == RN_CHAR || k->type == RN_ANY || k->type == RN_CLASS;
}

static int rn_byte_match(RNode* k, const unsigned char* text, int len, int pos) {
    if (pos >= len) return 0;
    unsigned char ch = text[pos];
    switch (k->type) {
        case RN_CHAR: return ch == k->ch;
        case RN_ANY: return ch != '\n';
        case RN_CLASS: {
            int hit = 0;
            for (int i = 0; i < k->ncls; i++)
                if (ch >= k->cls_lo[i] && ch <= k->cls_hi[i]) { hit = 1; break; }
            return hit != k->neg;
        }
        default: return 0;
    }
}

static RCandList rmatch(RNode* n, const unsigned char* text, int len, int pos, const int64_t* groups) {
    RCandList out = rcand_new();
    switch (n->type) {
        case RN_CHAR:
            if (pos < len && text[pos] == n->ch) rcand_add(&out, pos + 1, groups);
            break;
        case RN_ANY:
            if (pos < len && text[pos] != '\n') rcand_add(&out, pos + 1, groups);
            break;
        case RN_CLASS:
            if (pos < len) {
                unsigned char ch = text[pos];
                int hit = 0;
                for (int i = 0; i < n->ncls; i++) if (ch >= n->cls_lo[i] && ch <= n->cls_hi[i]) { hit = 1; break; }
                if (hit != n->neg) rcand_add(&out, pos + 1, groups);
            }
            break;
        case RN_START:
            if (pos == 0) rcand_add(&out, pos, groups);
            break;
        case RN_END:
            if (pos == len) rcand_add(&out, pos, groups);
            break;
        case RN_START_ML:   // M138 `(?m)`：行首（^）—— 文本开头或前一字节是 \n
            if (pos == 0 || (pos > 0 && text[pos - 1] == '\n')) rcand_add(&out, pos, groups);
            break;
        case RN_END_ML:     // M138 `(?m)`：行尾（$）—— 文本结尾或当前字节是 \n
            if (pos == len || (pos < len && text[pos] == '\n')) rcand_add(&out, pos, groups);
            break;
        case RN_WB:      // M138：ASCII 词边界（零宽）
            if (rn_word_boundary(text, len, pos)) rcand_add(&out, pos, groups);
            break;
        case RN_NWB:     // M138：非词边界（零宽）
            if (!rn_word_boundary(text, len, pos)) rcand_add(&out, pos, groups);
            break;
        case RN_ALT:
            for (int i = 0; i < n->nkids; i++) {
                RCandList sub = rmatch(n->kids[i], text, len, pos, groups);
                rcand_extend(&out, &sub);
                rcand_free(&sub);
            }
            break;
        case RN_GROUP: {
            int64_t g[RG_N];
            memcpy(g, groups, sizeof(g));
            g[n->gidx] = ((int64_t)pos << 32) | (unsigned)pos;
            RCandList sub = rmatch(n->child, text, len, pos, g);
            for (int i = 0; i < sub.len; i++) {
                int64_t gg[RG_N];
                memcpy(gg, sub.items[i].groups, sizeof(gg));
                gg[n->gidx] = ((int64_t)pos << 32) | (unsigned)sub.items[i].end;
                rcand_add(&out, sub.items[i].end, gg);
            }
            rcand_free(&sub);
            break;
        }
        case RN_REP: {
            // M138（qg-issue 87 缺陷 84）：child 是**零宽断言**（\b \B ^ $）时，
            //   每次"重复"都落在同一位置、产出同一候选 ⇒ BFS 的「end 必须前进」去重守卫会把
            //   level ≥ 1 全丢掉 ⇒ `\b{2}` 永不匹配。而 Go 实测（语料 m138）：
            //     min == 0 → 至少可匹配 0 次 ⇒ **恒匹配（零宽）**：`\b*` `\b?` `\b{0}` `$*` 皆然
            //     min ≥ 1 → 等价于断言本身：`\b+` `\b{2}` `\b{3,}` `\B{2}` `^{2}` `$+` 皆然
            //   （证明：零宽 child 的任意 level 候选恒为 (pos, groups) 同一项，去重后只剩一项。）
            if (rn_zero_width(n->child)) {
                RCandList sub = rmatch(n->child, text, len, pos, groups);
                int holds = sub.len > 0;
                rcand_free(&sub);
                if (n->min == 0 || holds) rcand_add(&out, pos, groups);
                break;
            }
            // M107-S1（Issue 34）：单字节原子 → 线性产出候选（等价性证明见 rn_byte_atom 上方）
            if (rn_byte_atom(n->child)) {
                int k = 0;
                while (n->max < 0 || k < n->max) {
                    if (!rn_byte_match(n->child, text, len, pos + k)) break;
                    k++;
                }
                for (int lv = k; lv >= n->min; lv--) rcand_add(&out, pos + lv, groups);
                break;
            }
            // BFS：all 记录 (end, groups, level)；贪心优先 = level 降序
            typedef struct { int end; int64_t groups[RG_N]; int level; } RRepCand;
            RRepCand* all = NULL;
            int all_len = 0, all_cap = 0;
            RRepCand* frontier = NULL;
            int flen = 0, fcap = 0;
            // level 0
            all = xrealloc(all, sizeof(RRepCand) * (all_len + 1));
            all[all_len].end = pos; memcpy(all[all_len].groups, groups, sizeof(int64_t) * RG_N); all[all_len].level = 0; all_len++;
            frontier = xrealloc(frontier, sizeof(RRepCand) * (flen + 1));
            frontier[flen].end = pos; memcpy(frontier[flen].groups, groups, sizeof(int64_t) * RG_N); flen++;
            int level = 0;
            for (;;) {
                if (n->max >= 0 && level >= n->max) break;
                RRepCand* next = NULL;
                int nlen = 0;
                for (int fi = 0; fi < flen; fi++) {
                    RCandList sub = rmatch(n->child, text, len, frontier[fi].end, frontier[fi].groups);
                    for (int si = 0; si < sub.len; si++) {
                        if (sub.items[si].end > frontier[fi].end) {
                            int dup = 0;
                            for (int ni = 0; ni < nlen; ni++) {
                                if (next[ni].end == sub.items[si].end &&
                                    memcmp(next[ni].groups, sub.items[si].groups, sizeof(int64_t) * RG_N) == 0) { dup = 1; break; }
                            }
                            if (!dup) {
                                next = xrealloc(next, sizeof(RRepCand) * (nlen + 1));
                                next[nlen].end = sub.items[si].end;
                                memcpy(next[nlen].groups, sub.items[si].groups, sizeof(int64_t) * RG_N);
                                nlen++;
                            }
                        }
                    }
                    rcand_free(&sub);
                }
                if (nlen == 0) { if (next) xfree(next); break; }
                level++;
                for (int i = 0; i < nlen; i++) {
                    all = xrealloc(all, sizeof(RRepCand) * (all_len + 1));
                    all[all_len].end = next[i].end;
                    memcpy(all[all_len].groups, next[i].groups, sizeof(int64_t) * RG_N);
                    all[all_len].level = level;
                    all_len++;
                }
                if (frontier) xfree(frontier);
                frontier = next;
                flen = nlen;
            }
            // 插入排序：level 降序（贪心优先，稳定）
            for (int i = 1; i < all_len; i++) {
                RRepCand key = all[i];
                int j = i - 1;
                while (j >= 0 && all[j].level < key.level) { all[j + 1] = all[j]; j--; }
                all[j + 1] = key;
            }
            for (int i = 0; i < all_len; i++) {
                if (all[i].level >= n->min) rcand_add(&out, all[i].end, all[i].groups);
            }
            if (all) xfree(all);
            if (frontier) xfree(frontier);
            break;
        }
        case RN_SEQ: {
            RCandList cur = rcand_new();
            rcand_add(&cur, pos, groups);
            for (int i = 0; i < n->nkids; i++) {
                RCandList next = rcand_new();
                for (int j = 0; j < cur.len; j++) {
                    RCandList sub = rmatch(n->kids[i], text, len, cur.items[j].end, cur.items[j].groups);
                    rcand_extend(&next, &sub);
                    rcand_free(&sub);
                }
                rcand_free(&cur);
                cur = next;
                if (cur.len == 0) break;
            }
            return cur;
        }
        default:
            // M138：新增节点类型若忘记在此处理，旧代码会**静默返回「永不匹配」**
            //   （空候选列表 = 正则静默失效）。按缺陷 86 的纪律：绝不静默 ⇒ 显式报错。
            px_error("R9001: 正则节点类型未实现: %d（引擎内部错误）", n->type);
    }
    return out;
}

// ---- 顶层搜索 ----
static int rsearch_from(RNode* root, const unsigned char* text, int len, int start, int* out_s, int* out_e, int64_t* out_g) {
    int64_t g0[RG_N];
    for (int i = 0; i < RG_N; i++) g0[i] = -1;
    // M107-S1b：必备字面前缀预筛（只跳过「结构上不可能成为起点」的位置；顺序语义不变）
    {
        int L = root->lit_len;
        int usable = L > 0;
        for (int i = 0; usable && i < L; i++) if (root->lit[i] == 0) usable = 0;
        if (usable) {
            int s = start;
            while (s <= len - L) {
                const unsigned char* hit = rn_find_lit(text + s, len - s, root->lit, L);
                if (!hit) return 0;
                int cand = (int)(hit - text);
                RCandList l = rmatch(root, text, len, cand, g0);
                if (l.len > 0) {
                    *out_s = cand;
                    *out_e = l.items[0].end;
                    memcpy(out_g, l.items[0].groups, sizeof(int64_t) * RG_N);
                    out_g[0] = ((int64_t)cand << 32) | (unsigned)l.items[0].end;
                    rcand_free(&l);
                    return 1;
                }
                rcand_free(&l);
                s = cand + 1;
            }
            return 0;
        }
    }
    // M110-S1（Issue 34 附页2 / Issue 38）：前缀不可用时改用「必备字面核心」整串预筛 ——
    //   每个核心都是「模式若匹配则必出现于文本」的字面串；一个都不出现 ⇒ 必不匹配 ⇒
    //   直接返回无匹配（免去 len 次 rmatch 及其 O(len) 级分配 —— 现网 p1 1MB 的主诉）。
    //   只做「不成立即整段跳过」：首个匹配起点、零宽匹配、组捕获等语义一律不变。
    if (root->core_n > 0 && start <= len) {
        if (!rn_find_any_lit(text + start, len - start, root->core, root->core_len, root->core_n)) return 0;
    }
    for (int s = start; s <= len; s++) {
        RCandList l = rmatch(root, text, len, s, g0);
        if (l.len > 0) {
            *out_s = s;
            *out_e = l.items[0].end;
            memcpy(out_g, l.items[0].groups, sizeof(int64_t) * RG_N);
            out_g[0] = ((int64_t)s << 32) | (unsigned)(*out_e);
            rcand_free(&l);
            return 1;
        }
        rcand_free(&l);
    }
    return 0;
}

static int rfullmatch(RNode* root, const unsigned char* text, int len, int64_t* out_g) {
    int64_t g0[RG_N];
    for (int i = 0; i < RG_N; i++) g0[i] = -1;
    RCandList l = rmatch(root, text, len, 0, g0);
    int found = 0;
    for (int i = 0; i < l.len; i++) {
        if (l.items[i].end == len) {
            memcpy(out_g, l.items[i].groups, sizeof(int64_t) * RG_N);
            out_g[0] = 0; // start=0
            out_g[0] = ((int64_t)0 << 32) | (unsigned)len;
            found = 1;
            break;
        }
    }
    rcand_free(&l);
    return found;
}

static void r_expand_repl(const char* repl, const int64_t* g, const unsigned char* text, int tlen, RStrBuf* out) {
    int rl = (int)strlen(repl);
    for (int i = 0; i < rl; i++) {
        if (repl[i] == '$' && i + 1 < rl) {
            char c = repl[i + 1];
            if (c == '$') { rsb_append(out, "$", 1); i++; continue; }
            if (c >= '0' && c <= '9') {
                int idx = c - '0';
                if (idx < RG_N && g[idx] != -1) {
                    int s = (int)(g[idx] >> 32);
                    int e = (int)(g[idx] & 0xffffffff);
                    if (s >= 0 && s <= e && e <= tlen) rsb_append(out, (const char*)text + s, e - s);
                }
                i++;
                continue;
            }
        }
        rsb_append(out, repl + i, 1);
    }
}

static void r_replace(RNode* root, const unsigned char* text, int len, const char* repl, RStrBuf* out) {
    // M138：与 bi_regex_find_all 同一迭代规则（Go ReplaceAllString 复用 allMatches）。
    //   空匹配紧跟前一次匹配尾部 ⇒ 跳过（不产出替换、也不额外拷贝字节）。
    int pos = 0, prev_end = -1, copy_from = 0;
    while (pos <= len) {
        int s, e;
        int64_t g[RG_N];
        if (!rsearch_from(root, text, len, pos, &s, &e, g)) break;
        // ⚠️ 「搜索位置 pos」与「上次已拷贝到的位置 copy_from」必须分开：
        //   丢弃一个空匹配时 pos 前进、copy_from 不动（否则会漏拷一个字节）。
        if (e == s && s == prev_end) {                   // 丢弃：不拷贝、不替换，仅前进搜索位置
            pos = s + 1;
        } else {
            rsb_append(out, (const char*)text + copy_from, s - copy_from);
            g[0] = ((int64_t)s << 32) | (unsigned)e;
            r_expand_repl(repl, g, text, len, out);
            copy_from = e;                               // 空匹配时 e == s（不吞字节，留给下一次拷贝）
            pos = (e == s) ? s + 1 : e;
        }
        prev_end = e;
    }
    rsb_append(out, (const char*)text + copy_from, len - copy_from);
}

static void r_split(RNode* root, const unsigned char* text, int len, LXValue list) {
    int pos = 0;
    while (pos <= len) {
        int s = -1, e = -1;
        for (int start = pos; start <= len; start++) {
            int64_t g0[RG_N];
            for (int i = 0; i < RG_N; i++) g0[i] = -1;
            RCandList l = rmatch(root, text, len, start, g0);
            if (l.len > 0 && l.items[0].end > start) { s = start; e = l.items[0].end; rcand_free(&l); break; }
            rcand_free(&l);
        }
        if (s < 0) break;
        px_list_push(list, px_str_len((const char*)text + pos, s - pos));
        pos = e;
    }
    px_list_push(list, px_str_len((const char*)text + pos, len - pos));
}

// ---- 内置函数 ----
static LXValue bi_regex_find(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 2) px_error("R1002: regex_find 需要 2 个参数: (pattern, text)");
    const char* pat = val_cstr(args[0]);
    const char* text = val_cstr(args[1]);
    int tlen = (int)strlen(text);
    char err[160];
    err[0] = 0;
    RNode* root = rcompile(pat, err, sizeof(err));
    if (!root) px_error("regex: %s", err);
    int s, e;
    int64_t g[RG_N];
    int found = rsearch_from(root, (const unsigned char*)text, tlen, 0, &s, &e, g);
    rp_free(root);
    if (found) return px_str_len(text + s, e - s);
    return px_null();
}

// regex_valid(pattern) → bool（M133：**只编译不匹配**，失败返回 false 而**不杀进程**）
//   背景（token-cache PuXian 化第 12 轮 · qg-issue 87 缺陷 75）：Go 侧
//   `regexp.Compile(p)` 的常态用法是「探测合法性」——`if _, err := regexp.Compile(p); err != nil {...}`
//   （token-cache 的本地快判：secret_patterns **任一**编译失败即整体禁用快判）。
//   而 native 表里的 regex_* 一律 `px_error("regex: %s", err)` ⇒ **一个坏正则直接杀掉服务进程**，
//   "探测合法性"这个语义根本表达不出来（只能 try 别的办法猜，或干脆不检查）。
static LXValue bi_regex_valid(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: regex_valid 需要 (pattern) 参数");
    const char* pat = px_val_cstr(args[0]);
    char err[160];
    err[0] = 0;
    RNode* root = rcompile(pat, err, sizeof(err));
    if (!root) return px_bool(false);
    rp_free(root);
    return px_bool(true);
}

static LXValue bi_regex_match(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 2) px_error("R1002: regex_match 需要 2 个参数: (pattern, text)");
    const char* pat = val_cstr(args[0]);
    const char* text = val_cstr(args[1]);
    char err[160];
    err[0] = 0;
    RNode* root = rcompile(pat, err, sizeof(err));
    if (!root) px_error("regex: %s", err);
    int64_t g[RG_N];
    int found = rfullmatch(root, (const unsigned char*)text, (int)strlen(text), g);
    rp_free(root);
    return px_bool(found != 0);
}

static LXValue bi_regex_search(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 2) px_error("R1002: regex_search 需要 2 个参数: (pattern, text)");
    const char* pat = val_cstr(args[0]);
    const char* text = val_cstr(args[1]);
    int tlen = (int)strlen(text);
    char err[160];
    err[0] = 0;
    RNode* root = rcompile(pat, err, sizeof(err));
    if (!root) px_error("regex: %s", err);
    int s, e;
    int64_t g[RG_N];
    int found = rsearch_from(root, (const unsigned char*)text, tlen, 0, &s, &e, g);
    rp_free(root);
    if (!found) return px_null();
    LXValue d = px_dict();
    px_root_push();
    PX_KEEP(d);    // M92 precise：结果 dict 跨 px_dict_set/px_list_push/px_str_len 分配
    px_dict_set(d, "match", px_str_len(text + s, e - s));
    px_dict_set(d, "start", px_int(s));
    px_dict_set(d, "end", px_int(e));
    LXValue gl = px_list(0);
    PX_KEEP(gl);   // M92 precise：groups list 跨 px_list_push/px_str_len 分配（入 d 前仅局部）
    for (int i = 1; i < RG_N; i++) {
        if (g[i] != -1) {
            int gs = (int)(g[i] >> 32), ge = (int)(g[i] & 0xffffffff);
            px_list_push(gl, px_str_len(text + gs, ge - gs));
        } else {
            px_list_push(gl, px_null());
        }
    }
    px_dict_set(d, "groups", gl);
    px_root_pop();
    return d;
}

static LXValue bi_regex_find_all(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 2) px_error("R1002: regex_find_all 需要 2 个参数: (pattern, text)");
    const char* pat = val_cstr(args[0]);
    const char* text = val_cstr(args[1]);
    int tlen = (int)strlen(text);
    char err[160];
    err[0] = 0;
    RNode* root = rcompile(pat, err, sizeof(err));
    if (!root) px_error("regex: %s", err);
    LXValue r = px_list(0);
    px_root_push();
    PX_KEEP(r);   // M92 precise：累积 list 跨 px_list_push/px_str_len 分配
    // M138：迭代规则照 Go `allMatches`（Rust find_iter 同）——
    //   非空匹配：下一个搜索位置 = 匹配尾部；空匹配：位置 +1，**且若其起点恰为前一次匹配的尾部
    //   则丢弃该空匹配**。旧实现无此丢弃 ⇒ `a*` 在 "baab" 上多产出一个 [3,3]（Go: [[0,0],[1,3],[4,4]]）。
    int pos = 0, prev_end = -1;
    while (pos <= tlen) {
        int s, e;
        int64_t g[RG_N];
        if (!rsearch_from(root, (const unsigned char*)text, tlen, pos, &s, &e, g)) break;
        if (e == s) {
            if (s != prev_end) px_list_push(r, px_str_len(text + s, e - s));
            pos = s + 1;
        } else {
            px_list_push(r, px_str_len(text + s, e - s));
            pos = e;
        }
        prev_end = e;
    }
    rp_free(root);
    px_root_pop();
    return r;
}

static LXValue bi_regex_replace(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 3) px_error("R1002: regex_replace 需要 3 个参数: (pattern, text, repl)");
    const char* pat = val_cstr(args[0]);
    const char* text = val_cstr(args[1]);
    const char* repl = val_cstr(args[2]);
    int tlen = (int)strlen(text);
    char err[160];
    err[0] = 0;
    RNode* root = rcompile(pat, err, sizeof(err));
    if (!root) px_error("regex: %s", err);
    RStrBuf out = {0, 0, 0};
    r_replace(root, (const unsigned char*)text, tlen, repl, &out);
    rp_free(root);
    LXValue v = px_str_len(out.data ? out.data : "", out.len);
    if (out.data) xfree(out.data);
    return v;
}

static LXValue bi_regex_split(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 2) px_error("R1002: regex_split 需要 2 个参数: (pattern, text)");
    const char* pat = val_cstr(args[0]);
    const char* text = val_cstr(args[1]);
    int tlen = (int)strlen(text);
    char err[160];
    err[0] = 0;
    RNode* root = rcompile(pat, err, sizeof(err));
    if (!root) px_error("regex: %s", err);
    LXValue r = px_list(0);
    px_root_push();
    PX_KEEP(r);   // M92 precise：r_split 内部 px_list_push 分配
    r_split(root, (const unsigned char*)text, tlen, r);
    rp_free(root);
    px_root_pop();
    return r;
}

static LXValue bi_exists(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1 || args[0].type != PX_STR) px_error("R1002: exists 需要一个路径参数");
    struct stat st;
    return px_bool(stat(args[0].as.obj->as.str.data, &st) == 0);
}

// is_dir(path) → bool（M129 / qg-issue 87 缺陷 44）：路径存在**且**是目录。
//   对齐 Go `fi, err := os.Stat(p); err == nil && fi.IsDir()`。
//   不存在 / 非目录 / stat 失败 → false（不报错，与 Go 的 err 分支一致）。
static LXValue bi_is_dir(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1 || args[0].type != PX_STR) px_error("R1002: is_dir 需要一个路径参数");
    struct stat st;
    if (stat(args[0].as.obj->as.str.data, &st) != 0) return px_bool(false);
    return px_bool(S_ISDIR(st.st_mode) ? true : false);
}

static LXValue bi_list_dir(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1 || args[0].type != PX_STR) px_error("R1002: list_dir 需要一个路径参数");
    const char* path = args[0].as.obj->as.str.data;
    DIR* d = opendir(path);
    if (!d) px_error("fs: 读取目录失败 %s", path);
    LXValue r = px_list(0);
    px_root_push();
    PX_KEEP(r);   // M92 precise：累积 list 跨 px_list_push/px_str 分配
    struct dirent* e;
    while ((e = readdir(d)) != NULL) {
        if (strcmp(e->d_name, ".") == 0 || strcmp(e->d_name, "..") == 0) continue;
        px_list_push(r, px_str(e->d_name));
    }
    closedir(d);
    // 简单排序
    LXObject* ro = r.as.obj;
    for (int i = 0; i < ro->as.list.len; i++) {
        for (int j = i + 1; j < ro->as.list.len; j++) {
            if (compare_values(ro->as.list.items[j], ro->as.list.items[i]) < 0) {
                LXValue t = ro->as.list.items[i];
                ro->as.list.items[i] = ro->as.list.items[j];
                ro->as.list.items[j] = t;
            }
        }
    }
    px_root_pop();
    return r;
}

static LXValue bi_mkdir(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    // M116（qg-issue 71 D6）：新增可选 mode —— `mkdir(path[, mode])`。
    //   此前权限恒 0755（且**不可传**），Go 的 os.MkdirAll(dir, 0700) 这种"放私钥的目录"
    //   表达不出，只能退化为 0755 或外挂 chmod（引入 shell 依赖）。语义对齐 Go：
    //   mode 作用于**所有新建层级**，最终仍受进程 umask 约束（POSIX 标准行为）。
    if ((nargs != 1 && nargs != 2) || args[0].type != PX_STR)
        px_error("R1002: mkdir 需要 (path[, mode]) 参数");
    int mode = 0755;
    if (nargs == 2) {
        if (args[1].type != PX_INT) px_error("R1002: mkdir 的 mode 需要整数（如 0o700）");
        mode = (int)(args[1].as.i & 07777);
    }
    const char* path = args[0].as.obj->as.str.data;
    // 递归创建
    char tmp[1024];
    snprintf(tmp, sizeof(tmp), "%s", path);
    int len = (int)strlen(tmp);
    for (int i = 1; i < len; i++) {
        if (tmp[i] == '/') {
            tmp[i] = 0;
            mkdir(tmp, (mode_t)mode);
            tmp[i] = '/';
        }
    }
    mkdir(tmp, (mode_t)mode);
    return px_null();
}

static LXValue bi_remove(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1 || args[0].type != PX_STR) px_error("R1002: remove 需要一个路径参数");
    const char* path = args[0].as.obj->as.str.data;
    if (remove(path) != 0 && rmdir(path) != 0) px_error("fs: 删除失败 %s", path);
    return px_null();
}

// ---- std.json ----

typedef struct {
    const char* p;
} JsonCtx;

static void json_ws(JsonCtx* j) {
    while (*j->p == ' ' || *j->p == '\t' || *j->p == '\n' || *j->p == '\r') j->p++;
}
// M136（qg-issue 87 缺陷 94）：**字符串值必须长度感知** ——
//   `\u0000` 解码出来是真正的 0x00，此前调用方用 `px_str(s)` 重造 ⇒
//   在首个 NUL 处**静默截断**（`{"s":"a\u0000b"}` 变成 `"a"`，而 Go 原样保留）。
//   对拍实证（第 16 轮媒体代理 rep-nul 用例）：上游收到 `"s":"a"` vs Go `"a\u0000b\u001fc"`。
//   out_len 为 NULL 时退化为旧行为（仅键路径仍如此 —— dict 键是 C 串，NUL 键无法表示，见 README §五）。
static char* json_str_raw(JsonCtx* j, int* out_len) {
    // 前置：已消费 '"'；返回 malloc 字符串（已解码）
    char* out = xmalloc(strlen(j->p) + 1);
    int k = 0;
    while (*j->p && *j->p != '"') {
        if (*j->p == '\\') {
            j->p++;
            switch (*j->p) {
                case 'n': out[k++] = '\n'; j->p++; break;
                case 't': out[k++] = '\t'; j->p++; break;
                case 'r': out[k++] = '\r'; j->p++; break;
                case 'b': out[k++] = '\b'; j->p++; break;
                case 'f': out[k++] = '\f'; j->p++; break;
                case '"': out[k++] = '"'; j->p++; break;
                case '\\': out[k++] = '\\'; j->p++; break;
                case '/': out[k++] = '/'; j->p++; break;
                case 'u': {
                    char hex[5] = {0};
                    for (int i = 0; i < 4 && j->p[1+i]; i++) hex[i] = j->p[1+i];
                    j->p += 5;
                    unsigned code = (unsigned)strtoul(hex, NULL, 16);
                    if (code < 0x80) out[k++] = (char)code;
                    else if (code < 0x800) {
                        out[k++] = (char)(0xC0 | (code >> 6));
                        out[k++] = (char)(0x80 | (code & 0x3F));
                    } else {
                        out[k++] = (char)(0xE0 | (code >> 12));
                        out[k++] = (char)(0x80 | ((code >> 6) & 0x3F));
                        out[k++] = (char)(0x80 | (code & 0x3F));
                    }
                    break;
                }
                default: out[k++] = *j->p; j->p++; break;
            }
        } else {
            out[k++] = *j->p;
            j->p++;
        }
    }
    if (*j->p == '"') j->p++;
    out[k] = 0;
    if (out_len) *out_len = k;
    return out;
}

static LXValue json_parse_value(JsonCtx* j);

static LXValue json_parse_value(JsonCtx* j) {
    json_ws(j);
    if (*j->p == '{') {
        j->p++;
        LXValue d = px_dict();
        px_root_push();
        PX_KEEP(d);   // M92 precise：递归解析结果 dict 跨 px_dict_set/json_parse_value 分配
        json_ws(j);
        if (*j->p == '}') { j->p++; px_root_pop(); return d; }
        while (1) {
            json_ws(j);
            if (*j->p != '"') px_error("json: 期望对象键");
            j->p++;
            char* key = json_str_raw(j, NULL);   // 键仍是 C 串（NUL 键不可表示，已登记）
            json_ws(j);
            if (*j->p != ':') px_error("json: 期望 ':'");
            j->p++;
            LXValue v = json_parse_value(j);
            px_dict_set(d, key, v);
            xfree(key);
            json_ws(j);
            if (*j->p == ',') { j->p++; continue; }
            if (*j->p == '}') { j->p++; break; }
            px_error("json: 对象解析失败");
        }
        px_root_pop();
        return d;
    }
    if (*j->p == '[') {
        j->p++;
        LXValue a = px_list(0);
        px_root_push();
        PX_KEEP(a);   // M92 precise：递归解析结果 list 跨 px_list_push/json_parse_value 分配
        json_ws(j);
        if (*j->p == ']') { j->p++; px_root_pop(); return a; }
        while (1) {
            LXValue v = json_parse_value(j);
            px_list_push(a, v);
            json_ws(j);
            if (*j->p == ',') { j->p++; continue; }
            if (*j->p == ']') { j->p++; break; }
            px_error("json: 数组解析失败");
        }
        px_root_pop();
        return a;
    }
    if (*j->p == '"') {
        j->p++;
        int slen = 0;
        char* s = json_str_raw(j, &slen);
        LXValue r = px_str_len(s, slen);   // 长度感知（可含 NUL）
        xfree(s);
        return r;
    }
    if (strncmp(j->p, "true", 4) == 0) { j->p += 4; return px_bool(true); }
    if (strncmp(j->p, "false", 5) == 0) { j->p += 5; return px_bool(false); }
    if (strncmp(j->p, "null", 4) == 0) { j->p += 4; return px_null(); }
    // 数字
    char* end;
    // M136（qg-issue 87 缺陷 93）：**整数溢出必须回落浮点，而不是夹到 INT64_MAX**。
    //   此前 `strtoll` 溢出返回 LLONG_MAX 且 end 已越过全部数字 ⇒ 判定"整数解析成功"
    //   ⇒ 静默把值改成 9223372036854775807。
    //   实证（第 16 轮媒体代理对拍）：`{"b":12345678901234567890}` 经本实现重编码为
    //   `{"b":9223372036854775807}`，而 Go（`json.Unmarshal` 到 `interface{}` =
    //   float64 中转）给出 `{"b":12345678901234567000}` —— 上游收到的**请求体**不同。
    //   修法：`errno==ERANGE` 时按浮点走（与 Go 的 interface{} 语义一致）。
    //   ⚠️ errno 存取要成对（本函数会被嵌在别的 IO 路径里调用）。
    int saved_errno = errno;
    errno = 0;
    long long iv = strtoll(j->p, &end, 10);
    int int_ovf = (errno == ERANGE);
    errno = saved_errno;
    if (!int_ovf && end != j->p && (*end == 0 || *end == ',' || *end == '}' || *end == ']' || *end == ' ' || *end == '\t' || *end == '\n' || *end == '\r')) {
        j->p = end;
        return px_int(iv);
    }
    double dv = strtod(j->p, &end);
    if (end != j->p) {
        j->p = end;
        return px_float(dv);
    }
    px_error("json: 无法解析");
    return px_null();
}

static LXValue bi_json_parse(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1 || args[0].type != PX_STR) px_error("R1002: json_parse 需要一个字符串参数");
    JsonCtx j = { args[0].as.obj->as.str.data };
    LXValue r = json_parse_value(&j);
    return r;
}

// Value -> JSON 字符串（写入动态缓冲）
typedef struct { char* buf; int len, cap; } JOut;
// 追加 n 个原始字节（原供合法多字节 UTF-8 序列直出；M155 起为**唯一**实现，`jout_append`
//   也走它）。M155（缺陷 152）：长度感知追加 —— `jout_append` 走 strlen，**追加单个 NUL 字节做不到**
//   （`{c, 0}` 的 strlen 恒 0 ⇒ 该字节被静默丢掉）。`json_stringify` 的默认分支（控制字符
//   裸输出）因此既截断又丢字节；本函数给出「按长度」的追加路径。
static void jout_append_n(JOut* o, const char* s, int n) {
    if (n <= 0) return;
    if (o->len + n + 1 > o->cap) {
        o->cap = o->cap * 2 + n + 16;
        o->buf = xrealloc(o->buf, o->cap);
    }
    memcpy(o->buf + o->len, s, (size_t)n);
    o->len += n;
    o->buf[o->len] = 0;
}
static void jout_append(JOut* o, const char* s) {
    jout_append_n(o, s, (int)strlen(s));
}
// M155（第 37 轮 · 缺陷 152）：**长度感知**。此前的 `for (p = s; *p; p++)` 在首个 0x00
//   处**丢掉整条尾巴**（实测 `json_stringify("A\0B")` → `"A"`）—— 与本文档化的契约
//   「控制字符**裸输出**（可产出非法 JSON）」也不一致：契约说的是「裸输出」，不是「截断」。
//   注：Go 保真口径由 `json_stringify_go`（`jout_escape_go(o, s, n)`）承担，此处**不改**
//   转义风格（仍不转义 0x01 等控制字符），只把「按 C 串走」改成「按显式长度走」。
static void jout_escape_n(JOut* o, const char* s, int n) {
    jout_append(o, "\"");
    for (int _i = 0; _i < n; _i++) {
        char c = s[_i];
        switch (c) {
            case '"': jout_append(o, "\\\""); break;
            case '\\': jout_append(o, "\\\\"); break;
            case '\n': jout_append(o, "\\n"); break;
            case '\r': jout_append(o, "\\r"); break;
            case '\t': jout_append(o, "\\t"); break;
            default: jout_append_n(o, &c, 1);   /* M155：裸输出（含 0x00），不再按 C 串丢字节 */
        }
    }
    jout_append(o, "\"");
}
static void jout_escape(JOut* o, const char* s) { jout_escape_n(o, s, (int)strlen(s)); }
static void json_stringify_value_raw(JOut* o, LXValue v);
static void json_stringify_value(JOut* o, LXValue v) {
    // 缺陷 125（M145）：环上**报错**（不段错误）。Go `json.Marshal` 在环上返回
    //   `json: unsupported value: encountered a cycle via ...` ⇒ 此处同族文案可诊断。
    if (px_is_container(v)) {
        if (px_path_has(&g_json_path, v.as.obj))
            px_error("json: unsupported value: encountered a cycle via %s", px_type_name(v));
        px_path_push(&g_json_path, v.as.obj);
        json_stringify_value_raw(o, v);
        px_path_pop(&g_json_path);
        return;
    }
    json_stringify_value_raw(o, v);
}
static void json_stringify_value_raw(JOut* o, LXValue v) {
    switch (v.type) {
        case PX_NULL: jout_append(o, "null"); break;
        case PX_BOOL: jout_append(o, v.as.b ? "true" : "false"); break;
        case PX_INT: {
            char tmp[32];
            snprintf(tmp, sizeof(tmp), "%lld", (long long)v.as.i);
            jout_append(o, tmp);
            break;
        }
        case PX_FLOAT: {
            char tmp[64];
            snprintf(tmp, sizeof(tmp), "%g", v.as.f);
            jout_append(o, tmp);
            break;
        }
        case PX_STR: jout_escape_n(o, v.as.obj->as.str.data, v.as.obj->as.str.len); break;   // M155
        case PX_LIST: {
            jout_append(o, "[");
            LXObject* ob = v.as.obj;
            for (int i = 0; i < ob->as.list.len; i++) {
                if (i) jout_append(o, ",");
                json_stringify_value(o, ob->as.list.items[i]);
            }
            jout_append(o, "]");
            break;
        }
        case PX_TUPLE: {
            jout_append(o, "[");
            LXObject* ob = v.as.obj;
            for (int i = 0; i < ob->as.tuple.len; i++) {
                if (i) jout_append(o, ",");
                json_stringify_value(o, ob->as.tuple.items[i]);
            }
            jout_append(o, "]");
            break;
        }
        case PX_DICT: {
            jout_append(o, "{");
            LXObject* ob = v.as.obj;
            for (int i = 0; i < ob->as.dict.len; i++) {
                if (i) jout_append(o, ",");
                jout_escape(o, ob->as.dict.keys[i]);
                jout_append(o, ":");
                json_stringify_value(o, ob->as.dict.vals[i]);
            }
            jout_append(o, "}");
            break;
        }
        case PX_RESULT: {
            // M39：Result 序列化为 {"ok":bool,"value":...}（保留 Ok/Err 结构）
            LXObject* ob = v.as.obj;
            jout_append(o, "{\"ok\":");
            jout_append(o, ob->as.result.ok ? "true" : "false");
            jout_append(o, ",\"value\":");
            json_stringify_value(o, ob->as.result.value);
            jout_append(o, "}");
            break;
        }
        default: px_error("json: 无法序列化类型 %s", px_type_name(v));
    }
}
// json_parse_opt(s) → Ok(值) | Err(文案)（对齐 Go `json.Unmarshal` 的 error 返回）
//   失败**不抛错、不退出、不污染 stderr**；嵌套调用被拒绝（捕获点只有一个）。
static LXValue bi_json_parse_opt(LXValue* args, int nargs, void* ctx) {
    if (nargs != 1) px_error("R1002: json_parse_opt 需要一个参数");
    if (g_json_opt_active)
        return px_err(px_str("json_parse_opt 不支持嵌套调用"));
    g_json_opt_msg[0] = 0;
    g_json_opt_active = 1;
    px_root_iso_mark();   // M170：记录根栈深度（TLS；**不得**用栈局部，见其注释）
    if (setjmp(g_json_opt_jb) == 0) {
        LXValue r = bi_json_parse(args, nargs, ctx);
        g_json_opt_active = 0;
        return px_ok(r);
    }
    px_root_restore_iso();   // M170：归还（只收缩根栈；marks 栈协程共享，**不得**动）   // M170：作废被 longjmp 跳过的桥局部登记（野根）
    g_json_opt_active = 0;
    return px_err(px_str(g_json_opt_msg[0] ? g_json_opt_msg : "json 解析失败"));
}

static LXValue bi_json_stringify(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1) px_error("R1002: json_stringify 需要一个参数");
    JOut o = { NULL, 0, 0 };
    o.buf = xmalloc(64); o.cap = 64; o.buf[0] = 0;
    px_path_reset(&g_json_path);
    json_stringify_value(&o, args[0]);
    LXValue r = px_str_len(o.buf, o.len);   // M155（缺陷 152）：尾串不再 strlen 截断
    xfree(o.buf);
    return r;
}

// ═══ M129（qg-issue 87 缺陷 16）：json_stringify_go —— Go encoding/json 兼容序列化 ═══
// 建立背景：api-server（Go）大量用 `json.NewEncoder(w).Encode(v)` / `json.Marshal` 输出
//   **json.Unmarshal 得到的 interface{}**（透传上游 JSON、回显落盘文件）。Go 对
//   map[string]interface{} 的序列化有四条与 PuXian `json_stringify` **逐字节不同**的语义，
//   而它们全都静默（不报错、字段看着对）——是移植保真最危险的一类：
//   ① **dict 键递归按字节序排序**（Go 对 map 恒排序；json_stringify 保持插入序）；
//   ② **SetEscapeHTML(true)**：`<` `>` `&` → \u003c \u003e \u0026（Go 默认开）；
//   ③ 控制字符 < 0x20（\n \r \t 除外）→ \u00XX；U+2028/U+2029 恒转义；
//      非法 UTF-8 → \ufffd（Go 的 encodeString；json_stringify 直接吐**裸控制字节 = 非法 JSON**）；
//   ④ float64 走**最短往返**（strconv.FormatFloat(f,'f'|-1|64)，|x|<1e-6 或 ≥1e21 用 'e'，
//      并把 `e-0X` 收敛为 `e-X`）；json_stringify 用 `%g`（6 位有效数字）会**丢精度**。
// 另：本函数按 str.len 写出（Go 字符串可含 NUL）；json_stringify 在 M155 前走 C 串遇 NUL
//   截断，M155（缺陷 152）起同样按长度写出（保持「控制字符裸输出」的既有契约）。
// 约定：非有限浮点（NaN/Inf）Go 会返回 UnsupportedValueError，此处写 `null` 并在文档标注
//   （api-server 全部字段均不会出现，不为此在 runtime 里造错误通道）。
// 注：kwargs 语义与 json_stringify 同名共用（dict/list/tuple/Result）；PX_BYTES 按 Go `[]byte`
//   语义输出 **base64 字符串**（json_stringify 对 bytes 直接报错，故此处是纯增量）。
static void jgo_b64(JOut* o, const unsigned char* d, int n) {
    static const char* T = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    jout_append(o, "\"");
    int i = 0;
    while (i + 2 < n) {
        int v = (d[i] << 16) | (d[i + 1] << 8) | d[i + 2];
        char t[5] = { T[(v >> 18) & 63], T[(v >> 12) & 63], T[(v >> 6) & 63], T[v & 63], 0 };
        jout_append(o, t);
        i += 3;
    }
    if (i < n) {
        int rem = n - i;
        int v = d[i] << 16;
        if (rem == 2) v |= d[i + 1] << 8;
        char t[6] = { T[(v >> 18) & 63], T[(v >> 12) & 63], rem == 2 ? T[(v >> 6) & 63] : '=', '=', 0, 0 };
        jout_append(o, t);
    }
    jout_append(o, "\"");
}

// 追加 n 个原始字节（含 NUL）：定义见上方 `jout_append_n`（M155 合一，避免重复定义）。

// M129-2：`json_stringify_go` 的可选项（定义见文件后方 bi_json_stringify_go 上方）。
// M129（qg-issue 87 缺陷 51）：opts 状态必须是**线程局部**（__thread）。
//   背景：`json_stringify_go(v, {"sort_keys": false})` 的 opts 原先是两个**进程全局**
//   变量（g_json_go_sort / g_json_go_escape_html），调用前后 save/restore。单线程下没问题，
//   但 `http_serve` 是**多线程**（连接线程池）+ 语言层有 `spawn` 协程 —— 两个线程同时
//   序列化时，A 线程设的 sort_keys=false 会污染 B 线程的输出。
//   实测（第 7 轮对拍，webhook heavy 分支）：请求线程正在序列化响应 `{"ok":true,"event_id":…}`
//   的同时，`spawn` 出来的异步处置线程在写事件日志（那里用 sort_keys:false）⇒ **响应键序
//   被污染成插入序** `{"ok":…,"event_id":…}`，而 Go 恒为字母序。偶发、无报错。
//   修法：改 `__thread`（TLS），逐线程独立、语义与单线程完全一致（零回归）。
static __thread int g_json_go_sort = 1;
static __thread int g_json_go_escape_html = 1;

// Go encoding/json 的 encodeString 等价物（s 带显式长度，可含 NUL）
static void jout_escape_go(JOut* o, const char* s, int n) {
    jout_append(o, "\"");
    int i = 0;
    while (i < n) {
        unsigned char c = (unsigned char)s[i];
        if (c < 0x80) {
            switch (c) {
                case '"': jout_append(o, "\\\""); break;
                case '\\': jout_append(o, "\\\\"); break;
                case '\n': jout_append(o, "\\n"); break;
                case '\r': jout_append(o, "\\r"); break;
                case '\t': jout_append(o, "\\t"); break;
                case '<': if (g_json_go_escape_html) jout_append(o, "\\u003c"); else jout_append_n(o, s + i, 1); break;
                case '>': if (g_json_go_escape_html) jout_append(o, "\\u003e"); else jout_append_n(o, s + i, 1); break;
                case '&': if (g_json_go_escape_html) jout_append(o, "\\u0026"); else jout_append_n(o, s + i, 1); break;
                default: {
                    if (c < 0x20) {
                        char tmp[8];
                        snprintf(tmp, sizeof(tmp), "\\u%04x", (unsigned)c);
                        jout_append(o, tmp);
                    } else {
                        jout_append_n(o, s + i, 1);
                    }
                }
            }
            i++;
            continue;
        }
        // 多字节序列：严格校验（对齐 Go 的 utf8.DecodeRune：过长/孤立续字节/代理区/越界 → 1 字节非法）
        int len = 0;
        unsigned cp = 0;
        if (c >= 0xC2 && c <= 0xDF) { len = 2; cp = c & 0x1F; }
        else if (c >= 0xE0 && c <= 0xEF) { len = 3; cp = c & 0x0F; }
        else if (c >= 0xF0 && c <= 0xF4) { len = 4; cp = c & 0x07; }
        int ok = len > 0 && i + len <= n;
        if (ok) {
            for (int k = 1; k < len; k++) {
                unsigned char cc = (unsigned char)s[i + k];
                if ((cc & 0xC0) != 0x80) { ok = 0; break; }
                cp = (cp << 6) | (cc & 0x3F);
            }
            if (ok) {
                // 过长编码 / 代理区 / >U+10FFFF 一律判非法（Go 同样拒绝）
                if ((len == 3 && cp < 0x800) || (len == 4 && cp < 0x10000) ||
                    (cp >= 0xD800 && cp <= 0xDFFF) || cp > 0x10FFFF)
                    ok = 0;
            }
        }
        if (!ok) {
            jout_append(o, "\\ufffd");
            i++;
            continue;
        }
        if (cp == 0x2028) { jout_append(o, "\\u2028"); i += len; continue; }
        if (cp == 0x2029) { jout_append(o, "\\u2029"); i += len; continue; }
        jout_append_n(o, s + i, len);
        i += len;
    }
    jout_append(o, "\"");
}

// 最短往返浮点（对齐 Go strconv.FormatFloat(f, fmt, -1, 64) + json 的 e-0X 收敛）
//
// M136（qg-issue 87 缺陷 95）：**先取"最短数字串"再按样式渲染**。
//   此前按 fmt 直接扫 `%.*f` / `%.*e` 的精度：'f' 样式下 `%.0f` 对
//   1.2345678901234567e19 直接给出**精确值** 12345678901234567168（17 位以外全是
//   二进制补零），而 Go 的 -1 精度给的是**最短往返数字** 12345678901234567 再按 'f'
//   展开 ⇒ 12345678901234567000。差 168 —— 对拍实证（媒体代理 rep-bigint 用例：
//   上游收到的请求体不同）。
//   修法：① 用 `%.*e` 递增精度扫出**最短数字串**（含十进制指数）；
//        ② 按 Go 规则（|x|∈[1e-6,1e21) 用 'f'，否则 'e'）渲染该数字串。
// M143（第 24 轮 · 缺陷 117 同族）：把「符号 + 最短数字串 + 十进制指数」渲染成 Go
//   `encoding/json` 的数字文本 —— 从 jgo_format_float 里**抽出**，float64 / float32
//   两条路径共用（渲染规则唯一，杜绝两份实现漂移；本工程的既有教训：同一语义两处
//   实现必然分叉）。两条路径的差别只在**取哪套数字**（位数 + 回读函数）与**科学计数
//   阈值**，渲染完全一致：
//     · 'f' 定点：小数点位置由 exp10 决定（pt = exp10+1），pt<=0 补 "0."+前导零、
//       pt>=nd 补尾零、否则插小数点；
//     · 'e' 科学：d.ddd e±NN（指数**至少两位** + 负号收敛 `e-0d`→`e-d`，Go 原文
//       `clean up e-09 to e-9` 逐字照抄；正指数**不**收敛 —— Go 的判据只看 `b[n-3]=='-'`）。
static void jgo_render_num(char* out, int cap, int neg, const char* digits, int nd, int exp10, char style) {
    int pt = exp10 + 1;   // 小数点前应有的位数
    char buf[64];
    int k = 0;
    if (neg) buf[k++] = '-';
    if (style == 'f') {
        if (pt <= 0) {
            buf[k++] = '0';
            buf[k++] = '.';
            for (int z = 0; z < -pt && k < 60; z++) buf[k++] = '0';
            for (int i = 0; i < nd && k < 62; i++) buf[k++] = digits[i];
        } else if (pt >= nd) {
            for (int i = 0; i < nd && k < 62; i++) buf[k++] = digits[i];
            for (int z = 0; z < pt - nd && k < 62; z++) buf[k++] = '0';
        } else {
            for (int i = 0; i < pt && k < 60; i++) buf[k++] = digits[i];
            buf[k++] = '.';
            for (int i = pt; i < nd && k < 62; i++) buf[k++] = digits[i];
        }
    } else {
        buf[k++] = digits[0];
        if (nd > 1) {
            buf[k++] = '.';
            for (int i = 1; i < nd && k < 60; i++) buf[k++] = digits[i];
        }
        buf[k++] = 'e';
        int e2 = exp10;
        buf[k++] = (e2 < 0) ? '-' : '+';
        if (e2 < 0) e2 = -e2;
        char eb[8];
        snprintf(eb, sizeof(eb), "%d", e2);
        if (strlen(eb) < 2) buf[k++] = '0';   // Go 指数至少两位
        for (const char* pe = eb; *pe && k < 63; pe++) buf[k++] = *pe;
    }
    buf[k] = 0;
    // Go json：仅把 `e-0d` 收敛成 `e-d`（`e+0d` 保持两位）
    if (style == 'e') {
        int n = k;
        if (n >= 4 && buf[n - 4] == 'e' && buf[n - 3] == '-' && buf[n - 2] == '0') {
            buf[n - 2] = buf[n - 1];
            buf[n - 1] = 0;
        }
    }
    snprintf(out, (size_t)cap, "%s", buf);
}

// 从 `%.*e` 文本里取「符号 / 数字串 / 十进制指数」—— 两条路径共用的解析段。
static void jgo_split_sci(const char* sci, int* neg, char* digits, int* nd, int* exp10) {
    *neg = 0;
    const char* s = sci;
    if (*s == '-') { *neg = 1; s++; }
    *nd = 0;
    for (const char* q = s; *q && *q != 'e' && *q != 'E'; q++) {
        if (*q != '.' && *nd < 39) digits[(*nd)++] = *q;
    }
    digits[*nd] = 0;
    const char* ep = strchr(s, 'e');
    if (!ep) ep = strchr(s, 'E');
    *exp10 = ep ? atoi(ep + 1) : 0;
}

static void jgo_format_float(char* out, int cap, double f) {
    if (!isfinite(f)) { snprintf(out, (size_t)cap, "null"); return; }
    double a = fabs(f);
    char style = 'f';
    if (a != 0 && (a < 1e-6 || a >= 1e21)) style = 'e';
    // ① 最短往返数字串（%.*e 递增精度，首个能回读相等的即最短）
    char sci[64];
    sci[0] = 0;
    for (int p = 0; p <= 17; p++) {
        snprintf(sci, sizeof(sci), "%.*e", p, f);
        if (strtod(sci, NULL) == f) break;
    }
    int neg = 0, nd = 0, exp10 = 0;
    char digits[40];
    jgo_split_sci(sci, &neg, digits, &nd, &exp10);
    if (nd == 0) { snprintf(out, (size_t)cap, "0"); return; }
    jgo_render_num(out, cap, neg, digits, nd, exp10, style);
}

// M143：Go `encoding/json` 的 **float32** 文本（floatEncoder 的 bits=32 分支）。
//   与 float64 路径的差别只有三处：
//     ① 先把值**窄化到 float32**（Go 侧值本身就是 float32 类型，序列化前已窄化）；
//     ② 科学计数阈值按 **float32** 比较（Go：`float32(abs) < 1e-6 || float32(abs) >= 1e21`）；
//     ③ 最短往返位数上界 **9**（float32 的 round-trip 位数上界）、回读用 `strtof`。
//   实测口径（Go 1.26.6，M143 门内真值，`json.Marshal(float32(v))`）：
//     0.1 → "0.1" · 1/3 → "0.33333334"（**32 位最短**，与 float64 的
//     "0.3333333333333333" 不同）· -2.5e-8 → "-2.5e-8"（`e-0d`→`e-d`）·
//     1e-6 → "0.000001"（阈值不含）· 1e-7 → "1e-7" · 1e20 → "100000000000000000000"
//     （float32(1e20) 仍是 1e20 < 1e21 ⇒ 定点）· 1e21 → "1e+21" ·
//     -0.0 → "-0"（**Go 的 JSON 不把负零写成 0**；注意 Go 源码里字面量 `-0.0` 会被
//     常量折叠成 +0，真值必须用 `math.Copysign(0,-1)` 造）·
//     MaxFloat32 → "3.4028235e+38" · 最小次正规 → "1e-45"。
static void jgo_format_float32(char* out, int cap, double f) {
    if (!isfinite(f)) { snprintf(out, (size_t)cap, "null"); return; }
    float g = (float)f;
    if (!isfinite((double)g)) { snprintf(out, (size_t)cap, "null"); return; }
    float ag = fabsf(g);
    char style = 'f';
    if (ag != 0 && (ag < 1e-6f || ag >= 1e21f)) style = 'e';
    char sci[64];
    sci[0] = 0;
    for (int p = 0; p <= 9; p++) {
        snprintf(sci, sizeof(sci), "%.*e", p, (double)g);
        if (strtof(sci, NULL) == g) break;
    }
    int neg = 0, nd = 0, exp10 = 0;
    char digits[40];
    jgo_split_sci(sci, &neg, digits, &nd, &exp10);
    if (nd == 0) { snprintf(out, (size_t)cap, "0"); return; }
    jgo_render_num(out, cap, neg, digits, nd, exp10, style);
}

typedef struct { const char* k; LXValue v; } JGoKV;
static int jgo_kv_cmp(const void* a, const void* b) {
    return strcmp(((const JGoKV*)a)->k, ((const JGoKV*)b)->k);
}

// M129-2：`json_stringify_go` 的可选 opts（Go 侧 map/struct 之别在 PuXian 里同是 dict，
//   故排序与转义必须**可分别关闭** —— 例如 "map 里嵌结构体数组" 的响应：map 要排序、
//   结构体字段要保持声明序，此时用 {"sort_keys": false} 并手工按序 set）。

static void json_go_value_raw(JOut* o, LXValue v);
static void json_go_value(JOut* o, LXValue v) {
    // 缺陷 125（M145）：同 json_stringify_value —— 环上报错而非段错误
    if (px_is_container(v)) {
        if (px_path_has(&g_json_path, v.as.obj))
            px_error("json: unsupported value: encountered a cycle via %s", px_type_name(v));
        px_path_push(&g_json_path, v.as.obj);
        json_go_value_raw(o, v);
        px_path_pop(&g_json_path);
        return;
    }
    json_go_value_raw(o, v);
}
static void json_go_value_raw(JOut* o, LXValue v) {
    switch (v.type) {
        case PX_NULL: jout_append(o, "null"); break;
        case PX_BOOL: jout_append(o, v.as.b ? "true" : "false"); break;
        case PX_INT: {
            char tmp[32];
            snprintf(tmp, sizeof(tmp), "%lld", (long long)v.as.i);
            jout_append(o, tmp);
            break;
        }
        case PX_FLOAT: {
            char tmp[64];
            jgo_format_float(tmp, sizeof(tmp), v.as.f);
            jout_append(o, tmp);
            break;
        }
        case PX_STR:
            jout_escape_go(o, v.as.obj->as.str.data, v.as.obj->as.str.len);
            break;
        case PX_BYTES:
            jgo_b64(o, (const unsigned char*)v.as.obj->as.str.data, v.as.obj->as.str.len);
            break;
        case PX_LIST: {
            jout_append(o, "[");
            LXObject* ob = v.as.obj;
            for (int i = 0; i < ob->as.list.len; i++) {
                if (i) jout_append(o, ",");
                json_go_value(o, ob->as.list.items[i]);
            }
            jout_append(o, "]");
            break;
        }
        case PX_TUPLE: {
            jout_append(o, "[");
            LXObject* ob = v.as.obj;
            for (int i = 0; i < ob->as.tuple.len; i++) {
                if (i) jout_append(o, ",");
                json_go_value(o, ob->as.tuple.items[i]);
            }
            jout_append(o, "]");
            break;
        }
        case PX_DICT: {
            jout_append(o, "{");
            LXObject* ob = v.as.obj;
            int n = ob->as.dict.len;
            JGoKV* kv = n > 0 ? (JGoKV*)xmalloc(sizeof(JGoKV) * (size_t)n) : NULL;
            for (int i = 0; i < n; i++) { kv[i].k = ob->as.dict.keys[i]; kv[i].v = ob->as.dict.vals[i]; }
            if (n > 1 && g_json_go_sort) qsort(kv, (size_t)n, sizeof(JGoKV), jgo_kv_cmp);
            for (int i = 0; i < n; i++) {
                if (i) jout_append(o, ",");
                jout_escape_go(o, kv[i].k, (int)strlen(kv[i].k));
                jout_append(o, ":");
                json_go_value(o, kv[i].v);
            }
            if (kv) xfree(kv);
            jout_append(o, "}");
            break;
        }
        case PX_RESULT: {
            LXObject* ob = v.as.obj;
            jout_append(o, "{\"ok\":");
            jout_append(o, ob->as.result.ok ? "true" : "false");
            jout_append(o, ",\"value\":");
            json_go_value(o, ob->as.result.value);
            jout_append(o, "}");
            break;
        }
        default: px_error("json: 无法序列化类型 %s", px_type_name(v));
    }
}

static LXValue bi_json_stringify_go(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1 && nargs != 2) px_error("R1002: json_stringify_go 需要 (值[, opts]) 参数");
    int old_sort = g_json_go_sort, old_esc = g_json_go_escape_html;
    if (nargs == 2) {
        if (args[1].type != PX_DICT) px_error("R1002: json_stringify_go 的 opts 需要 dict");
        LXObject* od = args[1].as.obj;
        for (int i = 0; i < od->as.dict.len; i++) {
            const char* k = od->as.dict.keys[i];
            LXValue vv = od->as.dict.vals[i];
            if (strcmp(k, "sort_keys") == 0) g_json_go_sort = px_is_truthy(vv) ? 1 : 0;
            else if (strcmp(k, "escape_html") == 0) g_json_go_escape_html = px_is_truthy(vv) ? 1 : 0;
        }
    }
    JOut o = { NULL, 0, 0 };
    o.buf = xmalloc(64); o.cap = 64; o.buf[0] = 0;
    px_path_reset(&g_json_path);
    json_go_value(&o, args[0]);
    LXValue r = px_str_len(o.buf, o.len);
    xfree(o.buf);
    g_json_go_sort = old_sort;
    g_json_go_escape_html = old_esc;
    return r;
}

// ---- M29：JSON 路径运算符（JSONB 基石）----
// json_path(json_or_str, "$.a[0].b") → 按路径取（.key ["key"] [n] 负索引；取不到 → null）
// json_path_set(json_or_str, path, value) → 返回更新后的新值（路径不存在自动创建）

// 段类型：字符串键 / 数组索引
typedef struct { int is_idx; long long idx; char* key; } JPathSeg;

// 解析路径 → 段数组（返回段数；失败返回 -1）
static int json_path_parse(const char* path, JPathSeg* segs, int max) {
    int n = 0;
    const char* p = path;
    if (*p == '$') p++;
    while (*p) {
        if (n >= max) return -1;
        if (*p == '.') {
            p++;
            if (*p == '[') {
                // .["key"] 或 .[n]
                p++;
                if (*p == '"') {
                    p++;
                    const char* s = p;
                    while (*p && *p != '"') p++;
                    if (!*p) return -1;
                    char* key = xmalloc((size_t)(p - s) + 1);
                    memcpy(key, s, (size_t)(p - s)); key[p - s] = 0;
                    p++; // "
                    if (*p != ']') { xfree(key); return -1; }
                    p++; // ]
                    segs[n].is_idx = 0; segs[n].key = key; n++;
                } else {
                    char* end;
                    long long v = strtoll(p, &end, 10);
                    if (end == p) return -1;
                    if (*end != ']') return -1;
                    segs[n].is_idx = 1; segs[n].idx = v; segs[n].key = NULL; n++;
                    p = end + 1;
                }
            } else {
                const char* s = p;
                while (*p && *p != '.' && *p != '[') p++;
                if (p == s) return -1;
                char* key = xmalloc((size_t)(p - s) + 1);
                memcpy(key, s, (size_t)(p - s)); key[p - s] = 0;
                segs[n].is_idx = 0; segs[n].key = key; n++;
            }
        } else if (*p == '[') {
            p++;
            if (*p == '"') {
                p++;
                const char* s = p;
                while (*p && *p != '"') p++;
                if (!*p) return -1;
                char* key = xmalloc((size_t)(p - s) + 1);
                memcpy(key, s, (size_t)(p - s)); key[p - s] = 0;
                p++;
                if (*p != ']') { xfree(key); return -1; }
                p++;
                segs[n].is_idx = 0; segs[n].key = key; n++;
            } else {
                char* end;
                long long v = strtoll(p, &end, 10);
                if (end == p) return -1;
                if (*end != ']') return -1;
                segs[n].is_idx = 1; segs[n].idx = v; segs[n].key = NULL; n++;
                p = end + 1;
            }
        } else {
            // 无前缀：a.b[0]
            const char* s = p;
            while (*p && *p != '.' && *p != '[') p++;
            if (p == s) return -1;
            char* key = xmalloc((size_t)(p - s) + 1);
            memcpy(key, s, (size_t)(p - s)); key[p - s] = 0;
            segs[n].is_idx = 0; segs[n].key = key; n++;
        }
    }
    return n;
}

static void json_path_segs_free(JPathSeg* segs, int n) {
    for (int i = 0; i < n; i++) if (!segs[i].is_idx && segs[i].key) xfree(segs[i].key);
}

// 按路径取（不 deep copy，返回内部引用）
static LXValue json_path_walk(LXValue cur, JPathSeg* segs, int n) {
    for (int i = 0; i < n; i++) {
        if (segs[i].is_idx) {
            if (cur.type != PX_LIST) return px_null();
            LXObject* o = cur.as.obj;
            long long idx = segs[i].idx;
            if (idx < 0) idx += o->as.list.len;
            if (idx < 0 || idx >= o->as.list.len) return px_null();
            cur = o->as.list.items[(int)idx];
        } else {
            if (cur.type != PX_DICT) return px_null();
            cur = px_dict_get(cur, segs[i].key);
            if (cur.type == PX_NULL) return px_null();
        }
    }
    return cur;
}

// 深拷贝（JSON 可序列化部分）
static LXValue json_value_copy(LXValue v) {
    switch (v.type) {
        case PX_NULL: case PX_BOOL: case PX_INT: case PX_FLOAT: case PX_STR: case PX_BYTES:
            return v;
        case PX_LIST: {
            LXValue r = px_list(0);
            px_root_push();
            PX_KEEP(r);   // M92 precise：深拷贝 list 跨递归 json_value_copy/px_list_push 分配
            LXObject* o = v.as.obj;
            for (int i = 0; i < o->as.list.len; i++) px_list_push(r, json_value_copy(o->as.list.items[i]));
            px_root_pop();
            return r;
        }
        case PX_TUPLE: {
            LXObject* o = v.as.obj;
            LXValue* items = xmalloc(sizeof(LXValue) * (size_t)(o->as.tuple.len > 0 ? o->as.tuple.len : 1));
            px_root_push();
            for (int i = 0; i < o->as.tuple.len; i++) {
                items[i] = json_value_copy(o->as.tuple.items[i]);
                PX_KEEP(items[i]);   // M92 precise：收集数组仅 C 持有，跨后续递归分配
            }
            LXValue r = px_tuple(items, o->as.tuple.len);
            px_root_pop();
            xfree(items);
            return r;
        }
        case PX_DICT: {
            LXValue r = px_dict();
            px_root_push();
            PX_KEEP(r);   // M92 precise：深拷贝 dict 跨递归 json_value_copy/px_dict_set 分配
            LXObject* o = v.as.obj;
            for (int i = 0; i < o->as.dict.len; i++) {
                px_dict_set(r, o->as.dict.keys[i], json_value_copy(o->as.dict.vals[i]));
            }
            px_root_pop();
            return r;
        }
        case PX_RESULT: {
            // M39：Result 深拷贝（Ok/Err 标志 + 载荷递归）
            LXObject* o = v.as.obj;
            if (o->as.result.ok) return px_ok(json_value_copy(o->as.result.value));
            return px_err(json_value_copy(o->as.result.value));
        }
        default: return v;
    }
}

// 递归设值：在 base 的 segs[0..] 处写入 new_val，返回新对象
static LXValue json_path_set_at(LXValue base, JPathSeg* segs, int n, LXValue new_val) {
    if (n == 0) return new_val;
    if (segs[0].is_idx) {
        long long idx = segs[0].idx;
        LXValue lst = (base.type == PX_LIST) ? base : px_list(0);
        LXObject* o = lst.as.obj;
        int len = o->as.list.len;
        long long real = (idx < 0) ? len + idx : idx;
        // 深拷贝现有元素（M92 precise：items 收集数组 + 结果 list 仅 C 局部持有，
        // 跨 json_value_copy/px_list_push 分配须登记）
        LXValue* items = xmalloc(sizeof(LXValue) * (size_t)(len > 0 ? len : 1));
        px_root_push();
        PX_KEEP(lst);   // base（bi_json_path_set 深拷贝临时，仅 C 持有）跨拷贝分配存活
        for (int i = 0; i < len; i++) {
            items[i] = json_value_copy(o->as.list.items[i]);
            PX_KEEP(items[i]);   // 收集数组仅 C 持有，跨后续递归/分配
        }
        LXValue r = px_list(len);
        PX_KEEP(r);   // 结果 list 跨 px_list_push/递归分配
        for (int i = 0; i < len; i++) px_list_push(r, items[i]);
        xfree(items);
        LXObject* ro = r.as.obj;
        if (real < 0) {
            // 负索引越界 → 插入 0
            LXValue child = json_path_set_at(px_null(), segs + 1, n - 1, new_val);
            // 在 0 处插入：新 list 重建
            LXValue* ni = xmalloc(sizeof(LXValue) * (size_t)(ro->as.list.len + 1));
            ni[0] = child;
            PX_KEEP(child);   // 入 rr 前 child 仅 ni[0] 持有
            for (int i = 0; i < ro->as.list.len; i++) ni[i + 1] = ro->as.list.items[i];
            LXValue rr = px_list(ro->as.list.len + 1);
            PX_KEEP(rr);   // 结果 list 跨 px_list_push 分配
            for (int i = 0; i < ro->as.list.len + 1; i++) px_list_push(rr, ni[i]);
            xfree(ni);
            px_root_pop();
            return rr;
        } else if (real < ro->as.list.len) {
            // 原位设值（child 赋入 r 前无分配，r 已登记）
            LXValue child = json_path_set_at(ro->as.list.items[(int)real], segs + 1, n - 1, new_val);
            ro->as.list.items[(int)real] = child;
            px_root_pop();
            return r;
        } else {
            // 越界扩展：null 填充 + 追加
            while (ro->as.list.len < real) px_list_push(r, px_null());
            LXValue child = json_path_set_at(px_null(), segs + 1, n - 1, new_val);
            PX_KEEP(child);   // 入 r 前仅 C 局部
            px_list_push(r, child);
            px_root_pop();
            return r;
        }
    } else {
        // dict 字段
        LXValue d = (base.type == PX_DICT) ? base : px_dict();
        LXObject* o = d.as.obj;
        LXValue r = px_dict();
        px_root_push();
        PX_KEEP(d);   // base（bi_json_path_set 深拷贝临时，仅 C 持有）跨拷贝分配存活
        PX_KEEP(r);   // 结果 dict 跨 px_dict_set/json_value_copy 分配
        for (int i = 0; i < o->as.dict.len; i++) {
            px_dict_set(r, o->as.dict.keys[i], json_value_copy(o->as.dict.vals[i]));
        }
        LXValue child = px_dict_get(d, segs[0].key);
        LXValue nv = (child.type == PX_NULL)
            ? json_path_set_at(px_null(), segs + 1, n - 1, new_val)
            : json_path_set_at(child, segs + 1, n - 1, new_val);
        PX_KEEP(nv);   // 入 r 前仅 C 局部（递归返回值）
        px_dict_set(r, segs[0].key, nv);
        px_root_pop();
        return r;
    }
}

static LXValue bi_json_path(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 2) px_error("R1002: json_path 需要 (json, path) 参数");
    // 输入归一化：str → 解析
    LXValue v = args[0];
    if (v.type == PX_STR) {
        JsonCtx j = { v.as.obj->as.str.data };
        v = json_parse_value(&j);
    }
    if (args[1].type != PX_STR) px_error("R1002: json_path 的 path 需要字符串");
    JPathSeg segs[64];
    int n = json_path_parse(args[1].as.obj->as.str.data, segs, 64);
    if (n < 0) { json_path_segs_free(segs, 0); px_error("json_path: 非法路径"); }
    LXValue r = json_path_walk(v, segs, n);
    json_path_segs_free(segs, n);
    return r;
}

static LXValue bi_json_path_set(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 3) px_error("R1002: json_path_set 需要 (json, path, value) 参数");
    LXValue v = args[0];
    if (v.type == PX_STR) {
        JsonCtx j = { v.as.obj->as.str.data };
        v = json_parse_value(&j);
    }
    if (args[1].type != PX_STR) px_error("R1002: json_path_set 的 path 需要字符串");
    JPathSeg segs[64];
    int n = json_path_parse(args[1].as.obj->as.str.data, segs, 64);
    if (n < 0) { json_path_segs_free(segs, 0); px_error("json_path_set: 非法路径"); }
    LXValue r;
    if (n == 0) {
        r = json_value_copy(args[2]);
    } else {
        r = json_path_set_at(json_value_copy(v), segs, n, args[2]);
    }
    json_path_segs_free(segs, n);
    return r;
}

// ---- std.time ----

static LXValue bi_now(LXValue* args, int nargs, void* ctx) {
    (void)args; (void)nargs; (void)ctx;
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    char buf[64];
    snprintf(buf, sizeof(buf), "%04d-%02d-%02d %02d:%02d:%02d",
             tmv.tm_year + 1900, tmv.tm_mon + 1, tmv.tm_mday,
             tmv.tm_hour, tmv.tm_min, tmv.tm_sec);
    return px_str(buf);
}

// ---- std.os ----

static LXValue bi_env(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 1 || args[0].type != PX_STR) px_error("R1002: env 需要一个变量名");
    const char* v = getenv(args[0].as.obj->as.str.data);
    return v ? px_str(v) : px_null();
}

// M-B2 修复：编译版保存原始命令行参数（自举 lexer 需要 args() 取输入文件）
static char** g_px_argv = NULL;
static int g_px_argc = 0;

void px_args_init(int argc, char** argv) {
    g_px_argc = argc;
    g_px_argv = argv;
}

static LXValue bi_args(LXValue* args, int nargs, void* ctx) {
    (void)args; (void)nargs; (void)ctx;
    LXValue l = px_list(0);
    px_root_push();
    PX_KEEP(l);   // M92 precise：累积 list 跨 px_list_push/px_str 分配
    for (int i = 0; i < g_px_argc; i++) {
        px_list_push(l, px_str(g_px_argv[i]));
    }
    px_root_pop();
    return l;
}

// ---- std.collections（高阶函数） ----
// M92：map/filter/reduce 循环内 px_call 回调用户代码（可大量分配触发 GC）+ px_list_push
// （扩容分配）。precise 模式下 C 栈不扫 → 桥内新建、跨回调/跨分配的局部（结果 list r /
// 累积 acc）须 PX_KEEP 登记（fn/item 为参数/参数子对象，上层根已保护）。

static LXValue bi_map(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 2 || args[0].type != PX_LIST) px_error("R1002: map 需要 (list, fn)");
    LXObject* o = args[0].as.obj;
    LXValue fn = args[1];
    LXValue r = px_list(0);
    px_root_push();
    PX_KEEP(r);          // 累积结果 list：px_list_push 扩容分配/回调期间需存活
    for (int i = 0; i < o->as.list.len; i++) {
        LXValue item = o->as.list.items[i];
        LXValue res = px_call(fn, &item, 1);
        px_list_push(r, res);
    }
    px_root_pop();
    return r;
}

static LXValue bi_filter(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs != 2 || args[0].type != PX_LIST) px_error("R1002: filter 需要 (list, fn)");
    LXObject* o = args[0].as.obj;
    LXValue fn = args[1];
    LXValue r = px_list(0);
    px_root_push();
    PX_KEEP(r);
    for (int i = 0; i < o->as.list.len; i++) {
        LXValue item = o->as.list.items[i];
        LXValue res = px_call(fn, &item, 1);
        if (px_is_truthy(res)) px_list_push(r, item);
    }
    px_root_pop();
    return r;
}

static LXValue bi_reduce(LXValue* args, int nargs, void* ctx) {
    (void)ctx;
    if (nargs < 2 || nargs > 3 || args[0].type != PX_LIST) px_error("R1002: reduce 需要 (list, fn, [init])");
    LXObject* o = args[0].as.obj;
    LXValue fn = args[1];
    LXValue acc = (nargs >= 3) ? args[2] : px_int(0);
    for (int i = 0; i < o->as.list.len; i++) {
        LXValue item = o->as.list.items[i];
        LXValue pair[2] = { acc, item };
        px_root_push();
        PX_KEEP(acc);    // 累积值跨 px_call 回调存活（回调内 GC 会回收仅栈持有的对象）
        LXValue nacc = px_call(fn, pair, 2);
        px_root_pop();
        acc = nacc;
    }
    return acc;
}

